-- v0.0.70: newindex neutra
pcall(function()
    if not (getgc and hookfunction and setthreadidentity and getrenv) then return end
    local dbg = false          -- flip true to see what the AC tried to do
    local held = {}
    local flagged, killer

    -- v0.22.0: sweep gets its OWN pcall so identity always restores. Bare, a
    -- raise mid-walk left the thread parked at identity 2 for the rest of boot.
    setthreadidentity(2)
    pcall(function()
        for _, v in getgc(true) do
            if typeof(v) == "table" then
                local det = rawget(v, "Detected")
                local kil = rawget(v, "Kill")
                if typeof(det) == "function" and not flagged then
                    flagged = det
                    pcall(function()
                        hookfunction(flagged, function(method, info)
                            if dbg and method ~= "_" then
                                warn(("Adonis AntiCheat flagged\nMethod: %s\nInfo: %s"):format(tostring(method), tostring(info)))
                            end
                            return true
                        end)
                        table.insert(held, flagged)
                    end)
                end
                if rawget(v, "Variables") and rawget(v, "Process") and typeof(kil) == "function" and not killer then
                    killer = kil
                    pcall(function()
                        hookfunction(killer, function(reason)
                            if dbg then warn("adonis tried to kill (fb): " .. tostring(reason)) end
                        end)
                        table.insert(held, killer)
                    end)
                end
                -- v0.22.0: stop once both hooks are in. Used to walk the whole gc
                -- table anyway. No task.wait() here on purpose: a late Adonis
                -- hook is a hook that already let you get flagged.
                if flagged and killer then break end
            end
        end
    end)

    -- v0.45.1: only hook the global debug.info when Adonis was actually
    -- found. Good ACs watch this primitive; hooking it blind is a flag.
    if flagged then pcall(function()
        local realInfo = getrenv().debug.info
        local wrapper  = newcclosure or function(f) return f end
        local o; o = hookfunction(realInfo, wrapper(function(...)
            local a = ...
            if flagged and a == flagged then
                if dbg then warn("[koffee] adonis gone") end
                return coroutine.yield(coroutine.running())
            end
            return o(...)
        end))
    end) end

    setthreadidentity(7)
end)

pcall(function()
    local dbg = false
    if not (getgc and debug and debug.info and hookfunction) then return end
    local genv = (getgenv and getgenv()) or nil
    if genv then
        if genv["\6_rt_an_ctx"] then return end
        genv["\6_rt_an_ctx"] = true
    end

    local NEEDLES = { "AnalyticsPipelineController" }
    local held = {}

    local function hang() return task.wait(9e9) end
    local function noop() end

    task.spawn(function()
        -- v0.45.1: presence-gated + deferred. The old code walked GC and hung
        -- closures on every game, and the 8s WaitForChild grabs stalled load.
        -- Now: nothing runs unless the pipeline remote exists, past boot.
        task.wait(6)
        local RS0 = game:GetService("ReplicatedStorage")
        local present = false
        pcall(function()
            local remotes = RS0:FindFirstChild("Remotes")
            local pipe = remotes and remotes:FindFirstChild("AnalyticsPipeline")
            if pipe and pipe:FindFirstChild("RemoteEvent") then present = true return end
            for _, d in ipairs(RS0:GetDescendants()) do
                if d:IsA("RemoteEvent") and d.Parent
                   and d.Parent.Name:find("Analytics", 1, true) then present = true break end
            end
        end)
        if not present then return end
        local ok, gc = pcall(getgc)
        if ok and type(gc) == "table" then
            local n = 0
            for _, v in pairs(gc) do
                n = n + 1
                if n % 3000 == 0 then task.wait() end   -- never hitch a frame
                if type(v) == "function" then
                    local o, src = pcall(debug.info, v, "s")
                    if o and type(src) == "string" then
                        for _, needle in ipairs(NEEDLES) do
                            if src:find(needle, 1, true) then
                                if pcall(hookfunction, v, hang) then
                                    held[#held + 1] = v
                                    if dbg then warn("[koffee] hung " .. src) end
                                end
                                break
                            end
                        end
                    end
                end
            end
        end

        if not getconnections then return end
        local RS = game:GetService("ReplicatedStorage")

        -- presence confirmed above; re-resolve the handle instantly, no waits.
        local ev
        pcall(function()
            local remotes = RS:FindFirstChild("Remotes")
            local pipe = remotes and remotes:FindFirstChild("AnalyticsPipeline")
            ev = pipe and pipe:FindFirstChild("RemoteEvent")
            if not ev then
                for _, d in ipairs(RS:GetDescendants()) do
                    if d:IsA("RemoteEvent") and d.Parent
                       and d.Parent.Name:find("Analytics", 1, true) then ev = d break end
                end
            end
        end)
        if not ev then return end

        for pass = 1, 3 do
            local o, conns = pcall(getconnections, ev.OnClientEvent)
            if o and type(conns) == "table" then
                for _, c in pairs(conns) do
                    local done = pcall(function() c:Disable() end)
                    if not done then
                        local o2, f = pcall(function() return c.Function end)
                        if o2 and type(f) == "function" and pcall(hookfunction, f, noop) then
                            held[#held + 1] = f
                            done = true
                        end
                    end
                    if dbg and done then warn("[koffee] silenced a listener") end
                end
            end
            if pass < 3 then task.wait(2) end
        end
    end)
end)

-- operation one neutra
if game.PlaceId == 13997018456 then pcall(function()
    if not (hookmetamethod and hookfunction and newcclosure and getconnections and isfunctionhooked) then return end
    local rs = game:GetService("ReplicatedStorage")

    local clientReporters = {}
    for _, name in ipairs({"ForeignInstanceDetected", "UnknownHighlight", "RageRemote"}) do
        local r = rs:FindFirstChild(name, true)
        if r then clientReporters[r] = name end
    end

    local oldNamecall
    oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
        if getnamecallmethod() == "FireServer" and clientReporters[self] then return end
        return oldNamecall(self, ...)
    end))

    local function nukeConns(remote)
        for _, conn in ipairs(getconnections(remote.OnClientEvent)) do
            local fn = conn.Function
            if fn and not isfunctionhooked(fn) then
                hookfunction(fn, newcclosure(function(...) end))
            end
        end
    end

    local fuid = rs:FindFirstChild("ForeignUIDetected", true)
    if fuid then nukeConns(fuid) end

    task.spawn(function()
        while task.wait(2) do
            for remote in pairs(clientReporters) do nukeConns(remote) end
            if fuid then nukeConns(fuid) end
        end
    end)
end) end

-- dahood neutra
if game.PlaceId == 2788229376 then
    if not game:IsLoaded() then
        game.Loaded:Wait()
    end
    local function executed(kickreason)
        game:GetService("Players").LocalPlayer:Kick("K - " .. kickreason)
    end
    coroutine.wrap(function()
        local yes, err = pcall(function()
            local grm = getrawmetatable(game)
            setreadonly(grm, false)
            old__namecall1 = grm.__namecall
            grm.__namecall = newcclosure(function(self, ...)
                local args = {...}
                local remoteName = tostring(args[1])
                local blockedRemotes = {
                    TeleportDetect = true,
                    CHECKER_1 = true,
                    CHECKER = true,
                    GUI_CHECK = true,
                    OneMoreTime = true,
                    checkingSPEED = true,
                    BANREMOTE = true,
                    PERMAIDBAN = true,
                    KICKREMOTE = true,
                    BR_KICKPC = true,
                    BR_KICKMOBILE = true,
                }
                if blockedRemotes[remoteName] then
                    return
                end
                return old__namecall1(self, ...)
            end)
        end)
        if not yes then
            executed("trashexec: " .. tostring(err))
            return
        end
    end)()

    local mt = getrawmetatable(game)
    setreadonly(mt, false)
    local oldIndex = mt.__index
    local oldNewIndex = mt.__newindex
    mt.__index = newcclosure(function(self, key)
        if not checkcaller() and self and typeof(self) == "Instance" and self:IsA("Humanoid") and key == "WalkSpeed" then
            return 16
        end
        return oldIndex(self, key)
    end)
    -- dont remove this write.
    mt.__newindex = newcclosure(function(self, key, value)
        if not checkcaller() and self and typeof(self) == "Instance" and self:IsA("Humanoid") and key == "WalkSpeed" then
            return
        end
        return oldNewIndex(self, key, value)
    end)
    setreadonly(mt, true)
end

