local tabs = {}
local tabOrder = 0        -- explicit LayoutOrder per tab
local activeTab = nil
local pillFirstShow = true

-- v0.0.98/99 pill machinery. Follower pill: resting state is ALWAYS the active
-- tab button's live rect; on switch it pops (stretch past destination) then
-- contracts; snaps via pillResync whenever button geometry moves. v0.0.99:
-- a generation token lets stale tween completions bail instead of fighting a
-- newer switch (the "pill flickers every other click" fix).
local PILL_STRETCH  = TweenInfo.new(0.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
local PILL_CONTRACT = TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local pillAnimating = false
local pillT1, pillT2 = nil, nil
local pillGen = 0

-- active button's rect expressed in tabBar-local offsets
local function pillRectFor(button)
    return UDim2.new(0, button.AbsolutePosition.X - tabBar.AbsolutePosition.X,
                     0, button.AbsolutePosition.Y - tabBar.AbsolutePosition.Y),
           UDim2.new(0, button.AbsoluteSize.X, 0, button.AbsoluteSize.Y)
end

local function pillSnap(button)
    pillGen = pillGen + 1   -- v0.99: a snap supersedes every in-flight tween
    if pillT1 then pillT1:Cancel(); pillT1 = nil end
    if pillT2 then pillT2:Cancel(); pillT2 = nil end
    pillAnimating = false
    local pos, size = pillRectFor(button)
    pill.Position, pill.Size = pos, size
    if pillFirstShow then
        tween(pill, Theme.Animation.Normal, { BackgroundTransparency = 0 })
        pillFirstShow = false
    end
end

local function movePillTo(button, snap)
    -- v0.48.0: pill motion honours Animations > Tab Switching; off snaps.
    if pillFirstShow or snap or not Koffee.Anim.spot("AnimTabs") then pillSnap(button); return end
    if pillT1 then pillT1:Cancel(); pillT1 = nil end
    if pillT2 then pillT2:Cancel(); pillT2 = nil end
    local targetPos, targetSize = pillRectFor(button)
    pillGen = pillGen + 1
    local gen = pillGen
    pillAnimating = true
    -- v0.0.98: the pill POP: grows only HALF A PILL past the destination (hard
    -- cap, centered on the target so it reads as the pill swelling, not moving
    -- across), then the only move left is shrinking to the exact resting rect.
    -- No walk-span, no accumulation: a switch mid-flight cancels both tweens and
    -- the pop restarts from the CURRENT rect, so the pill can never grow forever.
    local w    = targetSize.X.Offset
    local ow   = w + w * 0.5
    local ox   = targetPos.X.Offset - (ow - w) * 0.5
    local y    = targetPos.Y.Offset
    local h    = targetSize.Y.Offset
    pillT1 = TweenService:Create(pill, Koffee.Anim.info(PILL_STRETCH), {
        Position = UDim2.new(0, ox, 0, y),
        Size     = UDim2.new(0, ow, 0, h),
    })
    pillT1:Play()
    pillT1.Completed:Connect(function(state)
        if gen ~= pillGen then return end   -- superseded: the newer switch owns everything
        if state ~= Enum.PlaybackState.Completed then return end
        if pillT2 then pillT2:Cancel() end
        pillT2 = TweenService:Create(pill, Koffee.Anim.info(PILL_CONTRACT), {
            Position = targetPos,
            Size     = targetSize,
        })
        pillT2:Play()
        pillT2.Completed:Connect(function(_)
            if gen ~= pillGen then return end   -- stale: a newer pop or snap already owns the pill
            -- v0.98 hard rule: ANY finish clears the flag. A stale `true`
            -- permanently blocked pillResync and wedged the pill huge.
            pillAnimating = false
        end)
    end)
end

-- single geometry watcher: re-snap the pill to the active button whenever anything
-- shifts its rect (font reflow, window drag/resize) UNLESS a switch animation owns
-- the pill right now. Fed by the tabBar move signal + each button's own size/pos
-- signals (hooked in addTab).
local function pillResync()
    if pillAnimating or not activeTab then return end
    local tab = tabs[activeTab]
    if tab then pillSnap(tab.Button) end
end
tabBar:GetPropertyChangedSignal("AbsolutePosition"):Connect(pillResync)

local function selectTab(name)
    if activeTab == name then return end
    activeTab = name
    -- v0.48.0: tab switches honour Animations > Tab Switching; off snaps the
    -- colours, panels and pill straight to their resting states.
    local tabsAnim = Koffee.Anim.spot("AnimTabs")
    for tabName, tab in pairs(tabs) do
        local isActive = tabName == name
        if tabsAnim then
            tween(tab.Button, Theme.Animation.Fast, {
                TextColor3 = isActive and Theme.Palette.Text or Theme.Palette.TextMuted,
            })
        else
            tab.Button.TextColor3 = isActive and Theme.Palette.Text or Theme.Palette.TextMuted
        end
        -- v0.0.99: pure crossfade: the outgoing panel fades out, the incoming
        -- fades in. No scale pop, no scroll jump: panels are ScrollingFrames so
        -- the fade lives on each tab's CanvasGroup wrapper (GroupTransparency).
        -- Panels get CanvasGroup wrappers in addTab; the wrapper's Visible flag
        -- is the real show/hide (GroupTransparency = 1 is not enough: children
        -- of an invisible canvas can still eat input).
        local w = tab.Wrap
        if isActive then
            tab.Panel.CanvasPosition = Vector2.new(0, 0)
            if tabsAnim then
                w.GroupTransparency = 1
                w.Visible = true
                tween(w, Theme.Animation.Slow, { GroupTransparency = 0 })
            else
                w.GroupTransparency = 0
                w.Visible = true
            end
            movePillTo(tab.Button)
        else
            if tabsAnim then
                tween(w, Theme.Animation.Slow, { GroupTransparency = 1 })
                task.delay(Koffee.Anim.wait(0.35), function()
                    if activeTab ~= tabName then w.Visible = false end
                end)
            else
                w.GroupTransparency = 1
                w.Visible = false
            end
        end
    end
end

-- v0.0.34: forward-declared shared upvalues. Config + team/friend helpers live inside
-- IIFEs so their locals get their OWN register budget (Luau's 200-local ceiling is
-- per-function; main chunk is already close). Only these handles are promoted so
-- ESP / World / Combat can call them.
-- Options flag + Team Check config:
--   MyTeams      : Team NAMES the user marked "my team" (allies -> skipped)
--   AdvancedTeam : use automatic isSameTeam heuristic instead of manual list
local Shared = { IgnoreFriends = false, IgnoreFriendsScope = "Everything", AdvancedTeam = false, MyTeams = {} }
-- v0.0.97 Target Lock: type a player name, toggle the feature on, hit the keybind
-- to "activate": while active, the named player is the ONLY target for aimbot,
-- silent aim, trigger bot AND the only player ESP renders. Deactivate (hit the
-- keybind again) -> normal multi-target behaviour resumes. The toggle (Enabled)
-- arms the feature; the keybind (Active) engages / disengages the lock at runtime.
Shared.TargetLock = {
    Enabled  = false,   -- master toggle (arms the keybind)
    Name     = "",      -- target's username or display name (case-insensitive substring match)
    Key      = nil,     -- activation keybind (set via the keybind pill)
    _active  = false,   -- runtime: is the lock currently engaged?
}
-- v0.67.0: real module so the arraylist shows Armed plus a live on/off while
-- engaged. OnDisable also disengages, so disable never strands a stale lock.
registerModule("targetlock", "Target Lock",
    function() Shared.TargetLock.Enabled = true end,
    function() Shared.TargetLock.Enabled = false; Shared.TargetLock._active = false end)
Modules.targetlock.IsActive = function() return Shared.TargetLock._active end
-- resolve the current TargetLock.Name to a live Player or nil.
-- v0.3.1: match ranking. Previous first-match-wins picked whoever appeared
-- earliest in the Players list: typing "a" could lock onto "Anna" when
-- the intended target was "alice". Now every player is scored and the
-- best is returned:
--   6 = exact Name              (case-insensitive)
--   5 = exact DisplayName
--   4 = Name starts with query
--   3 = DisplayName starts with query
--   2 = Name contains query
--   1 = DisplayName contains query
--   0 = no match
-- Ties break on the FIRST player scored (arbitrary but deterministic).
-- v0.63.2: Target Lock now locks onto the player-list PRIORITIZE set (multi-target)
-- instead of a single typed name. `targetMark` (defined just below) is the resolver;
-- these two just ask "is the lock engaged, and is this player prioritized?".
function Shared.targetLockPlayer()
    if not (Shared.TargetLock.Enabled and Shared.TargetLock._active) then return nil end
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= Players.LocalPlayer and Shared.targetMark(plr) == "prioritize" then return plr end
    end
    return nil
end
function Shared.targetLockMatches(plr)
    if not (Shared.TargetLock.Enabled and Shared.TargetLock._active) then return false end
    return Shared.targetMark(plr) == "prioritize"
end
local isSameTeam, isFriend, registerConfig, rebuildConfigTabs, isTeammate
-- v0.0.97 hardening: give the forward-declared registerConfig a real default NOW so
-- a nil never reaches the registry call sites (the REAL definition is re-assigned
-- by the config IIFE below: same local slot, later assignment wins at runtime).
registerConfig = function(name, tbl) end

-- v0.63.2: target eligibility resolver. Precedence: custom-graph (a Custom Features
-- node -- reserved, nil until stage 3) > player-list status > nothing. Returns
-- "exclude" | "prioritize" | nil.
function Shared.targetMark(plr)
    local cg = Shared._customTargetMark and Shared._customTargetMark(plr)
    if cg == "exclude" or cg == "prioritize" then return cg end
    local pl = Shared.PlayerList
    if pl and pl.statusFor then return pl.statusFor(plr) end
    return nil
end
-- is `plr` a legal aim / trigger target? Exclude = never; lock engaged = ONLY the
-- Prioritize set; otherwise the normal team-check + ignore-friends filters apply.
-- (Prioritize is dormant while the lock is off; None defers to those filters.)
-- v0.90.0: Ignore Friends can cover only combat, only visuals, or everything (default)
function Shared.friendIgnored(plr, kind)
    if not (Shared.IgnoreFriends and isFriend and isFriend(plr)) then return false end
    local sc = Shared.IgnoreFriendsScope or "Everything"
    return sc == "Everything" or sc == kind
end
function Shared.aimAllowed(plr, teamCheck)
    local mark = Shared.targetMark(plr)
    if mark == "exclude" then return false end
    if Shared.TargetLock.Enabled and Shared.TargetLock._active then
        return mark == "prioritize"
    end
    if teamCheck and isTeammate and isTeammate(plr) then return false end
    if Shared.friendIgnored(plr, "Combat") then return false end
    return true
end
-- v0.65.0: the custom-graph tier of targetMark. A Custom Features "Target Status"
-- node calls _customMark(plr, mode) every frame it's active; the mark self-expires
-- shortly after (TTL) so it clears the moment the node stops painting / is removed.
Shared._customMarks = {}
function Shared._customMark(plr, mode)
    if plr then Shared._customMarks[tostring(plr.UserId)] = { mode = mode, at = os.clock() } end
end
function Shared._customTargetMark(plr)
    local m = plr and Shared._customMarks[tostring(plr.UserId)]
    if m and (os.clock() - m.at) < 0.3 then return m.mode end
    return nil
end

-- v0.0.37: OS-level input from the Koffee Helper (Roblox can't see mouse 4/5).
-- The poll loop at the bottom of the file fills XB1/XB2; binds can be the virtual
-- strings "XButton1"/"XButton2" which the helper-driven Heartbeats resolve.
-- v0.22.0: single source for the helper contract. :7912 feeds XButton state,
-- :27374 is the External silent-aim bridge. Both now send the key header.
-- NOTE: Key is a constant in a distributed script: a seam, not real auth.
local Helper = {
    Connected = false, XB1 = false, XB2 = false,
    Host = "http://127.0.0.1", PortInput = 7912, PortAim = 27374,
    Key = "KoffeeBetaDevelopmentTesting",
}
function Helper.Url(port, path) return Helper.Host .. ":" .. port .. (path or "") end
function Helper.Headers()
    return { ["X-Koffee-Key"] = Helper.Key, ["Content-Type"] = "application/json" }
end
local VIRTUAL_LABELS = { XButton1 = "XB1", XButton2 = "XB2" }
-- display text for ANY bind: virtual string, Roblox EnumItem, or nil.
-- v0.0.94: short-name modifier map for combo pill display ("LeftShift" -> "Shift").
local MOD_SHORT = {
    LeftShift = "Shift", RightShift = "Shift",
    LeftControl = "Ctrl", RightControl = "Ctrl",
    LeftAlt = "Alt",   RightAlt = "Alt",
}
-- v0.27.0: compact mouse-button labels for module pills (matches combat's inputName).
local MOUSE_SHORT_LBL = { MouseButton1 = "LMB", MouseButton2 = "RMB", MouseButton3 = "MMB" }
local function keyLabel(bind)
    if bind == nil then return nil end
    if type(bind) == "string" then return VIRTUAL_LABELS[bind] or bind end
    if typeof(bind) == "EnumItem" then
        if bind.EnumType == Enum.UserInputType then return MOUSE_SHORT_LBL[bind.Name] or bind.Name end
        return bind.Name
    end
    -- v0.0.94 combo bind: { mod = KeyCode, key = KeyCode } -> "Shift+C"
    if type(bind) == "table" and bind.mod and bind.key then
        local m = (typeof(bind.mod) == "EnumItem") and (MOD_SHORT[bind.mod.Name] or bind.mod.Name) or tostring(bind.mod)
        local k = (typeof(bind.key) == "EnumItem") and bind.key.Name or tostring(bind.key)
        return m .. "+" .. k
    end
    return nil
end

local function addTab(name, buildFn)
    tabOrder = tabOrder + 1
    local button = new("TextButton", {
        Name = name,
        -- v0.48.3: Primary Tab labels render lowercase (keys stay as-is).
        Text = name:lower(),
        FontFace = Theme.Fonts.Medium,
        TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1,
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.new(0, 0, 1, 0),
        AutoButtonColor = false,
        LayoutOrder = tabOrder,
        ZIndex = 34,
        Parent = buttonLayer,
    }, {
        new("UIPadding", {
            PaddingLeft = UDim.new(0, 12),
            PaddingRight = UDim.new(0, 12),
        }),
    })

    -- v0.0.30: the button's own rect changing (AutomaticSize settling after the
    -- font's glyph metrics load, or a reflow) re-snaps the pill if this tab is the
    -- active one: kills the "pill offset on launch until you switch tabs" bug.
    button:GetPropertyChangedSignal("AbsoluteSize"):Connect(pillResync)
    button:GetPropertyChangedSignal("AbsolutePosition"):Connect(pillResync)

    -- ScrollingFrame per tab so long panel stacks don't clip. AutomaticCanvasSize
    -- reads its own children's total height so we don't have to size manually.
    -- v0.0.99: each panel sits inside a CanvasGroup wrapper so tab switches can
    -- CROSSFADE (ScrollingFrames have no GroupTransparency of their own). The
    -- wrap owns Visible; the panel owns scroll.
    local wrap = new("CanvasGroup", {
        Name = "Wrap",
        Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1,
        GroupTransparency = 1,
        Visible = false,
        ZIndex = 32,
        Parent = content,
    })
    local panel = new("ScrollingFrame", {
        Name = name,
        Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = true,
        ZIndex = 33,
        ScrollBarThickness = 4,
        ScrollBarImageColor3 = Theme.Palette.TextFaint,
        ScrollBarImageTransparency = 0.4,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        VerticalScrollBarPosition = Enum.VerticalScrollBarPosition.Right,
        ScrollingDirection = Enum.ScrollingDirection.Y,
        Parent = wrap,
    })

    if buildFn then
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            Padding = UDim.new(0, 12),
            SortOrder = Enum.SortOrder.LayoutOrder,
            Parent = panel,
        })
        new("UIPadding", {
            -- v0.70.2: 2px breathing room on three sides. Feature-box UIStrokes
            -- draw half outside the card rect and the scroller clips them.
            PaddingLeft = UDim.new(0, 2), PaddingTop = UDim.new(0, 2),
            PaddingRight = UDim.new(0, 2),
            PaddingBottom = UDim.new(0, 12),   -- room past last panel so scroll feels right
            Parent = panel,
        })
        buildFn(panel)
    else
        new("TextLabel", {
            Text = name .. ": Coming Soon",
            FontFace = Theme.Fonts.Regular,
            TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.TextFaint,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 1, 0),
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            ZIndex = 33,
            Parent = panel,
        })
    end

    button.MouseEnter:Connect(function()
        if activeTab ~= name then
            tween(button, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
        end
    end)
    button.MouseLeave:Connect(function()
        if activeTab ~= name then
            tween(button, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
        end
    end)
    button.MouseButton1Click:Connect(function() selectTab(name) end)
    -- NOTE: no popFx here: tab labels must never squash/scale on press (per he).
    -- The pill's own pop is the tab switch's motion.

    -- v0.0.34: stash the build fn so the config system can re-run it against the
    -- same panel (clears children first) to push loaded values into every widget.
    tabs[name] = { Button = button, Panel = panel, Wrap = wrap, Build = buildFn }
end

-- v0.0.34: rebuild the config-driven tabs after a config load so sliders /
-- dropdowns / checkboxes / keybind pills re-read the freshly applied state.
-- moduleCheckbox is the only Watchers subscriber, so clearing Watchers first
-- keeps the subscriber count flat across reloads (they re-subscribe here).
local function rebuildTabPanel(name)
    local entry = tabs[name]
    if not (entry and entry.Build) then return end
    local p = entry.Panel
    for _, c in ipairs(p:GetChildren()) do c:Destroy() end
    new("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        Padding = UDim.new(0, 12),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = p,
    })
    new("UIPadding", { PaddingBottom = UDim.new(0, 12), Parent = p })
    pcall(entry.Build, p)
end
rebuildConfigTabs = function()
    for _, m in pairs(Modules) do m.Watchers = {} end
    for _, n in ipairs({ "Visuals", "Combat", "World", "Character", "Custom", "Options", "NPC" }) do
        rebuildTabPanel(n)
    end
    -- v0.60.2: the Extra tab is not rebuilt here (its Mods loop must not respawn),
    -- but its module checkboxes just lost their watchers in the wipe above. Let the
    -- anticheat panel re-subscribe + resync its checkboxes to the live state.
    if Shared and Shared._acResync then pcall(Shared._acResync) end
    -- v0.67.0: same staleness class one window over. The player list is never
    -- rebuilt, so its Target Lock row re-syncs here (checkbox + keybind pill).
    if Shared and Shared._targetlockResync then pcall(Shared._targetlockResync) end
    -- v0.68.0: Extra is never rebuilt either. Same treatment for the HvH rows.
    if Shared and Shared._hvhResync then pcall(Shared._hvhResync) end
    -- v0.62.0: replay the window-switcher bar drop-in on a config switch, and
    -- re-sync each slot's on/off visual to the freshly loaded open-states.
    if Koffee.Windows and Koffee.Windows.playIntro then pcall(Koffee.Windows.playIntro) end
end

-- PANEL / CARD (grouped rounded container with optional title)
-- Matcha groups related controls in cards inside tab content.
-- Card auto-sizes vertically to fit its rows.
local function panel(parent, title)
    local card = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = Theme.Palette.Panel,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        ZIndex = 33,
        Parent = parent,
    }, {
        corner(Theme.Radius.XLarge),
        stroke(Theme.Palette.BorderSubtle),
        -- v0.0.48: subtle top-lit gradient for depth. A UIGradient on a plain Frame
        -- only tints THIS frame's own background fill (children render on top,
        -- untouched: unlike a CanvasGroup, which flattens + tints everything). The
        -- ramp is grayscale so it just darkens the card's lower half ~10%, giving each
        -- panel a soft light-from-above read instead of a flat slab.
        new("UIGradient", {
            Rotation = 90,
            Color = ColorSequence.new(
                Color3.fromRGB(255, 255, 255),
                Color3.fromRGB(226, 226, 226)),
        }),
        new("UIPadding", {
            PaddingTop    = UDim.new(0, 14),
            PaddingBottom = UDim.new(0, 14),
            PaddingLeft   = UDim.new(0, 16),
            PaddingRight  = UDim.new(0, 16),
        }),
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            Padding = UDim.new(0, 6),   -- compact between toggles (per he)
            SortOrder = Enum.SortOrder.LayoutOrder,
        }),
    })
    if title then
        new("TextLabel", {
            Text = title,
            FontFace = Theme.Fonts.Medium,
            TextSize = Theme.Text.Header,
            TextColor3 = Theme.Palette.Text,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 18),
            TextXAlignment = Enum.TextXAlignment.Left,
            LayoutOrder = -1,
            ZIndex = 34,
            Parent = card,
        })
    end
    -- v0.0.98: every card enters with a short fade + grow when its tab first
    -- builds (rebuildConfigTabs re-runs build fns, so cards re-pop on reload too).
    -- GroupTransparency only exists on CanvasGroups, and cards stay plain Frames
    -- (their own UIGradient must not flatten children), so the entrance is a pure
    -- scale pop: same quick-arrive feel, zero alpha dependency.
    local sc = uScaleOf(card)
    sc.Scale = 0.96
    task.delay(0.03, function()
        if not card.Parent then return end
        tween(sc, Theme.Animation.Normal, { Scale = 1 })
    end)
    return card
end

-- HOVER helper: adds a subtle background overlay that fades in/out
-- when the target's TextButton child is hovered. Idempotent per row.
local function attachHover(row, hoverBtn)
    local bg = new("Frame", {
        Name = "HoverBg",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 0),
        Size = UDim2.new(1, 8, 1, 4),
        BackgroundColor3 = Theme.Palette.PanelElevated,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 33,
        Parent = row,
    }, { corner(4) })
    hoverBtn.MouseEnter:Connect(function()
        -- v0.48.0: hover flag is read live so the Options toggle takes effect
        -- without a rebuild; off means snap straight to the resting state.
        if Koffee.Anim and Koffee.Anim.spot("AnimHover") then
            tween(bg, Theme.Animation.Fast, { BackgroundTransparency = 0.85 })
        else
            bg.BackgroundTransparency = 0.85
        end
    end)
    hoverBtn.MouseLeave:Connect(function()
        if Koffee.Anim and Koffee.Anim.spot("AnimHover") then
            tween(bg, Theme.Animation.Fast, { BackgroundTransparency = 1 })
        else
            bg.BackgroundTransparency = 1
        end
    end)
end

-- v0.48.0: button background hover: the pill behind a button eases in on
-- enter and back out on leave. Text-only hover was the gap; this closes it.
-- A Koffee field, not a chunk local (register ceiling: see Anim above).
function Koffee.attachBtnHover(b, hovered, resting)
    hovered = hovered == nil and 0 or hovered
    resting = resting == nil and 0.2 or resting
    b.MouseEnter:Connect(function()
        if Koffee.Anim and Koffee.Anim.spot("AnimHover") then
            tween(b, Theme.Animation.Fast, { BackgroundTransparency = hovered })
        else
            b.BackgroundTransparency = hovered
        end
    end)
    b.MouseLeave:Connect(function()
        if Koffee.Anim and Koffee.Anim.spot("AnimHover") then
            tween(b, Theme.Animation.Fast, { BackgroundTransparency = resting })
        else
            b.BackgroundTransparency = resting
        end
    end)
end

-- CHECKBOX (visual primitive shared by module + config variants)
-- v0.0.12 semantics per he:
--   OFF -> ON  = fill GROWS OUTWARD from middle (size 0 -> INNER, opaque throughout)
--   ON  -> OFF = fill SHRINKS INWARD to middle (size INNER -> 0) with a super-fast
--                fade tail so it doesn't pop out of existence
-- Also cancels any in-flight tweens on each state change so rapid clicking can't
-- stack animations and desync the visual from the actual state.
local CBOX = { h = 22, outer = 16, inner = 12, off = 26, reserve = 74 }

local function checkboxVisual(parent, label, initialOn)
    local state = initialOn and true or false
    local row = new("Frame", {
        Size = UDim2.new(1, 0, 0, CBOX.h),
        BackgroundTransparency = 1,
        ZIndex = 34,
        Parent = parent,
    })
    -- outer box: subtle panel-elevated bg, no stroke
    local box = new("Frame", {
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 0, 0.5, 0),
        Size = UDim2.new(0, CBOX.outer, 0, CBOX.outer),
        BackgroundColor3 = Theme.Palette.PanelElevated,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        ZIndex = 35,
        Parent = row,
    }, { corner(4) })
    -- inner fill: anchored at box center so size 0 -> INNER grows outward evenly.
    -- Off state = size 0 + transparency 1. On state = size INNER + transparency 0.
    local innerFill = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 0),
        Size = state and UDim2.new(0, CBOX.inner, 0, CBOX.inner)
                     or UDim2.new(0, 0, 0, 0),
        BackgroundColor3 = Theme.Palette.Accent,
        BackgroundTransparency = state and 0 or 1,
        BorderSizePixel = 0,
        ZIndex = 36,
        Parent = box,
    }, { corner(3) })
    local lbl = new("TextLabel", {
        Text = label,
        FontFace = Theme.Fonts.Medium,
        TextSize = Theme.Text.Body,
        TextColor3 = state and Theme.Palette.Accent or Theme.Palette.Text,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, CBOX.off, 0, 0),
        Size = UDim2.new(1, -CBOX.off - CBOX.reserve, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Center,
        ZIndex = 35,
        Parent = row,
    })
    local btn = new("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, -CBOX.reserve, 1, 0),
        ZIndex = 37,
        AutoButtonColor = false,
        Parent = row,
    })
    attachHover(row, btn)
    popFx(btn)   -- v0.0.98: checkbox rows squash on press

    local CB_GROW   = TweenInfo.new(0.16, Enum.EasingStyle.Quart,  Enum.EasingDirection.Out)
    local CB_SHRINK = TweenInfo.new(0.12, Enum.EasingStyle.Quart,  Enum.EasingDirection.Out)
    local CB_FADE   = TweenInfo.new(0.05, Enum.EasingStyle.Linear, Enum.EasingDirection.Out)

    local activeSize, activeFade
    local seq = 0
    local function applyState()
        seq = seq + 1
        local mySeq = seq
        -- kill anything in flight so rapid clicks don't fight each other
        if activeSize then activeSize:Cancel(); activeSize = nil end
        if activeFade then activeFade:Cancel(); activeFade = nil end
        -- v0.48.0: Toggles off snaps the fill + label straight to rest.
        local togAnim = Koffee.Anim.spot("AnimToggles")
        if state then
            -- OFF -> ON: grow OUTWARD from center. Snap to 0 first (in case a
            -- prior tween was mid-shrink) and pop opacity to opaque immediately
            -- so the growth reads as substance appearing, not a fade-in.
            if togAnim then
                innerFill.Size = UDim2.new(0, 0, 0, 0)
                innerFill.BackgroundTransparency = 0
                activeSize = tween(innerFill, CB_GROW, {
                    Size = UDim2.new(0, CBOX.inner, 0, CBOX.inner),
                })
                pulse(box, 1.12)   -- v0.0.98: box ticks out as the fill grows in
            else
                innerFill.Size = UDim2.new(0, CBOX.inner, 0, CBOX.inner)
                innerFill.BackgroundTransparency = 0
            end
        else
            -- ON -> OFF: shrink INWARD to center, then super-fast fade to hide.
            -- Ensure opacity is opaque going in (guards against superseded fade).
            if togAnim then
                innerFill.BackgroundTransparency = 0
                activeSize = tween(innerFill, CB_SHRINK, {
                    Size = UDim2.new(0, 0, 0, 0),
                })
                task.delay(Koffee.Anim.wait(0.10), function()
                    if mySeq ~= seq then return end   -- superseded by newer click
                    activeFade = tween(innerFill, CB_FADE, { BackgroundTransparency = 1 })
                end)
            else
                innerFill.Size = UDim2.new(0, 0, 0, 0)
                innerFill.BackgroundTransparency = 1
            end
        end
        if togAnim then
            tween(lbl, Theme.Animation.Fast, {
                TextColor3 = state and Theme.Palette.Accent or Theme.Palette.Text,
            })
        else
            lbl.TextColor3 = state and Theme.Palette.Accent or Theme.Palette.Text
        end
    end
    return {
        row = row,
        button = btn,
        setState = function(newState)
            local nb = newState and true or false
            if nb == state then return end   -- no-op guard against redundant sets
            state = nb
            applyState()
        end,
        getState = function() return state end,
    }
end

local function moduleCheckbox(parent, label, moduleId)
    local mod = Modules[moduleId]
    local ctrl = checkboxVisual(parent, label, mod and mod.Enabled or false)
    ctrl.button.MouseButton1Click:Connect(function()
        toggleModule(moduleId)
        -- state sync is handled by the watcher below: covers keybind toggles too
    end)
    -- v0.0.13: subscribe so keybind toggles (or any other toggleModule caller)
    -- keep the visual in lockstep with the actual module state
    subscribeModule(moduleId, function(newState)
        ctrl.setState(newState)
    end)
    return ctrl
end

local function configCheckbox(parent, label, initialOn, onChange)
    local ctrl = checkboxVisual(parent, label, initialOn)
    ctrl.button.MouseButton1Click:Connect(function()
        local newState = not ctrl.getState()
        ctrl.setState(newState)
        if onChange then onChange(newState) end
    end)
    return ctrl
end

-- KEYBIND SYSTEM + KEYBIND PILL
-- Keybinds table maps moduleId -> KeyCode. InputBegan at bottom of file
-- reads it. Pill widget shows current key + click-to-rebind flow.
local Keybinds = {}     -- moduleId -> Enum.KeyCode
local pendingRebind = nil    -- { moduleId, pill } while waiting for next key

local function keybindPill(row, moduleId, initialKey, label)
    -- v0.66.0: register this bindable feature (id + friendly label) so the Keybinds
    -- window can enumerate every hotkey. Ordered list lives on Koffee (a field, not a
    -- new main-chunk local, since the chunk is at the 200-register ceiling).
    Koffee._keybinds = Koffee._keybinds or {}
    Koffee._keybindSeen = Koffee._keybindSeen or {}
    -- label priority: explicit arg -> the module's own DisplayName -> the raw id.
    local lbl = label or (Modules[moduleId] and Modules[moduleId].DisplayName) or moduleId
    if not Koffee._keybindSeen[moduleId] then
        Koffee._keybindSeen[moduleId] = true
        Koffee._keybinds[#Koffee._keybinds + 1] = { id = moduleId, label = lbl }
    elseif lbl ~= moduleId then
        for _, e in ipairs(Koffee._keybinds) do if e.id == moduleId then e.label = lbl end end
    end
    -- v0.0.34: only seed the default when nothing is bound yet, so a config load
    -- (or a tab rebuild) never clobbers the user's chosen / loaded keybind.
    if initialKey and Keybinds[moduleId] == nil then Keybinds[moduleId] = initialKey end
    local currentKey = Keybinds[moduleId]
    local pill = new("TextButton", {
        Name = "KeybindPill",
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, 0, 0.5, 0),
        Size = UDim2.new(0, 34, 0, 15),
        AutomaticSize = Enum.AutomaticSize.X,   -- v0.0.17: grow for long key names
        BackgroundColor3 = Theme.Palette.PanelElevated,
        BackgroundTransparency = 0.2,
        BorderSizePixel = 0,
        AutoButtonColor = false,
            Text = keyLabel(currentKey) or "No Keybind",
        FontFace = Theme.Fonts.Mono,
        TextSize = Theme.Text.Tiny,
        TextColor3 = Theme.Palette.TextMuted,
        ZIndex = 38,
        Parent = row,
    }, {
        pillCorner(),
        stroke(Theme.Palette.BorderSubtle),
        -- v0.0.17: pad so AutomaticSize.X doesn't glue text to the edges
        new("UIPadding", {
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 8),
        }),
    })
    pill.MouseEnter:Connect(function()
        tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
    end)
    pill.MouseLeave:Connect(function()
        if not (pendingRebind and pendingRebind.moduleId == moduleId) then
            tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
        end
    end)
    pill.MouseButton1Click:Connect(function()
        -- v0.0.17: restore any previously-pending pill before switching rebind
        -- target. Without this, clicking pill A then pill B leaves pill A
        -- stuck showing "..." forever.
        if pendingRebind and pendingRebind.pill ~= pill then
            pendingRebind.pill.Text = keyLabel(Keybinds[pendingRebind.moduleId]) or "No Keybind"
            tween(pendingRebind.pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
        end
        pill.Text = "..."
        tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Accent })
        pulse(pill, 1.1)   -- v0.0.98: pill ticks when the rebind arms
        pendingRebind = { moduleId = moduleId, pill = pill }
    end)
    popFx(pill)
    return pill
end

-- called from InputBegan when a rebind is pending
local function completeRebind(keyCode)
    if not pendingRebind then return end
    local moduleId = pendingRebind.moduleId
    local pill = pendingRebind.pill
    Keybinds[moduleId] = keyCode
    pill.Text = keyLabel(keyCode) or "?"
    -- growing pulse animation
    local origSize = pill.Size
    pill.Size = UDim2.new(0, origSize.X.Offset + 8, 0, origSize.Y.Offset + 4)
    tween(pill, Theme.Animation.Normal, { Size = origSize, TextColor3 = Theme.Palette.TextMuted })
    pendingRebind = nil
end

-- COLOR PICKER (popup: SV area + hue slider + hex input)
-- Parented to `screen` so it renders above the window CanvasGroup.
-- Reused across all color swatches: one picker instance, retargeted.
-- v0.58.0: the whole section is an IIFE so its internal helpers (parseHex,
-- ColorPicker, makeRainbowSequence, buildColorPicker, openColorPicker) do NOT
-- consume main-chunk registers -- the main function is at the 200 local ceiling
-- and the executor compiles UNOPTIMIZED (O0), where every named local counts.
-- colorSwatch + closeColorPicker + the ColorPicker state (all touched by other
-- sections, e.g. the outside-click handler) are published as chunk upvalues.
local colorSwatch, closeColorPicker, ColorPicker
;(function()
local function parseHex(str)
    if not str then return nil end
    str = str:gsub("#", ""):gsub("%s", "")
    if #str ~= 6 then return nil end
    local r = tonumber(str:sub(1, 2), 16)
    local g = tonumber(str:sub(3, 4), 16)
    local b = tonumber(str:sub(5, 6), 16)
    if not (r and g and b) then return nil end
    return Color3.fromRGB(r, g, b)
end

ColorPicker = { root = nil, activeSwatch = nil, callback = nil, h = 0, s = 0, v = 0,
    a = 1, alphaEnabled = false, onAlpha = nil }

local function makeRainbowSequence()
    -- 7 stops around the hue wheel
    return ColorSequence.new({
        ColorSequenceKeypoint.new(0.000, Color3.fromHSV(0.000, 1, 1)),
        ColorSequenceKeypoint.new(0.166, Color3.fromHSV(0.166, 1, 1)),
        ColorSequenceKeypoint.new(0.333, Color3.fromHSV(0.333, 1, 1)),
        ColorSequenceKeypoint.new(0.500, Color3.fromHSV(0.500, 1, 1)),
        ColorSequenceKeypoint.new(0.666, Color3.fromHSV(0.666, 1, 1)),
        ColorSequenceKeypoint.new(0.833, Color3.fromHSV(0.833, 1, 1)),
        ColorSequenceKeypoint.new(1.000, Color3.fromHSV(1.000, 1, 1)),
    })
end

-- v0.58.0: full redesign. Vertical stack -- SV square, a HORIZONTAL hue slider, a
-- HORIZONTAL alpha slider over a checkerboard, and a bottom row (format selector +
-- value box + alpha %). Same singleton + open/close API; only the layout changed.
local function buildColorPicker()
    local function rnd(x) return math.floor(x + 0.5) end
    -- v0.61.1: bigger for easier editing. W = width, SV_H = square, sliders taller.
    local W, SV_H, ROW_H, TRACK_H, HANDLE = 300, 176, 18, 14, 18
    local root = new("Frame", {
        Name = "ColorPicker",
        Size = UDim2.new(0, W, 0, 300),
        BackgroundColor3 = Theme.Palette.Panel,
        BackgroundTransparency = 0.02,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 250,
        Parent = popupScreen,
    }, {
        corner(12),
        stroke(Theme.Palette.Border, 1),
        new("UIPadding", {
            PaddingTop = UDim.new(0, 12), PaddingBottom = UDim.new(0, 12),
            PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
        }),
    })

    -- SV square (full width). Hue background, white left->right, black top->bottom.
    local svArea = new("Frame", {
        Position = UDim2.new(0, 0, 0, 0),
        Size = UDim2.new(1, 0, 0, SV_H),
        BackgroundColor3 = Color3.fromHSV(0, 1, 1),
        BorderSizePixel = 0, ZIndex = 251, Parent = root,
    }, { corner(10) })
    new("Frame", {
        Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 0, ZIndex = 252, Parent = svArea,
    }, { corner(10), new("UIGradient", { Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }) }) })
    new("Frame", {
        Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0),
        BorderSizePixel = 0, ZIndex = 253, Parent = svArea,
    }, { corner(10), new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }) })
    -- v0.61.0: cursor is a smooth circle FILLED with the live colour (preview in the
    -- middle) + a clean white ring. Not clipped, so it reads at the very edges.
    local svCursor = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 0, 1, 0),
        Size = UDim2.new(0, 18, 0, 18), BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 0, ZIndex = 254, Parent = svArea,
    }, { pillCorner(), stroke(Color3.new(1, 1, 1), 2) })

    -- v0.61.0: horizontal slider builder. A clipped rounded TRACK (visual) plus a
    -- circular HANDLE that lives on the row (NOT the track), so it can overhang and
    -- "magnify" the colour in its middle without the track's clip cutting it.
    local function makeSlider(y, buildTrack)
        local row = new("Frame", {
            Position = UDim2.new(0, 0, 0, y), Size = UDim2.new(1, 0, 0, ROW_H),
            BackgroundTransparency = 1, ZIndex = 251, Parent = root,
        })
        local track = new("Frame", {
            AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
            Size = UDim2.new(1, 0, 0, TRACK_H), BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 251, Parent = row,
        }, { corner(TRACK_H / 2) })
        buildTrack(track)
        local handle = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
            Size = UDim2.new(0, HANDLE, 0, HANDLE), BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0, ZIndex = 254, Parent = row,
        }, { pillCorner(), stroke(Color3.new(1, 1, 1), 2) })
        return row, handle
    end

    local hueRow, hueHandle = makeSlider(SV_H + 12, function(track)
        new("UIGradient", { Color = makeRainbowSequence(), Parent = track })
    end)

    local alphaFill
    local alphaRow, alphaHandle = makeSlider(SV_H + 12 + ROW_H + 8, function(track)
        -- v0.61.1: checkerboard on a ROUND track. ClipsDescendants clips the cells to
        -- the track's UICorner, so the bar is perfectly rounded (no square-corner
        -- "cutout"); alphaFill also carries the same corner as a belt-and-braces round.
        local CH_COLS = 30
        for i = 0, CH_COLS * 2 - 1 do
            local col, rowi = i % CH_COLS, math.floor(i / CH_COLS)
            if (col + rowi) % 2 == 1 then
                new("Frame", {
                    Position = UDim2.new(col / CH_COLS, 0, rowi / 2, 0),
                    Size = UDim2.new(1 / CH_COLS, 1, 0.5, 0),
                    BackgroundColor3 = Color3.fromRGB(150, 150, 150), BorderSizePixel = 0,
                    ZIndex = 251, Parent = track,
                })
            end
        end
        alphaFill = new("Frame", {
            Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0, ZIndex = 252, Parent = track,
        }, { corner(TRACK_H / 2), new("UIGradient", { Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }) })
    end)

    -- bottom row: format DROPDOWN (arrow left) + colour chip + value box + alpha %
    local bottomRow = new("Frame", {
        Position = UDim2.new(0, 0, 0, 240), Size = UDim2.new(1, 0, 0, 30),
        BackgroundTransparency = 1, ZIndex = 251, Parent = root,
    })
    local FORMATS = { "HEX", "RGB", "HSV" }
    local fmtIdx = 1
    local fmtBtn = new("TextButton", {
        Text = "", AutoButtonColor = true, BackgroundColor3 = Theme.Palette.PanelElevated,
        BackgroundTransparency = 0.2, BorderSizePixel = 0,
        Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(0, 64, 1, 0), ZIndex = 252, Parent = bottomRow,
    }, { corner(7), stroke(Theme.Palette.BorderSubtle) })
    local caret = Koffee.lucideIcon(fmtBtn, "chevron-down", 12, Theme.Palette.TextMuted, 253)
    caret.AnchorPoint = Vector2.new(0, 0.5); caret.Position = UDim2.new(0, 9, 0.5, 0)
    local fmtLbl = new("TextLabel", {
        Text = "HEX", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
        BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 26, 0, 0), Size = UDim2.new(1, -30, 1, 0), ZIndex = 253, Parent = fmtBtn,
    })
    -- v0.61.1: dropdown menu is a CanvasGroup so it can fade + pop open (animated).
    local fmtMenu = new("CanvasGroup", {
        Visible = false, GroupTransparency = 1, BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.02,
        BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0),
        Position = UDim2.new(0, 0, 1, 6), Size = UDim2.new(0, 64, 0, #FORMATS * 26 + 8), ZIndex = 262, Parent = fmtBtn,
    }, { corner(7), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4),
            PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4) }),
        new("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }) })
    local fmtScale = new("UIScale", { Scale = 1, Parent = fmtMenu })
    local menuOpen = false
    local function closeFmtMenu()
        if not menuOpen then return end
        menuOpen = false
        tween(fmtMenu, Theme.Animation.Fast, { GroupTransparency = 1 })
        tween(fmtScale, Theme.Animation.Fast, { Scale = 0.9 })
        task.delay(Koffee.Anim.wait(0.14), function() if not menuOpen then fmtMenu.Visible = false end end)
    end
    local function openFmtMenu()
        menuOpen = true
        fmtMenu.Visible = true
        fmtMenu.GroupTransparency = 1
        fmtScale.Scale = 0.9
        tween(fmtMenu, Theme.Animation.Fast, { GroupTransparency = 0 })
        tween(fmtScale, Theme.Animation.Fast, { Scale = 1 })
    end
    local chip = new("Frame", {
        AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 72, 0.5, 0),
        Size = UDim2.new(0, 20, 0, 20), BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 0, ZIndex = 252, Parent = bottomRow,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
    chip:SetAttribute("KUserColor", true)
    local valueBox = new("TextBox", {
        Text = "#FFFFFF", ClearTextOnFocus = false, FontFace = Theme.Fonts.Mono,
        TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2, BorderSizePixel = 0,
        Position = UDim2.new(0, 100, 0, 0), Size = UDim2.new(1, -100, 1, 0), ZIndex = 252, Parent = bottomRow,
    }, { corner(7), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }) })
    local pctBox = new("TextBox", {
        Text = "100%", ClearTextOnFocus = false, FontFace = Theme.Fonts.Mono,
        TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text, TextXAlignment = Enum.TextXAlignment.Center,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2, BorderSizePixel = 0,
        AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.new(0, 50, 1, 0),
        Visible = false, ZIndex = 252, Parent = bottomRow,
    }, { corner(7), stroke(Theme.Palette.BorderSubtle) })

    -- format the current colour/alpha for the value box
    local function fmtValue(c)
        if fmtIdx == 2 then
            return string.format("%d, %d, %d", rnd(c.R * 255), rnd(c.G * 255), rnd(c.B * 255))
        elseif fmtIdx == 3 then
            local h, s, v = c:ToHSV()
            return string.format("%d, %d, %d", rnd(h * 360), rnd(s * 100), rnd(v * 100))
        end
        local hex = colorToHex(c)
        if ColorPicker.alphaEnabled then hex = hex .. string.format("%02X", rnd(ColorPicker.a * 255)) end
        return hex
    end
    local function parseValue(text)
        if fmtIdx == 2 then
            local r, g, b = text:match("(%d+)%D+(%d+)%D+(%d+)")
            if r then return Color3.fromRGB(math.clamp(r, 0, 255), math.clamp(g, 0, 255), math.clamp(b, 0, 255)) end
        elseif fmtIdx == 3 then
            local h, s, v = text:match("(%d+)%D+(%d+)%D+(%d+)")
            if h then return Color3.fromHSV(math.clamp(h, 0, 360) / 360, math.clamp(s, 0, 100) / 100, math.clamp(v, 0, 100) / 100) end
        else
            local hx = text:gsub("#", ""):gsub("%s", "")
            if #hx == 8 then
                local c = parseHex("#" .. hx:sub(1, 6))
                local a = tonumber(hx:sub(7, 8), 16)
                if c and a then ColorPicker.a = a / 255 end
                return c
            end
            return parseHex(text)
        end
        return nil
    end

    local function applyToUI()
        svArea.BackgroundColor3 = Color3.fromHSV(ColorPicker.h, 1, 1)
        local c = Color3.fromHSV(ColorPicker.h, ColorPicker.s, ColorPicker.v)
        -- SV cursor: sits on the point, filled with the live colour (preview inside)
        svCursor.Position = UDim2.new(ColorPicker.s, 0, 1 - ColorPicker.v, 0)
        svCursor.BackgroundColor3 = c
        svCursor.BackgroundTransparency = 0
        -- hue handle: the PURE hue at the slider position (vivid, matches the rainbow
        -- directly under it), not the desaturated selected colour.
        hueHandle.Position = UDim2.new(ColorPicker.h, 0, 0.5, 0)
        hueHandle.BackgroundColor3 = Color3.fromHSV(ColorPicker.h, 1, 1)
        hueHandle.BackgroundTransparency = 0
        -- alpha handle: filled with the colour AT the current alpha, so the dot itself
        -- shows the transparency (see-through at low alpha); ring stays solid white.
        alphaHandle.Position = UDim2.new(ColorPicker.a, 0, 0.5, 0)
        alphaHandle.BackgroundColor3 = c
        alphaHandle.BackgroundTransparency = 1 - ColorPicker.a
        chip.BackgroundColor3 = c
        alphaFill.BackgroundColor3 = c
        if not valueBox:IsFocused() then valueBox.Text = fmtValue(c) end
        if not pctBox:IsFocused() then pctBox.Text = rnd(ColorPicker.a * 100) .. "%" end
        if ColorPicker.alphaEnabled and ColorPicker.onAlpha then ColorPicker.onAlpha(ColorPicker.a) end
        if ColorPicker.callback then ColorPicker.callback(c) end
    end

    -- generic horizontal-drag binder (fraction 0..1 along X -> setter)
    local function bindDrag(area, setter)
        local dragging = false
        local function pull(input)
            local abs, siz = area.AbsolutePosition, area.AbsoluteSize
            setter(math.clamp((input.Position.X - abs.X) / math.max(siz.X, 1), 0, 1))
            applyToUI()
        end
        area.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true; closeFmtMenu(); pull(input)
            end
        end)
        area.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
        end)
        return function() return dragging end, pull
    end
    -- SV needs both axes, so it is bound directly
    local svDragging = false
    local function svPull(input)
        local abs, siz = svArea.AbsolutePosition, svArea.AbsoluteSize
        ColorPicker.s = math.clamp((input.Position.X - abs.X) / math.max(siz.X, 1), 0, 1)
        ColorPicker.v = 1 - math.clamp((input.Position.Y - abs.Y) / math.max(siz.Y, 1), 0, 1)
        applyToUI()
    end
    svArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            svDragging = true; closeFmtMenu(); svPull(input)
        end
    end)
    svArea.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then svDragging = false end
    end)
    local hueDrag, huePull = bindDrag(hueRow, function(f) ColorPicker.h = f end)
    local alphaDrag, alphaPull = bindDrag(alphaRow, function(f) ColorPicker.a = f end)
    UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        if svDragging then svPull(input) end
        if hueDrag() then huePull(input) end
        if alphaDrag() then alphaPull(input) end
    end)

    -- format dropdown: click animates the menu open; picking an option sets the format.
    fmtBtn.MouseButton1Click:Connect(function()
        if menuOpen then closeFmtMenu() else openFmtMenu() end
    end)
    for i, f in ipairs(FORMATS) do
        local opt = new("TextButton", {
            Text = f, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = (i == fmtIdx) and Theme.Palette.Accent or Theme.Palette.Text,
            BackgroundColor3 = Theme.Palette.Pill, BackgroundTransparency = 0.4, AutoButtonColor = true,
            Size = UDim2.new(1, 0, 0, 24), LayoutOrder = i, ZIndex = 263, Parent = fmtMenu,
        }, { corner(6) })
        opt.MouseButton1Click:Connect(function()
            fmtIdx = i
            fmtLbl.Text = f
            for _, o in ipairs(fmtMenu:GetChildren()) do
                if o:IsA("TextButton") then o.TextColor3 = (o.Text == f) and Theme.Palette.Accent or Theme.Palette.Text end
            end
            closeFmtMenu()
            applyToUI()
        end)
    end
    valueBox.FocusLost:Connect(function()
        local c = parseValue(valueBox.Text)
        if c then
            ColorPicker.h, ColorPicker.s, ColorPicker.v = c:ToHSV()
        end
        applyToUI()
    end)
    pctBox.FocusLost:Connect(function()
        local n = tonumber((pctBox.Text:gsub("%%", "")))
        if n then ColorPicker.a = math.clamp(n, 0, 100) / 100 end
        applyToUI()
    end)

    ColorPicker.root = root
    ColorPicker.apply = applyToUI
    ColorPicker.svArea = svArea
    ColorPicker.hueSlider = hueRow
    ColorPicker.alphaBar = alphaRow
    ColorPicker.bottomRow = bottomRow
    ColorPicker.pctBox = pctBox
    -- reflow for alpha: show/hide the alpha slider + %, shift the bottom row, resize.
    ColorPicker.reflow = function(alphaOn)
        closeFmtMenu()
        alphaRow.Visible = alphaOn
        pctBox.Visible = alphaOn
        valueBox.Size = UDim2.new(1, alphaOn and -100 - 56 or -100, 1, 0)
        bottomRow.Position = UDim2.new(0, 0, 0, alphaOn and 240 or 214)
        root.Size = UDim2.new(0, W, 0, alphaOn and 294 or 268)
    end
    return root
end

local function openColorPicker(swatchInstance, initialColor, onChange, opts)
    if not ColorPicker.root then buildColorPicker() end
    -- v0.0.16: cancel any pending close from a prior closeColorPicker call.
    -- Without this, the task.delay(0.22) from close fires AFTER open and
    -- hides the now-visible picker.
    if ColorPicker.closeTask then
        pcall(task.cancel, ColorPicker.closeTask)
        ColorPicker.closeTask = nil
    end
    opts = opts or {}
    ColorPicker.activeSwatch = swatchInstance
    ColorPicker.callback = onChange
    -- v0.0.31: alpha mode (fills). v0.58.0: reflow shows/hides the alpha slider + %.
    ColorPicker.alphaEnabled = opts.alpha == true
    ColorPicker.a = opts.initialAlpha or 1
    ColorPicker.onAlpha = opts.onAlpha
    ColorPicker.reflow(ColorPicker.alphaEnabled)
    local h, s, v = initialColor:ToHSV()
    ColorPicker.h, ColorPicker.s, ColorPicker.v = h, s, v
    -- position near swatch (below + right, but clamp to viewport)
    local abs = swatchInstance.AbsolutePosition
    local siz = swatchInstance.AbsoluteSize
    local vp = Workspace.CurrentCamera.ViewportSize
    local pickerW, pickerH = 300, (ColorPicker.alphaEnabled and 294 or 268)
    local dx = math.min(abs.X, vp.X - pickerW - 8)
    local dy = math.min(abs.Y + siz.Y + 6, vp.Y - pickerH - 8)
    -- convert screen-space target -> popup Position offset (inset-safe).
    local x, y = popupOffsetFor(ColorPicker.root, dx, dy)
    ColorPicker.root.Position = UDim2.new(0, x, 0, y - 4)
    ColorPicker.root.Visible = true
    -- v0.48.0: picker open honours Popups; off shows at rest instantly.
    if Koffee.Anim.spot("AnimPopups") then
        ColorPicker.root.BackgroundTransparency = 1
        local rsc = uScaleOf(ColorPicker.root)   -- v0.0.98: picker grows open
        rsc.Scale = 0.94
        tween(ColorPicker.root, Theme.Animation.Menu, {
            BackgroundTransparency = 0.02,
            Position = UDim2.new(0, x, 0, y),
        })
        tween(rsc, Theme.Animation.Menu, { Scale = 1 })
    else
        ColorPicker.root.BackgroundTransparency = 0.02
        ColorPicker.root.Position = UDim2.new(0, x, 0, y)
        local rsc = uScaleOf(ColorPicker.root)
        rsc.Scale = 1
    end
    ColorPicker.apply()
end

function closeColorPicker()
    if not ColorPicker.root or not ColorPicker.root.Visible then return end
    -- v0.0.16: track the close thread so openColorPicker can cancel it if
    -- the picker is reopened before the fade completes.
    if ColorPicker.closeTask then
        pcall(task.cancel, ColorPicker.closeTask)
    end
    -- v0.48.0: Popups off hides instantly instead of fading out.
    if Koffee.Anim.spot("AnimPopups") then
        tween(ColorPicker.root, Theme.Animation.Menu, {
            BackgroundTransparency = 1,
        })
        ColorPicker.closeTask = task.delay(Koffee.Anim.wait(0.22), function()
            ColorPicker.closeTask = nil
            if ColorPicker.root then ColorPicker.root.Visible = false end
        end)
    else
        ColorPicker.root.BackgroundTransparency = 1
        ColorPicker.root.Visible = false
        ColorPicker.closeTask = nil
    end
    ColorPicker.activeSwatch = nil
    ColorPicker.callback = nil
end

-- COLOR SWATCH: clickable, opens picker; also hover-shows a tooltip preview
-- Optional { onChange = fn(newColor), getColor = fn() -> Color3 } table.
function colorSwatch(parent, initialColor, size, opts)
    opts = opts or {}
    size = size or 14
    local currentColor = initialColor
    local sw = new("TextButton", {
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.new(0, size, 0, size),
        BackgroundColor3 = currentColor,
        BorderSizePixel = 0,
        ZIndex = 38,
        Parent = parent,
    }, { corner(3), stroke(Theme.Palette.Border, 1) })
    -- v0.11.2: this square shows the USER'S colour, not a theme role. Marked so the
    -- Options colour sweep skips it: repainting it desynced the preview from the
    -- value behind it whenever a feature colour happened to equal a palette colour.
    sw:SetAttribute("KUserColor", true)
    popFx(sw)   -- v0.0.98: swatches squash on press

    -- v0.0.17: tooltip parented to popupScreen (not the swatch) so it
    -- escapes the window CanvasGroup's clip bounds. Positioned live on
    -- every hover from the swatch's AbsolutePosition.
    local TIP_W, TIP_H = 132, 34
    local tip = new("Frame", {
        Name = "Tooltip",
        Size = UDim2.new(0, TIP_W, 0, TIP_H),
        BackgroundColor3 = Theme.Palette.Panel,
        BackgroundTransparency = 0.05,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 100,
        Parent = popupScreen,
    }, { corner(4), stroke(Theme.Palette.Border) })
    local chip = new("Frame", {
        Position = UDim2.new(0, 4, 0, 4),
        Size = UDim2.new(0, 26, 1, -8),
        BackgroundColor3 = currentColor,
        BorderSizePixel = 0,
        ZIndex = 101,
        Parent = tip,
    }, { corner(3) })
    chip:SetAttribute("KUserColor", true)   -- v0.11.2: user data, not chrome
    local hexLbl = new("TextLabel", {
        Text = colorToHex(currentColor),
        FontFace = Theme.Fonts.Bold,
        TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Text,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 36, 0, 4),
        Size = UDim2.new(1, -40, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 101,
        Parent = tip,
    })
    local rgbLbl = new("TextLabel", {
        Text = colorToRGB(currentColor),
        FontFace = Theme.Fonts.Mono,
        TextSize = Theme.Text.Tiny,
        TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 36, 0, 18),
        Size = UDim2.new(1, -40, 0, 12),
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 101,
        Parent = tip,
    })

    local function refreshUI()
        sw.BackgroundColor3 = currentColor
        chip.BackgroundColor3 = currentColor
        hexLbl.Text = colorToHex(currentColor)
        rgbLbl.Text = colorToRGB(currentColor)
    end

    sw.MouseEnter:Connect(function()
        local abs = sw.AbsolutePosition
        local siz = sw.AbsoluteSize
        local vp  = Workspace.CurrentCamera.ViewportSize
        local tipX = abs.X + siz.X * 0.5 - TIP_W * 0.5
        local tipY = abs.Y - TIP_H - 8
        tipX = math.clamp(tipX, 4, vp.X - TIP_W - 4)
        if tipY < 4 then tipY = abs.Y + siz.Y + 8 end
        local ox, oy = popupOffsetFor(tip, tipX, tipY)   -- inset-safe placement
        tip.Position = UDim2.new(0, ox, 0, oy)
        tip.Visible = true
    end)
    sw.MouseLeave:Connect(function() tip.Visible = false end)

    sw.MouseButton1Click:Connect(function()
        -- if picker already open on this swatch, close it
        if ColorPicker.activeSwatch == sw then
            closeColorPicker()
            return
        end
        openColorPicker(sw, currentColor, function(newColor)
            currentColor = newColor
            refreshUI()
            if opts.onChange then opts.onChange(newColor) end
        end, {
            alpha = opts.alpha,
            initialAlpha = opts.getAlpha and opts.getAlpha() or opts.initialAlpha,
            onAlpha = opts.onAlpha,
        })
    end)

    return {
        instance = sw,
        setColor = function(c)
            currentColor = c
            refreshUI()
        end,
        getColor = function() return currentColor end,
    }
end
end)()   -- end COLOR PICKER IIFE (v0.58.0)

-- DROPDOWN (label above + button that opens popup list below)
-- Popup is parented to `screen` (NOT the panel/window) so it renders
-- above the CanvasGroup and isn't clipped by it. Positioned each open
-- from the button's AbsolutePosition. Slide+fade animation. Lucide
-- chevron-down glyph (rotates 180 on open). Closes on outside click.
local openDropdowns = {}  -- popup frames -> close-fn

local function chevron(parent, sizePx)
    sizePx = sizePx or 8
    -- v0.47.0: lucide chevron-down glyph instead of two rotated 1px lines.
    -- Callers still rotate the root 180 to flip it; kept that contract.
    local root = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(1, -10, 0.5, 0),
        Size = UDim2.new(0, sizePx, 0, sizePx),
        BackgroundTransparency = 1,
        ZIndex = 37,
        Parent = parent,
    })
        local img = Koffee.lucideIcon(root, "chevron-down", sizePx, Theme.Palette.TextMuted, 38)
    if img then
        img.AnchorPoint = Vector2.new(0.5, 0.5)
        img.Position = UDim2.new(0.5, 0, 0.5, 0)
    end
    return root, img, img
end

local function dropdown(parent, label, options, initial, onChange)
    -- v0.10.0: never let a nil/absent option list take the whole tab down with it.
    -- An empty dropdown is a visible, reportable bug; a stack trace is a dead UI.
    options = options or {}
    local wrap = new("Frame", {
        Size = UDim2.new(1, 0, 0, 48),
        BackgroundTransparency = 1,
        ZIndex = 34,
        Parent = parent,
    })
    new("TextLabel", {
        Text = label,
        FontFace = Theme.Fonts.Regular,
        TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 0, 0, 0),
        Size = UDim2.new(1, 0, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 35,
        Parent = wrap,
    })
    local btn = new("TextButton", {
        Text = "",
        AutoButtonColor = false,
        Position = UDim2.new(0, 0, 0, 22),   -- extra gap between label and button (was 14)
        Size = UDim2.new(1, 0, 0, 26),
        BackgroundColor3 = Theme.Palette.PanelElevated,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        ZIndex = 35,
        Parent = wrap,
    }, { corner(4), stroke(Theme.Palette.BorderSubtle) })
    local valueLbl = new("TextLabel", {
        Text = initial or options[1] or "",
        FontFace = Theme.Fonts.Medium,
        TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Text,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 0, 0),
        Size = UDim2.new(1, -30, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 36,
        Parent = btn,
    })
    local caretRoot = chevron(btn, 10)

    -- popup lives in the dedicated popup ScreenGui, above everything: ZIndex 260
    -- so it clears the settings popup (210) AND the colour picker (250) when a
    -- dropdown is opened from inside one of them.
    -- v0.10.1: ScrollingFrame, not Frame. The sound catalog is 43 entries: at 26px
    -- a row that is a 1118px list, taller than most screens, and the tail was simply
    -- unreachable. Capped at LIST_MAX with the full height as CanvasSize.
    local LIST_MAX = 260
    local list = new("ScrollingFrame", {
        Size = UDim2.new(0, 100, 0, math.min(#options * 26, LIST_MAX)),
        CanvasSize = UDim2.new(0, 0, 0, #options * 26),
        ScrollBarThickness = 4,
        ScrollBarImageColor3 = Theme.Palette.TextFaint,
        ScrollingDirection = Enum.ScrollingDirection.Y,
        BackgroundColor3 = Theme.Palette.Panel,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 260,
        Parent = popupScreen,
    }, {
        corner(4),
        stroke(Theme.Palette.Border, 1),
    })

    local isOpen = false
    -- v0.0.12: RenderStepped lock keeps popup glued below the button even when it shifts
    -- (scroll, tab-switch, drag): calculate every frame, not once at open.
    local positionConn = nil
    -- v0.0.20: rule-based placement: anchor list TOP-LEFT to button bottom-left every
    -- frame, clamp X to viewport, flip above when no room below. All from live rect.
    local GAP = 6
    local function placeBelow()
        local abs = btn.AbsolutePosition
        local siz = btn.AbsoluteSize
        if siz.X <= 0 or siz.Y <= 0 then return end
        local vp = viewport()
        -- v0.10.1: the RENDERED height is capped; CanvasSize keeps the rest reachable.
        local listH = math.min(#options * 26, LIST_MAX)
        list.AnchorPoint = Vector2.new(0, 0)
        -- desired TOP-LEFT in the button's screen space.
        local desX = abs.X
        local desY = abs.Y + siz.Y + GAP
        -- flip above only if there is genuinely no room below.
        if vp.Y > 0 and desY + listH > vp.Y then
            local aboveY = abs.Y - listH - GAP
            if aboveY >= 0 then desY = aboveY end
        end
        if vp.X > 0 then
            desX = math.clamp(desX, 0, math.max(0, vp.X - siz.X))
        end
        -- convert the screen-space target into this popup's Position offset so it
        -- actually lands there (see popupOffsetFor: fixes the inset mismatch).
        local ox, oy = popupOffsetFor(list, desX, desY)
        list.Size = UDim2.new(0, siz.X, 0, listH)
        list.Position = UDim2.new(0, ox, 0, oy)
    end

    local function closeList(instant)
        if not isOpen then return end
        isOpen = false
        openDropdowns[list] = nil
        if positionConn then positionConn:Disconnect(); positionConn = nil end
        -- v0.48.0: dropdowns honour Animations > Popups; off (or forced
        -- instant, e.g. window close) hides immediately instead of fading.
        if instant or not Koffee.Anim.spot("AnimPopups") then
            caretRoot.Rotation = 0
            list.Visible = false
        else
            tween(caretRoot, Theme.Animation.Menu, { Rotation = 0 })
            tween(list, Theme.Animation.Menu, {
                BackgroundTransparency = 1,
            })
            task.delay(Koffee.Anim.wait(0.22), function()
                if not isOpen then list.Visible = false end
            end)
        end
        -- v0.0.17: option button bg stays at transparency 1 (hover drives it to 0.7).
        -- Only the text labels need to fade out.
        for _, child in ipairs(list:GetChildren()) do
            if child:IsA("TextButton") then
                for _, sub in ipairs(child:GetChildren()) do
                    if sub:IsA("TextLabel") then
                        if instant or not Koffee.Anim.spot("AnimPopups") then
                            sub.TextTransparency = 1
                        else
                            tween(sub, Theme.Animation.Menu, { TextTransparency = 1 })
                        end
                    end
                end
            end
        end
    end
    local function openList()
        if isOpen then return end
        for _, entry in pairs(openDropdowns) do
            if entry.close ~= closeList then entry.close(true) end
        end
        isOpen = true
        openDropdowns[list] = { btn = btn, close = closeList }
        placeBelow()
        list.Visible = true
        -- lock position while open: RenderStepped keeps `list` glued to btn
        if positionConn then positionConn:Disconnect() end
        positionConn = RunService.RenderStepped:Connect(function()
            if not isOpen or not btn.Parent then return end
            placeBelow()
        end)
        -- v0.48.0: options cascade in with a tiny per-row stagger (capped, so a
        -- 40-option list doesn't take all day). Off means everything just shows.
        local popAnim = Koffee.Anim.spot("AnimPopups")
        if popAnim then
            list.BackgroundTransparency = 1
            tween(list, Theme.Animation.Menu, {
                BackgroundTransparency = 0.05,
            })
            -- v0.0.98: popup drops open with a quick grow (scale from 0.92) instead
            -- of materialising: same Menu timing as the fade so they land together.
            local usc = uScaleOf(list)
            usc.Scale = 0.92
            tween(usc, Theme.Animation.Menu, { Scale = 1 })
            tween(caretRoot, Theme.Animation.Menu, { Rotation = 180 })
        else
            list.BackgroundTransparency = 0.05
            caretRoot.Rotation = 180
        end
        -- v0.0.17: only text labels fade in. Option button bg is always 1
        -- (invisible): hover drives it to 0.7.
        local stagger = 0
        for _, child in ipairs(list:GetChildren()) do
            if child:IsA("TextButton") then
                for _, sub in ipairs(child:GetChildren()) do
                    if sub:IsA("TextLabel") then
                        if popAnim then
                            sub.TextTransparency = 1
                            local d, target = math.min(stagger * 0.02, 0.3), sub
                            stagger = stagger + 1
                            task.delay(d, function()
                                if isOpen and target.Parent then
                                    tween(target, Theme.Animation.Menu, { TextTransparency = 0 })
                                end
                            end)
                        else
                            sub.TextTransparency = 0
                        end
                    end
                end
            end
        end
    end

    for i, opt in ipairs(options) do
        local optBtn = new("TextButton", {
            Text = "",
            AutoButtonColor = false,
            Size = UDim2.new(1, 0, 0, 26),
            Position = UDim2.new(0, 0, 0, (i - 1) * 26),
            BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 261,
            Parent = list,
        })
        new("TextLabel", {
            Text = opt,
            FontFace = Theme.Fonts.Medium,
            TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text,
            BackgroundTransparency = 1,
            TextTransparency = 1,
            Position = UDim2.new(0, 12, 0, 0),
            Size = UDim2.new(1, -20, 1, 0),
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 262,
            Parent = optBtn,
        })
        optBtn.MouseEnter:Connect(function()
            tween(optBtn, Theme.Animation.Fast, { BackgroundTransparency = 0.7 })
        end)
        optBtn.MouseLeave:Connect(function()
            tween(optBtn, Theme.Animation.Fast, { BackgroundTransparency = 1 })
        end)
        optBtn.MouseButton1Click:Connect(function()
            valueLbl.Text = opt
            pulse(valueLbl, 1.08)   -- v0.0.98: value ticks on pick
            closeList()
            if onChange then onChange(opt) end
        end)
    end

    btn.MouseButton1Click:Connect(function()
        if isOpen then closeList() else openList() end
    end)
    popFx(btn)   -- v0.0.98: dropdowns squash on press
    return {
        frame = wrap,
        button = btn,
        setValue = function(v) valueLbl.Text = v end,
        close = function() closeList(true) end,
        -- v0.0.47: full teardown: the popup `list` lives on popupScreen (not a
        -- child of wrap), so destroying the wrap alone leaks it. Callers that
        -- rebuild a dropdown (e.g. the config manager's live selector) use this.
        destroy = function() closeList(true); list:Destroy(); wrap:Destroy() end,
    }
end

-- outside-click closer: closes any open dropdown OR color picker if click missed
UserInputService.InputBegan:Connect(function(input, processed)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1
    and input.UserInputType ~= Enum.UserInputType.Touch then return end
    local mp = input.Position

    -- dropdowns. Skip the click that lands ON a list's own button: that click
    -- is handled by the button's own toggle handler, so the closer must not close
    -- first (otherwise: press closes on mouse-down via the closer, release
    -- reopens on the button's click: the flicker/reopen the closer caused).
    for list, entry in pairs(openDropdowns) do
        local abs = list.AbsolutePosition
        local siz = list.AbsoluteSize
        local inside = mp.X >= abs.X and mp.X <= abs.X + siz.X
                   and mp.Y >= abs.Y and mp.Y <= abs.Y + siz.Y
        local playsOwnToggle = false
        if entry.btn then
            local babs = entry.btn.AbsolutePosition
            local bsiz = entry.btn.AbsoluteSize
            playsOwnToggle = mp.X >= babs.X and mp.X <= babs.X + bsiz.X
                        and mp.Y >= babs.Y and mp.Y <= babs.Y + bsiz.Y
        end
        if not inside and not playsOwnToggle then entry.close() end
    end

    -- color picker (skip close if click is on its owning swatch)
    if ColorPicker.root and ColorPicker.root.Visible then
        local abs = ColorPicker.root.AbsolutePosition
        local siz = ColorPicker.root.AbsoluteSize
        local insidePicker = mp.X >= abs.X and mp.X <= abs.X + siz.X
                         and mp.Y >= abs.Y and mp.Y <= abs.Y + siz.Y
        local onSwatch = false
        if ColorPicker.activeSwatch then
            local sabs = ColorPicker.activeSwatch.AbsolutePosition
            local ssiz = ColorPicker.activeSwatch.AbsoluteSize
            onSwatch = mp.X >= sabs.X and mp.X <= sabs.X + ssiz.X
                   and mp.Y >= sabs.Y and mp.Y <= sabs.Y + ssiz.Y
        end
        if not insidePicker and not onSwatch then
            closeColorPicker()
        end
    end
end)

-- SLIDER (thicker track, bigger knob, knob color contrasts fill)
-- Value doubles as click-to-edit TextBox with a hover-pill background.
local function slider(parent, label, min, max, initial, precision, onChange, opts)
    precision = precision or 0
    opts = opts or {}   -- v0.0.56: opts.infinite -> value at max shows "Infinite", onChange gets math.huge
    local function round(v)
        local m = 10 ^ precision
        return math.floor(v * m + 0.5) / m
    end
    local current = round(math.clamp(initial, min, max))
    local row = new("Frame", {
        Size = UDim2.new(1, 0, 0, 44),                       -- v0.0.32: taller
        BackgroundTransparency = 1,
        ZIndex = 34,
        Parent = parent,
    })
    new("TextLabel", {
        Text = label,
        FontFace = Theme.Fonts.Medium,
        TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 0, 0, 0),
        Size = UDim2.new(1, -90, 0, 18),
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 35,
        Parent = row,
    })
    -- value = TextBox with pill-hover background (matcha spec)
    local valueBox = new("TextBox", {
        Text = (opts.infinite and current >= max) and "Infinite" or tostring(current),
        PlaceholderText = "",
        FontFace = Theme.Fonts.Mono,
        TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Text,
        BackgroundColor3 = Theme.Palette.PanelElevated,
        BackgroundTransparency = 1,   -- invisible until hovered/focused
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, 0, 0, 0),
        Size = UDim2.new(0, 82, 0, 18),
        TextXAlignment = Enum.TextXAlignment.Right,
        ClearTextOnFocus = false,
        ZIndex = 38,
        Parent = row,
    }, {
        pillCorner(),
        stroke(Theme.Palette.BorderSubtle, 1),
        new("UIPadding", {
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 10),
        }),
    })
    local valueStroke = valueBox:FindFirstChildOfClass("UIStroke")
    if valueStroke then valueStroke.Transparency = 1 end   -- hide stroke by default too
    local track = new("Frame", {
        Position = UDim2.new(0, 0, 0, 30),
        Size = UDim2.new(1, 0, 0, 6),                     -- v0.0.32: thicker track
        BackgroundColor3 = Theme.Palette.PanelElevated,
        BorderSizePixel = 0,
        ZIndex = 34,
        Parent = row,
    }, { pillCorner() })
    local startPct = (current - min) / (max - min)
    local fill = new("Frame", {
        Size = UDim2.new(startPct, 0, 1, 0),
        BackgroundColor3 = Theme.Palette.Accent,
        BorderSizePixel = 0,
        ZIndex = 35,
        Parent = track,
    }, { pillCorner() })
    -- v0.0.99: a proper knob: small ball at the fill tip (AnchorPoint 0.5,0.5 so
    -- it sits ON the tip, straddling the fill edge, instead of hanging off it).
    local knob = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(startPct, 0, 0.5, 0),
        Size = UDim2.new(0, 12, 0, 12),
        BackgroundColor3 = Theme.Palette.Accent,
        BorderSizePixel = 0,
        ZIndex = 36,
        Parent = track,
    }, { corner(6), stroke(Theme.Palette.Border, 1) })
    -- v0.0.99: drag area is the ENTIRE row width (was reserving 86px for the value
    -- box: when the fill sat far right, the last 86px of the track was dead
    -- space and the knob end was unreachable). The value box lives at the top of
    -- the row, nowhere near the track, so nothing needs reserving.
    local hitArea = new("TextButton", {
        Text = "",
        AutoButtonColor = false,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 0, 0, 24),
        Size = UDim2.new(1, 0, 0, 18),
        ZIndex = 37,
        Parent = row,
    })
    local dragging = false

    local function applyValue(animate)
        local pct = (current - min) / (max - min)
        -- v0.48.0: Toggles off snaps the fill + knob (drag already passes
        -- false; this covers typed values settling in).
        if animate and Koffee.Anim.spot("AnimToggles") then
            tween(fill, Theme.Animation.Fast, { Size = UDim2.new(pct, 0, 1, 0) })
            tween(knob, Theme.Animation.Fast, { Position = UDim2.new(pct, 0, 0.5, 0) })
        else
            fill.Size = UDim2.new(pct, 0, 1, 0)
            knob.Position = UDim2.new(pct, 0, 0.5, 0)
        end
        if animate then pulse(track, 1.02) end   -- v0.0.98: track ticks on settle
        local atMax = opts.infinite and current >= max
            valueBox.Text = atMax and "Infinite" or tostring(current)
        if onChange then onChange(atMax and math.huge or current) end
    end
    local function setFromInputX(inputX)
        local trackAbs = track.AbsolutePosition.X
        local trackW = track.AbsoluteSize.X
        if trackW <= 0 then return end
        local pct = math.clamp((inputX - trackAbs) / trackW, 0, 1)
        current = round(min + (max - min) * pct)
        applyValue(false)
    end
    UserInputService.InputChanged:Connect(function(input)
        if dragging
        and (input.UserInputType == Enum.UserInputType.MouseMovement
          or input.UserInputType == Enum.UserInputType.Touch) then
            setFromInputX(input.Position.X)
        end
    end)
    -- v0.0.98: track squashes to 0.98 while the drag grabs it, springs back on
    -- release (both on the button's own end AND the service end as a failsafe).
    -- v0.48.0: gated on Button Press; off leaves the scale at rest.
    hitArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            if Koffee.Anim.spot("AnimPress") then
                tween(uScaleOf(hitArea), Theme.Animation.Fast, { Scale = 0.98 })
            end
            setFromInputX(input.Position.X)
        end
    end)
    hitArea.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
            if Koffee.Anim.spot("AnimPress") then
                tween(uScaleOf(hitArea), Theme.Animation.Fast, { Scale = 1 })
            else
                uScaleOf(hitArea).Scale = 1
            end
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if dragging
        and (input.UserInputType == Enum.UserInputType.MouseButton1
          or input.UserInputType == Enum.UserInputType.Touch) then
            dragging = false
            if Koffee.Anim.spot("AnimPress") then
                tween(uScaleOf(hitArea), Theme.Animation.Fast, { Scale = 1 })
            else
                uScaleOf(hitArea).Scale = 1
            end
        end
    end)
    -- v0.48.0: the knob swells slightly under the cursor so the track reads
    -- grabbable before you touch it. Off snaps back to resting size.
    hitArea.MouseEnter:Connect(function()
        if Koffee.Anim.spot("AnimHover") then
            tween(knob, Theme.Animation.Fast, { Size = UDim2.new(0, 15, 0, 15) })
        else
            knob.Size = UDim2.new(0, 15, 0, 15)
        end
    end)
    hitArea.MouseLeave:Connect(function()
        if Koffee.Anim.spot("AnimHover") then
            tween(knob, Theme.Animation.Fast, { Size = UDim2.new(0, 12, 0, 12) })
        else
            knob.Size = UDim2.new(0, 12, 0, 12)
        end
    end)
    valueBox.FocusLost:Connect(function(enterPressed)
        if opts.infinite and valueBox.Text:lower():find("inf") then
            current = max
        else
            local n = tonumber(valueBox.Text)
            if n then current = round(math.clamp(n, min, max)) end
        end
        applyValue(true)
    end)
    -- hover: bg pill lights up
    valueBox.MouseEnter:Connect(function()
        tween(valueBox, Theme.Animation.Fast, {
            BackgroundTransparency = 0.35,
            TextColor3 = Theme.Palette.Accent,
        })
        if valueStroke then
            tween(valueStroke, Theme.Animation.Fast, { Transparency = 0 })
        end
    end)
    valueBox.MouseLeave:Connect(function()
        tween(valueBox, Theme.Animation.Fast, {
            BackgroundTransparency = 1,
            TextColor3 = Theme.Palette.Text,
        })
        if valueStroke then
            tween(valueStroke, Theme.Animation.Fast, { Transparency = 1 })
        end
    end)
    -- v0.87.0: push a value in without firing onChange, so a slider can mirror live data
    return { row = row, set = function(v)
        if dragging or valueBox:IsFocused() then return end
        v = round(math.clamp(tonumber(v) or min, min, max))
        if v == current then return end
        current = v
        local pct = (current - min) / (max - min)
        fill.Size = UDim2.new(pct, 0, 1, 0)
        knob.Position = UDim2.new(pct, 0, 0.5, 0)
        valueBox.Text = (opts.infinite and current >= max) and "Infinite" or tostring(current)
    end }
end

-- RIGHT-CLICK SETTINGS POPUP (v0.0.25)
-- Right-click a config row to open a small floating panel of extra controls
-- (built by the caller via api:slider(...)). Lives in popupScreen like the
-- dropdowns / colour picker, positioned inset-safe, closes on outside click.
local openSettingsPopups = {}   -- frame -> close fn

-- v0.13.0: `alsoLeft` additionally opens on LEFT click. Used by Custom Features,
-- where the button IS the options button and hiding it behind RMB is a trap.
-- v0.19.1: `dynamic` rebuilds the body on every open. The default builds once,
-- which is right for fixed knobs and wrong for anything listing live state.
local function rightClickSettings(row, title, buildFn, alsoLeft, dynamic)
    local btn
    for _, c in ipairs(row:GetDescendants()) do
        if c:IsA("TextButton") then btn = c break end
    end
    if not btn then return end

    local popupFrame, isOpen = nil, false
    local body, spawned = nil, {}
    -- v0.36.0: cap the popup height and scroll the body, so tall setting lists
    -- (Fire Remote, big colour panels) don't run off the bottom of the screen.
    local BODY_MAX = 300   -- v0.37.1: hard cap; body scrolls past this
    local function ensurePopup()
        if popupFrame then return end
        popupFrame = new("Frame", {
            Name = "Settings",
            Size = UDim2.new(0, 210, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = Theme.Palette.Panel,
            BackgroundTransparency = 0.02,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            Visible = false,
            ZIndex = 210,
            Parent = popupScreen,
        }, {
            corner(6), stroke(Theme.Palette.Border, 1),
            new("UIPadding", {
                PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10),
                PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
            }),
            new("UIListLayout", {
                FillDirection = Enum.FillDirection.Vertical,
                Padding = UDim.new(0, 4),
                SortOrder = Enum.SortOrder.LayoutOrder,
            }),
        })
        new("TextLabel", {
            Text = title, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
            LayoutOrder = 0, ZIndex = 211, Parent = popupFrame,
        })
        -- content lives in a scrolling body; grows to its content, then scrolls once
        -- it hits BODY_MAX (a hard cap, not a fraction of anything).
        body = new("ScrollingFrame", {
            Name = "Body", Size = UDim2.fromScale(1, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(0, 0, 0, 0),
            BackgroundTransparency = 1, ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.Palette.TextFaint,
            ScrollingDirection = Enum.ScrollingDirection.Y, LayoutOrder = 1, ZIndex = 210, Parent = popupFrame,
        }, {
            new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical,
                Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
        })
        local bl = body:FindFirstChildOfClass("UIListLayout")
        bl:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            body.Size = UDim2.new(1, 0, 0, math.min(bl.AbsoluteContentSize.Y, BODY_MAX))
        end)
    end

    -- dropdowns park their option list on popupScreen, NOT under the popup, so a
    -- rebuild has to run their own destroyers or the lists pile up invisibly
    local function buildBody()
        for _, kill in ipairs(spawned) do pcall(kill) end
        table.clear(spawned)
        -- v0.36.0: clear the scrolling body's items (its layout is not a GuiObject,
        -- so it survives); popupFrame's own children (title, body) are kept.
        for _, c in ipairs(body:GetChildren()) do
            if c:IsA("GuiObject") then c:Destroy() end
        end
        local api = { frame = body }   -- v0.0.46: expose parent for custom content
        function api:slider(label, mn, mx, initial, precision, onChange)
            slider(body, label, mn, mx, initial, precision, onChange)
        end
        function api:toggle(label, initial, onChange)
            return configCheckbox(body, label, initial, onChange)
        end
        function api:dropdown(label, options, initial, onChange)
            local d = dropdown(body, label, options, initial, onChange)
            spawned[#spawned + 1] = d.destroy
            return d
        end
        -- v0.0.28: colour control inside a settings popup (label + right swatch).
        -- v0.0.32: optional `sopts` (alpha etc) forwarded to colorSwatch.
        function api:swatch(label, initial, onChange, sopts)
            local r = new("Frame", {
                Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1,
                ZIndex = 211, Parent = body,
            })
            new("TextLabel", {
                Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
                TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
                Size = UDim2.new(1, -22, 1, 0), TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 212, Parent = r,
            })
            local wrap = new("Frame", {
                AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
                Size = UDim2.new(0, 14, 0, 16), BackgroundTransparency = 1,
                ZIndex = 212, Parent = r,
            })
            local o = { onChange = onChange }
            if sopts then for k, v in pairs(sopts) do o[k] = v end end
            colorSwatch(wrap, initial, 14, o)
            return r
        end
        -- v0.0.32: a row of N colour swatches (transparency is separate sliders now).
        function api:swatchRow(colors, onColor)
            local r = new("Frame", {
                Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, ZIndex = 211, Parent = body,
            }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
                Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }) })
            for i = 1, #colors do
                colorSwatch(r, colors[i], 14, { onChange = function(c) onColor(i, c) end })
            end
            return r
        end
        -- v0.17.0: clickable action (popup built once, needs button not toggle).
        function api:action(label, onClick)
            local b = new("TextButton", {
                Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.Text, AutoButtonColor = false,
                BackgroundColor3 = Theme.Palette.PanelElevated, BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, 20), ZIndex = 211, Parent = body,
            }, { corner(4), stroke(Theme.Palette.Border, 1) })
            b.MouseButton1Click:Connect(function() pcall(onClick, b) end)
            popFx(b)
            return b
        end
        -- v0.90.0: redraw the popup (e.g. a style pick that changes which settings apply)
        function api:rebuild()
            task.defer(function() if body and body.Parent then buildBody() end end)
        end
        buildFn(api)
    end

    local popupSeq = 0   -- v0.48.0: guards the close-shrink delay below
    local function closePopup()
        if not isOpen then return end
        isOpen = false
        openSettingsPopups[popupFrame] = nil
        if not popupFrame then return end
        -- v0.48.0: popups shrink out on close instead of blinking away. Off
        -- (or master off, via tween's snap) hides immediately.
        if Koffee.Anim.spot("AnimPopups") then
            popupSeq = popupSeq + 1
            local mySeq = popupSeq
            tween(uScaleOf(popupFrame), Theme.Animation.Menu, { Scale = 0.94 })
            task.delay(Koffee.Anim.wait(0.16), function()
                if mySeq == popupSeq and not isOpen then popupFrame.Visible = false end
            end)
        else
            popupFrame.Visible = false
        end
    end
    local function openPopup()
        local fresh = popupFrame == nil
        ensurePopup()
        if fresh or dynamic then buildBody() end
        for _, closer in pairs(openSettingsPopups) do closer() end
        -- v0.5.3: openDropdowns stores { btn, close } tables, not bare functions
        -- (see openList at ~3355). Old contract lingered here and tripped
        -- "attempt to call a table value" the moment a right-click popup was
        -- opened while any dropdown was open. Same access pattern openList uses.
        for _, entry in pairs(openDropdowns) do entry.close(true) end
        isOpen = true
        openSettingsPopups[popupFrame] = closePopup
        -- v0.72.2: open at the cursor, not the row rect. v0.72.3: no guessed
        -- sizes or offsets. GetMouseLocation includes the topbar inset while
        -- popup space does not (that gap was the downward drift), and the
        -- popup's real size is measured one frame after showing, then clamped.
        local mp = UserInputService:GetMouseLocation()
        local inset = game:GetService("GuiService"):GetGuiInset()
        local vp = viewport()
        local cx, cy = mp.X - inset.X - 4, mp.Y - inset.Y - 4
        local ox, oy = popupOffsetFor(popupFrame, cx, cy)
        popupFrame.Position = UDim2.new(0, ox, 0, oy)
        popupFrame.Visible = true
        task.defer(function()
            if not isOpen or not popupFrame.Parent then return end
            local w, h = popupFrame.AbsoluteSize.X, popupFrame.AbsoluteSize.Y
            local px, py = cx, cy
            if px + w > vp.X - 4 then px = vp.X - 4 - w end
            if py + h > vp.Y - 4 then py = vp.Y - 4 - h end
            if px < 4 then px = 4 end
            if py < 4 then py = 4 end
            local fx, fy = popupOffsetFor(popupFrame, px, py)
            popupFrame.Position = UDim2.new(0, fx, 0, fy)
        end)
        -- v0.0.98: settings popup grows open. v0.48.0: gated on Popups; off
        -- leaves the scale at rest (a close-shrink may have left 0.94 behind).
        local psc = uScaleOf(popupFrame)   -- v0.0.98: settings popup grows open
        if Koffee.Anim.spot("AnimPopups") then
            popupSeq = popupSeq + 1   -- a reopen supersedes any close-shrink wait
            psc.Scale = 0.94
            tween(psc, Theme.Animation.Menu, { Scale = 1 })
        else
            psc.Scale = 1
        end
    end

    local function toggle()
        if isOpen then closePopup() else openPopup() end
    end
    btn.MouseButton2Click:Connect(toggle)
    if alsoLeft then btn.MouseButton1Click:Connect(toggle) end
end

-- outside-click closer for the settings popups (own handler since openSettingsPopups
-- is declared below the main dropdown/picker closer).
UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1
    and input.UserInputType ~= Enum.UserInputType.Touch then return end
    local mp = input.Position
    local function hits(f)
        local abs, siz = f.AbsolutePosition, f.AbsoluteSize
        return mp.X >= abs.X and mp.X <= abs.X + siz.X
           and mp.Y >= abs.Y and mp.Y <= abs.Y + siz.Y
    end
    -- v0.19.3: a dropdown's option list is parented to popupScreen and drawn BELOW
    -- the popup, so picking an option lands outside the popup's rect and used to
    -- close the popup out from under the dropdown mid-click.
    for lst in pairs(openDropdowns) do
        if lst.Visible and hits(lst) then return end
    end
    for frame, closer in pairs(openSettingsPopups) do
        if not hits(frame) then closer() end
    end
end)

-- v0.0.46: shared Team Check settings popup. Lists every Team as an ally toggle (ticked = skip in ESP/aim).
-- "Advanced" ignores the manual list, uses the automatic isSameTeam heuristic, and greys the list out.
local function teamCheckSettings(api)
    local frame = api.frame
    local dimGroups = {}
    local function refreshDim()
        local t = Shared.AdvancedTeam and 0.62 or 0
        for _, cg in ipairs(dimGroups) do cg.GroupTransparency = t end
    end
    api:toggle("Advanced", Shared.AdvancedTeam, function(v)
        Shared.AdvancedTeam = v
        refreshDim()
    end)
    local teams = {}
    pcall(function() teams = game:GetService("Teams"):GetTeams() end)
    if #teams == 0 then
        new("TextLabel", {
                Text = "No teams in this game: use Advanced",
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true, ZIndex = 212, Parent = frame,
        })
    end
    for _, team in ipairs(teams) do
        local name = team.Name
        -- CanvasGroup so GroupTransparency dims the whole row uniformly when greyed.
        local cg = new("CanvasGroup", {
            Size = UDim2.new(1, 0, 0, CBOX.h),
            BackgroundTransparency = 1, GroupTransparency = 0,
            BorderSizePixel = 0, ZIndex = 211, Parent = frame,
        })
        local ctrl = checkboxVisual(cg, name, Shared.MyTeams[name] == true)
        ctrl.button.MouseButton1Click:Connect(function()
            if Shared.AdvancedTeam then return end   -- greyed out: ignore clicks
            local ns = not ctrl.getState()
            ctrl.setState(ns)
            Shared.MyTeams[name] = ns and true or nil
        end)
        dimGroups[#dimGroups + 1] = cg
    end
    refreshDim()
end

-- SHARED STATE + CONFIG SYSTEM (v0.0.34)
-- Wrapped in an IIFE so its ~20 locals get their own register budget (Luau's
-- 200-local limit is per-function; the main chunk is already near it). Only the
-- forward-declared upvalues (Shared/isSameTeam/isFriend/registerConfig/
-- rebuildConfigTabs) + Koffee.Config escape to the main chunk.
--   isSameTeam    : robust team check: Team instance first, TeamColor/Neutral
--                   fallback for games that never assign a Team object
--   isFriend      : cached friendship lookup (IsFriendsWith yields, so resolve
--                   async once per userId; render loops read the cache)
--   ConfigRegistry: name -> live state table, walked by the config save/load
;(function()

-- Team check that survives games which never set Player.Team. If either player
-- carries a real Team object we trust it; otherwise we fall back to TeamColor
-- (skipping the neutral/FFA case so nobody is falsely marked a teammate).
function isSameTeam(plr, localPlr)
    localPlr = localPlr or LocalPlayer
    if not plr or plr == localPlr then return false end
    local a, b = localPlr.Team, plr.Team
    if a ~= nil or b ~= nil then return a == b end
    if localPlr.Neutral or plr.Neutral then return false end
    return localPlr.TeamColor == plr.TeamColor
end

-- v0.0.46: the "is this player an ally to skip?" gate every Team Check reads.
--   Advanced ON  -> automatic isSameTeam (robust for FFA / TDM / single-Team games).
--   Advanced OFF -> manual: ally iff player's Team name is in Shared.MyTeams (right-click list).
function isTeammate(plr)
    if not plr or plr == LocalPlayer then return false end
    if Shared.AdvancedTeam then return isSameTeam(plr) end
    local t = plr.Team
    return t ~= nil and Shared.MyTeams[t.Name] == true
end

-- IsFriendsWith is a yielding web call: never run it inside a render loop.
-- Resolve once per userId on a background thread; the loop reads the cache and
-- treats "unknown yet" as not-a-friend until the lookup lands.
local friendStatus  = {}   -- userId -> bool
local friendPending = {}
function isFriend(plr)
    if not plr or plr == LocalPlayer then return false end
    local uid = plr.UserId
    if not uid or uid <= 0 then return false end
    local cached = friendStatus[uid]
    if cached ~= nil then return cached end
    if not friendPending[uid] then
        friendPending[uid] = true
        task.spawn(function()
            local ok, res = pcall(function() return LocalPlayer:IsFriendsWith(uid) end)
            friendStatus[uid]  = (ok and res) or false
            friendPending[uid] = nil
        end)
    end
    return false
end

--== CONFIG SYSTEM: save / load / auto-load per PlaceId. Subsystems register
-- their live state tables; save serializes to a Lua literal (Color3 / EnumItem /
-- Vector aware), load applies back IN PLACE so every live reference keeps
-- working, then re-syncs modules + rebuilds the config-driven tabs.
local ConfigRegistry = {}          -- name -> live table
function registerConfig(name, tbl) ConfigRegistry[name] = tbl end

local CFG_DIR = "Koffee/configs"

-- executor file API, all guarded so a locked-down runtime degrades to no-op.
local fileAPI = {
    write   = writefile,
    read    = readfile,
    isfile  = isfile,
    isfolder= isfolder,
    makefolder = makefolder,
    delfile = delfile,
    listfiles = listfiles,
}
local function filesReady()
    return fileAPI.write and fileAPI.read and fileAPI.isfile and fileAPI.listfiles
end
local function ensureDir()
    if not (fileAPI.isfolder and fileAPI.makefolder) then return end
    if not fileAPI.isfolder("Koffee")   then pcall(fileAPI.makefolder, "Koffee") end
    if not fileAPI.isfolder(CFG_DIR)     then pcall(fileAPI.makefolder, CFG_DIR) end
end

-- === serialize ============================================================
local encValue
local function encTable(tbl)
    local parts = {}
    for k, v in pairs(tbl) do
        -- skip private/runtime keys (_hooked, _target, connections handled below)
        if not (type(k) == "string" and k:sub(1, 1) == "_") then
            local ev = encValue(v)
            if ev ~= nil then
                local ek
                if type(k) == "number" then ek = "[" .. k .. "]"
                elseif type(k) == "string" then ek = "[" .. string.format("%q", k) .. "]"
                end
                if ek then parts[#parts + 1] = ek .. "=" .. ev end
            end
        end
    end
    return "{" .. table.concat(parts, ",") .. "}"
end
encValue = function(v)
    local t = typeof(v)
    if t == "number" then
        if v ~= v then return "0" end                       -- NaN -> 0
        if v == math.huge then return "math.huge" end        -- v0.0.56: "Infinite" sliders round-trip
        if v == -math.huge then return "-math.huge" end
        return tostring(v)
    elseif t == "boolean" then return tostring(v)
    elseif t == "string" then return string.format("%q", v)
    elseif t == "Color3" then
        return string.format("Color3.new(%.6f,%.6f,%.6f)", v.R, v.G, v.B)
    elseif t == "EnumItem" then return tostring(v)          -- "Enum.KeyCode.E"
    elseif t == "Vector2" then return string.format("Vector2.new(%.6f,%.6f)", v.X, v.Y)
    elseif t == "Vector3" then return string.format("Vector3.new(%.6f,%.6f,%.6f)", v.X, v.Y, v.Z)
    elseif t == "table" then return encTable(v)
    end
    return nil   -- functions / Instances / connections / threads -> dropped
end

local function snapshotAll()
    local snap = { registry = {}, keybinds = {}, modules = {} }
    for name, tbl in pairs(ConfigRegistry) do snap.registry[name] = tbl end
    for id, key in pairs(Keybinds) do snap.keybinds[id] = key end
    for id, m in pairs(Modules) do snap.modules[id] = m.Enabled and true or false end
    return snap
end

-- === apply ================================================================
-- v0.0.50: SET-shaped tables must be REPLACED, not deep-merged. `MyTeams` is a
-- name-set where unticking a team does `MyTeams[name] = nil`: an absent key IS
-- the "not my team" value. Deep-merging can only ADD keys, so loading a config
-- left every previously-ticked team behind and the player kept being treated as
-- an ally. (Flagged as a caveat when MyTeams shipped in v0.0.46.) Cleared IN
-- PLACE rather than reassigned so live references to the table keep working:
-- the same reason the whole loader applies in place.
-- Deep-merge stays the default: every other registered table is a fixed schema
-- where a missing key means "this config predates the field", not "unset it".
-- v0.13.0: Custom Features' node array is REPLACE too: it's a list, so merging
-- would resurrect every node the user deleted since the config was written.
-- v0.54.0: NPC Entries / Folders / a folder's Rules are lists, so REPLACE like
-- Nodes: merging would resurrect entries/rules the user deleted since the save.
local REPLACE_TABLES = { MyTeams = true, Nodes = true, Blacklist = true,
    Entries = true, Folders = true, Rules = true, Accessories = true,
    ExcludeNames = true, ExcludeSigs = true,   -- v0.57.0: NPC learn exclusion lists
    Pins = true,                               -- v0.75.0: gun-mod pins (saved set wins)
    excludes = true }                          -- v0.62.0: player-list Exclude set (by UserId)
local function applyInto(target, src)
    for k, v in pairs(src) do
        if type(v) == "table" and type(target[k]) == "table" then
            if REPLACE_TABLES[k] then
                for old in pairs(target[k]) do target[k][old] = nil end
            end
            applyInto(target[k], v)
        else
            target[k] = v
        end
    end
end

-- loadSnapshot applies a decoded config and then rebuilds the config-driven
-- tabs (rebuildConfigTabs is a main-chunk upvalue set near addTab) so sliders /
-- dropdowns / checkboxes / keybind pills re-read the freshly loaded state.
local function loadSnapshot(data)
    if type(data) ~= "table" then return false end
    if data.registry then
        for name, tbl in pairs(data.registry) do
            local target = ConfigRegistry[name]
            if target and type(tbl) == "table" then applyInto(target, tbl) end
        end
    end
    -- v0.54.0: NPC entries loaded above carry no modules yet; reconcile hands
    -- them fresh session-unique ids (and applies their saved on/off), so the
    -- module-enable loop below must skip npc_* rows: their state is already set.
    if Shared.NPC and Shared.NPC.reconcile then pcall(Shared.NPC.reconcile, data and data.modules) end
    -- v0.75.0: gun-mod pins reseed from the loaded set (best resolving source
    -- re-scanned); the heartbeat re-hooks + enforces from there.
    if Shared._modsReconcile then pcall(Shared._modsReconcile) end
    -- per-game custom-anim list (place 155615604): a config saved in another
    -- game can carry an animation Name that doesn't exist in THIS game's list.
    -- Snap it before the tab rebuild renders the dropdown (reads the live
    -- registered table, freshly merged above; the per-game lists are seeded
    -- onto Koffee by the character-visual IIFE).
    local ca = ConfigRegistry and ConfigRegistry["custom_anim"]
    if ca then
        local ids = Koffee._animIDs
        if ids and not ids[ca.Name] then
            local opts = Koffee._animDropdown
            ca.Name = (opts and opts[1]) or "Orbit 1"
        end
    end
    if data.keybinds then
        for k in pairs(Keybinds) do Keybinds[k] = nil end
        for id, key in pairs(data.keybinds) do
            -- v0.66.1: combat has no toggle bind. v0.69.1: the HvH box is Blink
            -- alone now. Skip stale entries from old saves.
            if id ~= "aimbot" and id ~= "silentaim" and id ~= "triggerbot" and id ~= "hvh_flash" then
                -- v0.75.0: combo binds ({mod,key} tables) decoded fine but were
                -- dropped here, so Shift+C-style pills forgot their bind on load.
                local isCombo = type(key) == "table" and typeof(key.mod) == "EnumItem" and typeof(key.key) == "EnumItem"
                -- accept Roblox EnumItems AND virtual XButton strings (v0.0.37)
                if typeof(key) == "EnumItem" or key == "XButton1" or key == "XButton2" or isCombo then
                    Keybinds[id] = key
                end
            end
        end
    end
    if data.modules then
        for id, state in pairs(data.modules) do
            -- v0.67.0: npc_* rows are owned by reconcile (fresh ids per load with
            -- saved on/off already applied); the old ids below no longer exist.
            if not (type(id) == "string" and id:sub(1, 4) == "npc_") then
                local m = Modules[id]
                if m and (m.Enabled and true or false) ~= (state and true or false) then
                    toggleModule(id)
                end
            end
        end
    end
    -- v0.55.0: re-apply avatar deco against the freshly loaded accessory list even
    -- when the module's on/off state did not change (so a load updates the deco).
    if Shared.Deco and Shared.Deco.apply then pcall(Shared.Deco.apply) end
    if rebuildConfigTabs then pcall(rebuildConfigTabs) end
    -- v0.0.96: the Arraylist option is registered state too, so a load can flip
    -- it: re-apply the actual column visibility (the rebuilt tab's checkbox
    -- reads KoffeeOptions but nothing drives the live column off it).
    if activeArray then activeArray.Visible = KoffeeOptions.Arraylist == true end
    if applyArrayLineColor then pcall(applyArrayLineColor) end   -- v0.33.0
    if applyTopBar then pcall(applyTopBar) end
    -- v0.0.97: a loaded config can flip CustomFontOn / change the font / size:
    -- push those into the Theme so the feature interface reflects the saved state.
    pcall(function()
        Theme.setFeiSize(KoffeeOptions.CustomFontSize)
        Theme.setFeiOn(KoffeeOptions.CustomFontOn == true)
        if KoffeeOptions.CustomFontOn then Theme.setFeiFont(KoffeeOptions.CustomFontName) end
        -- v0.0.99: mirror the MI font toggle across config loads (fonts + tab
        -- rebuilds happen together; re-apply AFTER the rebuild so fresh labels
        -- get the swap too). loadSnapshot's rebuildConfigTabs ran above.
        Theme.applyMIFont(window, KoffeeOptions.MIFontOn and Theme.loadFeiFont(KoffeeOptions.MIFontName) or nil,
            KoffeeOptions.MIFontOn and KoffeeOptions.MIFontSize or nil)
    end)
    -- v0.0.97: Target Lock runtime state must not ride a config load: a save
    -- taken mid-engagement would resurrect a stale lock after switching configs.
    if Shared.TargetLock then Shared.TargetLock._active = false end
    return true
end

-- === disk ops =============================================================
local ConfigIO = {}
function ConfigIO.list()
    local out = {}
    if not filesReady() then return out end
    ensureDir()
    local ok, files = pcall(fileAPI.listfiles, CFG_DIR)
    if not ok or type(files) ~= "table" then return out end
    for _, path in ipairs(files) do
        local name = tostring(path):match("([^/\\]+)%.koffee$")
        if name then out[#out + 1] = name end
    end
    table.sort(out)
    return out
end
function ConfigIO.save(name)
    if not filesReady() then return false, "no file access" end
    name = tostring(name):gsub("[^%w _%-]", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false, "name required" end
    ensureDir()
    local ok, text = pcall(function() return "return " .. encTable(snapshotAll()) end)
    if not ok then return false, "encode failed" end
    local wok = pcall(fileAPI.write, CFG_DIR .. "/" .. name .. ".koffee", text)
    if not wok then return false, "write failed" end
    return true, name
end
function ConfigIO.load(name)
    if not filesReady() then return false, "no file access" end
    local path = CFG_DIR .. "/" .. name .. ".koffee"
    if not fileAPI.isfile(path) then return false, "not found" end
    local rok, text = pcall(fileAPI.read, path)
    if not rok or type(text) ~= "string" then return false, "read failed" end
    local ldr = loadstring or load
    if not ldr then return false, "no loadstring" end
    local fn = ldr(text)
    if not fn then return false, "parse failed" end
    local dok, data = pcall(fn)
    if not dok then return false, "eval failed" end
    -- v0.0.50 fix: `return loadSnapshot(data), name` handed the CONFIG NAME back as
    -- the second return on failure, so the UI printed "load failed: <name>" instead
    -- of a reason. Split the two paths so the error slot always carries an error.
    if not loadSnapshot(data) then return false, "bad config data" end
    return true, name
end
function ConfigIO.delete(name)
    if not (filesReady() and fileAPI.delfile) then return false end
    local path = CFG_DIR .. "/" .. name .. ".koffee"
    if fileAPI.isfile(path) then return pcall(fileAPI.delfile, path) end
    return false
end
-- v0.12.3: rename = copy the file's bytes to the new name, then drop the old one.
-- Deliberately NOT a save() under the new name: that would snapshot whatever is
-- live right now and silently rewrite the config you were only renaming.
function ConfigIO.rename(old, newName)
    if not (filesReady() and fileAPI.delfile) then return false, "no file access" end
    newName = tostring(newName):gsub("[^%w _%-]", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if newName == "" then return false, "name required" end
    if newName == old then return true, old end
    local src, dst = CFG_DIR .. "/" .. old .. ".koffee", CFG_DIR .. "/" .. newName .. ".koffee"
    if not fileAPI.isfile(src) then return false, "not found" end
    if fileAPI.isfile(dst) then return false, "name already used" end
    local rok, text = pcall(fileAPI.read, src)
    if not rok or type(text) ~= "string" then return false, "read failed" end
    if not pcall(fileAPI.write, dst, text) then return false, "write failed" end
    pcall(fileAPI.delfile, src)
    return true, newName
end
-- v0.56.0: auto-load rules. One JSON sidecar holds ONE global rule (loads in any
-- game) plus any number of per-game rules keyed by PlaceId (each loads only in its
-- game). A game rule wins over the global when you are in that game. Each rule has
-- its own on/off switch. Shape: { global={name,on}, games={ ["<placeId>"]={name,on,place} } }.
--   Koffee/configs/_autoload.json
local AUTO_PATH = CFG_DIR .. "/_autoload.json"
local OLD_AUTO  = CFG_DIR .. "/_auto_" .. tostring(game.PlaceId) .. ".txt"   -- legacy per-place marker
local autoStore = nil
local function hjson() return game:GetService("HttpService") end
local function loadAuto()
    if autoStore then return autoStore end
    autoStore = { global = nil, games = {} }
    if filesReady() and fileAPI.isfile(AUTO_PATH) then
        local ok, t = pcall(fileAPI.read, AUTO_PATH)
        if ok and type(t) == "string" and t ~= "" then
            local dok, d = pcall(function() return hjson():JSONDecode(t) end)
            if dok and type(d) == "table" then
                autoStore.global = type(d.global) == "table" and d.global or nil
                autoStore.games  = type(d.games) == "table" and d.games or {}
            end
        end
    elseif filesReady() and fileAPI.isfile(OLD_AUTO) then
        -- migrate the legacy single-place marker into a game rule (once)
        local ok, v = pcall(fileAPI.read, OLD_AUTO)
        if ok and type(v) == "string" and v ~= "" then
            autoStore.games[tostring(game.PlaceId)] = { name = v, on = true, place = "This Game" }
        end
    end
    return autoStore
end
local function saveAuto()
    if not filesReady() then return end
    ensureDir()
    local ok, text = pcall(function() return hjson():JSONEncode(autoStore or { games = {} }) end)
    if ok then pcall(fileAPI.write, AUTO_PATH, text) end
end

-- the config name that should load on join right now (game rule beats global; both
-- must be enabled). nil = nothing pinned.
function ConfigIO.autoResolve()
    local s = loadAuto()
    local g = s.games[tostring(game.PlaceId)]
    if g and g.on and g.name and g.name ~= "" then return g.name end
    if s.global and s.global.on and s.global.name and s.global.name ~= "" then return s.global.name end
    return nil
end
-- flat list for the UI: global first (if set), then each game rule.
function ConfigIO.autoRules()
    local s = loadAuto()
    local out = {}
    if s.global and s.global.name and s.global.name ~= "" then
        out[#out + 1] = { scope = "global", name = s.global.name, on = s.global.on ~= false }
    end
    local ids = {}
    for id in pairs(s.games) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, id in ipairs(ids) do
        local g = s.games[id]
        if g and g.name and g.name ~= "" then
            out[#out + 1] = { scope = "game", placeId = id, place = g.place or ("Place " .. id),
                              name = g.name, on = g.on ~= false, current = (id == tostring(game.PlaceId)) }
        end
    end
    return out
end
function ConfigIO.autoSetGlobal(name)
    local s = loadAuto()
    if name and name ~= "" then s.global = { name = name, on = true } else s.global = nil end
    saveAuto()
end
function ConfigIO.autoSetGame(name, placeId)
    local s = loadAuto()
    local id = tostring(placeId or game.PlaceId)
    if name and name ~= "" then
        local place = "This Game"
        pcall(function()
            if game.PlaceId == tonumber(id) then
                local info = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
                if info and info.Name then place = info.Name end
            end
        end)
        s.games[id] = { name = name, on = true, place = place }
    else
        s.games[id] = nil
    end
    saveAuto()
end
function ConfigIO.autoToggle(scope, placeId)
    local s = loadAuto()
    if scope == "global" and s.global then s.global.on = not (s.global.on ~= false)
    elseif scope == "game" then local g = s.games[tostring(placeId)]; if g then g.on = not (g.on ~= false) end end
    saveAuto()
end
function ConfigIO.autoRemove(scope, placeId)
    local s = loadAuto()
    if scope == "global" then s.global = nil
    elseif scope == "game" then s.games[tostring(placeId)] = nil end
    saveAuto()
end
-- keep rules valid across a config rename / delete (they reference names by string)
function ConfigIO.autoRename(old, newName)
    local s = loadAuto()
    if s.global and s.global.name == old then s.global.name = newName end
    for _, g in pairs(s.games) do if g.name == old then g.name = newName end end
    saveAuto()
end
function ConfigIO.autoDrop(name)
    local s = loadAuto()
    if s.global and s.global.name == name then s.global = nil end
    for id, g in pairs(s.games) do if g.name == name then s.games[id] = nil end end
    saveAuto()
end
-- back-compat shims for the Config Manager "Auto" button: it pins/reads the rule
-- for the CURRENT game (a game rule), so the old per-place semantics are preserved.
function ConfigIO.getAuto()
    local g = loadAuto().games[tostring(game.PlaceId)]
    if g and g.on and g.name and g.name ~= "" then return g.name end
    return nil
end
function ConfigIO.setAuto(name)
    ConfigIO.autoSetGame(name and name ~= "" and name or nil)
end

-- v0.29.0 Cloud Configs: mirrors the Aero worker (CF + KV). Each config's raw
-- .koffee text rides as `data`; honor-system owner auth via UserId (?actor=).
-- Reuses the deployed Aero endpoint (stores arbitrary data, so no redeploy).
local CLOUD_ENDPOINT = "https://konstant-aero-cloud.kar-cloud.workers.dev"
local CLOUD_META = CFG_DIR .. "/_cloudmeta.json"   -- name -> {id,owner,ownerName,cloudName}
local function myId()   return LocalPlayer and LocalPlayer.UserId or 0 end
local function myName() return LocalPlayer and LocalPlayer.Name or "unknown" end

-- blocking HTTP (call inside task.spawn). Returns decoded, err.
local function cloudCall(method, path, body)
    local httpReq = (syn and syn.request) or (http and http.request) or http_request or request
    if not httpReq then return nil, "executor has no request()" end
    local HttpService = game:GetService("HttpService")
    local opts = { Url = CLOUD_ENDPOINT .. path, Method = method,
                   Headers = { ["Content-Type"] = "application/json" } }
    if body ~= nil then opts.Body = HttpService:JSONEncode(body) end
    local ok, resp = pcall(httpReq, opts)
    if not ok then return nil, tostring(resp) end
    if not resp then return nil, "no response" end
    local decoded
    if resp.Body and resp.Body ~= "" then
        local dok, dval = pcall(function() return HttpService:JSONDecode(resp.Body) end)
        if dok then decoded = dval end
    end
    local status = resp.StatusCode or resp.Status or 0
    if status >= 400 then return nil, (decoded and decoded.error) or ("HTTP " .. tostring(status)) end
    return decoded, nil
end

-- cloud pushes/pulls the .koffee file text verbatim (same format load() eats)
local function readConfigText(name)
    if not filesReady() then return nil end
    local p = CFG_DIR .. "/" .. name .. ".koffee"
    if not fileAPI.isfile(p) then return nil end
    local ok, t = pcall(fileAPI.read, p)
    if ok and type(t) == "string" then return t end
    return nil
end
local function writeConfigText(name, text)
    if not filesReady() then return false end
    ensureDir()
    return (pcall(fileAPI.write, CFG_DIR .. "/" .. name .. ".koffee", text))
end

-- cloud meta map (JSON sidecar, skipped by list()'s .koffee filter)
local cloudMeta = nil
local function loadCloudMeta()
    if cloudMeta then return cloudMeta end
    cloudMeta = {}
    if filesReady() and fileAPI.isfile(CLOUD_META) then
        local ok, t = pcall(fileAPI.read, CLOUD_META)
        if ok and type(t) == "string" and t ~= "" then
            local dok, d = pcall(function() return game:GetService("HttpService"):JSONDecode(t) end)
            if dok and type(d) == "table" then cloudMeta = d end
        end
    end
    return cloudMeta
end
local function saveCloudMeta()
    if not filesReady() then return end
    ensureDir()
    local ok, text = pcall(function() return game:GetService("HttpService"):JSONEncode(cloudMeta or {}) end)
    if ok then pcall(fileAPI.write, CLOUD_META, text) end
end

function ConfigIO.cloudMetaFor(name) return loadCloudMeta()[name] end
function ConfigIO.cloudIsOwner(name)
    local m = loadCloudMeta()[name]
    return m ~= nil and m.owner == myId()
end

-- upload (create) or overwrite (owner). Returns id, err. Blocks.
function ConfigIO.cloudUpload(name)
    if not filesReady() then return nil, "no file access" end
    local text = readConfigText(name)
    if not text then return nil, "config not found" end
    loadCloudMeta()
    local meta = cloudMeta[name]
    if meta and meta.owner == myId() then
        local doc, err = cloudCall("PUT", "/config/" .. meta.id .. "?actor=" .. myId(),
            { name = meta.cloudName or name, data = text })
        if not doc then return nil, err end
        meta.cloudName = doc.name; saveCloudMeta()
        return meta.id, nil
    end
    local doc, err = cloudCall("POST", "/config",
        { name = name, owner = myId(), ownerName = myName(), data = text })
    if not doc then return nil, err end
    cloudMeta[name] = { id = doc.id, owner = doc.owner, ownerName = doc.ownerName or myName(), cloudName = doc.name }
    saveCloudMeta()
    return doc.id, nil
end

-- download by id -> writes a local .koffee file. Returns localName, err. Blocks.
function ConfigIO.cloudDownload(id)
    id = tostring(id):upper():gsub("%s+", "")
    if #id ~= 8 then return nil, "enter an 8-char cloud id" end
    local doc, err = cloudCall("GET", "/config/" .. id)
    if not doc then return nil, err end
    if type(doc.data) ~= "string" then return nil, "bad cloud data" end
    loadCloudMeta()
    local localName = tostring(doc.name or ("cloud-" .. id)):gsub("[^%w _%-]", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if localName == "" then localName = "cloud-" .. id end
    -- collision: a DIFFERENT cloud config already sits at this name -> tag with id
    if cloudMeta[localName] and cloudMeta[localName].id ~= id then
        localName = localName .. " (" .. id .. ")"
    end
    if not writeConfigText(localName, doc.data) then return nil, "write failed" end
    cloudMeta[localName] = { id = id, owner = doc.owner, ownerName = doc.ownerName or "", cloudName = doc.name or localName }
    saveCloudMeta()
    return localName, nil
end

function ConfigIO.cloudDelete(name)
    loadCloudMeta()
    local meta = cloudMeta[name]
    if not (meta and meta.owner == myId()) then return false, "not the owner" end
    local ok, err = cloudCall("DELETE", "/config/" .. meta.id .. "?actor=" .. myId())
    if not ok then return false, err end
    cloudMeta[name] = nil; saveCloudMeta()   -- local file stays
    return true, nil
end

function ConfigIO.cloudRename(name)
    loadCloudMeta()
    local meta = cloudMeta[name]
    if not (meta and meta.owner == myId()) then return false, "not the owner" end
    local doc, err = cloudCall("PATCH", "/config/" .. meta.id .. "?actor=" .. myId(), { name = name })
    if not doc then return false, err end
    meta.cloudName = doc.name; saveCloudMeta()
    return true, nil
end

-- keep the meta map in step with local rename / delete
function ConfigIO.cloudMetaRename(old, newName)
    loadCloudMeta()
    if cloudMeta[old] then cloudMeta[newName] = cloudMeta[old]; cloudMeta[old] = nil; saveCloudMeta() end
end
function ConfigIO.cloudMetaDrop(name)
    loadCloudMeta()
    if cloudMeta[name] then cloudMeta[name] = nil; saveCloudMeta() end
end

Koffee.Config = ConfigIO

end)()   -- end SHARED STATE + CONFIG SYSTEM IIFE

-- ESP MODULE (v0.0.10)
-- Master toggle ("Enabled") just turns on the ESP framework + render loop.
-- Nothing draws until a sub-feature (Box / Name / Indicators / Health /
-- Tracer) is enabled: the master applies no color to players on its own.
--
-- Config groups:
--   Config (ESP-level toggles): shared across future widgets
--   Boxes (Boxes widget config)
--   Colors (color pool)
local ESP = {
    Config = {
        -- TextBackground: shared bool for future text modules (Names/Distance/Health
        -- all read the same preference). No module renders text yet; config-only.
        TextBackground = false,
        -- v0.0.28: Text Background is now tunable (right-click the toggle): colour,
        -- transparency, and padding around every ESP text tag.
        TextBgColor        = Color3.fromRGB(0, 0, 0),
        TextBgTransparency = 0.35,
        TextBgPadding      = 5,
        CharacterOnly  = false,      -- ignore accessories/tools in bounding-box calc
        -- v0.0.28: Follow Direction is a CUBE-ONLY feature (orienting a flat 2D box
        -- to facing only made it less accurate). Default OFF; the Box Type dropdown
        -- forces it off on any switch and the toggle refuses to arm unless Cube.
        FollowDirection = false,     -- v0.0.23: box/cube orients to the player's facing
        ImmediateMode  = true,       -- true = snap-to-frame, false = lerp smoothing
        -- v0.18.4: periodic stale-rig sweep. CharacterRemoving does not fire when a
        -- game Destroys or reparents a character itself, which is how ESP ends up
        -- drawing people who are not there.
        Rescan         = true,
        RescanRate     = 2,          -- seconds between sweeps
        OverScan       = false,      -- v0.59.0: resolve rigs by username in workspace (PF-style games)
        TeamCheck      = false,
        VisibleCheck   = false,
        TeamBasedColor = false,      -- team color overrides box outline color on same-team
        -- v0.0.17: Outline is a thickness ACCENT (not a gate): +1px on all box lines when on.
        -- v0.0.19: Glow removed; Outline no longer controls the arraylist accent line.
        Outline        = true,
        SelfESP        = false,
        TextGradient   = false,        -- v0.0.21: animated gradient on all ESP text
        -- v0.0.22: text gradient endpoint colors, editable via two swatches.
        GradientColorA = Color3.fromRGB(255, 253, 248),
        GradientColorB = Color3.fromRGB(212, 145, 90),
        -- v0.0.25: Gradient = animated gradient on every NON-text Second-Interface
        -- element (box, cube edges, corners, skeleton, tracer, head dot). Own
        -- colours. When on it OVERRIDES each feature's colour.
        Gradient       = false,
        GradientColorA2 = Color3.fromRGB(120, 200, 255),
        GradientColorB2 = Color3.fromRGB(200, 130, 255),
        -- v0.0.26: gradient tuning (right-click the Gradient toggle).
        GradientSpeed     = 0.5,   -- cycles/sec
        GradientRotation  = 0,     -- degrees; 0 = horizontal, 90 = vertical
        GradientSpacing   = 0.5,   -- 0..1 where the B color sits between the A ends
        GradientReverse   = false, -- flip travel direction
        SizingType     = "Algorithm",  -- v0.65.1: tight silhouette default
        -- v0.77.1: grown targets force the live Bounding projection so the box
        -- shows the hittable area. Untouched rigs keep SizingType.
        HitboxBox      = false,
        RenderDistance = 1000,
        -- v0.11.0 COLOR MODE. One master that resolves the colour for every
        -- Second-Interface element (box, cube, corners, skeleton, tracer, head dot,
        -- name/distance text, health bar) instead of each carrying a flat
        -- swatch. "Static" returns nil so every element keeps its own configured
        -- colour: i.e. exactly the pre-v0.11 behaviour, and the default.
        --   Gradient  animated A2/B2 ramp, targets spread along it
        --   Rainbow   hue cycle, targets spread across the wheel
        --   Health    red -> amber -> green by the target's health fraction
        --   Team      team colour for allies, visible/hidden colour otherwise
        --   Distance  ColorNear -> ColorFar across RenderDistance
        ColorMode      = "Static",
        ColorNear      = Color3.fromRGB(120, 255, 140),
        ColorFar       = Color3.fromRGB(255, 90, 90),
        RainbowSpeed   = 0.35,   -- cycles/sec
        -- per-target hue/phase offset. 0 = every target identical (one solid
        -- colour that changes together); higher fans a lineup across the ramp,
        -- which is most of what makes these modes read as "a different script".
        ColorSpread    = 0.35,
        RainbowSat     = 0.85,
        RainbowVal     = 1,
    },
    -- v0.0.22: shared Feature-Interface render model. One place drives the
    -- thickness of every rendered feature (box lines, cube edges, skeleton,
    -- tracer, corners, head dot, health bar). EqualSize on = constant thickness
    -- regardless of distance; off = thickness scales with distance (thicker up
    -- close, thinner far) so it reads like classic depth-scaled ESP.
    Render = {
