-- v0.90.0 CONSTELLATIONS: wireframe shapes drifting in the air (thin Beams between
-- attachments on one hidden host, dots at the joints). Each shape wanders, turns
-- slowly and fades in and out, then respawns somewhere else around you.
;(function()
    local st = { shapes = {}, host = nil }
    local function drop()
        if st.host then pcall(function() st.host:Destroy() end) end
        st.shapes, st.host = {}, nil
    end
    local function hostPart()
        if st.host and st.host.Parent then return st.host end
        local p = Instance.new("Part")
        p.Name = KID.name("cst")
        p.Anchored, p.CanCollide, p.Transparency = true, false, 1
        pcall(function() p.CanQuery = false; p.CanTouch = false; p.CastShadow = false end)
        p.Size = Vector3.new(0.1, 0.1, 0.1)
        p.CFrame = CFrame.new()
        p.Parent = Workspace.CurrentCamera
        KID.track(p)
        st.host = p
        return p
    end
    local function spawnShape(sh, cfg, cam, fresh)
        local host = hostPart()
        local S = math.max(cfg.Size or 1, 0.2)
        local reach = math.clamp(cfg.Reach or 1, 0.25, 6)
        -- a random walk of 4 to 7 joints, flattened a little, with the odd branch
        local n = math.random(4, 7)
        local pts = { Vector3.zero }
        for i = 2, n do
            local d = Vector3.new(math.random() - 0.5, (math.random() - 0.5) * 0.7, math.random() - 0.5).Unit
            pts[i] = pts[i - 1] + d * ((2.5 + math.random() * 4) * S)
        end
        local mid = Vector3.zero
        for _, v in ipairs(pts) do mid += v end
        mid /= n
        for i, v in ipairs(pts) do pts[i] = v - mid end
        local edges = {}
        for i = 2, n do edges[#edges + 1] = { i - 1, i } end
        if n >= 5 and math.random() < 0.6 then edges[#edges + 1] = { math.random(1, n - 3), n } end
        -- clear the old instances, build atts/beams/dots for the new shape
        for _, x in ipairs(sh.inst or {}) do pcall(function() x:Destroy() end) end
        sh.inst, sh.atts, sh.beams, sh.dots = {}, {}, {}, {}
        for i = 1, n do
            local a = Instance.new("Attachment")
            a.Parent = host
            sh.atts[i] = a
            sh.inst[#sh.inst + 1] = a
            local dot = Instance.new("Part")
            dot.Shape = Enum.PartType.Ball
            dot.Anchored, dot.CanCollide = true, false
            pcall(function() dot.CanQuery = false; dot.CanTouch = false; dot.CastShadow = false end)
            dot.Material = Enum.Material.Neon
            dot.Size = Vector3.one * 0.16 * S
            dot.Parent = host
            sh.dots[i] = dot
            sh.inst[#sh.inst + 1] = dot
        end
        for _, e in ipairs(edges) do
            local b = Instance.new("Beam")
            b.Attachment0, b.Attachment1 = sh.atts[e[1]], sh.atts[e[2]]
            b.FaceCamera = true
            b.Segments = 1
            b.LightEmission, b.LightInfluence = 1, 0
            b.Width0, b.Width1 = 0.05 * S, 0.05 * S
            b.Parent = host
            sh.beams[#sh.beams + 1] = b
            sh.inst[#sh.inst + 1] = b
        end
        sh.pts = pts
        local p = cam.CFrame.Position
        local ang, r = math.random() * math.pi * 2, (14 + math.random() * 60) * reach
        sh.center = p + Vector3.new(math.cos(ang) * r, -4 + math.random() * 30, math.sin(ang) * r)
        local vd = Vector3.new(math.random() - 0.5, (math.random() - 0.5) * 0.3, math.random() - 0.5)
        sh.vel = (vd.Magnitude > 0.01 and vd.Unit or Vector3.xAxis) * (0.4 + math.random() * 0.9)
        sh.axis = Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5).Unit
        sh.spin = (math.random() - 0.5) * 0.35
        sh.born = os.clock() - (fresh and math.random() * 8 or 0)
        sh.life = 10 + math.random() * 8
    end
    RunService.RenderStepped:Connect(function(dt)
        if Koffee.dead() then drop(); return end
        local cfg = World.FX.Constellations
        local cam = Workspace.CurrentCamera
        if not (cfg and cfg.Enabled and cam) then if st.host then drop() end; return end
        local want = math.clamp(math.floor(cfg.Count or 14), 1, 60)
        local key = tostring(cfg.Size) .. "|" .. tostring(cfg.Reach)
        if st.key ~= key then
            for _, sh in ipairs(st.shapes) do for _, x in ipairs(sh.inst or {}) do pcall(function() x:Destroy() end) end end
            st.shapes, st.key = {}, key
        end
        while #st.shapes < want do
            local sh = {}
            spawnShape(sh, cfg, cam, true)
            st.shapes[#st.shapes + 1] = sh
        end
        while #st.shapes > want do
            local sh = table.remove(st.shapes)
            for _, x in ipairs(sh.inst or {}) do pcall(function() x:Destroy() end) end
        end
        local now = os.clock()
        local camPos = cam.CFrame.Position
        local reach = math.clamp(cfg.Reach or 1, 0.25, 6)
        local base = math.clamp(cfg.Alpha or 0.35, 0, 0.95)
        local sp = math.max(cfg.Speed or 1, 0)
        local colSeq = ColorSequence.new(cfg.Color)
        for _, sh in ipairs(st.shapes) do
            local age = now - sh.born
            if age > sh.life or (sh.center - camPos).Magnitude > 110 * reach then
                spawnShape(sh, cfg, cam, false)
                age = 0
            end
            sh.center += sh.vel * dt * sp
            -- fade in over 1.5s, out over the last 2s
            local k = math.min(age / 1.5, 1, (sh.life - age) / 2)
            local a = 1 - (1 - base) * math.clamp(k, 0, 1)
            local rot = CFrame.fromAxisAngle(sh.axis, age * sh.spin * sp)
            for i, att in ipairs(sh.atts) do
                local wp = sh.center + rot * sh.pts[i]
                att.Position = wp
                local dot = sh.dots[i]
                dot.CFrame = CFrame.new(wp)
                dot.Color = cfg.Color
                dot.Transparency = (cfg.Dots == false) and 1 or math.min(a + 0.1, 1)
            end
            local tr = NumberSequence.new(a)
            for _, b in ipairs(sh.beams) do b.Color = colSeq; b.Transparency = tr end
        end
    end)
end)()

-- v0.17.0 BULLET TRACERS: listen on server rebroadcast (only way to see others'
-- shots), shape-match args, gate on muzzle near character. Own IIFE for registers.
Koffee.Bullets = {
    Enabled     = false,
    Bindables   = false,   -- also watch BindableEvents (games that hop remote -> localscript)
    Color       = Color3.fromRGB(255, 176, 46),
    ColorMode   = "Static",   -- Static / Shooter Team / Distance / Random Per Shot
    TeamColor   = false,      -- pre-v0.19 key, still honoured as Shooter Team
    Style       = "Instant",  -- Instant / Travel / Grow / Retract
    TravelLen   = 0.35,       -- Travel: dash length as a fraction of the shot
    ThroughWalls = true,
    Taper       = false,
    Outline     = true,
    OutlineColor = Color3.new(0, 0, 0),
    OutlineThickness = 1,
    Gradient    = false,
    OriginDot   = false,
    ImpactSize  = 5,
    Thickness   = 2,
    Duration    = 0.7,
    Fade        = true,
    Impact      = true,
    MaxDistance = 3000,
    TeamCheck   = false,
    ShowOwn     = true,
    MaxLive     = 24,
    Blacklist   = {},     -- remote full names learning must never pin
}
registerConfig("bullets", Koffee.Bullets)
;(function()
    local B = Koffee.Bullets
    local RS  = game:GetService("ReplicatedStorage")
    local RF  = game:GetService("ReplicatedFirst")

    local MAX_HOOKS  = 500   -- connection budget across the whole tree
    local NEAR_CHAR  = 16    -- studs a muzzle may sit from a torso and still count
    local FLOOD      = 60    -- calls/sec above which a remote is state sync, not a gun
    local LOCK_HITS  = 3     -- valid shots before a remote is pinned as THE gun remote
    local NEAR_PLANE = 0.5
    local WALL_SEGS  = 5     -- occlusion resolution when Through Walls is off

    local hooks, stats, pinned, hookCount = {}, {}, nil, 0
    local shots, linePool, dotPool = {}, {}, {}
    local layer, started = nil, false

    -- v0.19.2: our OWN layer. These used to live in ESP.BoxLayer, which ESP DESTROYS
    -- when you switch it off: taking every pooled frame with it. Reparenting a
    -- destroyed frame throws, so one ESP toggle killed the render loop until reload.
    local function ensureBLayer()
        if layer and layer.Parent then return layer end
        layer = new("Frame", {
            Name = "KBulletLayer", Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 12, Parent = screen,
        })
        -- anything pooled or in flight belongs to the old layer and is unusable
        table.clear(linePool)
        table.clear(dotPool)
        for i = #shots, 1, -1 do shots[i] = nil end
        return layer
    end

    -- v0.17.1 OWN SHOTS: server excludes shooter from broadcast, so capture from
    -- outbound __namecall hook and drain on RenderStepped (safe from namecalls).
    local outQ, statsOut, pinnedOut = {}, {}, nil
    Shared._bulletOut = outQ

    -- GetFullName is stable across sessions, so a blacklist survives a rejoin.
    -- Cached weakly: it walks the ancestry and onFire is a hot path.
    local keyCache = setmetatable({}, { __mode = "k" })
    local blSet = nil
    local function blKey(ev)
        local k = keyCache[ev]
        if not k then
            local ok, n = pcall(function() return ev:GetFullName() end)
            k = (ok and n) or tostring(ev)
            keyCache[ev] = k
        end
        return k
    end
    local function blacklisted(ev)
        if not blSet then
            blSet = {}
            for _, n in ipairs(B.Blacklist or {}) do blSet[n] = true end
        end
        return blSet[blKey(ev)] == true
    end

    -- re-exec: park connections on boot ctx (KID sweep can't clean game-remote connections).
    for _, c in ipairs(KID.ctx.bulletConns or {}) do pcall(function() c:Disconnect() end) end
    KID.ctx.bulletConns = {}

    local function setStatus(s)
        Shared._bulletStatus = s
        if Shared._bulletSetStatus then pcall(Shared._bulletSetStatus, s) end
    end

    -- :: detection ::

    -- money filter: real muzzle is near a character (UI ping / loot spawn is not).
    local function charAt(pos)
        local best, bd = nil, NEAR_CHAR
        for _, p in ipairs(Players:GetPlayers()) do
            local c = p.Character
            local r = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Head"))
            if r then
                local d = (r.Position - pos).Magnitude
                if d < bd then best, bd = p, d end
            end
        end
        return best
    end

    -- shape-match: unit-length Vector3 is direction, long is point, CFrame is both.
    local function collect(n, args)
        local pts, dirs, who, budget = {}, {}, nil, 0
        local function look(v, depth)
            budget = budget + 1
            if budget > 64 then return end
            local t = typeof(v)
            if t == "Vector3" then
                local m = v.Magnitude
                if m > 0.02 and m < 1.2 then dirs[#dirs + 1] = v
                elseif m >= 1.2 then pts[#pts + 1] = v end
            elseif t == "CFrame" then
                pts[#pts + 1] = v.Position
                dirs[#dirs + 1] = v.LookVector
            elseif t == "Instance" then
                if v:IsA("Player") then who = who or v
                elseif v:IsA("BasePart") then pts[#pts + 1] = v.Position end
            elseif t == "table" and depth < 2 then
                for _, sub in pairs(v) do look(sub, depth + 1) end
            end
        end
        for i = 1, n do look(args[i], 0) end
        return pts, dirs, who
    end

    local function resolve(pts, dirs, who)
        for i = 1, #pts do
            local o = pts[i]
            local src = charAt(o)
            if src then
                local target
                for j = 1, #pts do
                    if j ~= i then target = pts[j] break end
                end
                if not target and dirs[1] then target = o + dirs[1].Unit * 900 end
                if target then
                    local len = (target - o).Magnitude
                    if len > 3 and len < 6000 then return o, target, who or src end
                end
            end
        end
        return nil
    end

    -- :: drawing ::

    local function grabLine()
        local l = table.remove(linePool)
        if not l then
            l = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0, Visible = false, ZIndex = 12,
            }, { lineOutline(), lineGradient() })
        end
        if l.Parent ~= layer then l.Parent = layer end
        return l
    end

    local function grabDot()
        local d = table.remove(dotPool)
        if not d then
            d = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0, Visible = false, ZIndex = 13,
            }, { pillCorner() })
        end
        if d.Parent ~= layer then d.Parent = layer end
        return d
    end

    local function release(s)
        for i = #(s.lines or {}), 1, -1 do
            s.lines[i].Visible = false
            linePool[#linePool + 1] = s.lines[i]
            s.lines[i] = nil
        end
        if s.dot then s.dot.Visible = false; dotPool[#dotPool + 1] = s.dot; s.dot = nil end
        if s.odot then s.odot.Visible = false; dotPool[#dotPool + 1] = s.odot; s.odot = nil end
    end

    -- every style reduces to one pair of fractions along origin -> impact, so the
    -- renderer draws all four identically
    local function span(style, prog)
        if style == "Travel" then
            local head = math.min(prog, 1)
            return math.max(head - math.clamp(B.TravelLen or 0.35, 0.02, 1), 0), head
        elseif style == "Grow" then
            return 0, math.min(prog / 0.3, 1)
        elseif style == "Retract" then
            return math.clamp((prog - 0.3) / 0.7, 0, 1), 1
        end
        return 0, 1
    end

    -- one ray per segment, cached. A bullet lives under a second and the camera
    -- does not travel far in 70ms, so re-testing every frame buys nothing at five
    -- rays per tracer per frame.
    -- `ignore` is built once per frame by the caller: without every character in it
    -- a tracer that ends in somebody's chest is occluded by that somebody.
    local function occlude(s, cam, now, ignore)
        if s.mask and now < (s.maskAt or 0) then return s.mask end
        s.maskAt = now + 0.07
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = ignore
        local m, o = s.mask or {}, cam.CFrame.Position
        for i = 1, WALL_SEGS do
            local mid = s.a:Lerp(s.b, (i - 0.5) / WALL_SEGS)
            m[i] = Workspace:Raycast(o, mid - o, rp) == nil
        end
        s.mask = m
        return m
    end

    local function dot(s, field, on, x, y, px, tr)
        if on then
            s[field] = s[field] or grabDot()
            local sz = math.max(px, 2)
            s[field].Size = UDim2.new(0, sz, 0, sz)
            s[field].Position = UDim2.new(0, x, 0, y)
            s[field].BackgroundColor3 = s.col
            s[field].BackgroundTransparency = tr
            s[field].Visible = true
        elseif s[field] then
            s[field].Visible = false
        end
    end

    -- a tracer spans hundreds of studs, so one end is regularly behind the camera
    -- where WorldToViewportPoint mirrors through the origin. Clipping the world
    -- segment to the near plane first is exact and costs one frame, where the ESP
    -- look-ray's segment sampling would just drop the visible half.
    local function clip(cam, a, b)
        local cf = cam.CFrame
        local o, f = cf.Position, cf.LookVector
        local da, db = (a - o):Dot(f), (b - o):Dot(f)
        if da < NEAR_PLANE and db < NEAR_PLANE then return nil end
        if da < NEAR_PLANE then a = a + (b - a) * ((NEAR_PLANE - da) / (db - da)) end
        if db < NEAR_PLANE then b = b + (a - b) * ((NEAR_PLANE - db) / (da - db)) end
        return a, b
    end

    -- :: intake ::

    -- a game that DOES echo your own shot back sends it a round-trip later than the
    -- outbound tap recorded it, so own shots get a much wider window than the plain
    -- two-sources-one-shot case.
    -- v0.19.2: the wide window exists ONLY to swallow the server's rebroadcast of a
    -- shot we already recorded outbound, so it may only apply ACROSS sources. Two
    -- outbound shots 100ms apart at the same wall are two bullets, not a duplicate:
    -- the old shared window ate three of every four rounds from an automatic weapon,
    -- which is why tracers showed "sometimes". Same-source now only catches a literal
    -- repeat, so shotgun pellets and fast fire both survive.
    local function dupe(o, t, now, tag)
        for i = #shots, math.max(1, #shots - 8), -1 do
            local s = shots[i]
            local cross = s.tag ~= tag
            if now - s.t < (cross and 0.4 or 0.02)
               and (s.a - o).Magnitude < (cross and 3 or 1)
               and (s.b - t).Magnitude < (cross and 12 or 1) then
                return true
            end
        end
        return false
    end

    -- resolved once at intake: a shot's colour must not shift under it while it is
    -- still on screen
    local function colorFor(o, src)
        local m = B.ColorMode
        if B.TeamColor and m == "Static" then m = "Shooter Team" end
        if m == "Shooter Team" and src and src.TeamColor then return src.TeamColor.Color end
        if m == "Random Per Shot" then return Color3.fromHSV(math.random(), 0.7, 1) end
        if m == "Distance" then
            local cam = Workspace.CurrentCamera
            local d = cam and (o - cam.CFrame.Position).Magnitude or 0
            local f = math.clamp(d / math.max(B.MaxDistance, 1), 0, 1)
            return Color3.fromHSV(0.33 * (1 - f), 0.85, 1)   -- green near, red far
        end
        return B.Color
    end

    local function push(o, t, src, tag)
        if src == LocalPlayer and not B.ShowOwn then return false end
        if B.TeamCheck and src and src.Team and LocalPlayer.Team
            and src.Team == LocalPlayer.Team then return false end
        local cam = Workspace.CurrentCamera
        if cam and (o - cam.CFrame.Position).Magnitude > B.MaxDistance then return false end
        local now = os.clock()
        tag = tag or "in"
        if dupe(o, t, now, tag) then return false end
        shots[#shots + 1] = { a = o, b = t, t = now, tag = tag,
                              col = colorFor(o, src), lines = {} }
        local cap = math.clamp(B.MaxLive or 24, 1, 64)
        while #shots > cap do release(shots[1]); table.remove(shots, 1) end
        return true
    end

    local function onFire(ev, ...)
        if Koffee.dead() or not B.Enabled then return end
        -- once a remote has proven itself, every other one is noise
        if pinned and pinned ~= ev then return end
        local st = stats[ev]
        if not st then st = { n = 0, win = 0, hits = 0, dead = false, quiet = 0 }; stats[ev] = st end
        local now = os.clock()
        if st.dead or now < (st.quiet or 0) then return end
        -- same exemption as the outbound path: a pinned remote is proven
        if pinned ~= ev then
            if now - st.win > 1 then st.win, st.n = now, 0 end
            st.n = st.n + 1
            if st.n > FLOOD then st.quiet = now + 5; return end
        end
        local args = table.pack(...)
        if args.n == 0 or args.n > 12 then return end
        local pts, dirs, who = collect(args.n, args)
        if #pts == 0 then return end
        local o, t, src = resolve(pts, dirs, who)
        if not o then return end
        if push(o, t, src) then
            st.hits = st.hits + 1
            if not pinned and st.hits >= LOCK_HITS then
                pinned = ev
                setStatus("(locked on " .. ev.Name .. ")")
            end
        end
    end

    -- :: own shots ::

    -- for our own fire the shooter is never in doubt, so the origin does not have to
    -- be guessed: if the remote sent one near us we use it (that is the real muzzle),
    -- otherwise we fall back to our own head. That means a game which sends nothing
    -- but a hit position still draws a correct tracer.
    local function ownShot(pts, dirs)
        local c = LocalPlayer.Character
        local r = c and (c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart"))
        local cam = Workspace.CurrentCamera
        local me = (r and r.Position) or (cam and cam.CFrame.Position)
        if not me then return nil end
        local origin, target = nil, nil
        for i = 1, #pts do
            local p = pts[i]
            if not origin and (p - me).Magnitude < NEAR_CHAR then origin = p
            elseif not target then target = p end
        end
        if not target and dirs[1] then
            -- a direction settles it: the near point really was the muzzle
            target = (origin or me) + dirs[1].Unit * 900
        elseif not target and origin then
            -- v0.19.4: a lone near point with nothing to aim at is the IMPACT, not
            -- the muzzle. Claiming it as the muzzle left nothing to aim at and the
            -- shot was dropped, which is every close-range round in a tight map.
            origin, target = nil, origin
        end
        origin = origin or me
        if not target then return nil end
        local len = (target - origin).Magnitude
        -- floor was 3 studs, which threw away point-blank shots as well
        if len > 0.5 and len < 6000 then return origin, target end
        return nil
    end

    local function drainOut()
        while #outQ > 0 do
            local e = table.remove(outQ, 1)
            local ev, args = e.r, e.a
            local st = statsOut[ev]
            if not st then st = { n = 0, win = 0, hits = 0, dead = false, quiet = 0 }; statsOut[ev] = st end
            if blacklisted(ev) then st.dead = true end
            local now = os.clock()
            -- v0.19.4: the flood gate exists to stop a chatty remote being PINNED, so
            -- it must stop applying once one has proven itself. It used to keep
            -- counting after the lock and latch st.dead for the rest of the session,
            -- which is a weapon that works for a few seconds and then never again.
            -- Blacklisting stays permanent; a flood is now a 5s backoff.
            if not st.dead and now >= (st.quiet or 0)
               and not (pinnedOut and pinnedOut ~= ev) then
                local flooding = false
                if pinnedOut ~= ev then
                    if now - st.win > 1 then st.win, st.n = now, 0 end
                    st.n = st.n + 1
                    flooding = st.n > FLOOD
                end
                if flooding then
                    st.quiet = now + 5
                else
                    local pts, dirs = collect(args.n, args)
                    local o, t = ownShot(pts, dirs)
                    -- pre-lock only: a shot goes roughly where you are looking, which
                    -- is what stops a movement or camera remote from being pinned.
                    -- Dropped once a remote wins, so silent aim's redirect (which
                    -- deliberately points away from your crosshair) still draws.
                    -- v0.19.4: this compared against the camera as it is NOW, but the
                    -- queue drains a frame or more after the shot. Flick while firing
                    -- and your own bullet failed its own aim test. The tap records the
                    -- look direction from the firing frame instead. Threshold relaxed
                    -- 0.4 -> 0.25 as well: the blacklist covers a bad pin now, so the
                    -- gate does not have to be the only defence.
                    if o and not pinnedOut then
                        local lk, d = e.lk, t - o
                        if not lk or d.Magnitude < 1e-3
                            or d.Unit:Dot(lk) < 0.25 then o = nil end
                    end
                    if o and push(o, t, LocalPlayer, "out") then
                        st.hits = st.hits + 1
                        if not pinnedOut and st.hits >= LOCK_HITS then
                            pinnedOut = ev
                            setStatus("(locked on " .. ev.Name .. ")")
                        end
                    end
                end
            end
        end
    end

    local function hook(inst)
        if hookCount >= MAX_HOOKS or hooks[inst] then return end
        local sig
        if inst:IsA("RemoteEvent") or inst:IsA("UnreliableRemoteEvent") then
            sig = inst.OnClientEvent
        elseif B.Bindables and inst:IsA("BindableEvent") then
            sig = inst.Event
        else
            return
        end
        if blacklisted(inst) then return end
        local ok, conn = pcall(function()
            return sig:Connect(function(...) onFire(inst, ...) end)
        end)
        if ok and conn then
            hooks[inst] = conn
            table.insert(KID.ctx.bulletConns, conn)
            hookCount = hookCount + 1
        end
    end

    local function sweep()
        setStatus("(scanning)")
        task.spawn(function()
            local seen = 0
            for _, root in ipairs({ RS, RF, Lighting, Workspace }) do
                local ok, kids = pcall(function() return root:GetDescendants() end)
                if ok then
                    for _, d in ipairs(kids) do
                        if hookCount >= MAX_HOOKS then break end
                        hook(d)
                        seen = seen + 1
                        -- a loaded map is 50k+ instances; yield so the sweep never
                        -- shows up as a hitch on the frame the feature is switched on
                        if seen % 4000 == 0 then task.wait() end
                    end
                end
            end
            if not pinned then setStatus("(watching " .. hookCount .. ")") end
        end)
    end

    local function start()
        if started then return end
        started = true
        sweep()
        -- remotes created after join land in ReplicatedStorage essentially always,
        -- and DescendantAdded on Workspace would fire for every part the game spawns
        RS.DescendantAdded:Connect(hook)
        RF.DescendantAdded:Connect(hook)
    end

    -- full reset: drops every hook so the Bindables toggle can go both ways, clears
    -- the pin so a different remote can win, then re-sweeps from scratch
    -- v0.19.3: the two paths pin INDEPENDENTLY and can hold different remotes, so
    -- "blacklist the current one" was ambiguous and picked inbound whatever the
    -- status line happened to be showing. Both pins are published instead and the
    -- popup offers a button per pin, so the click is never a guess.
    Shared._bulletPins = function()
        local out, seen = {}, {}
        local function add(ev, tag)
            if not ev then return end
            local k = blKey(ev)
            if seen[k] then seen[k].tag = "both" return end
            local e = { tag = tag, key = k, short = k:match("([^%.]+)$") or k }
            seen[k] = e
            out[#out + 1] = e
        end
        add(pinned, "in")
        add(pinnedOut, "out")
        return out
    end

    Shared._bulletBlacklistKey = function(key)
        if not key then return false end
        for _, n in ipairs(B.Blacklist) do if n == key then return false end end
        table.insert(B.Blacklist, key)
        blSet = nil
        Shared._bulletRelearn()
        return true
    end

    Shared._bulletUnBlacklist = function(full)
        for i = #B.Blacklist, 1, -1 do
            if B.Blacklist[i] == full then table.remove(B.Blacklist, i) end
        end
        blSet = nil
        Shared._bulletRelearn()
    end

    Shared._bulletBlNames = function()
        local t = {}
        for _, n in ipairs(B.Blacklist or {}) do t[#t + 1] = n end
        return t
    end

    Shared._bulletRelearn = function()
        for inst, c in pairs(hooks) do
            pcall(function() c:Disconnect() end)
            hooks[inst] = nil
        end
        KID.ctx.bulletConns = {}
        hookCount, pinned, stats = 0, nil, {}
        pinnedOut, statsOut = nil, {}
        if started then sweep() else setStatus("") end
    end

    -- :: render ::

    RunService.RenderStepped:Connect(function()
        if Koffee.dead() then return end
        if not B.Enabled then
            for i = #shots, 1, -1 do release(shots[i]); shots[i] = nil end
            for i = #outQ, 1, -1 do outQ[i] = nil end
            return
        end
        if not started then start() end
        drainOut()
        ensureBLayer()
        local cam = Workspace.CurrentCamera
        -- read once here so the namecall tap can stamp a shot with the direction you
        -- were facing when you fired, without touching the camera from inside the hook
        Shared._bulletLook = cam and cam.CFrame.LookVector or nil
        local now, dur = os.clock(), math.max(B.Duration, 0.05)
        local thick = math.max(B.Thickness, 0.5)
        local ignore = nil
        if not B.ThroughWalls then
            ignore = { cam }
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl.Character then ignore[#ignore + 1] = pl.Character end
            end
        end
        for i = #shots, 1, -1 do
            local s = shots[i]
            local age = now - s.t
            if age > dur or not cam then
                release(s)
                table.remove(shots, i)
            else
                local prog = age / dur
                local tr = B.Fade and math.clamp(prog, 0, 0.96) or 0
                local lo, hi = span(B.Style, prog)

                -- style and the wall test collapse into the same thing: a list of
                -- sub-spans to draw. One entry through walls, up to WALL_SEGS when
                -- occlusion is on.
                local segs = {}
                if hi > lo then
                    if B.ThroughWalls then
                        segs[1] = { lo, hi }
                    else
                        local m, run = occlude(s, cam, now, ignore), nil
                        for k = 1, WALL_SEGS do
                            local x0 = math.max((k - 1) / WALL_SEGS, lo)
                            local x1 = math.min(k / WALL_SEGS, hi)
                            if m[k] and x1 > x0 then
                                if run and math.abs(run[2] - x0) < 1e-4 then run[2] = x1
                                else run = { x0, x1 }; segs[#segs + 1] = run end
                            else
                                run = nil
                            end
                        end
                    end
                end

                while #s.lines > #segs do
                    local l = table.remove(s.lines)
                    l.Visible = false
                    linePool[#linePool + 1] = l
                end
                while #s.lines < #segs do s.lines[#s.lines + 1] = grabLine() end

                local tipX, tipY, tipOn = 0, 0, false
                for k = 1, #segs do
                    local sp = segs[k]
                    local ca, cb = clip(cam, s.a:Lerp(s.b, sp[1]), s.a:Lerp(s.b, sp[2]))
                    local l = s.lines[k]
                    if not ca then
                        l.Visible = false
                    else
                        local pa = cam:WorldToViewportPoint(ca)
                        local pb = cam:WorldToViewportPoint(cb)
                        local dx, dy = pb.X - pa.X, pb.Y - pa.Y
                        local tk = math.max(B.Taper and (thick * (1 - 0.7 * sp[1])) or thick, 0.5)
                        l.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy) + 1, 0, tk)
                        l.Position = UDim2.new(0, (pa.X + pb.X) * 0.5, 0, (pa.Y + pb.Y) * 0.5)
                        l.Rotation = math.deg(math.atan2(dy, dx))
                        l.BackgroundColor3 = s.col
                        l.BackgroundTransparency = tr
                        l.Visible = true
                        applyLineOutline(l, B.Outline, B.OutlineColor,
                            math.max(B.OutlineThickness or 1, 0.5))
                        applyLineGradient(l, B.Gradient)
                        if sp[2] >= hi then tipX, tipY, tipOn = pb.X, pb.Y, pb.Z > 0 end
                    end
                end

                -- impact only once the line has actually arrived, so Travel does not
                -- mark the wall before the bullet gets there
                dot(s, "dot", B.Impact and tipOn and hi >= 1, tipX, tipY, B.ImpactSize or 5, tr)
                if B.OriginDot and lo <= 0 then
                    local op = cam:WorldToViewportPoint(s.a)
                    dot(s, "odot", op.Z > 0, op.X, op.Y, (B.ImpactSize or 5) * 0.8, tr)
                else
                    dot(s, "odot", false, 0, 0, 0, tr)
                end
            end
        end
    end)
end)()

-- v0.10.0 CUSTOM SKYBOXES: 3-20MB sets download on first pick, cached thereafter.
-- Own IIFE for register budget (not prefetched like other assets).
World.SkyBox = { Name = "None", Celestial = false }
registerConfig("world_skybox", World.SkyBox)
;(function()
    local SKY_BASE = "https://raw.githubusercontent.com/lowkeymyself/Takurin/main/topsky/"
    local FACES = { "bk", "dn", "ft", "lf", "rt", "up" }
    Shared._skyNames = { "None", "Aurora", "Emo", "Goodnight", "Hades", "Hazy",
        "Moonlight", "Overcast", "Pink Sunrise", "Space Blue", "Spooky", "Universe", "Void Veins" }

    local ownSky, hidden, applied, busy = nil, nil, "None|0", false
    local parked = setmetatable({}, { __mode = "k" })
    local nextScan = 0

    -- v0.16.2: show download status (cold pick is 20-40s, looks broken without it).
    local function setStatus(s)
        Shared._skyStatusText = s
        if Shared._skySetStatus then pcall(Shared._skySetStatus, s) end
    end

    -- Name + nonce: bump nonce on re-pick to retry failed downloads.
    local function keyOf()
        return World.SkyBox.Name .. "|" .. tostring(World.SkyBox._nonce or 0)
    end

    local function httpGet(url)
        local req = (syn and syn.request) or (http and http.request) or http_request or request
        if req then
            local ok, r = pcall(req, { Url = url, Method = "GET" })
            if ok and r and r.Body and #r.Body > 1024 then return r.Body end
        end
        local ok, b = pcall(function() return game:HttpGetAsync(url) end)
        if ok and b and #b > 1024 then return b end
        return nil
    end

    -- download + resolve all six faces, return reason on failure (no partial skies).
    local function ensureFaces(name)
        -- v0.88.0: built-in set, one tileable face texture fetched with the fx art
        if name == "Void Veins" then
            local ok, id = pcall(getcustomasset, "Koffee/fx/fx_sky_veins.png")
            if not (ok and type(id) == "string" and #id > 0) then return nil, "asset failed" end
            local ids = {}
            for _, f in ipairs(FACES) do ids[f] = id end
            return ids
        end
        if not (writefile and isfile and getcustomasset) then return nil, "no file api" end
        if makefolder then
            pcall(makefolder, "Koffee/sky")
            pcall(makefolder, "Koffee/sky/" .. name)
        end
        local ids = {}
        for i, f in ipairs(FACES) do
            local path = "Koffee/sky/" .. name .. "/sky512_" .. f .. ".tex"
            if not isfile(path) then
                setStatus("(downloading " .. i .. "/6)")
                local body = httpGet(SKY_BASE .. name:gsub(" ", "%%20") .. "/sky512_" .. f .. ".tex")
                if not body then return nil, "Download failed" end
                if not pcall(writefile, path, body) then return nil, "write failed" end
            end
            local ok, id = pcall(getcustomasset, path)
            if not (ok and type(id) == "string" and #id > 0) then return nil, "asset failed" end
            ids[f] = id
        end
        return ids
    end

    -- v0.10.1: park everything (Atmosphere, Clouds, Sky under Workspace). Parked
    -- (not destroyed) so "None" restores exactly. v0.16.2: dedupe to avoid unbounded growth.
    local function park(inst)
        if inst == ownSky or parked[inst] then return end
        parked[inst] = true
        hidden = hidden or {}
        table.insert(hidden, { sky = inst, parent = inst.Parent })
        inst.Parent = nil
    end

    local function purgeSky()
        for _, s in ipairs(Lighting:GetChildren()) do
            if s:IsA("Sky") or s:IsA("Atmosphere") then park(s) end
        end
        for _, s in ipairs(Workspace:GetChildren()) do
            if s:IsA("Sky") or s:IsA("Atmosphere") then park(s) end
        end
        local terrain = Workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            for _, c in ipairs(terrain:GetChildren()) do
                if c:IsA("Clouds") then park(c) end
            end
        end
    end

    -- v0.16.2: engine caches sky faces, won't repaint on swap ("stuck on last skybox").
    -- Toggle CelestialBodiesShown across a frame to force repaint.
    local function kick(sky, want)
        if not (sky and sky.Parent) then return end
        pcall(function()
            sky.CelestialBodiesShown = not want
            task.wait()
            if sky.Parent then sky.CelestialBodiesShown = want end
        end)
    end

    local function restoreGame()
        for _, e in ipairs(hidden or {}) do
            parked[e.sky] = nil
            if e.sky and not e.sky.Parent then pcall(function() e.sky.Parent = e.parent end) end
        end
        hidden = nil
    end

    local function apply(name, key)
        if busy then return end
        busy = true
        task.spawn(function()
            -- v0.28.0: protect the whole body. An uncaught throw used to leave
            -- busy=true forever, freezing the heartbeat and sticking the sky on the
            -- last pick. busy is released unconditionally after the pcall below.
            local ok = pcall(function()
            if name == "None" then
                if ownSky then ownSky:Destroy(); ownSky = nil end
                task.wait()
                restoreGame()
                local s = Lighting:FindFirstChildOfClass("Sky")
                if s then kick(s, s.CelestialBodiesShown) end
                applied, busy = key, false
                setStatus("")
                return
            end
            setStatus("(loading)")
            local ids, why = ensureFaces(name)
            -- applied set on failure too, heartbeat edge-triggers on key (prevents retry loop).
            applied = key
            if not ids then
                busy = false
                setStatus("(" .. (why or "failed") .. ", pick it again)")
                return
            end
            if World.SkyBox.Name ~= name then busy = false; setStatus("") return end
            purgeSky()
            if ownSky then ownSky:Destroy(); ownSky = nil end
            task.wait()   -- the engine needs a frame to actually drop the old Sky
            local sky = KID.track(Instance.new("Sky"))
            sky.Name = KID.name("sky")
            sky.SkyboxBk, sky.SkyboxDn = ids.bk, ids.dn
            sky.SkyboxFt, sky.SkyboxLf = ids.ft, ids.lf
            sky.SkyboxRt, sky.SkyboxUp = ids.rt, ids.up
            -- Roblox's sun/moon/stars render on top of baked faces (off by default,
            -- right-click dropdown to restore them).
            local want = World.SkyBox.Celestial == true
            sky.CelestialBodiesShown = want
            sky.StarCount       = want and 3000 or 0
            sky.SunAngularSize  = want and 21 or 0
            sky.MoonAngularSize = want and 11 or 0
            sky.Parent = Lighting
            ownSky = sky
            setStatus("")
            kick(sky, want)
            end)
            -- guaranteed release + edge-consume so an error can't retry-loop or freeze.
            if not ok then applied = key; setStatus("(error, pick again)") end
            busy = false
        end)
    end

    -- Heartbeat-driven (not callback), so loaded configs apply sky too.
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() or busy then return end
        local key = keyOf()
        if key ~= applied then apply(World.SkyBox.Name, key); return end
        -- v0.10.1: keep it ours. Games re-add Sky (day/night), re-park new ones.
        -- Throttled 0.25s (used to walk every frame).
        if not ownSky then return end
        local now = os.clock()
        if now < nextScan then return end
        nextScan = now + 0.25
        if ownSky.Parent ~= Lighting then ownSky.Parent = Lighting end
        for _, s in ipairs(Lighting:GetChildren()) do
            if s ~= ownSky and (s:IsA("Sky") or s:IsA("Atmosphere")) then park(s) end
        end
    end)
end)()

registerModule("fullbright", "Fullbright",
    function()
        World.Fullbright.Saved = {
            Ambient           = Lighting.Ambient,
            OutdoorAmbient    = Lighting.OutdoorAmbient,
            ColorShift_Top    = Lighting.ColorShift_Top,
            ColorShift_Bottom = Lighting.ColorShift_Bottom,
            Brightness        = Lighting.Brightness,
            GlobalShadows     = Lighting.GlobalShadows,
        }
        Lighting.Ambient           = Color3.fromRGB(178, 178, 178)
        Lighting.OutdoorAmbient    = Color3.fromRGB(178, 178, 178)
        Lighting.ColorShift_Top    = Color3.fromRGB(0, 0, 0)
        Lighting.ColorShift_Bottom = Color3.fromRGB(0, 0, 0)
        Lighting.Brightness        = 1
        Lighting.GlobalShadows     = false
        -- v0.0.17: re-assert every frame so server day/night cycles can't
        -- override us (consistent with Custom Time's Heartbeat).
        World.Fullbright.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            if Lighting.Ambient ~= Color3.fromRGB(178, 178, 178) then
                Lighting.Ambient = Color3.fromRGB(178, 178, 178)
            end
            Lighting.OutdoorAmbient    = Color3.fromRGB(178, 178, 178)
            Lighting.ColorShift_Top    = Color3.fromRGB(0, 0, 0)
            Lighting.ColorShift_Bottom = Color3.fromRGB(0, 0, 0)
            Lighting.Brightness        = 1
            Lighting.GlobalShadows     = false
        end)
    end,
    function()
        if World.Fullbright.Conn then
            World.Fullbright.Conn:Disconnect()
            World.Fullbright.Conn = nil
        end
        local s = World.Fullbright.Saved
        if not s then return end
        Lighting.Ambient           = s.Ambient
        Lighting.OutdoorAmbient    = s.OutdoorAmbient
        Lighting.ColorShift_Top    = s.ColorShift_Top
        Lighting.ColorShift_Bottom = s.ColorShift_Bottom
        Lighting.Brightness        = s.Brightness
        Lighting.GlobalShadows     = s.GlobalShadows
        World.Fullbright.Saved     = nil
    end
)

registerModule("nofog", "No Fog",
    function()
        World.NoFog.Saved = {
            FogEnd   = Lighting.FogEnd,
            FogStart = Lighting.FogStart,
        }
        Lighting.FogEnd   = 100000
        Lighting.FogStart = 100000
        -- v0.0.17: re-assert so games that dynamically push fog can't fight us.
        World.NoFog.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            if Lighting.FogEnd ~= 100000 then Lighting.FogEnd = 100000 end
            if Lighting.FogStart ~= 100000 then Lighting.FogStart = 100000 end
        end)
    end,
    function()
        if World.NoFog.Conn then
            World.NoFog.Conn:Disconnect()
            World.NoFog.Conn = nil
        end
        local s = World.NoFog.Saved
        if not s then return end
        Lighting.FogEnd   = s.FogEnd
        Lighting.FogStart = s.FogStart
        World.NoFog.Saved = nil
    end
)

registerModule("customtime", "Custom Time",
    function()
        World.Time.Saved = { ClockTime = Lighting.ClockTime }
        Lighting.ClockTime = World.Time.Target
        World.Time.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            if math.abs(Lighting.ClockTime - World.Time.Target) > 0.01 then
                Lighting.ClockTime = World.Time.Target
            end
        end)
    end,
    function()
        if World.Time.Conn then World.Time.Conn:Disconnect() World.Time.Conn = nil end
        local s = World.Time.Saved
        if s then
            Lighting.ClockTime = s.ClockTime
            World.Time.Saved = nil
        end
    end
)

-- WORLD EFFECTS (v0.0.100): color correction, ambient tint, sky/clouds kill,
-- low graphics. Same save/restore + Heartbeat re-assert pattern as above.

registerModule("colorcorrection", "Color Correction",
    function()
        local fx = Lighting:FindFirstChildOfClass("ColorCorrectionEffect")
        if fx then
            World.CC.Owned = false
        else
            fx = Instance.new("ColorCorrectionEffect")
            fx.Name = "KoffeeCC"
            fx.Parent = Lighting
            World.CC.Owned = true
        end
        World.CC.Saved = {
            Enabled = fx.Enabled, Saturation = fx.Saturation,
            Contrast = fx.Contrast, Brightness = fx.Brightness, TintColor = fx.TintColor,
        }
        World.CC.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            local f = Lighting:FindFirstChildOfClass("ColorCorrectionEffect")
            if not f then
                f = Instance.new("ColorCorrectionEffect")
                f.Name = "KoffeeCC"
                f.Parent = Lighting
                World.CC.Owned = true
            end
            f.Saturation = World.CC.Saturation
            f.Contrast   = World.CC.Contrast
            f.Brightness = World.CC.Brightness
            f.TintColor  = World.CC.Tint
        end)
    end,
    function()
        if World.CC.Conn then World.CC.Conn:Disconnect(); World.CC.Conn = nil end
        local fx = Lighting:FindFirstChildOfClass("ColorCorrectionEffect")
        local s = World.CC.Saved
        if fx and s then
            if World.CC.Owned then
                fx:Destroy()
            else
                fx.Enabled = s.Enabled; fx.Saturation = s.Saturation
                fx.Contrast = s.Contrast; fx.Brightness = s.Brightness
                fx.TintColor = s.TintColor
            end
        end
        World.CC.Saved = nil; World.CC.Owned = nil
    end
)

-- v0.10.0: indoor and outdoor ambient are separate colours now. They were pinned to
-- one swatch driving both, which throws away the only interesting thing about the
-- pair: Ambient lifts shadowed/indoor surfaces, OutdoorAmbient lifts sky-lit ones,
-- and splitting them is how you get a lit interior under a cold sky (or the reverse).
-- Split defaults to off so existing configs keep the single-colour behaviour.
registerModule("ambientcolor", "Ambient Color",
    function()
        World.Light.Saved = {
            Ambient = Lighting.Ambient,
            OutdoorAmbient = Lighting.OutdoorAmbient,
            FogStart = Lighting.FogStart, FogEnd = Lighting.FogEnd,
            FogColor = Lighting.FogColor, Brightness = Lighting.Brightness,
            Exposure = Lighting.ExposureCompensation,
        }
        World.Light.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            local L = World.Light
            local i = L.Intensity
            -- Color3 has NO arithmetic metamethods in Roblox, so `Color3 * number`
            -- throws. Scale the components by hand and clamp (Intensity goes to 2).
            local function scale(c)
                return Color3.new(math.clamp(c.R * i, 0, 1),
                                  math.clamp(c.G * i, 0, 1),
                                  math.clamp(c.B * i, 0, 1))
            end
            if L.Split then
                Lighting.Ambient        = scale(L.Indoor)
                Lighting.OutdoorAmbient = scale(L.Outdoor)
            else
                local c = scale(L.Color)
                Lighting.Ambient = c
                Lighting.OutdoorAmbient = c
            end
            Lighting.Brightness = L.Brightness
            Lighting.ExposureCompensation = L.Exposure
            -- fog is opt-in: the No Fog module also writes these, so leaving it off
            -- keeps the two from fighting over the same properties every frame.
            if L.Fog then
                Lighting.FogStart = math.min(L.FogStart, L.FogEnd)
                Lighting.FogEnd   = L.FogEnd
                Lighting.FogColor = L.FogColor
            end
        end)
    end,
    function()
        if World.Light.Conn then World.Light.Conn:Disconnect(); World.Light.Conn = nil end
        local s = World.Light.Saved
        if not s then return end
        Lighting.Ambient = s.Ambient
        Lighting.OutdoorAmbient = s.OutdoorAmbient
        Lighting.Brightness = s.Brightness
        Lighting.ExposureCompensation = s.Exposure
        if World.Light.Fog then
            Lighting.FogStart = s.FogStart
            Lighting.FogEnd   = s.FogEnd
            Lighting.FogColor = s.FogColor
        end
        World.Light.Saved = nil
    end
)

registerModule("removesky", "Remove Sky",
    function()
        local skies = {}
        for _, sky in ipairs(Lighting:GetChildren()) do
            if sky:IsA("Sky") then table.insert(skies, { sky = sky, parent = sky.Parent }) end
        end
        for _, w in ipairs(workspace:GetChildren()) do
            if w:IsA("Sky") then table.insert(skies, { sky = w, parent = w.Parent }) end
        end
        World.Sky.Saved = skies
        for _, e in ipairs(skies) do e.sky.Parent = nil end
        World.Sky.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            for _, e in ipairs(World.Sky.Saved or {}) do e.sky.Parent = nil end
        end)
    end,
    function()
        if World.Sky.Conn then World.Sky.Conn:Disconnect(); World.Sky.Conn = nil end
        local s = World.Sky.Saved
        if not s then return end
        for _, e in ipairs(s) do
            if e.parent then e.sky.Parent = e.parent end
        end
        World.Sky.Saved = nil
    end
)

registerModule("noclouds", "Disable Clouds",
    function()
        local list = {}
        for _, c in ipairs(workspace:GetChildren()) do
            if c:IsA("Clouds") then table.insert(list, { c = c, on = c.Enable }) end
        end
        World.Clouds.Saved = list
        for _, e in ipairs(list) do e.c.Enable = false end
        World.Clouds.Conn = RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end   -- v0.85.0: superseded runs stop re-asserting
            for _, c in ipairs(workspace:GetChildren()) do
                if c:IsA("Clouds") and c.Enable then c.Enable = false end
            end
        end)
    end,
    function()
        if World.Clouds.Conn then World.Clouds.Conn:Disconnect(); World.Clouds.Conn = nil end
        local s = World.Clouds.Saved
        if not s then return end
        for _, e in ipairs(s) do e.c.Enable = e.on end
