)

registerModule("lowgfx", "Low Graphics",
    function()
        local rs = settings().Rendering
        World.Gfx.Saved = rs.QualityLevel
        pcall(function() rs.QualityLevel = 1 end)
    end,
    function()
        local s = World.Gfx.Saved
