-- v0.71.0 FREECAM. Detached Scriptable camera: RMB-hold to look, WASD + Space
-- / Ctrl to move, Shift for speed, wheel dollies along the look in snaps.
-- Runs one render notch AFTER the aimbot so it owns the final CFrame: camera
-- aimbot fights it (both write the camera), silent aim + triggerbot do not,
-- they read the weapon and the freecam view, so that is the pairing.
;(function()
local FC = { Speed = 120, FastMul = 4, WheelStep = 20 }
registerConfig("world_freecam", FC)
Shared.FreeCam = FC
local pos, yaw, pitch = Vector3.new(), 0, 0
local rmb, lastM = false, nil
local savedControls, anchorPart = nil, nil
local function cam() return Workspace.CurrentCamera end
-- window is built later in the file, so it cannot be an upvalue here. Resolve
-- through screen at call time instead; missing window means not open yet.
local function menuHidden()
    local w = screen and screen:FindFirstChild("Window")
    return not (w and w.GroupTransparency < 1)
end
local function grab()
    local c = cam(); if not c then return end
    pos = c.CFrame.Position
    local lv = c.CFrame.LookVector
    yaw = math.atan2(-lv.X, -lv.Z)
    pitch = math.asin(math.clamp(lv.Y, -1, 1))
end
local function push()
    local c = cam(); if not c then return end
    c.CFrame = CFrame.new(pos) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)
end
local function lookDir()
    return (CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)).LookVector
end
UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton2 then rmb = true; lastM = nil end
end)
UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton2 then rmb = false; lastM = nil end
end)
UserInputService.InputChanged:Connect(function(input)
    local m = Modules.freecam
    if not (m and m.Enabled) then return end
    if input.UserInputType == Enum.UserInputType.MouseMovement then
        if rmb and menuHidden() then
            local mp = input.Position
            if lastM then
                yaw = yaw - (mp.X - lastM.X) * 0.0045
                pitch = math.clamp(pitch - (mp.Y - lastM.Y) * 0.0045, -1.55, 1.55)
            end
            lastM = mp
        else lastM = nil end
    elseif input.UserInputType == Enum.UserInputType.MouseWheel then
        -- wheel dollies along the look in snaps. Scriptable cameras ignore zoom,
        -- so while the menu is open the wheel stays the UI's (scrolls tab lists).
        if menuHidden() then pos = pos + lookDir() * (input.Position.Z * (FC.WheelStep or 20)) end
    end
end)
local function step(dt)
    local c = cam(); if not c then return end
    local speed = (FC.Speed or 120)
    if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
    or UserInputService:IsKeyDown(Enum.KeyCode.RightShift) then
        speed = speed * (FC.FastMul or 4)
    end
    local cf = CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)
    local v = Vector3.new()
    if UserInputService:IsKeyDown(Enum.KeyCode.W) then v = v + cf.LookVector end
    if UserInputService:IsKeyDown(Enum.KeyCode.S) then v = v - cf.LookVector end
    if UserInputService:IsKeyDown(Enum.KeyCode.D) then v = v + cf.RightVector end
    if UserInputService:IsKeyDown(Enum.KeyCode.A) then v = v - cf.RightVector end
    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then v = v + Vector3.new(0, 1, 0) end
    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
    or UserInputService:IsKeyDown(Enum.KeyCode.C) then v = v - Vector3.new(0, 1, 0) end
    if v.Magnitude > 0 then pos = pos + v.Unit * speed * dt end
    push()
end
registerModule("freecam", "Freecam",
    function()
        grab()
        local c = cam()
        if c then pcall(function() c.CameraType = Enum.CameraType.Scriptable end) end
        -- v0.72.0: park the body. Controls:Disable cuts movement input cleanly
        -- (no physics touched, nothing replicates); anchored HRP is the fallback
        -- for runtimes without a reachable PlayerModule. Either way WASD stops
        -- walking the character while it flies the camera.
        local ok = pcall(function()
            local ps = LocalPlayer:FindFirstChild("PlayerScripts")
            local pm = ps and ps:FindFirstChild("PlayerModule")
            assert(pm, "no PlayerModule")
            savedControls = require(pm):GetControls()
            savedControls:Disable()
        end)
        if not ok then
            local ch = LocalPlayer.Character
            anchorPart = ch and ch:FindFirstChild("HumanoidRootPart") or nil
            if anchorPart then pcall(function() anchorPart.Anchored = true end) end
        end
        pcall(function() RunService:UnbindFromRenderStep("KFreeCam") end)
        RunService:BindToRenderStep("KFreeCam", Enum.RenderPriority.Last.Value + 2, step)
    end,
    function()
        pcall(function() RunService:UnbindFromRenderStep("KFreeCam") end)
        if savedControls then pcall(function() savedControls:Enable() end); savedControls = nil end
        if anchorPart then
            pcall(function() anchorPart.Anchored = false end)
            anchorPart = nil
        end
        local c = cam()
        if c then pcall(function()
            c.CameraType = Enum.CameraType.Custom
            local ch = LocalPlayer.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if hum then c.CameraSubject = hum end
        end) end
        rmb, lastM = false, nil
    end)
LocalPlayer.CharacterAdded:Connect(function()
    local m = Modules.freecam
    if m and m.Enabled and savedControls == nil then
        local ch = LocalPlayer.Character
        anchorPart = ch and ch:FindFirstChild("HumanoidRootPart") or nil
        if anchorPart then pcall(function() anchorPart.Anchored = true end) end
    end
end)
end)()

-- MOVEMENT MODULES (v0.0.49)
-- No Jump Cooldown / Infinite Jump. Both bypass client anti-jumps that throttle via
-- GetPropertyChangedSignal("Jump"): we drive ChangeState(Jumping) instead, so their
-- watcher never fires.
--   Infinite Jump    = jump on every request, air included.
--   No Jump Cooldown = same bypass, grounded-only (kills throttle, keeps gravity).
-- One shared JumpRequest handler reads both states; OnEnable/OnDisable are no-ops.
-- JumpRequest is universal (keyboard/mobile/gamepad); humanoid re-resolved per press
-- for respawn-safety.
registerModule("nojumpcd", "No Jump Cooldown", function() end, function() end)
registerModule("infjump",  "Infinite Jump",    function() end, function() end)

UserInputService.JumpRequest:Connect(function()
    local inf = Modules.infjump  and Modules.infjump.Enabled
    local njc = Modules.nojumpcd and Modules.nojumpcd.Enabled
    if not (inf or njc) then return end
    local char = LocalPlayer.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    if not inf and hum.FloorMaterial == Enum.Material.Air then return end
    hum:ChangeState(Enum.HumanoidStateType.Jumping)
end)

-- MOVEMENT SUITE (v0.0.52)
-- Character-tab movement features with a two-step activation model (per He): the
-- checkbox ARMS a feature, a per-feature keybind ACTIVATES it (pill: left-click =
-- rebind, right-click = Hold/Toggle). Enable, then hold/press the key to use.
-- Antifling is the lone exception: no key, on = on. Own IIFE for the ~200-local
-- budget (same reason as Combat). Tab builder is published on Koffee._characterTab
-- so the Character addTab (below, in normal tab order) can call it.
;(function()

local UIS = UserInputService
local function char()   return LocalPlayer.Character end
local function humOf()  local c = char(); return c and c:FindFirstChildOfClass("Humanoid") end
local function rootOf()
    local c = char(); if not c then return nil end
    return c:FindFirstChild("HumanoidRootPart") or (humOf() and humOf().RootPart) or c.PrimaryPart
end
local function camCF() local cc = Workspace.CurrentCamera; return cc and cc.CFrame end

-- persisted config. Key = EnumItem/string/nil, Mode = "Hold"|"Toggle", speeds numeric.
local Move = {
    WalkSpeed    = { Speed = 60,  Key = nil, Mode = "Hold"   },
    TeleportWalk = { Speed = 80,  Key = nil, Mode = "Hold"   },
    Fly          = { Speed = 120, Key = nil, Mode = "Toggle", Kind = "Default Fly" },
    Spin         = { Speed = 600, Key = nil, Mode = "Toggle",
        Smoothing = 1, JitterAmp = 15, JitterSpeed = 8 },
    AAJitter     = {              Key = nil, Mode = "Toggle" },
    Noclip       = {              Key = nil, Mode = "Toggle" },
    Float        = { Speed = 50,  Key = nil, Mode = "Hold"   },
    ClickTP      = {              Key = nil, Mode = "Toggle" },
    Jitter       = { Range = 12,  Key = nil, Mode = "Hold"   },
}
registerConfig("movement", Move)

-- id -> its config sub-table (activation pills + input matching)
local CustomAnimCFG = { Key = nil, Mode = "Toggle", Name = "Orbit 1" }
local CFG = {
    walkspeed = Move.WalkSpeed, teleportwalk = Move.TeleportWalk, fly = Move.Fly,
    spinbot = Move.Spin, noclip = Move.Noclip, float = Move.Float, clicktp = Move.ClickTP,
    jitterwalk = Move.Jitter, customanim = CustomAnimCFG, aajitter = Move.AAJitter,
}
-- v0.0.96: CustomAnim got its own registry slot. Its Key/Mode live here (off
-- the movement CFG table) and the Name field must survive a config save/load just
-- like every other dropdown value: without this it only rode along implicitly
-- through Visual.CustomAnim and could be lost when the CFG was reloaded.
registerConfig("custom_anim", CustomAnimCFG)

-- held[id] = keybind-driven "active" flag; a feature RUNS only when its module is
-- Enabled (armed) AND held (activated).
local held = {}
local function isActive(id)
    local m = Modules[id]
    return (m and m.Enabled and held[id]) or false
end

local function matchBind(input, bind)
    if typeof(bind) ~= "EnumItem" then return false end
    if bind.EnumType == Enum.KeyCode then
        return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == bind
    elseif bind.EnumType == Enum.UserInputType then
        return input.UserInputType == bind
    end
    return false
end

    -- :: movers (BodyVelocity/BodyGyro: universal, KID-tracked for cleanup) ::
local st = {}
local function makeBV(part, maxForce)
    local bv = new("BodyVelocity", { Name = KID.name("m_bv"), MaxForce = maxForce, Velocity = Vector3.zero, P = 1250 })
    KID.track(bv); bv.Parent = part; return bv
end
local function makeBG(part)
    local bg = new("BodyGyro", { Name = KID.name("m_bg"), MaxTorque = Vector3.new(4e5, 4e5, 4e5), P = 3e4, D = 500 })
    KID.track(bg); bg.Parent = part; return bg
end
local function killMover(s)
    if not s then return end
    if s.bv then pcall(function() s.bv:Destroy() end); s.bv = nil end
    if s.bg then pcall(function() s.bg:Destroy() end); s.bg = nil end
    s.part = nil
end

-- v0.49.0: modern-constraint fly rig. One Attachment0 on the part; with no
-- Attachment1 the Position property is the world-space goal.
local function makeAlign(part)
    local a0 = new("Attachment", { Name = KID.name("m_a0") })
    KID.track(a0); a0.Parent = part
    local ap = new("AlignPosition", {
        Name = KID.name("m_ap"), Attachment0 = a0,
        MaxForce = 9e9, Responsiveness = 200, RigidityEnabled = false,
    })
    local ao = new("AlignOrientation", {
        Name = KID.name("m_ao"), Attachment0 = a0,
        MaxTorque = 9e9, Responsiveness = 200, RigidityEnabled = false,
    })
    KID.track(ap); KID.track(ao); ap.Parent = part; ao.Parent = part
    return a0, ap, ao
end
local function killAlign(s)
    if not s then return end
    if s.ap then pcall(function() s.ap:Destroy() end); s.ap = nil end
    if s.ao then pcall(function() s.ao:Destroy() end); s.ao = nil end
    if s.a0 then pcall(function() s.a0:Destroy() end); s.a0 = nil end
    s.goal = nil
end

-- v0.49.0: states that fight a forced Swimming state (Swimming out of water
-- auto-reverts to GettingUp, so swimmers disable the ladder back).
local SWIM_KILL = {
    Enum.HumanoidStateType.Climbing, Enum.HumanoidStateType.FallingDown,
    Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.GettingUp,
    Enum.HumanoidStateType.Seated, Enum.HumanoidStateType.Jumping,
    Enum.HumanoidStateType.Landed, Enum.HumanoidStateType.Physics,
}
local function swimSetup(s, h)
    s.swimSaved = {}
    s.swimWalk = h.WalkSpeed
    for _, st8 in ipairs(SWIM_KILL) do
        local ok, en = pcall(function() return h:GetStateEnabled(st8) end)
        s.swimSaved[st8] = (ok and en) and true or false
        pcall(function() h:SetStateEnabled(st8, false) end)
    end
    pcall(function() h:SetStateEnabled(Enum.HumanoidStateType.Swimming, true) end)
end
local function swimRestore(s, h)
    if not (s and s.swimSaved) then return end
    if h then
        for st8, en in pairs(s.swimSaved) do
            pcall(function() h:SetStateEnabled(st8, en) end)
        end
        if s.swimWalk then pcall(function() h.WalkSpeed = s.swimWalk end) end
    end
    s.swimSaved, s.swimWalk, s.swimHum = nil, nil, nil
end

-- world-space fly/float direction from WASD + camera (+ vertical keys)
local function moveVector(includeVertical)
    local cf = camCF(); if not cf then return Vector3.zero end
    local v = Vector3.zero
    if UIS:IsKeyDown(Enum.KeyCode.W) then v = v + cf.LookVector end
    if UIS:IsKeyDown(Enum.KeyCode.S) then v = v - cf.LookVector end
    if UIS:IsKeyDown(Enum.KeyCode.D) then v = v + cf.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.A) then v = v - cf.RightVector end
    if includeVertical then
        if UIS:IsKeyDown(Enum.KeyCode.Space) then v = v + Vector3.new(0, 1, 0) end
        if UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.LeftShift) then
            v = v - Vector3.new(0, 1, 0)
        end
    end
    if v.Magnitude > 0 then v = v.Unit end
    return v
end

-- :: per-feature on/off/step (driven by the edge loop below) ::
local FEAT = {}

FEAT.walkspeed = {
    on   = function() local h = humOf(); st.walkspeed = { orig = h and h.WalkSpeed or 16 } end,
    off  = function() local h = humOf(); if h and st.walkspeed then pcall(function() h.WalkSpeed = st.walkspeed.orig end) end st.walkspeed = nil end,
    step = function() local h = humOf(); if h then h.WalkSpeed = Move.WalkSpeed.Speed end end,
}

FEAT.teleportwalk = {
    step = function(dt)
        local h, r = humOf(), rootOf(); if not (h and r) then return end
        local d = h.MoveDirection
        if d.Magnitude > 0 then r.CFrame = r.CFrame + d * (Move.TeleportWalk.Speed * dt) end
    end,
}

-- v0.70.0: Jitter-walk. Lateral blink-steps along the facing X axis, throttled
-- to 10/s. Every jump clears 4 studs minimum (wider than any rig), so it never
-- reads as sliding: resolvers lead the old spot, you are already sideways.
-- v0.70.1: velocity untouched. Zeroing it ate WalkSpeed momentum (slower) and
-- the jump impulse (no air): the CFrame jump is the whole move, keep momentum.
local lastJit = 0
FEAT.jitterwalk = {
    step = function()
        local now = os.clock()
        if now - lastJit < 0.1 then return end
        lastJit = now
        local h, r = humOf(), rootOf(); if not (h and r) then return end
        local rng = Random.new()
        local range = math.max(tonumber(Move.Jitter.Range) or 12, 4)
        local d = rng:NextNumber(4, range) * (rng:NextNumber() < 0.5 and -1 or 1)
        pcall(function() r.CFrame = r.CFrame + r.CFrame.RightVector * d end)
    end,
}

FEAT.fly = {
    on  = function() st.fly = {} end,
    off = function()
        local s = st.fly
        killMover(s); killAlign(s)
        local h = humOf()
        swimRestore(s, h)
        if h then h.PlatformStand = false end
        local c = char(); local head = c and c:FindFirstChild("Head")
        if head then head.Anchored = false end
        st.fly = nil
    end,
    step = function(dt)
        local s = st.fly; if not s then return end
        local h, r = humOf(), rootOf()
        if not (h and r) then killMover(s); killAlign(s); swimRestore(s, h); return end
        local kind, speed = Move.Fly.Kind, Move.Fly.Speed
        local c = char(); local head = c and c:FindFirstChild("Head")
        -- v0.49.0: leaving one method for another tears down the old rig first,
        -- or disabled swim states and stray movers leak across the switch.
        if s.mode ~= kind then
            killMover(s); killAlign(s); swimRestore(s, h)
            if head and head.Anchored then head.Anchored = false end
            s.mode = kind
        end
        if kind == "CFrame Fly" then
            killMover(s); killAlign(s)
            speed = math.min(speed, 1000)
            if not head then return end
            h.PlatformStand = true; head.Anchored = true
            local v = moveVector(true)
            if v.Magnitude > 0 then head.CFrame = head.CFrame + v * (speed * dt) end
        elseif kind == "Velocity Fly" then
            -- v0.49.0: assembly velocity straight on the root, no mover instances
            -- for sweeps to find. Same motion as Default, smaller footprint.
            killMover(s); killAlign(s)
            if head and head.Anchored then head.Anchored = false end
            h.PlatformStand = true
            r.AssemblyLinearVelocity = moveVector(true) * speed
            r.AssemblyAngularVelocity = Vector3.zero
        elseif kind == "Align Fly" then
            -- v0.49.0: modern constraints instead of legacy movers. A goal point
            -- chases input; the constraint does the pulling.
            killMover(s)
            if head and head.Anchored then head.Anchored = false end
            if s.part ~= r or not (s.ap and s.ap.Parent) then
                killAlign(s); s.part = r
                s.a0, s.ap, s.ao = makeAlign(r)
                s.goal = r.Position
            end
            h.PlatformStand = true
            local v = moveVector(true)
            if v.Magnitude > 0 then s.goal = s.goal + v * (speed * dt) end
            s.ap.Position = s.goal
            local cf = camCF(); if cf and s.ao then s.ao.CFrame = cf end
        elseif kind == "Swim Fly" then
            -- v0.49.0: forced Swimming state plus Move(), straight through the
            -- character controller. No CFrame, velocity, or mover writes at all.
            killMover(s); killAlign(s)
            if head and head.Anchored then head.Anchored = false end
            if s.swimHum ~= h then swimRestore(s, h); s.swimSaved = nil end
            if not s.swimSaved then swimSetup(s, h); s.swimHum = h end
            h.PlatformStand = false
            pcall(function()
                if h:GetState() ~= Enum.HumanoidStateType.Swimming then
                    h:ChangeState(Enum.HumanoidStateType.Swimming)
                end
            end)
            h.WalkSpeed = speed
            local v = moveVector(true)
            h:Move(v.Magnitude > 0 and v or Vector3.zero, false)
        else
            if head and head.Anchored then head.Anchored = false end
            killAlign(s)
            local target = r
            if kind == "Vehicle Fly" then
                local seat = h.SeatPart
                if seat then target = seat.AssemblyRootPart or seat end
            end
            if s.part ~= target or not (s.bv and s.bv.Parent) then
                killMover(s); s.part = target
                s.bv = makeBV(target, Vector3.new(9e9, 9e9, 9e9))
                s.bg = makeBG(target)
            end
            h.PlatformStand = true
            s.bv.Velocity = moveVector(true) * speed
            local cf = camCF(); if cf and s.bg then s.bg.CFrame = cf end
        end
    end,
}

-- v0.79.1 Spinbot + AA Jitter: one Last+1 writer, first-activated wins (ties
-- go to spinbot). Spin whirls the root; AA rides the camera yaw on the root
-- (shiftlock cooperates instead of fighting) while the twist joint oscillates.
-- Legs keep their anims in both modes.
local function findRootJoint(char)
    if not char then return nil end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    for _, c in ipairs(hrp:GetChildren()) do
        if c:IsA("Motor6D") then return c end
    end
    return nil
end
-- shared spin writer: bound while either feature runs, released when neither
-- does. Stamps in on() record activation order for the first-wins rule.
local function ensureSpinBind()
    if st.spinBound then return end
    st.spinBound = true
    pcall(function()
        RunService:BindToRenderStep("KSpinbot",
            Enum.RenderPriority.Last.Value + 1, function(rsDt)
                local frameDt = rsDt or 0.016
                local sp, aa = st.spin, st.aa
                if not (sp or aa) then return end
                local r = rootOf(); if not r then return end
                local useSpin
                if sp and aa then useSpin = (st.spinAt or 0) <= (st.aaAt or 0)
                elseif sp then useSpin = true
                else useSpin = false end
                if useSpin then
                    if st.aaJoint and st.aaOrigC0 then
                        pcall(function() st.aaJoint.C0 = st.aaOrigC0 end)
                        st.aaJoint, st.aaOrigC0, st.aaChar = nil, nil, nil
                    end
                    -- Nonlinear map: slider 1..1000 -> rad/s via 0.05 * v^1.7,
                    -- so 1 crawls (~3 deg/s) and 1000 hits ~630 rev/s.
                    sp.a = (sp.a or 0) + math.rad(0.05 * Move.Spin.Speed ^ 1.7) * frameDt
                    r.CFrame = CFrame.new(r.Position) * CFrame.Angles(0, sp.a, 0)
                else
                    -- AA JITTER: root rides the camera yaw (what shiftlock wants,
                    -- so nothing fights) while the twist joint oscillates. Legs
                    -- keep their anims; jointless rigs just ride the camera.
                    local cam = workspace.CurrentCamera
                    if cam then
                        local look = cam.CFrame.LookVector
                        local flat = Vector3.new(look.X, 0, look.Z)
                        if flat.Magnitude >= 0.001 then
                            flat = flat.Unit
                            r.CFrame = CFrame.new(r.Position, r.Position + flat)
                        end
                    end
                    local ch = r.Parent
                    local j = st.aaJoint
                    if not j or not j.Parent or st.aaChar ~= ch then
                        if st.aaJoint and st.aaOrigC0 then
                            pcall(function() st.aaJoint.C0 = st.aaOrigC0 end)
                        end
                        st.aaJoint, st.aaOrigC0, st.aaChar = nil, nil, ch
                        if ch then
                            local lt = ch:FindFirstChild("LowerTorso")
                            local w = lt and lt:FindFirstChild("Waist")
                            if w and w:IsA("Motor6D") then
                                st.aaJoint = w
                            else
                                local rt = r:FindFirstChild("Root")
                                if rt and rt:IsA("Motor6D") then st.aaJoint = rt end
                            end
                            if st.aaJoint then st.aaOrigC0 = st.aaJoint.C0 end
                        end
                        j = st.aaJoint
                    end
                    aa.jt = (aa.jt or 0) + frameDt
                    local ang = math.sin(aa.jt
                        * (Move.Spin.JitterSpeed or 8) * math.pi * 2)
                        * math.rad(Move.Spin.JitterAmp or 15)
                    if j and st.aaOrigC0 then
                        local target = st.aaOrigC0 * CFrame.Angles(0, ang, 0)
                        local sm = Move.Spin.Smoothing
                        pcall(function()
                            if sm == nil or sm >= 1 then j.C0 = target
                            else j.C0 = j.C0:Lerp(target, math.clamp(sm, 0.01, 1)) end
                        end)
                    end
                end
            end)
    end)
end
local function releaseSpinBind()
    if st.spin or st.aa then return end
    if st.aaJoint and st.aaOrigC0 then
        pcall(function() st.aaJoint.C0 = st.aaOrigC0 end)
    end
    st.aaJoint, st.aaOrigC0, st.aaChar = nil, nil, nil
    if st.spinBound then
        pcall(function() RunService:UnbindFromRenderStep("KSpinbot") end)
    end
    st.spinBound = nil
end
FEAT.spinbot = {
    on = function() st.spin = { a = 0 }; st.spinAt = os.clock(); ensureSpinBind() end,
    off = function() st.spin = nil; releaseSpinBind() end,
}
FEAT.aajitter = {
    on = function() st.aa = { jt = 0 }; st.aaAt = os.clock(); ensureSpinBind() end,
    off = function() st.aa = nil; releaseSpinBind() end,
}

FEAT.float = {
    on  = function() st.float = {} end,
    off = function() killMover(st.float); st.float = nil end,
    step = function()
        local s, r = st.float, rootOf()
        if not (s and r) then if s then killMover(s) end return end
        if s.part ~= r or not (s.bv and s.bv.Parent) then
            killMover(s); s.part = r
            s.bv = makeBV(r, Vector3.new(0, 9e9, 0))   -- vertical only; XZ free to walk
        end
        local vy = 0
        if UIS:IsKeyDown(Enum.KeyCode.E) then vy = Move.Float.Speed end
        if UIS:IsKeyDown(Enum.KeyCode.Q) then vy = -Move.Float.Speed end
        s.bv.Velocity = Vector3.new(0, vy, 0)
    end,
}

-- edge + step driver (Heartbeat). pcall-guarded so one feature erroring can't kill it.
local prev = {}
RunService.Heartbeat:Connect(function(dt)
    if Koffee.dead() then return end
    for id, f in pairs(FEAT) do
        local a = isActive(id)
        if a ~= prev[id] then
            prev[id] = a
            if a then if f.on then pcall(f.on) end else if f.off then pcall(f.off) end end
        end
        if a and f.step then pcall(f.step, dt) end
    end
end)

-- :: click-TP ground indicator (Koffee-styled ring + crosshair on the mouse point) ::
