        -- applying. Needs the __index hook, which it installs on demand.
        PerfectLock   = false,
        -- v0.27.0: target players behind the camera too, by world distance (killaura).
        BehindCam     = false,
        TeamCheck     = true,
        VisibleCheck  = false,
        HealthCheck   = false,
        Sticky        = false,
        Rage          = false,
        RageType      = "Camera Teleport",                -- "Camera Teleport" | "Character Teleport"
        RageYOffset   = 0,                                -- Character Teleport vertical offset (-10..10)
        Snaplines     = false,                            -- one snapline toggle at a time (aim XOR silent)
        Predict       = { Enabled = false, X = 1.0, Y = 1.0 },
        Smooth        = { Enabled = false, X = 1.0, Y = 1.0 },
        -- v0.50.0 legit kit. Underscore keys skip the serializer like the rest.
