    -- YOUR hits/kills trigger them. v0.9.0 presets: Impact / Sparks / Blood /
    -- Shockwave / Nova / Ember, all world-space (occluded by geometry).
    HitEffects = {
        Hit = {
            Enabled  = false,
            Preset   = "Impact",
            Color    = Color3.fromRGB(255, 220, 120),
            Scale    = 1.0,
            Duration = 0.35,
            Attach   = "Head",   -- "Head" | "HRP" | "Torso"
        },
        Kill = {
            Enabled  = false,
            Anim     = "Off",    -- v0.89.0 kill animation, plays on top of the preset
            Preset   = "Shockwave",
            Color    = Color3.fromRGB(255, 120, 90),
            Scale    = 1.5,
            Duration = 0.55,
            Attach   = "Head",
        },
    },
}

    -- one FOV config per context (aimbot + silent). Both can be active at once;
    -- each draws its own concentric ring at the size the user sets.
    local function defaultFovCfg()
        return {
            Enabled = false, Size = 100, Origin = "Center", Filled = false, Spin = false,
            -- v0.4.0: HideVisual keeps the FOV size gate active for targeting but
            -- suppresses the circle/outline/dots/fill entirely. Set via the Filled
            -- right-click popup ("Hide Visual"). Independent of Enabled: turning
            -- HideVisual on while Enabled is on means "invisible FOV, still gated".
            HideVisual = false,
            -- v0.5.0: Follow the current target. Smoothness 0=snap, 0.98=very slow.
            -- Lerp advances once per frame in stepFovFollow (called from the same
            -- RenderStepped that drives drawFov). fovCenter reads _screenX/_screenY
            -- straight out of this table so many-call sites don't over-step the lerp.
            -- Underscores keep them out of the config serializer.
            Follow = { Enabled = false, Smoothness = 0.15, _screenX = nil, _screenY = nil },
            Style = "Smooth", Color = Color3.new(1, 1, 1), FillColor = Color3.fromRGB(212, 145, 90),
            FillTransparency = 0.5, Thickness = 1, DotSize = 4, DotGap = 18,
            Fill = {
                RemoveOutline = false, Spin = false,
                Custom = {
                    Enabled = false, Points = 2, Triangle = false,
                    Colors = { Color3.fromRGB(212,145,90), Color3.fromRGB(230,200,120),
                               Color3.fromRGB(160,120,220), Color3.fromRGB(120,200,255) },
                    Alphas = { 0, 0, 0, 0 },
                    Moving = { Enabled = false, Speed = 1, Direction = 0 },
                },
            },
        }
    end
    Combat.Aim.FOV    = defaultFovCfg()
    Combat.Silent.FOV = defaultFovCfg()
    -- distinct defaults so both rings are visible at once: identical size + origin
    -- overlap into a single ring ("can't see both"). The user can still match them.
    Combat.Silent.FOV.Size  = 140
    Combat.Silent.FOV.Color = Color3.fromRGB(130, 200, 255)

    -- v0.0.34: expose combat state to the config system (FOV cfgs are nested in
    -- Aim/Silent so they ride along). Underscore keys (_hooked/_target/_rageLock)
    -- are skipped by the serializer.
    registerConfig("combat_aim",     Combat.Aim)
    registerConfig("combat_silent",  Combat.Silent)
    registerConfig("combat_trigger", Combat.Trigger)
    registerConfig("combat_misc",    Combat.Misc)
    registerConfig("combat_gun", Combat.Gun)
    registerConfig("combat_sounds",  Combat.HitSounds)
    -- v0.7.0 hit/kill visual effects. Rides HitSounds attribution.
    registerConfig("combat_hiteffects", Combat.HitEffects)

    -- :: math helpers ::
    local function shortestAngle(a) return (a + math.pi) % (2 * math.pi) - math.pi end
    local function lookAngles(dir)
        local flat = math.sqrt(dir.X * dir.X + dir.Z * dir.Z)
        return math.atan2(-dir.X, -dir.Z), math.atan2(dir.Y, flat)   -- yaw, pitch
    end
    local function aimCFrame(cam, from, targetPos, aX, aY)
        local dir = targetPos - from
        if dir.Magnitude < 1e-3 then return cam.CFrame end
        local gy, gp = lookAngles(dir)
        local cy, cp = lookAngles(cam.CFrame.LookVector)
        local ny = cy + shortestAngle(gy - cy) * aX
        local np = cp + (gp - cp) * aY
        return CFrame.new(from) * CFrame.fromEulerAnglesYXZ(np, ny, 0)
    end

    -- :: targeting engine (shared by aimbot / trigger / silent) ::
    -- v0.5.0: when cfg.Follow.Enabled, fovCenter returns the lerped follow-cache
    -- (updated once per frame in stepFovFollow) instead of the plain Center/Mouse
    -- origin. Falls back to origin when the cache is empty (first frame / no
    -- target yet). Targeting also uses this center so the FOV gate follows the
    -- visual ring consistently.
    local function fovCenter(cfg)
        local vp = viewport()
        local defX, defY = vp.X * 0.5, vp.Y * 0.5
        if cfg and cfg.Origin == "Mouse" then
            local m = UserInputService:GetMouseLocation()
            defX, defY = m.X, m.Y
        end
        if cfg and cfg.Follow and cfg.Follow.Enabled then
            local cx = cfg.Follow._screenX or defX
            local cy = cfg.Follow._screenY or defY
            return Vector2.new(cx, cy)
        end
        return Vector2.new(defX, defY)
    end

    -- friendly hit-part name -> candidate real part names (R15 first, R6 fallback)
    local HITPARTS = { "Head", "Torso", "HRP", "Left Arm", "Right Arm", "Left Leg",
        "Right Leg", "Left Hand", "Right Hand", "Left Foot", "Right Foot" }
    local HITMAP = {
        ["Head"]       = { "Head" },
        ["Torso"]      = { "UpperTorso", "Torso", "LowerTorso" },
        ["HRP"]        = { "HumanoidRootPart" },
        ["Left Arm"]   = { "LeftUpperArm", "LeftLowerArm", "Left Arm" },
        ["Right Arm"]  = { "RightUpperArm", "RightLowerArm", "Right Arm" },
        ["Left Leg"]   = { "LeftUpperLeg", "LeftLowerLeg", "Left Leg" },
        ["Right Leg"]  = { "RightUpperLeg", "RightLowerLeg", "Right Leg" },
        ["Left Hand"]  = { "LeftHand", "Left Arm" },
        ["Right Hand"] = { "RightHand", "Right Arm" },
        ["Left Foot"]  = { "LeftFoot", "Left Leg" },
        ["Right Foot"] = { "RightFoot", "Right Leg" },
    }
    local function aimPart(character, partName)
        local cands = HITMAP[partName] or { "Head" }
        for _, n in ipairs(cands) do
            local p = character:FindFirstChild(n)
            if p then return p end
        end
        return findTorso(character)
    end

    -- v0.31.1: reused params: occluded() runs per candidate per frame (aim + silent
    -- + crosshair), so a fresh RaycastParams each call was real per-frame GC churn.
    local occludeParams = RaycastParams.new()
    occludeParams.FilterType = Enum.RaycastFilterType.Exclude
    local function occluded(character, fromPos, toPos)
        occludeParams.FilterDescendantsInstances = { character, LocalPlayer.Character }
        return Workspace:Raycast(fromPos, toPos - fromPos, occludeParams) ~= nil
    end

    -- HealthCheck: skip protected targets (ForceField / spawn shield) or dead.
    local function healthOk(character, hum)
        if not (hum and hum.Health > 0) then return false end
        if character:FindFirstChildOfClass("ForceField") then return false end
        return true
    end

    -- v0.51.0 multi-part pool. Single Part keeps the Hit Part dropdown;
    -- Closest Part takes the enabled pool part nearest the crosshair;
    -- Random Part rolls one per target and holds it briefly, so the point
    -- does not flicker every frame. Absent pool entries read enabled.
    local function poolPick(char, plr, cfg, center)
        local L = cfg.Legit
        -- v0.52.0: aim's Legit is master-gated, so its part pool only applies when
        -- Legit is on (else the Aimbot tab's single Hit Part wins). Silent's Legit
        -- has no Enabled field, so it is never gated here.
        if L and L.Enabled == false then return nil end
        local mode = L and L.PartMode or "Single Part"
        if mode == "Single Part" then return nil end
        local pool = L and L.Parts
        local names = {}
        for _, n in ipairs(HITPARTS) do
            if not pool or pool[n] ~= false then names[#names + 1] = n end
        end
        if #names == 0 then return nil end
        if mode == "Random Part" then
            local now = os.clock()
            if L._rpPlr ~= plr or (now - (L._rpAt or 0)) > 0.4 then
                L._rpPlr, L._rpAt = plr, now
                L._rpName = names[math.random(#names)]
            end
            return aimPart(char, L._rpName)
        end
        local cam = Workspace.CurrentCamera
        if not cam then return nil end
        local bestP, bestD = nil, math.huge
        for _, n in ipairs(names) do
            local p = aimPart(char, n)
            if p then
                local sp = cam:WorldToViewportPoint(p.Position)
                if sp.Z > 0 then
                    local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                    if d < bestD then bestD, bestP = d, p end
                end
            end
        end
        return bestP
    end

    -- v0.51.1: forced-miss point. Random angle in the camera plane, 5 studs
    -- off the part: confidently off the body, still plausibly near it.
    local function missPoint(part)
        local mp = part.Position
        local mc = Workspace.CurrentCamera
        if mc then
            local cf = mc.CFrame
            local a = math.random() * math.pi * 2
            mp = mp + (cf.RightVector * math.cos(a) + cf.UpVector * math.sin(a)) * 5
        end
        return mp
    end

    -- returns player, part. maxRadius in screen px (math.huge = no FOV limit).
    local function getBestTarget(cfg, maxRadius, center)
        local cam = Workspace.CurrentCamera
        if not cam then return nil end
        center = center or fovCenter()
        local camPos = cam.CFrame.Position
        local best, bestPart, bestScore = nil, nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                local char = plr.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local alive = char and hum and hum.Health > 0
                local hcOk = (not cfg.HealthCheck) or (char and healthOk(char, hum))
                -- v0.0.46: team check (manual list / Advanced) + "Ignore Friends" gate
                -- v0.63.2: unified resolver -- Exclude (never a target) / Prioritize
                -- (lock engaged -> ONLY these), custom-graph then player-list, folded
                -- in with the team-check + ignore-friends filters.
                if alive and hcOk and Shared.aimAllowed(plr, cfg.TeamCheck) then
                    do
                        local part = aimPart(char, cfg.HitPart)
                        if part then
                            part = poolPick(char, plr, cfg, center) or part
                            local worldDist = (part.Position - camPos).Magnitude
                            if worldDist <= (cfg.Distance or math.huge) then
                                local sp = cam:WorldToViewportPoint(part.Position)
                                -- v0.27.0 Behind Cam: killaura targeting. Ignores camera
                                -- facing + the FOV ring, scores by world distance alone, so
                                -- people behind the camera still count (MC melee).
                                local pass, crossDist
                                if cfg.BehindCam then
                                    pass, crossDist = true, worldDist
                                elseif sp.Z > 0 then
                                    crossDist = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                    pass = crossDist <= maxRadius
                                end
                                if pass then
                                    local vis = not (cfg.VisibleCheck and occluded(char, camPos, part.Position))
                                    if vis then
                                        -- v0.50.0 target priority. Crosshair scores screen
                                        -- distance to the ring center; Distance scores world
                                        -- distance; Health scores lowest health fraction first.
                                        -- "Nearest" is the pre-rename Distance value.
                                        local pri = cfg.Priority
                                        local score
                                        if pri == "Nearest" or pri == "Distance" or cfg.BehindCam then
                                            score = worldDist
                                        elseif pri == "Health" then
                                            score = hum.Health / math.max(hum.MaxHealth or 100, 1)
                                        else
                                            score = crossDist
                                        end
                                        if score < bestScore then
                                            bestScore, best, bestPart = score, plr, part
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        -- v0.52.0: NPC entities join the same scoring, minus team / friend / lock.
        -- targetEntities honours the folder's per-feature exclusions.
        if Shared.NPC then
            local feat = (cfg == Combat.Silent) and "Silent" or "Aimbot"
            for _, e in ipairs(Shared.NPC.targetEntities(feat)) do
                local char, hum = e.char, e.hum
                -- v0.53.0: Humanoid optional (NPC can be any instance). Death-gate
                -- only when it has one; anchor part stands in for aimPart on props.
                if char and (not hum or hum.Health > 0)
                    and ((not cfg.HealthCheck) or (not hum) or healthOk(char, hum)) then
                    local part = aimPart(char, cfg.HitPart) or npcAnchor(char)
                    if part then
                        part = poolPick(char, e.wrapper, cfg, center) or part
                        local worldDist = (part.Position - camPos).Magnitude
                        if worldDist <= (cfg.Distance or math.huge) then
                            local sp = cam:WorldToViewportPoint(part.Position)
                            local pass, crossDist
                            if cfg.BehindCam then
                                pass, crossDist = true, worldDist
                            elseif sp.Z > 0 then
                                crossDist = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                pass = crossDist <= maxRadius
                            end
                            if pass and not (cfg.VisibleCheck and occluded(char, camPos, part.Position)) then
                                local pri = cfg.Priority
                                local score
                                if pri == "Nearest" or pri == "Distance" or cfg.BehindCam then
                                    score = worldDist
                                elseif pri == "Health" and hum then
                                    score = hum.Health / math.max(hum.MaxHealth or 100, 1)
                                else
                                    score = crossDist
                                end
                                if score < bestScore then
                                    bestScore, best, bestPart = score, e.wrapper, part
                                end
                            end
                        end
                    end
                end
            end
        end
        return best, bestPart
    end

    -- v0.9.0: entry point for the crosshair's Follow Target
    function Shared.crosshairTarget(which)
        local cfg = (which == "Silent") and Combat.Silent or Combat.Aim
        local F = cfg.FOV
        return getBestTarget(cfg, F.Enabled and F.Size or math.huge, fovCenter(F))
    end

    local function predicted(plr, part, pr)
        local pos = part.Position
        if not pr.Enabled then return pos end
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return pos end
        -- v0.72.1: schema is {Enabled,X,Y}, there is no Z. v0.1.1 pointed the Z
        -- term at pr.Z and made EVERY enabled frame throw (dead aimbot + silent).
        -- Z is horizontal like X, so it rides the X division again, guarded.
        local v = hrp.AssemblyLinearVelocity
        local dx = math.max(tonumber(pr.X) or 1, 0.01)
        local dy = math.max(tonumber(pr.Y) or 1, 0.01)
        return pos + Vector3.new(v.X / dx, v.Y / dy, v.Z / dx)
    end
    -- v0.75.0: dwell-centroid resolver (stolen shape). Each engaged target grows
    -- a root trail (0.25s samples, 120 cap); the aim point becomes the densest
    -- 4+ cluster centroid instead of the live point, so teleport spammers get
    -- shot where they dwell, not where they flash. Cold or clusterless trails
    -- fall back to live. Hit-part offset rides along from the live point.
    local dwellHist = {}
    local function dwellPos(plr, part, live)
        local now = os.clock()
        local ch = plr.Character
        local root = ch and ch:FindFirstChild("HumanoidRootPart")
        if not root then return live end
        local rec = dwellHist[plr]
        if not rec then rec = { pts = {}, at = 0, touch = now }; dwellHist[plr] = rec end
        rec.touch = now
        if now - rec.at >= 0.25 and #rec.pts < 120 then
            rec.at = now
            rec.pts[#rec.pts + 1] = root.Position
        end
        local nkeys = 0
        for _ in pairs(dwellHist) do nkeys = nkeys + 1 end
        if nkeys > 32 then
            for k, r in pairs(dwellHist) do
                if now - r.touch > 30 then dwellHist[k] = nil end
            end
        end
        local pts, rad = rec.pts, (tonumber(Combat.Misc.DwellRadius) or 16)
        if #pts < 10 then return live end
        local bestN, bestSum = 0, nil
        for i = 1, #pts do
            local pi, n, sx, sy, sz = pts[i], 0, 0, 0, 0
            for j = 1, #pts do
                local pj = pts[j]
                if (pi - pj).Magnitude <= rad then
                    n = n + 1; sx, sy, sz = sx + pj.X, sy + pj.Y, sz + pj.Z
                end
            end
            if n >= 4 and n > bestN then
                bestN, bestSum = n, Vector3.new(sx / n, sy / n, sz / n)
            end
        end
        if not bestSum then return live end
        return bestSum + (live - root.Position)
    end

    -- :: FOV circles (one per context: aimbot + silent, both can be active) ::
    -- (glow removed in v0.0.32: the real soft glow waits on the external app.)
    local FOV_MAX_DOTS = 160
    local function makeFov(name)
        local circle = new("Frame", {
            Name = name,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.new(0, 200, 0, 200),
            BackgroundColor3 = Color3.fromRGB(212, 145, 90),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Visible = false,
            ZIndex = 11,
            Parent = screen,
        }, { pillCorner(), stroke(Color3.new(1, 1, 1), 1), lineGradient() })
        local dotContainer = new("Frame", {
            Name = "Dots", Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, Visible = false, ZIndex = 12, Parent = circle,
        })
        local dots = {}
        for _ = 1, FOV_MAX_DOTS do
            dots[#dots + 1] = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.new(0, 4, 0, 4),
                BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0, ZIndex = 12, Parent = dotContainer,
            }, { pillCorner() })
        end
        return {
            circle = circle,
            stroke = circle:FindFirstChildOfClass("UIStroke"),
            grad = circle:FindFirstChild("KGrad"),
            dotContainer = dotContainer,
            dots = dots,
        }
    end
    local aimFov    = makeFov(KID.name("fov_aim"))
    local silentFov = makeFov(KID.name("fov_silent"))

    -- snaplines: one line from the FOV origin (mouse/center) to the targeted
    -- person. Uses the tracer backend (KGrad + KOutline, featureThickness, ESP
    -- tracer colour/gradient/outline). Only one context drives it (aim XOR silent).
    local snapLine = new("Frame", {
        Name = KID.name("snapline"), AnchorPoint = Vector2.new(0.5, 0.5),
        Size = UDim2.new(0, 0, 0, 1), BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 0, Visible = false, ZIndex = 11, Parent = screen,
    }, { lineGradient(), lineOutline() })

    -- :: activation state ::
    local aimHeld    = false
    local silentHeld = false   -- v0.0.34: optional silent arm key (nil key = always armed)
    local lmbDown    = false   -- v0.0.35: tracked LMB state (read inside the silent
                               -- hooks; IsMouseButtonPressed is a namecall + illegal there)
    local lmbClickAt = 0       -- v0.0.69: os.clock() of the last LMB press -> a short Pos Spoof
                               -- fire-window, so a weapon that reads a frame or two AFTER the
                               -- click (or fires multiple pellets) still gets the spoofed origin
    local trigHeld   = false
    local trigBusy   = false
    local silentTarget = nil   -- the part (for Mouse.Target)
    local silentPos    = nil   -- Vector3 redirect point (predicted; drives Hit/UnitRay)
    -- v0.11.1 Perfect Lock redirect. Not silentPos: the silent heartbeat nils that
    -- whenever Silent Aim is off, which is the case Perfect Lock must work in.
    local plPos, plPart = nil, nil
    local function plArmed()
        return plPos ~= nil and Combat.Aim.Enabled and Combat.Aim.PerfectLock
    end

    -- v0.0.39: fire-read resolver state + caller scoping. ONE local table so the
    -- Combat chunk's ~200-local budget stays below the limit; resolvers read it
    -- as an upvalue. cam/camPos/screen cached per frame (never re-read Camera.*
    -- inside the hook: re-entry/recursion), mouse for identity compares, and
    -- the learned weapon/camera-controller sets are only touched by namecall-safe
    -- code (never lazily inside a hook: FindFirstChild is a namecall).
    local SR = { cam = nil, camPos = nil, screen = nil, mouse = nil, pm = nil }
    Shared._SR = SR   -- v0.85.0: reachable for the Koffee Lab dev handle
    local getCS = getcallingscript   -- executor global; nil on runtimes without it
    SR.own = getCS and getCS()       -- Koffee's own script: never spoof its OWN camera
                                     -- reads (the aimbot loop) if silent is co-armed.
    pcall(function() SR.mouse = LocalPlayer:GetMouse() end)
    -- PlayerModule (the standard camera root) is resolved HERE + in the heartbeat:
    -- both namecall-safe contexts. NEVER resolve it lazily inside a hook (FindFirstChild
    -- is a namecall; a nested namecall inside the __namecall hook corrupts the pending
    -- dispatch and breaks the weapon after one shot).
    pcall(function()
        local ps = LocalPlayer:FindFirstChild("PlayerScripts")
        SR.pm = ps and ps:FindFirstChild("PlayerModule")
    end)
    -- is `src` the camera system? standard camera = a PlayerModule descendant: NEVER
    -- spoofed, so the real view can't be rotated out from under the player.
    -- CRITICAL: walks .Parent (property __index reads only): NO namecall: so this
    -- is safe to call from inside the __namecall hook.
    function SR.isView(src)
        if not src then return false end
        local pm = SR.pm
        if not pm then return false end
        local a, n = src, 0
        while a and n < 16 do
            if a == pm then return true end
            a = a.Parent
            n = n + 1
        end
        return false
    end
    -- should THIS caller be handed the spoofed aim direction (Camera.CFrame / cursor /
    -- camera-rays)? mouse.Hit/Target/UnitRay are handled separately + ungated (only aim
    -- code reads those). Excludes Koffee's own reads and the camera system (PlayerModule)
    -- so the real view / Popper are never touched.
    -- v0.0.70: learned CONTROLLER set. Any non-Koffee script that WRITES Camera.CFrame
    -- or the local root's CFrame/Position is a camera/position CONTROLLER (FpsController,
    -- custom movement handlers, etc.): it must NEVER be handed the spoofed aim/position,
    -- or the read-spoof rotates the real view / teleports you on games with custom handlers.
    -- Populated by the __newindex writer-detector; only pure-READER (shooting) code is left
    -- to be spoofed. Session-stable so re-exec keeps what it already learned.
    -- v0.1.5 Second-Camera: the learned set is actually ENFORCED (v0.0.70 shipped the
    -- detector but the revert removed enforcement). In SC mode a script that writes
    -- Camera.CFrame is a RENDERER and always gets real data, while pure-reader weapon
    -- scripts get bent continuously: that is the actual "two cameras" split: the game's
    -- fire logic sees the locked direction, your view never moves. Merged handler+weapon
    -- scripts land in the set too and degrade to MB (switch methods there).
    function SR.spoofAim(src)
        if not src then return false end
        if src == SR.own then return false end              -- never Koffee's own reads
        if SR.isView(src) then return false end             -- never the camera system
        if Combat.Silent.Method == "Second-Camera" then
            -- v0.1.5: learned renderers ALWAYS see real data: absolute, no waivers.
            -- (a v0.1.6 click-window waiver was ripped: bending a writer's reads at ANY
            -- time bends the view, because it writes what it read straight back.)
            -- These games are covered by the OUTBOUND path instead (FireServer arg
            -- rewrite in resolveNamecall): the client sees truth, the wire carries
            -- the lock.
            local set = getgenv and getgenv()[KID.ctx.keys.ctrl]
            if set and rawget(set, src) then return false end  -- learned renderer: real data
        end
        return true                                         -- any non-camera script
    end

    local function inputMatches(input, bind)
        if typeof(bind) == "EnumItem" then
            if bind.EnumType == Enum.KeyCode then
                return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == bind
            elseif bind.EnumType == Enum.UserInputType then
                return input.UserInputType == bind
            end
        end
        return false
    end
    local MOUSE_SHORT = { MouseButton1 = "LMB", MouseButton2 = "RMB", MouseButton3 = "MMB" }
    local function inputName(bind)
        -- v0.0.37: virtual helper binds (mouse 4/5) render as xb1/xb2
        if type(bind) == "string" then return VIRTUAL_LABELS[bind] or bind end
        if typeof(bind) == "EnumItem" then
            if bind.EnumType == Enum.UserInputType then
                return MOUSE_SHORT[bind.Name] or bind.Name
            end
            return bind.Name:lower()
        end
        return "-"
    end

    local pendingActivation = nil
    local actPills = {}
    -- v0.66.1: Toggle visibly sticks. Each pill registers a held reader; accent
    -- means latched or firing, muted means idle. Skipped mid-rebind ("..." state).
    -- v0.67.0: writes only on change (the Heartbeat calls this every frame for
    -- XButton-held state, so blind writes were 3 property sets at 60Hz).
    local function syncActPills(force)
        for _, e in ipairs(actPills) do
            if not (pendingActivation and pendingActivation.pill == e.pill) then
                local on = e.enabled() and e.held()
                if force or e._last ~= on then
                    e._last = on
                    e.pill.TextColor3 = on and Theme.Palette.Accent or Theme.Palette.TextMuted
                end
            end
        end
    end

    -- :: Hold/Toggle chooser popup (right-click the activation pill) ::
    local activeChooser = nil
    local function closeChooser()
        if activeChooser then
            pcall(function() activeChooser.frame:Destroy() end)
            if activeChooser.conn then activeChooser.conn:Disconnect() end
            activeChooser = nil
        end
    end
    local function openChooser(pill, cfg)
        closeChooser()
        local frame = new("Frame", {
            Name = "ModeChooser", Size = UDim2.new(0, 120, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = Theme.Palette.Panel,
            BackgroundTransparency = 0.02, BorderSizePixel = 0, ZIndex = 230, Parent = popupScreen,
        }, {
            corner(6), stroke(Theme.Palette.Border, 1),
            new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
                PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }),
            new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
        })
        for _, mode in ipairs({ "Hold", "Toggle" }) do
            local sel = cfg.ActivationMode == mode
            local opt = new("TextButton", {
                Size = UDim2.new(1, 0, 0, 22), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = sel and 0.2 or 1, AutoButtonColor = false, Text = mode,
                FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
                TextColor3 = sel and Theme.Palette.Accent or Theme.Palette.TextMuted, ZIndex = 231, Parent = frame,
            }, { corner(4) })
            opt.MouseButton1Click:Connect(function()
                cfg.ActivationMode = mode
                closeChooser()
                syncActPills(true)
            end)
        end
        local abs, siz = pill.AbsolutePosition, pill.AbsoluteSize
        local ox, oy = popupOffsetFor(frame, abs.X + siz.X - 120, abs.Y + siz.Y + 6)
        frame.Position = UDim2.new(0, ox, 0, oy)
        activeChooser = { frame = frame }
        task.defer(function()
            if not activeChooser then return end
            activeChooser.conn = UserInputService.InputBegan:Connect(function(input)
                local it = input.UserInputType
                if it == Enum.UserInputType.MouseButton1 or it == Enum.UserInputType.MouseButton2
                or it == Enum.UserInputType.Touch then
                    local mp = input.Position
                    local a, s = frame.AbsolutePosition, frame.AbsoluteSize
                    if not (mp.X >= a.X and mp.X <= a.X + s.X and mp.Y >= a.Y and mp.Y <= a.Y + s.Y) then
                        closeChooser()
                    end
                end
            end)
        end)
    end

    -- :: activation pill: click = rebind (any input), right-click = hold/toggle ::
    -- v0.66.1: enabled/held readers drive the latch tint. Callers pass closures
    -- over their own armed + held flags so Toggle visibly sticks.
    local function activationPill(row, cfg, enabled, held)
        local pill = new("TextButton", {
            Name = "ActivationPill", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.new(0, 30, 0, 16), AutomaticSize = Enum.AutomaticSize.X,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2, BorderSizePixel = 0,
            AutoButtonColor = false, Text = "-", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.TextMuted, ZIndex = 38, Parent = row,
        }, {
            pillCorner(), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }),
        })
        local function refresh() pill.Text = inputName(cfg.ActivationKey); syncActPills(true) end
        refresh()
        pill.MouseEnter:Connect(function()
            tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
        end)
        pill.MouseLeave:Connect(function()
            if not (pendingActivation and pendingActivation.pill == pill) then
                syncActPills(true)
            end
        end)
        pill.MouseButton1Click:Connect(function()
            -- v0.3.1: click-again cancels an active rebind on the same pill,
            -- preserving the existing key. Prior behaviour left you no way
            -- out of the "..." state except pressing a key or Escape.
            if pendingActivation and pendingActivation.pill == pill then
                pendingActivation.refresh(); pendingActivation = nil
                return
            end
            if pendingActivation and pendingActivation.pill ~= pill then pendingActivation.refresh() end
            pill.Text = "..."
            tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Accent })
            pendingActivation = { pill = pill, cfg = cfg, refresh = refresh }
        end)
        pill.MouseButton2Click:Connect(function() openChooser(pill, cfg) end)
        actPills[#actPills + 1] = {
            pill = pill,
            enabled = enabled or function() return true end,
            held = held or function() return false end,
        }
        syncActPills(true)
        return pill
    end

    -- :: firing / silent hooks (executor globals guarded: degrade cleanly) ::
    -- v0.0.79: prefer VirtualInputManager per v0.0.35 finding: on Potassium (and
    -- some other executors) mouse1click/mouse1press don't flip IsMouseButtonPressed
    -- and don't fire the game's InputBegan handler, so the game's weapon never sees
    -- a click. VIM's SendMouseButtonEvent DOES fire InputBegan reliably. Fall back
    -- to mouse1click / mouse1press+release only if VIM isn't available.
    local VIM = nil
    pcall(function() VIM = game:GetService("VirtualInputManager") end)
    -- v0.0.80: throttled LMB synthesis when the cursor is over the Koffee window,
    -- so silent/trigger can't re-click our own GUI (GetMouseLocation is inset-included;
    -- subtract GuiService:GetGuiInset() before comparing with AbsolutePosition).
    local GuiService = game:GetService("GuiService")
    local function mouseOverKoffee()
        if not (window and window.GroupTransparency < 1) then return false end
        local mp = UserInputService:GetMouseLocation()
        local inset = GuiService:GetGuiInset()
        local mx, my = mp.X - inset.X, mp.Y - inset.Y
        local wp, ws = window.AbsolutePosition, window.AbsoluteSize
        return mx >= wp.X and mx <= wp.X + ws.X
           and my >= wp.Y and my <= wp.Y + ws.Y
    end
    local function clickMouse()
        if mouseOverKoffee() then return end
        if VIM then
            -- v0.39.1: click at the live cursor, never 0,0 (that pressed
            -- the top-left pixel and stole selection on every trigger fire).
            local m = UserInputService:GetMouseLocation()
            pcall(function()
                VIM:SendMouseButtonEvent(m.X, m.Y, 0, true,  game, 0)
                VIM:SendMouseButtonEvent(m.X, m.Y, 0, false, game, 0)
            end)
            return
        end
        if mouse1click then pcall(mouse1click)
        elseif mouse1press and mouse1release then
            pcall(mouse1press); task.wait(); pcall(mouse1release)
        end
    end
    -- UNIVERSAL SILENT AIM: hooks the three fire-ray shapes (mouse reads,
    -- camera-rays, direct Workspace rays). Camera-ray + mouse reads redirect
    -- exactly; direct-cast rays only rotate the DIRECTION (never origin) and
    -- only when forward-facing (dir . LookVector > 0.5) and long-range (> 20),
    -- so camera-collision (Popper) and probe rays are skipped untouched.
    -- Hooks install once per session; all logic lives in getgenv-published
    -- resolvers so every re-exec just rewires the bodies.
    local function installSilentHooks()
        if Combat.Silent._hooked then return end
        Combat.Silent._hooked = true
        local genv = getgenv and getgenv()

        -- === LIVE LOGIC (repointable through getgenv every exec) ==================
        -- Each resolver returns (handled, value). handled=true short-circuits the
        -- game's real call; handled=false falls through to the original metamethod.
        local PASS_H, PASS_V = false, nil
        -- v0.0.35: redirect only when actually armed. silentPos is now kept fresh
        -- EVERY frame by the heartbeat (independent of LMB) so the redirect lands
        -- the instant the weapon reads it: fixes "Require Left-Click misses" (the
        -- old code set silentPos reactively, one frame behind the click). The LMB
        -- gate is applied HERE via a tracked flag: never IsMouseButtonPressed,
        -- which is a namecall and illegal inside these hooks.
        local function isArmed()
            if not silentPos then return false end
            -- v0.1.2 Second-Camera method: fully engagement-gated. Reads pass through
            -- REAL unless an actual shot is happening (optional activation key held +
            -- LMB down / post-click window). Between shots the game sees 100% vanilla
            -- aim data; during the window the full spoof set runs (v0.1.4).
            if Combat.Silent.Method == "Second-Camera" then
                if Combat.Silent.ActivationKey and not silentHeld then return false end
                return lmbDown or (os.clock() - lmbClickAt) < 0.12
            end
            if Combat.Silent.RequireLMB and not lmbDown then return false end
            return true
        end
        -- v0.0.64 Pos Spoof arm gate: active whenever a target is acquired (NO RequireLMB:
        -- "doesn't need left-click"). Only gated by the module + an optional activation key.
        -- v0.2.0: renamed Pos Spoof -> Wallbang and gated to the Raycast method ONLY. Under
        -- Forced MB / Second-Camera this is a hard no-op (posFire() collapses to false), so
        -- every legacy posFire()-guarded spoof block below is dormant unless the user picks
        -- Method = "Raycast". Wallbang's actual effect lives in the workspace:Raycast branch.
        local function posArmed()
            if Combat.Silent.Method ~= "Raycast" then return false end
            if not Combat.Silent.Wallbang then return false end
            if not (Combat.Silent.Enabled and silentPos and silentTarget) then return false end
            if Combat.Silent.ActivationKey and not silentHeld then return false end
            return true
        end
        -- v0.0.68: Pos Spoof only manipulates the ORIGIN during the actual shot (LMB frame).
        -- Doing it every frame corrupted the viewmodel (FpsController reads Camera.CFrame for
        -- BOTH the arms/gun render AND the shot): that broke the aim entirely. Gated to the
        -- fire frame, the viewmodel is normal between shots and only the shot gets moved.
        -- v0.0.75: RequireLMB OFF -> Pos Spoof fires continuously (matches silent aim's own
        -- RequireLMB behaviour); RequireLMB ON -> gated to the click frame + 120ms window so
        -- single-shot pistols/snipers that read one frame late still land. Fixes "pistols
        -- don't wallbang unless you hold left click" on games where the weapon reads mouse.Hit
        -- before our lmbDown flag flips.
        local function posFire()
            if not posArmed() then return false end
            -- v0.1.2: Second-Camera always rides the shot window (RequireLMB is
            -- inherent to the method: the click IS the engagement).
            if Combat.Silent.Method == "Second-Camera" then
                return lmbDown or (os.clock() - lmbClickAt) < 0.12
            end
            if not Combat.Silent.RequireLMB then return true end
            return lmbDown or (os.clock() - lmbClickAt) < 0.12
        end
        -- Camera.CFrame spoof gate for Forced MB lives inline in resolveIndex now
        -- (v0.1.8: RequireLMB-off is continuous for non-writer callers; learned camera
        -- writers stay click-window gated). The old camFire() helper is gone.
        -- the wallbang shot geometry: origin 3 studs IN FRONT of the target (your side, past
        -- any wall between you and them), aimed AT the target -> the client raycast hits them
        -- with no wall in the way. Uses cached camPos (no Camera re-read inside the hook).
        local function wallShot()
            local cp = SR.camPos
            if not cp then return silentPos, Vector3.new(0, 0, -1) end
            local d = silentPos - cp
            if d.Magnitude < 1e-3 then return silentPos, Vector3.new(0, 0, -1) end
            d = d.Unit
            return silentPos - d * 3, d
        end
        -- v0.34.0: wallbang for Forced Camera: shifts the spoofed Camera.CFrame to the
        -- wallshot location, so every weapon-facing read of the camera fires through walls.
        -- (Second-Camera wallbang lives on the outbound Ray rewrite instead: write scripts.)
        local function camWallbang()
            return Combat.Silent.Wallbang and not Combat.Silent._safe
                and Combat.Silent.Method == "Forced Camera"
                and silentPos ~= nil and silentTarget ~= nil
                and (not Combat.Silent.ActivationKey or silentHeld)
        end
        -- optional diagnostic: getgenv().KoffeePosDebug -> throttled log of what got spoofed
        -- for which calling script (confirms the weapon's reads are being caught).
        local lastDbg = 0
        local function dbg(what)
            if not (genv and genv.KoffeePosDebug) then return end
            local now = os.clock()
            if now - lastDbg < 0.5 then return end
            lastDbg = now
            print("[koffee][pos] spoofed " .. what .. " caller=" .. tostring(getCS and getCS()))
        end
        -- v0.1.6: outbound-path diagnostic: throttled log of EVERY FireServer/InvokeServer
        -- from a learned-controller script: arg types + whether any shape matched. This is
        -- how you tell "rewrite never fired" from "fired but the game uses buffer blobs".
        local lastOutDbg = 0
        -- SAFE default: redirect ONLY the Mouse's own aim reads (Hit / Target /
        -- UnitRay). These are what FE weapons read and NOTHING else in the engine
        -- touches, so cameras, Popper occlusion, physics and other scripts stay
        -- untouched: this is why the default never breaks the game / camera.
        local function resolveIndex(self, key)
            -- v0.18.0 SHOOT IN CAR (place-gated): spoof IsPlaying and SeatPart.
            -- Single __index hook delegates here (stacking hooks silently wins one).
            if Combat.Gun.ShootInCar and (key == "IsPlaying" or key == "SeatPart")
               and typeof(self) == "Instance" then
                if key == "IsPlaying" and self:IsA("AnimationTrack") then
                    local ok, anim = pcall(function() return self.Animation end)
                    if ok and anim and anim.AnimationId == Koffee._gunHoldAnim then return true, true end
                elseif key == "SeatPart" and self:IsA("Humanoid") then
                    -- ours only. Spoofing every humanoid would desync other players'
                    -- seated state for anything in the game that reads it.
                    if self.Parent == LocalPlayer.Character then return true, nil end
                end
                return PASS_H, PASS_V
            end
            -- v0.77.0 INFINITE AMMO (universal): spoof .Value reads on HUD ammo
            -- counters instead of writing them. Reads lie, writes pass through,
            -- so regen and reload code never sees a dirty value to correct.
            -- Scope is PlayerGui only (fail open when the gui cache is empty).
            if Combat.Gun.InfiniteAmmo and key == "Value"
               and typeof(self) == "Instance" and self:IsA("ValueBase") then
                local nm = string.lower(tostring(self.Name))
                if nm == "ammocount" or nm == "ammocount2" or nm == "ammo"
                   or nm == "currentammo" or nm == "magammo" or nm == "clipammo" then
                    local gui = Combat.Gun._ammoGui
                    if gui ~= nil then
                        local p, depth = self.Parent, 0
                        while p ~= nil and depth < 10 do
                            if p == gui then return true, 999 end
                            p, depth = p.Parent, depth + 1
                        end
                    end
                end
                return PASS_H, PASS_V
            end
            -- v0.11.1 Perfect Lock, answered above everything silent-aim (method,
            -- enabled state, LMB gate) so it never depends on them. Mouse aim reads
            -- only: the same subset safe mode allows.
            if plArmed() and (key == "Hit" or key == "Target" or key == "UnitRay")
               and typeof(self) == "Instance" and self:IsA("Mouse") then
                if key == "Hit" then return true, CFrame.new(plPos) end
                if key == "Target" then return true, plPart end
                if SR.camPos then return true, Ray.new(SR.camPos, (plPos - SR.camPos).Unit) end
                return PASS_H, PASS_V
            end
            -- v0.3.0: External method delegates ALL silent-aim work to KoffeeHelper.exe
            -- over localhost HTTP. Under this method, every Lua-side spoof stays dormant
            -- so the game sees 100% vanilla client behaviour: the raycast rewrite
            -- happens inside Roblox via the helper's inline hook on the raycast bound
            -- function, not here.
            if Combat.Silent.Method == "External" then return PASS_H, PASS_V end
            -- (A) Mouse aim reads (Hit/Target/UnitRay): safe on every game, no caller
            -- scoping needed (nothing but aim code reads these). v0.0.35 behaviour.
            if (key == "Hit" or key == "Target" or key == "UnitRay")
               and typeof(self) == "Instance" and self:IsA("Mouse") then
                if not isArmed() then return PASS_H, PASS_V end
                local pos, tgt = silentPos, silentTarget
                if key == "Hit" then return true, CFrame.new(pos) end
                if key == "Target" then return true, tgt end
                -- UnitRay: Pos Spoof (fire frame) -> origin in front of the target (wallbang);
                -- else the real camera origin (direction to target). Pos Spoof is
                -- gated off in safe mode: keep the plain camera-origin ray.
                -- v0.2.0: Raycast method's wallbang lives ONLY in the workspace:Raycast
                -- branch (see resolveNamecall). Skip the UnitRay wallshot cascade so
                -- the mouse.UnitRay fallback stays honest camera->target under Raycast.
                if not Combat.Silent._safe and Combat.Silent.Method ~= "Raycast"
                   and posFire() then local o, d = wallShot(); return true, Ray.new(o, d) end
                if SR.camPos then return true, Ray.new(SR.camPos, (pos - SR.camPos).Unit) end
                return PASS_H, PASS_V
            end
            -- v0.0.96 SAFE MODE: everything below (Camera.CFrame spoof, Mouse.X/Y
            -- spoof, Pos Spoof part reads) is skipped on weak execs: these paths
            -- are the ones that freeze/dump the game on runtimes that can't hold a
            -- stable hookmetamethod C-closure across the extra scoping work. Mouse
            -- aim reads above are enough for basic silent aim on client-authoritative
            -- games; server-authoritative wallbang stays disabled here.
            if Combat.Silent._safe then return PASS_H, PASS_V end
            -- (B) v0.0.39 FIRE-READ: spoof the aim the instant the WEAPON SCRIPT reads
            -- Camera.CFrame or the cursor: scoped by getcallingscript so the real
            -- camera/renderer is never modified. Camera.CFrame is gated by camFire
            -- (fire-frame window; continuous spoof froze custom camera controllers);
            -- Mouse.X/Y uses isArmed (continuous: only aim code reads mouse coords).
            -- v0.1.5 Second-Camera: the CFrame gate is ENGAGEMENT, not the click window.
            -- While armed (target + activation key if set), weapon-facing callers get the
            -- bent CFrame CONTINUOUSLY and learned renderers (writer-detector) always get
            -- real CFrame via spoofAim: so a separate controller never moves your view,
            -- spray or not. Merged handler+weapon games degrade (their script writes the
            -- camera -> excluded -> switch to Forced MB there).
            local scCam = false
            if Combat.Silent.Method == "Second-Camera" then
                scCam = silentPos ~= nil
                    and (not Combat.Silent.ActivationKey or silentHeld)
            elseif Combat.Silent.Method == "Forced Camera" and silentPos then
                -- Forced Camera. v0.1.8: Require Left-Click OFF is now TRULY continuous:
                -- v0.2.0: explicit method match: Raycast method never spoofs Camera.CFrame.
                -- the CFrame bend no longer collapses to the click window, EXCEPT for
                -- learned camera WRITERS (writer-detector set), which stay window-gated
                -- so custom-camera games can't freeze/crash under continuous spoofing
                -- (v0.0.89 lesson) while every pure-reader weapon script gets the
                -- always-on bend RequireLMB-off promises.
                if Combat.Silent.RequireLMB then
                    scCam = lmbDown or (os.clock() - lmbClickAt) < 0.12
                else
                    local msrc = getCS and getCS()
                    local mset = (msrc and genv) and genv[KID.ctx.keys.ctrl]
                    if mset and rawget(mset, msrc) then
                        scCam = lmbDown or (os.clock() - lmbClickAt) < 0.12
                    else
                        scCam = true
                    end
                end
            end
            if scCam then
                -- Camera.CFrame spoof, scoped by spoofAim (never the camera system).
                --   default (Forced MB): origin stays REAL, look-direction bends to target.
                --   Pos Spoof + fire frame: camera moves to 3 studs in FRONT of the target,
                --     looking at it, so a camera-origin gun raycasts into them through the wall
                --     (WALLBANG). Only on the shot frame, so the viewmodel stays normal.
                if key == "CFrame" and self == SR.cam and SR.camPos and silentPos then
                    if SR.spoofAim(getCS and getCS()) then
                        -- crash-safety: skip spoof if SR.camPos and silentPos coincide
                        -- (CFrame.new(pos, look) with pos == look produces NaN orientation
                        -- which can crash renderers / game scripts consuming the result).
                        if (silentPos - SR.camPos).Magnitude > 1e-3 then
                            dbg("Camera.CFrame")
                            if posFire() then
                                local o, d = wallShot(); return true, CFrame.new(o, o + d)
                            end
                            -- v0.34.0: Forced Camera wallbang: spoof the read to the
                            -- wallshot origin so camera-origin guns shoot through walls.
                            if camWallbang() then
                                local o, d = wallShot(); return true, CFrame.new(o, o + d)
                            end
                            return true, CFrame.new(SR.camPos, silentPos)
                        end
                    end
                end
            end
            -- v0.2.0: Mouse.X/Y is a Forced-MB/Second-Camera fire read (cursor spoof).
            -- Not raycast-flavored: skipped under the Raycast method.
            if isArmed() and Combat.Silent.Method ~= "Raycast" then
                if (key == "X" or key == "Y") and self == SR.mouse and SR.screen then
                    if SR.spoofAim(getCS and getCS()) then
                        return true, (key == "X") and SR.screen.X or SR.screen.Y
                    end
                end
            end
            -- (C) v0.0.64/65 POS SPOOF: report YOUR character/tool part + attachment positions
            -- as the target's, so the game's fire code builds the shot ORIGIN from inside the
            -- enemy (wallbang: the server ray starts inside them, no wall in the way, any
            -- range). Broad set = all character descendants incl. the gun's muzzle parts /
            -- attachments, so guns reading the tool position (not just HRP) land too. Real
            -- parts never move. Scoped by spoofAim (camera + Koffee excluded); no LMB gate.
            -- v0.2.0: Raycast method owns origin manipulation via workspace:Raycast ONLY:
            -- character/tool part reads stay honest so animations, IK and non-fire game
            -- systems that peek at those parts see truth. This block is legacy for the
            -- (now-dormant) Forced MB Pos Spoof; posFire() is already Raycast-gated but the
            -- explicit method guard keeps the intent readable.
            if posFire() and Combat.Silent.Method ~= "Raycast" then
                local sp = SR.spoofParts
                if sp and sp[self] then
                    if key == "Position" or key == "WorldPosition" then
                        if SR.spoofAim(getCS and getCS()) then dbg("part.Position"); return true, silentPos end
                    elseif key == "CFrame" or key == "WorldCFrame" then
                        if SR.spoofAim(getCS and getCS()) then dbg("part.CFrame"); return true, CFrame.new(silentPos) end
                    end
                elseif self == SR.mouse and key == "Origin" then
                    if SR.spoofAim(getCS and getCS()) then return true, CFrame.new(silentPos) end
                end
            end
            return PASS_H, PASS_V
        end
        local function resolveNamecall(self, method, args)
            -- v0.17.1 BULLET TRACER TAP: record outgoing shots, no rewrite.
            -- Namecall-free, args by reference so drawer shows actual path.
            if method == "FireServer" or method == "InvokeServer" then
                local q = Shared._bulletOut
                if q and Koffee.Bullets.Enabled and #q < 16 then
                    q[#q + 1] = { r = self, a = args, lk = Shared._bulletLook }
                end
            end
            -- v0.3.0: External method offloads everything to KoffeeHelper (see
            -- resolveIndex head comment). Every namecall passes through vanilla.
            if Combat.Silent.Method == "External" then return PASS_H, PASS_V end
            -- v0.0.39 fire-read universal path (always on: "Forced Magic-Bullet").
            -- CRITICAL: NOTHING in here may perform a Roblox namecall (a `:` method
            -- call). getnamecallmethod reads one shared C state, so a nested namecall
            -- while a real FireServer is dispatching corrupts it and bricks the weapon
            -- after one shot (this was the "one bullet then the gun dies" bug). Only
            -- global-fn calls, plain-table reads, property (__index) reads, equality
            -- and constructors are used below: no namecalls.
            -- v0.0.64 POS SPOOF: Character:GetPivot()/GetPrimaryPartCFrame -> target CFrame,
            -- BEFORE the LMB gate (Pos Spoof doesn't require left-click). Namecall-free.
            -- v0.2.0: legacy Forced-MB spoof: Raycast method skips this (same reasoning
            -- as the part.Position block: origin manipulation is workspace:Raycast-only).
            if method == "GetPivot" or method == "GetPrimaryPartCFrame" then
                if posFire() and Combat.Silent.Method ~= "Raycast"
                   and self == SR.char and SR.spoofAim(getCS and getCS()) then
                    return true, CFrame.new(silentPos)
                end
                return PASS_H, PASS_V
            end
            -- v0.1.6 OUTBOUND REWRITE (Second-Camera only): games whose weapon script
            -- WRITES the camera while firing (recoil / ADS / sway) can't have their reads
            -- bent at ALL without dragging the view (the writer-detector excludes them
            -- absolutely: a click-window waiver was tried and ripped same-day: bending a
            -- writer's reads at ANY time bends the view, because it writes back what it
            -- read). So for those scripts the reads stay REAL forever and the shot
            -- direction is rewritten inside the OUTGOING remote args instead: the client
            -- sees truth, the wire carries the lock. Surgical rules (v0.0.43/72 lesson:
            -- never clobber blind):
            --   * only callers already in the learned controller set are touched
            --   * direction-shaped Vector3s (sub-8 magnitude, within ~41 deg of the real
            --     look dir) rotate to aim at the target from the shooter's root; the
            --     original magnitude is preserved
            --   * point-shaped Vector3s (>50 studs out, within 12 studs of the look ray)
            --     move onto the target's hit point
            --   * Rays keep their EXACT origin; only the direction rotates
            --   * everything else passes untouched: args are never dropped/reordered/
            --     invented, so unmatched schemas behave exactly vanilla
            -- Namecall-safe: typeof / component math / constructors only: no :Dot(),
            -- :Unit() etc. on vectors (same shared-C-state rule as everything else here).
            if method == "FireServer" or method == "InvokeServer" then
                if Combat.Silent.Method ~= "Second-Camera" then return PASS_H, PASS_V end
                if not (silentPos and silentTarget and SR.camLook) then return PASS_H, PASS_V end
                if Combat.Silent.ActivationKey and not silentHeld then return PASS_H, PASS_V end
                local src = getCS and getCS()
                local set = (src and genv) and genv[KID.ctx.keys.ctrl]
                if not (set and rawget(set, src)) then return PASS_H, PASS_V end
                local origin = SR.rootPos or SR.camPos
                local lk = SR.camLook
                if not (origin and lk) then return PASS_H, PASS_V end
                local changed = false
                local matched = ""
                local touched = nil
                for i = 1, args.n do
                    local a = args[i]
                    local t = typeof(a)
                    if t == "Vector3" then
                        local m = a.Magnitude
                        if m > 1e-4 and m < 8 then
                            -- direction-shaped: near the real look direction?
                            if (a.X * lk.X + a.Y * lk.Y + a.Z * lk.Z) / m > 0.75 then
                                local nd = silentPos - origin
                                local nl = (nd.X * nd.X + nd.Y * nd.Y + nd.Z * nd.Z) ^ 0.5
                                if nl > 1e-3 then
                                    local s = m / nl
                                    args[i] = Vector3.new(nd.X * s, nd.Y * s, nd.Z * s)
                                    changed = true
                                    matched = matched .. i .. "(dir) "
                                end
                            end
                        elseif m >= 50 and SR.camPos then
                            -- point-shaped: far away AND hugging the look ray?
                            local rx, ry, rz = a.X - SR.camPos.X, a.Y - SR.camPos.Y, a.Z - SR.camPos.Z
                            local proj = rx * lk.X + ry * lk.Y + rz * lk.Z
                            if proj > 10 then
                                local px, py, pz = rx - lk.X * proj, ry - lk.Y * proj, rz - lk.Z * proj
                                if (px * px + py * py + pz * pz) ^ 0.5 < 12 then
                                    args[i] = silentPos
                                    changed = true
                                    matched = matched .. i .. "(pt) "
                                end
                            end
                        end
                    elseif t == "Ray" then
                        local o = a.Origin
                        -- v0.34.0: Second-Camera wallbang: shift the outgoing ORIGIN to
                        -- 3 studs in front of the target so a server-side wall check
                        -- between shooter and target passes. Off = keep the real origin.
                        if Combat.Silent.Wallbang and SR.camPos then
                            local dx, dy, dz = silentPos.X - SR.camPos.X, silentPos.Y - SR.camPos.Y, silentPos.Z - SR.camPos.Z
                            local dl = (dx * dx + dy * dy + dz * dz) ^ 0.5
                            if dl > 1e-3 then
                                o = Vector3.new(silentPos.X - dx / dl * 3, silentPos.Y - dy / dl * 3, silentPos.Z - dz / dl * 3)
                            end
                        end
                        local nd = silentPos - o
                        local nl = (nd.X * nd.X + nd.Y * nd.Y + nd.Z * nd.Z) ^ 0.5
                        if nl > 1e-3 then
                            local s = a.Direction.Magnitude / nl
                            args[i] = Ray.new(o, Vector3.new(nd.X * s, nd.Y * s, nd.Z * s))
                            changed = true
                            matched = matched .. i .. "(ray) "
                        end
                    end
                end
                if genv and genv.KoffeePosDebug then
                    local now2 = os.clock()
                    if now2 - lastOutDbg > 0.5 then
                        lastOutDbg = now2
                        local types = {}
                        for i = 1, args.n do types[i] = typeof(args[i]) end
                        print("[koffee][pos] outbound src=" .. tostring(src)
                            .. " n=" .. tostring(args.n)
                            .. " types=" .. table.concat(types, ",")
                            .. " matched=" .. (matched ~= "" and matched or "none"))
                    end
                end
                if changed then return "call", args end
                return PASS_H, PASS_V
            end
            -- v0.0.81: Wallbang Raycast REMOVED (as an always-on Forced-MB add-on). Was
            -- detected by some ACs, didn't work on Gun Grounds FFA (camera-baked-arg class
            --: see v0.0.42/74 history), and didn't cover Jack's tested game (the
            -- KoffeePosDebug log from v0.0.78 showed only Camera.CFrame spoofs + one stray
            -- raycast intercept: the weapon doesn't call workspace raycasts at fire time).
            -- v0.2.0: RE-ADDED, opt-in, as the "Raycast" method (see branch below). Now it
            -- is a top-level Method choice instead of an always-on cascade: users pick it
            -- specifically for FE FPS raycast weapons (Phantom Forces / Arsenal / Aimblox
            -- class). Wallbang rides on this method exclusively.
            if not isArmed() then return PASS_H, PASS_V end
            -- v0.2.0 RAYCAST METHOD: universal workspace:Raycast rewrite for games whose
            -- weapon builds its own ray (muzzle attachment / camera vector) and passes it
            -- straight into workspace:Raycast: these skip every Mouse/Camera read the
            -- Forced-MB spoofs catch. Direction rotates to point at the target from the
            -- caller's real origin; magnitude preserved so range checks pass. Wallbang
            -- (posFire) additionally moves the origin to 3 studs in FRONT of the target so
            -- the client ray reaches them through any wall. Gate order (namecall-safe: only
            -- constructors + component math, zero `:` calls):
            --   * dir.Magnitude > 20: skip probe/occlusion/IK rays
            --   * dir approx aligned with camLook OR with (target - origin): fire-shaped only
            -- Cheap comparisons short-circuit the 99% pass-through case.
            if method == "Raycast" and self == Workspace then
                if Combat.Silent.Method ~= "Raycast" then return PASS_H, PASS_V end
                if not silentPos then return PASS_H, PASS_V end
                local origin, dir, rparams = args[1], args[2], args[3]
                if typeof(origin) ~= "Vector3" or typeof(dir) ~= "Vector3" then return PASS_H, PASS_V end
                local mag = dir.Magnitude
                if mag < 20 then return PASS_H, PASS_V end
                local unit = dir / mag
                local aim = silentPos - origin
                local aimMag = aim.Magnitude
                if aimMag < 1e-3 then return PASS_H, PASS_V end
                local aimUnit = aim / aimMag
                local look = SR.camLook
                local dotLook = look and (look.X*unit.X + look.Y*unit.Y + look.Z*unit.Z) or -1
                local dotAim  = aimUnit.X*unit.X + aimUnit.Y*unit.Y + aimUnit.Z*unit.Z
                if dotLook < 0.5 and dotAim < 0.5 then return PASS_H, PASS_V end
                if posFire() then
                    local wo = silentPos - aimUnit * 3
                    dbg("workspace:Raycast (wallbang)")
                    return "call", { wo, aimUnit * mag, rparams }
                end
                dbg("workspace:Raycast")
                return "call", { origin, aimUnit * mag, rparams }
            end
            -- v0.2.0: ViewportPointToRay/ScreenPointToRay + GetMouseLocation are
            -- Forced-MB/Second-Camera fire reads. Skipped under Raycast method (that
            -- method deliberately touches ONLY Mouse.Hit reads + workspace:Raycast).
            if Combat.Silent.Method == "Raycast" then return PASS_H, PASS_V end
            -- camera-ray / cursor methods the game uses to build its shot. Direction bends to
            -- the target; on the Pos Spoof fire frame the ORIGIN moves in front of the target
            -- (wallbang), else real (SR.camPos). spoofAim excludes the camera + Koffee. Namecall-free.
            if method == "ViewportPointToRay" or method == "ScreenPointToRay" then
                if silentPos and SR.camPos and SR.spoofAim(getCS and getCS()) then
                    if posFire() then local o, d = wallShot(); return true, Ray.new(o, d) end
                    return true, Ray.new(SR.camPos, (silentPos - SR.camPos).Unit)
                end
            elseif method == "GetMouseLocation" then
                if SR.screen and SR.spoofAim(getCS and getCS()) then
                    return true, SR.screen
                end
            end
            return PASS_H, PASS_V
        end
        -- publish resolvers under obfuscated session-stable keys (no static "Koffee*" in getgenv)
        local K = KID.ctx.keys
        if genv then
            genv[K.ri]  = resolveIndex
            genv[K.nc]  = resolveNamecall
            genv[K.res] = function() return silentPos, silentTarget end
            -- v0.1.5: learned camera-controller set (weak keys -> destroyed scripts GC out).
            -- Session-stable: survives re-exec so what a game taught us isn't unlearned.
            if not genv[K.ctrl] then
                genv[K.ctrl] = setmetatable({}, { __mode = "k" })
            end
        end

        -- HOOK BODY: installed once per session, forever. Delegates to the repointable
        -- resolvers above so re-exec rewires behaviour without reinstalling the hook.
        if genv and genv[K.hooked] then return end
        if genv then genv[K.hooked] = true end
        pcall(function()
            local hookmm   = hookmetamethod
            local ncmethod = getnamecallmethod
            local ccaller  = checkcaller   -- true => called from our own executor thread
            if not hookmm then return end

            -- v0.0.96 SAFE MODE branch. On runtimes flagged by the load-time exec
            -- prompt (anything not on the known-good list), silent aim installs
            -- ONLY the __index hook, without newcclosure wrapping, without the
            -- __namecall hook, and the resolver never runs the Camera.CFrame /
            -- pos-spoof / wallshot paths (see Combat.Silent._safe checks inside
            -- resolveIndex). This avoids the newcclosure+__namecall pairing that
            -- freezes lightweight runtimes when a weapon triggers a FireServer
            -- redirect. Result: less powerful silent aim (no wallbang, no server-
            -- side forced-mb via namecall), but the game doesn't crash. Trade-off
            -- is what the popup asked the user about.
            local safe = Koffee._safeMode == true
            Combat.Silent._safe = safe
            local wrap = safe and function(f) return f end
                                or (newcclosure or function(f) return f end)

            local oldIndex
            oldIndex = hookmm(game, "__index", wrap(function(self, key)
                -- our own reads are never spoofed; also defeats trap-callbacks that
                -- run in our context and probe the hook behaviorally.
                if ccaller and ccaller() then return oldIndex(self, key) end
                local r = genv and genv[K.ri]
                if r then
                    local ok, handled, value = pcall(r, self, key)
                    if ok and handled then return value end
                end
                return oldIndex(self, key)
            end))

            if not safe then
                local oldNc
                oldNc = hookmm(game, "__namecall", wrap(function(self, ...)
                    -- Capture method BEFORE anything else. NEVER do a nested namecall here:
                    -- getnamecallmethod reads one shared C state; a nested namecall while a
                    -- real FireServer is dispatching corrupts it and bricks the weapon after
                    -- one shot ("one bullet then the gun dies" bug, fixed in v0.0.40).
                    local m = ncmethod and ncmethod() or ""
                    if ccaller and ccaller() then return oldNc(self, ...) end
                    local r = genv and genv[K.nc]
                    if r then
                        local args = table.pack(...)
                        local ok, handled, value = pcall(r, self, m, args)
                        if ok then
                            if handled == true then return value end
                            if handled == "call" then return oldNc(self, table.unpack(value, 1, args.n)) end
                        end
                    end
                    return oldNc(self, ...)
                end))

                -- v0.1.5 Second-Camera WRITER-DETECTOR: any game script that writes
                -- Camera.CFrame is a camera RENDERER/CONTROLLER (FpsController, custom
                -- orbit cams...). Recorded session-stable under K.ctrl (weak keys:
                -- destroyed scripts GC out) and excluded from spoofing by SR.spoofAim.
                -- Two cheap comparisons short-circuit the 99.9% case; only CFrame writes
                -- on the current camera do work. getcallingscript is a plain read here
                -- (no namecall involved), so this is hook-body safe.
                local gcs = getcallingscript
                local oldWi
                oldWi = hookmm(game, "__newindex", wrap(function(self, k, v)
                    if Combat.Silent.Method == "Second-Camera"
                        and k == "CFrame" and self == SR.cam then
                        if ccaller and ccaller() then return oldWi(self, k, v) end
                        if gcs then
                            local src = gcs()
                            if src and src ~= SR.own then
                                local set = genv[K.ctrl]
                                if set then set[src] = true end
                            end
                        end
                    end
                    return oldWi(self, k, v)
                end))
            end
        end)
    end

    -- :: render loops ::
    -- aimbot: run AFTER every camera controller in the game (Last+1) so our
    -- CFrame is the final write before render: fast mouse movement can't shake
    -- a Perfect Lock. cold-start safety: a prior run's binding survives re-exec
    -- and re-binding the same name throws: unbind first so the loader can be
    -- re-run cleanly.
    pcall(function() RunService:UnbindFromRenderStep(KID.ctx.bind) end)
    RunService:BindToRenderStep(KID.ctx.bind, Enum.RenderPriority.Last.Value + 1, function()
        -- v0.11.1: cleared every frame and only re-set below, so the redirect can
        -- never outlive the frame that armed it.
        plPos, plPart = nil, nil
        -- v0.66.1: no key bound means always armed while enabled (matches silent).
        -- An unbound aim key used to wedge aimHeld false forever and kill the aimbot.
        if not Combat.Aim.Enabled or (Combat.Aim.ActivationKey and not aimHeld) then
            Combat.Aim._target = nil; Combat.Aim._rageLock = nil; return
        end
        -- Perfect Lock answers reads through the __index hook, so it needs that hook
        -- installed even with Silent Aim off. Covers keybind + config-load paths too.
        if Combat.Aim.PerfectLock and not Combat.Silent._hooked then installSilentHooks() end
        local cam = Workspace.CurrentCamera
        if not cam then return end
        local maxR = Combat.Aim.FOV.Enabled and Combat.Aim.FOV.Size or math.huge
        local aimCenter = fovCenter(Combat.Aim.FOV)

        -- RAGEBOT: lock onto ONE victim when the key goes down and keep teleporting
        -- to them EVERY frame until release: independent of Sticky, so you keep
        -- full camera look (up/down) while the teleport tracks the locked player.
        if Combat.Aim.Rage then
            local lock = Combat.Aim._rageLock
            local part
            if lock and lock.Character then
                local hum = lock.Character:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 then part = aimPart(lock.Character, Combat.Aim.HitPart) end
            end
            if not part then
                lock, part = getBestTarget(Combat.Aim, maxR, aimCenter)
                Combat.Aim._rageLock = lock
            end
            if not (lock and part) then return end
            local tpos = predicted(lock, part, Combat.Aim.Predict)
            if Combat.Misc.Resolver then tpos = dwellPos(lock, part, tpos) end
            if Combat.Aim.RageType == "Character Teleport" then
                local myc = LocalPlayer.Character
                local myroot = myc and (myc:FindFirstChild("HumanoidRootPart") or findTorso(myc))
                if myroot then
                    myroot.CFrame = CFrame.new(tpos + Vector3.new(0, Combat.Aim.RageYOffset, 0)) * myroot.CFrame.Rotation
                end
            else
                cam.CFrame = CFrame.new(tpos) * cam.CFrame.Rotation
            end
            return
        end
        Combat.Aim._rageLock = nil

        local plr, part
        -- v0.0.97 true sticky: hold the locked player across FOV / off-screen, only
        -- drop when the player dies / respawns / leaves. The aim math (lookAt /
        -- aimCFrame) handles a target behind the camera by rotating back toward it,
        -- so the locked victim is chased off-screen too: not replaced the moment
        -- they leave the FOV circle. Falls through to getBestTarget for a fresh lock
        -- only when there's no valid held target.
        if Combat.Aim.Sticky and Combat.Aim._target then
            local t = Combat.Aim._target
            local char = t.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if char and hum and hum.Health > 0 then
                local p = aimPart(char, Combat.Aim.HitPart)
                -- v0.0.97: respect the Distance rule even for a held sticky target:
                -- if they run beyond Combat.Aim.Distance the lock releases and a fresh
                -- target is acquired inside range.
                if p then
                    local distOk = (not Combat.Aim.Distance)
                                or ((p.Position - cam.CFrame.Position).Magnitude <= Combat.Aim.Distance)
                    if distOk then
                        plr, part = t, p
                    end
                end
            end
        end
        if not plr then
            plr, part = getBestTarget(Combat.Aim, maxR, aimCenter)
            Combat.Aim._target = plr
        end
        if not (plr and part) then return end
        local tpos = predicted(plr, part, Combat.Aim.Predict)
        if Combat.Misc.Resolver then tpos = dwellPos(plr, part, tpos) end

        -- v0.50.0 legit kit. Reaction holds fire on fresh locks; jitter offsets
        -- the aim point by true angle (range independent); overshoot starts off
        -- in a fixed random direction and glides on. All paths share tpos.
        local LG = Combat.Aim.Legit
        local now = os.clock()
        if LG._acqPlr ~= plr then
            LG._acqPlr, LG._acqAt = plr, now
            local a = math.random() * math.pi * 2
            LG._osPlr, LG._osX, LG._osY, LG._osAt = plr, math.cos(a), math.sin(a), now
        end
        -- v0.52.0: the whole legit kit is gated behind the Legit master toggle.
        if LG.Enabled and (LG.Reaction or 0) > 0 and (now - (LG._acqAt or now)) * 1000 < LG.Reaction then return end
        if LG.Enabled and ((LG.Jitter or 0) > 0 or (LG.Overshoot or 0) > 0) and cam then
            local toT = tpos - cam.CFrame.Position
            local dist = toT.Magnitude
            if dist > 1e-3 then
                local cf = cam.CFrame
                local ox, oy = 0, 0
                if (LG.Jitter or 0) > 0 then
                    local m = dist * math.tan(math.rad(LG.Jitter))
                    ox = ox + (math.random() * 2 - 1) * m
                    oy = oy + (math.random() * 2 - 1) * m
                end
                if (LG.Overshoot or 0) > 0 and LG._osPlr == plr then
                    local dk = math.exp(-(now - (LG._osAt or now)) * 4)
                        * dist * math.tan(math.rad(LG.Overshoot))
                    ox = ox + (LG._osX or 0) * dk
                    oy = oy + (LG._osY or 0) * dk
                end
                tpos = tpos + cf.RightVector * ox + cf.UpVector * oy
            end
        end
        -- v0.51.0 deadzone: while the (fully humanized) point sits within N
        -- pixels of the aim center, touch nothing. The mouse only moves once
        -- the target truly leaves it. Sticky stays locked throughout.
        local dz = LG.Deadzone or 0
        if LG.Enabled and dz > 0 and cam then
            local dsp = cam:WorldToViewportPoint(tpos)
            if dsp.Z > 0 then
                local dd = (Vector2.new(dsp.X, dsp.Y) - aimCenter).Magnitude
                if dd <= dz then return end
            end
        end

        -- sensitivity (base pull) + optional per-axis smoothness (higher = slower)
        -- v0.0.86 sensitivity curve reshape. Was linear 0.01..1: 0.08 was already
        -- fast because 8% per frame converges to target in a few frames. Now sens^1.5
        -- pushes the low end down without touching the max: 1.0 -> 1.0 (perfect lock),
        -- 0.5 -> 0.354 (moderate), 0.08 -> 0.023 (smooth pull), 0.01 -> 0.001 (glacial).
        -- Endpoints preserved so users' existing feel at max/near-max is unchanged.
        local rawSens = math.clamp(Combat.Aim.Sensitivity, 0.01, 1)
        local sens = rawSens * math.sqrt(rawSens)   -- sens^1.5
        local aX, aY = sens, sens
        if Combat.Aim.Smooth.Enabled then
            aX = math.clamp(sens / math.max(Combat.Aim.Smooth.X, 0.01), 0, 1)
            aY = math.clamp(sens / math.max(Combat.Aim.Smooth.Y, 0.01), 0, 1)
        end

        if Combat.Aim.PerfectLock then
            -- v0.27.0: TRUE snap. Publish the redirect, then aim exactly this frame:
            -- no sensitivity/smoothing/euler.
            -- v0.58.4: when AimType is Mouse (or Third Person), drive the REAL mouse
            -- onto the target's exact screen point instead of writing cam.CFrame.
            -- Games like Phantom Forces aim off the mouse and run their own camera,
            -- so a written CFrame is stomped/detected while a mouse move feeds the
            -- game's own aim pipeline. Camera snap otherwise.
            -- v0.58.5: the mouse move is a feedback loop through the game's own
            -- sensitivity, so a raw full-delta snap OVERSHOOTS at high in-game sens
            -- and oscillates (shake/flicker). Smoothing now damps it: OFF = full
            -- snap (factor 1), ON = delta * 1/Smooth per axis, so it converges in a
            -- couple of frames without overshoot. Sensitivity stays ignored (perfect).
            plPos, plPart = tpos, part
            if Combat.Aim.ThirdPerson or Combat.Aim.AimType == "Mouse" then
                local sp = cam:WorldToViewportPoint(tpos)
                if sp.Z > 0 and mousemoverel then
                    local ml = UserInputService:GetMouseLocation()
                    local pfX, pfY = 1, 1
                    if Combat.Aim.Smooth.Enabled then
                        pfX = math.clamp(1 / math.max(Combat.Aim.Smooth.X, 0.01), 0, 1)
                        pfY = math.clamp(1 / math.max(Combat.Aim.Smooth.Y, 0.01), 0, 1)
                    end
                    pcall(mousemoverel, (sp.X - ml.X) * pfX, (sp.Y - ml.Y) * pfY)
                end
            else
                cam.CFrame = CFrame.new(cam.CFrame.Position, tpos)
            end
            return
        end
        if Combat.Aim.ThirdPerson then
            -- v0.0.36.1: drive the REAL mouse onto the target's screen point. Measured
            -- live: WorldToViewportPoint INCLUDES the 58px GUI inset but PlayerMouse.X/Y
            -- does NOT: mixing them aimed a constant ~58px low (whole-body error at
            -- range). GetMouseLocation() is inset-included, matching WorldToViewportPoint,
            -- so the delta is 0 exactly on-target. Each frame nudges the cursor a fraction
            -- (aX/aY) and converges. Works free-cursor AND shift-lock.
            local sp = cam:WorldToViewportPoint(tpos)
            if sp.Z > 0 and mousemoverel then
                local ml = UserInputService:GetMouseLocation()
                pcall(mousemoverel, (sp.X - ml.X) * aX, (sp.Y - ml.Y) * aY)
            end
        elseif Combat.Aim.AimType == "Mouse" then
            local sp = cam:WorldToViewportPoint(tpos)
            if sp.Z > 0 and mousemoverel then
                pcall(mousemoverel, (sp.X - aimCenter.X) * aX, (sp.Y - aimCenter.Y) * aY)
            end
        else
            cam.CFrame = aimCFrame(cam, cam.CFrame.Position, tpos, aX, aY)
        end
    end)

    -- custom multi-point gradient: Colors/Alphas map LEFT-TO-RIGHT (swatch 1..n).
    -- STATIC: plain linear ramp c1..cn evenly spaced across 0..1.
    -- MOVING: seamless cyclic scroll: palette is a ring (cn wraps to c1), sampled
    -- at fixed screen positions offset by a phase. pos 0 + pos 1 sample the same
    -- ring point, so no seam and no snap (fixes the "bounce" + stretch).
    local function ringSample(t, get, n)
        t = t % 1
        local seg = t * n
        local i = math.floor(seg)
        local f = seg - i
        local a = get((i % n) + 1)
        local b = get(((i + 1) % n) + 1)
        return a, b, f
    end
    local function ringColor(C, n, t)
        local a, b, f = ringSample(t, function(k) return C[k] end, n)
        return a:Lerp(b, f)
    end
    local function ringAlpha(A, n, t)
        local a, b, f = ringSample(t, function(k) return A[k] end, n)
        return a + (b - a) * f
    end
    local function customColorSeq(cs)
        local C, n = cs.Colors, math.clamp(cs.Points or 2, 2, 4)
        local kps = {}
        for k = 1, n do kps[k] = ColorSequenceKeypoint.new((k - 1) / (n - 1), C[k]) end
        return ColorSequence.new(kps)
    end
    local function customTransSeq(cs)
        local A, n = cs.Alphas, math.clamp(cs.Points or 2, 2, 4)
        local kps = {}
        for k = 1, n do kps[k] = NumberSequenceKeypoint.new((k - 1) / (n - 1), A[k]) end
        return NumberSequence.new(kps)
    end
    local function scrollColorSeq(cs, s)
        local C, n = cs.Colors, math.clamp(cs.Points or 2, 2, 4)
        local kps = {}
        for k = 0, n do kps[k + 1] = ColorSequenceKeypoint.new(k / n, ringColor(C, n, (k / n) + s)) end
        return ColorSequence.new(kps)
    end
    local function scrollTransSeq(cs, s)
        local A, n = cs.Alphas, math.clamp(cs.Points or 2, 2, 4)
        local kps = {}
        for k = 0, n do kps[k + 1] = NumberSequenceKeypoint.new(k / n, ringAlpha(A, n, (k / n) + s)) end
        return NumberSequence.new(kps)
    end

    -- draw one FOV circle from its config. Both aimbot + silent circles use this.
    -- v0.4.0: HideVisual hides everything the ring draws (circle, stroke, dots,
    -- fill, gradient) while leaving cfg.Enabled + cfg.Size intact for the
    -- targeting gate in getBestTarget. Effectively "invisible FOV".
    local function drawFov(h, cfg)
        if (not cfg.Enabled) or cfg.HideVisual then
            h.circle.Visible = false
            if h.dotContainer then h.dotContainer.Visible = false end
            if h.stroke then h.stroke.Enabled = false end
            return
        end
        local size = cfg.Size
        local c = fovCenter(cfg)
        h.circle.Visible = true
        h.circle.Position = UDim2.new(0, c.X, 0, c.Y)
        h.circle.Size = UDim2.new(0, size * 2, 0, size * 2)
        local dotsMode = cfg.Style == "Dots"
        local fillCfg  = cfg.Fill
        local custom   = fillCfg.Custom
        local filled   = cfg.Filled and not dotsMode
        local now      = os.clock()
        local spinDeg  = (now * 90) % 360

        -- FILL
        if filled then
            if custom.Enabled then
                h.circle.BackgroundColor3 = Color3.new(1, 1, 1)
                h.circle.BackgroundTransparency = cfg.FillTransparency
                if h.grad then
                    h.grad.Enabled = true
                    h.grad.Offset = Vector2.new(0, 0)   -- scroll is baked into the seq, never the offset
                    if custom.Moving.Enabled and not custom.Triangle then
                        local s = (now * custom.Moving.Speed * 0.15) % 1
                        h.grad.Color = scrollColorSeq(custom, s)
                        h.grad.Transparency = scrollTransSeq(custom, s)
                    else
                        h.grad.Color = customColorSeq(custom)
                        h.grad.Transparency = customTransSeq(custom)
                    end
                    local rot = custom.Moving.Direction or 0
                    if fillCfg.Spin or cfg.Spin then rot = rot + spinDeg end
                    h.grad.Rotation = rot
                end
            else
                -- v0.0.34: the FOV Fill is now FULLY decoupled from the Visuals
                -- "Gradient" toggle. Without its own Custom Gradient enabled the
                -- fill is a solid FillColor: the ESP gradient never bleeds in.
                if h.grad then h.grad.Enabled = false end
                h.circle.BackgroundColor3 = cfg.FillColor
                h.circle.BackgroundTransparency = cfg.FillTransparency
            end
        else
            if h.grad then h.grad.Enabled = false end
            h.circle.BackgroundTransparency = 1
        end

        -- OUTLINE (RemoveOutline drops the ring even with fill on)
        if h.stroke then
            h.stroke.Color = cfg.Color
            h.stroke.Thickness = cfg.Thickness
            h.stroke.Enabled = (not dotsMode) and (not fillCfg.RemoveOutline)
        end

        -- DOTS (count scales with size; gap + dot size configurable; spins)
        h.dotContainer.Visible = dotsMode
        if dotsMode then
            local count = math.clamp(math.floor((2 * math.pi * size) / math.max(cfg.DotGap, 4)), 3, FOV_MAX_DOTS)
            local baseRot = cfg.Spin and math.rad(spinDeg) or 0
            for i = 1, FOV_MAX_DOTS do
                local d = h.dots[i]
                if i <= count then
                    local ang = (i / count) * math.pi * 2 + baseRot
                    d.Position = UDim2.new(0.5, math.cos(ang) * size, 0.5, math.sin(ang) * size)
                    d.Size = UDim2.new(0, cfg.DotSize, 0, cfg.DotSize)
                    d.BackgroundColor3 = cfg.Color
                    d.Visible = true
                else
                    d.Visible = false
                end
            end
        end
    end

    -- snapline: v0.0.36.1: origin follows the mouse cursor. Uses GetMouseLocation()
    -- (inset-included, like WorldToViewportPoint + the IgnoreGuiInset overlay) so the
    -- line anchors exactly ON the cursor. The old PlayerMouse.X/Y source excluded the
    -- 58px inset, which floated the origin ~58px above the cursor.
    local function drawSnaplines()
        local cfg, ctx, part
        if Combat.Aim.Snaplines then
            cfg, ctx = Combat.Aim, Combat.Aim.FOV
            -- focus on the person currently being targeted (locked/aimed)
            local t = Combat.Aim._rageLock or Combat.Aim._target
            if t and t.Character then part = aimPart(t.Character, cfg.HitPart) end
        elseif Combat.Silent.Snaplines then
            cfg, ctx = Combat.Silent, Combat.Silent.FOV
            part = silentTarget
        end
        if not cfg then snapLine.Visible = false; return end
        local cam = Workspace.CurrentCamera
        if not cam then snapLine.Visible = false; return end
        local origin = UserInputService:GetMouseLocation()
        if not part then
            local maxR = ctx.Enabled and ctx.Size or math.huge
            local _, p = getBestTarget(cfg, maxR, origin)
            part = p
        end
        if not part then snapLine.Visible = false; return end
        local sp = cam:WorldToViewportPoint(part.Position)
        if sp.Z <= 0 then snapLine.Visible = false; return end
        local ex, ey = sp.X, sp.Y
        local dx, dy = ex - origin.X, ey - origin.Y
        local dist = (part.Position - cam.CFrame.Position).Magnitude
        local thick = featureThickness(dist)
        snapLine.Visible = true
        snapLine.Position = UDim2.new(0, (origin.X + ex) * 0.5, 0, (origin.Y + ey) * 0.5)
        snapLine.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy), 0, thick)
        snapLine.Rotation = math.deg(math.atan2(dy, dx))
        snapLine.BackgroundColor3 = ESP.Tracer.Color
        applyLineOutline(snapLine, ESP.Config.Outline, ESP.Boxes.OutlineColor, math.max(1, thick))
        applyLineGradient(snapLine, ESP.Config.Gradient)
    end

    -- v0.5.0: advance the FOV Follow-target lerp once per frame per cfg. Reads the
    -- "current target" for the cfg's owner (aim uses _rageLock or _target; silent
    -- uses the silentTarget part). Falls back to the default origin (Center/Mouse)
    -- when there's no target. Called BEFORE drawFov so this frame's fovCenter reads
    -- the freshly-advanced cache.
    local function stepFovFollow(cfg)
        if not (cfg and cfg.Follow and cfg.Follow.Enabled) then return end
        local vp = viewport()
        local defX, defY = vp.X * 0.5, vp.Y * 0.5
        if cfg.Origin == "Mouse" then
            local m = UserInputService:GetMouseLocation()
            defX, defY = m.X, m.Y
        end
        -- resolve the follow target: a Part, not a Player.
        local part
        if cfg == Combat.Aim.FOV then
            local p = Combat.Aim._rageLock or Combat.Aim._target
            if p and p.Character then part = aimPart(p.Character, Combat.Aim.HitPart) end
        elseif cfg == Combat.Silent.FOV then
            part = silentTarget
        end
        local tx, ty = defX, defY
        if part then
            local cam = Workspace.CurrentCamera
            if cam then
                local sp = cam:WorldToViewportPoint(part.Position)
                if sp.Z > 0 then tx, ty = sp.X, sp.Y end
            end
        end
        -- smoothness 0=snap; 0.98=very slow. Actual per-frame lerp weight a = 1-s.
        local s = math.clamp(cfg.Follow.Smoothness or 0, 0, 0.98)
        local a = 1 - s
        local cx = cfg.Follow._screenX or defX
        local cy = cfg.Follow._screenY or defY
        cx = cx + (tx - cx) * a
        cy = cy + (ty - cy) * a
        cfg.Follow._screenX = cx
        cfg.Follow._screenY = cy
    end

    -- both FOV circles render independently of the aimbot/silent master toggles.
    RunService.RenderStepped:Connect(function()
        if Koffee.dead() then return end
        stepFovFollow(Combat.Aim.FOV)
        stepFovFollow(Combat.Silent.FOV)
        drawFov(aimFov, Combat.Aim.FOV)
        drawFov(silentFov, Combat.Silent.FOV)
        drawSnaplines()
    end)

    -- triggerbot (v0.0.36 rewrite). The old version fired on screen-space proximity
    -- to the crosshair (5px): pixel-tight and it never actually checked the crosshair
    -- was ON an enemy (a wall in the way still counted). Now it raycasts from the camera
    -- THROUGH the crosshair: it only fires if that ray's first hit is a live enemy
    -- character (team / friend checks applied, occlusion handled for free since the ray
    -- stops at the first wall). HitboxMul widens the sample into a small ring.
    local trigParams = RaycastParams.new()
    trigParams.FilterType = Enum.RaycastFilterType.Exclude
    local function crosshairEnemy()
        local cam = Workspace.CurrentCamera
        if not cam then return nil end
        local vp = cam.ViewportSize
        local cx, cy = vp.X * 0.5, vp.Y * 0.5
        trigParams.FilterDescendantsInstances = { LocalPlayer.Character }
        -- v0.50.0: ray length follows the Distance cap; Head Only accepts
        -- exact head hits. healthOk skips spawn-shielded targets like the rest.
        local rayLen = Combat.Trigger.Distance or 2000
        local headOnly = Combat.Trigger.HeadOnly
        local function castAt(px, py)
            local ray = cam:ViewportPointToRay(px, py)
            local res = Workspace:Raycast(ray.Origin, ray.Direction * rayLen, trigParams)
            if not (res and res.Instance) then return nil end
            if headOnly and res.Instance.Name ~= "Head" then return nil end
            local model = res.Instance:FindFirstAncestorWhichIsA("Model")
            local plr = model and Players:GetPlayerFromCharacter(model)
            if not plr or plr == LocalPlayer then return nil end
            local hum = model:FindFirstChildOfClass("Humanoid")
            if not healthOk(model, hum) then return nil end
            if not Shared.aimAllowed(plr, Combat.Trigger.TeamCheck) then return nil end
            return plr
        end
        local hit = castAt(cx, cy)
        if hit then return hit end
        -- HitboxMul > 1: sample a small ring around the crosshair for forgiveness
        local mul = math.max(Combat.Trigger.HitboxMul, 1)
        if mul > 1 then
            local r = 5 * (mul - 1)
            for i = 0, 7 do
                local a = (i / 8) * math.pi * 2
                local p = castAt(cx + math.cos(a) * r, cy + math.sin(a) * r)
                if p then return p end
            end
        end
        return nil
    end
    -- v0.0.78: through-walls crosshair check. Iterates players, projects their key
    -- parts (Head/Torso/HRP variants for R6+R15) to screen space via WorldToViewportPoint,
    -- fires if any lands within HitboxMul*5 pixels of the crosshair: NO occlusion
    -- raycast, so walls between camera and enemy don't block. This is the "trigger
    -- whenever someone goes in the crosshair even through a wall" mode Jack asked for.
    local TRIG_PARTS = { "Head", "UpperTorso", "Torso", "HumanoidRootPart", "LowerTorso" }
    local function crosshairEnemyNoOcclusion()
        local cam = Workspace.CurrentCamera
        if not cam then return nil end
        local vp = cam.ViewportSize
        local cx, cy = vp.X * 0.5, vp.Y * 0.5
        local mul = math.max(Combat.Trigger.HitboxMul, 1)
        local r = 5 * mul
        local r2 = r * r
        -- v0.50.0: Head Only checks the head alone; everything here also
        -- honours the Distance cap and skips spawn-shielded targets.
        local parts = Combat.Trigger.HeadOnly and { "Head" } or TRIG_PARTS
        local maxD = Combat.Trigger.Distance or math.huge
        local camPos = cam.CFrame.Position
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                local char = plr.Character
                if char then
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if healthOk(char, hum) and Shared.aimAllowed(plr, Combat.Trigger.TeamCheck) then
                        for _, name in ipairs(parts) do
                            local part = char:FindFirstChild(name)
                            if part then
                                local sp = cam:WorldToViewportPoint(part.Position)
                                if sp.Z > 0 and (part.Position - camPos).Magnitude <= maxD then
                                    local dx, dy = sp.X - cx, sp.Y - cy
                                    if (dx * dx + dy * dy) <= r2 then return plr end
                                end
                            end
                        end
                    end
                end
            end
        end
        return nil
    end
    -- v0.0.86: silent-link now respects Visible Check. Was firing regardless (v0.0.78)
    -- so with Visible Check ON + Silent Aim armed, trigger fired even when the silent
    -- target was behind a wall: broke the "visible only" expectation. Now Visible
    -- Check gates BOTH the crosshair path AND the silent-link path.
    --   Visible Check ON  -> only fires if target has line-of-sight (raycast from
    --                        camera to silent target passes; crosshair enemy raycast passes)
    --   Visible Check OFF -> through-walls trigger (silent target OR nearest enemy in
    --                        screen-space crosshair area)
    -- silentHasLOS = camera-to-target raycast that ignores our character. If no wall
    -- between camera and target, it's visible.
    local trigLOSParams = RaycastParams.new()
    trigLOSParams.FilterType = Enum.RaycastFilterType.Exclude
    local function silentHasLOS()
        if not (silentTarget and silentTarget.Parent) then return false end
        local cam = Workspace.CurrentCamera
        if not cam then return false end
        local origin = cam.CFrame.Position
        local target = silentTarget.Position
        trigLOSParams.FilterDescendantsInstances = {
            LocalPlayer.Character, silentTarget.Parent
        }
        local res = Workspace:Raycast(origin, target - origin, trigLOSParams)
        return res == nil   -- nil = ray reached target unobstructed
    end
    local function triggerShouldFire()
        -- v0.50.0: Head Only scopes the silent link to head hits as well.
        local headOk = (not Combat.Trigger.HeadOnly)
            or (silentTarget and silentTarget.Name == "Head")
        if Combat.Trigger.VisibleCheck then
            -- silent link only fires when target is actually visible
            if headOk and silentTarget and silentTarget.Parent and Combat.Silent.Enabled and silentHasLOS() then
                return true
            end
            return crosshairEnemy() ~= nil
        end
        -- through-walls mode: any locked silent target fires
        if headOk and silentTarget and silentTarget.Parent and Combat.Silent.Enabled then return true end
        return crosshairEnemyNoOcclusion() ~= nil
    end
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        if not Combat.Trigger.Enabled then return end
        -- v0.67.0: Use Key is gone. No key bound means always firing while
        -- enabled; a bound key gates (Hold) or latches (Toggle) the fire.
        if Combat.Trigger.ActivationKey and not trigHeld then return end
        if trigBusy then return end
        if not triggerShouldFire() then return end
        trigBusy = true
        task.spawn(function()
            -- v0.50.0: humanized timing (Delay + Reaction + random Spread) and
            -- a guarded click: a throwing clickMouse used to wedge trigBusy on.
            local waitMs = Combat.Trigger.Delay
                + (Combat.Trigger.Reaction or 0)
                + math.random() * (Combat.Trigger.Spread or 0)
            if waitMs > 0 then task.wait(waitMs / 1000) end
            -- re-confirm right before firing (silent target might have died / crosshair moved)
            if Combat.Trigger.Enabled and triggerShouldFire() then
                local hc = Combat.Trigger.HitChance or 100
                if math.random(100) <= hc then pcall(clickMouse) end
            end
            if Combat.Trigger.Release > 0 then task.wait(Combat.Trigger.Release / 1000) end
            trigBusy = false
        end)
    end)

    -- v0.0.88 Hit/Kill sound engine. Universal per-player Humanoid.Health drop
    -- watcher; attribution via the screen-space mouse-target lock (LMB-held
    -- nearest-to-cursor sampling, kept fresh every heartbeat). Cooldowns per
    -- type; suppressed while the menu is open. Presets are <exec>/Koffee/sounds/
    -- mp3 names (getcustomasset per play; CustomId > 0 overrides with a
    -- rbxassetid://). Sound silently no-ops on executors without the API.
    -- v0.10.0: one list, two packs. The koffee-assets mp3s came first; everything
    -- from "bonk" down is the Takurin fx/ pack (ogg). Both prefetch in the loader
    -- manifest and resolveSoundId probes either extension, so the split is invisible
    -- from the dropdown. Was duplicated as SND_PRESETS_LIST in the tab builder.
    local SND_PRESETS = {
        "12", "agpa2", "basshit", "bell", "blizzard", "bubble", "chockpro",
        "cod", "copperbell", "crowbar", "headshot", "hit", "knob",
        "minecraft orb", "neverlose", "rust", "skeet",
        "bonk", "bring", "magic squash", "meow", "nya", "pop", "soft",
        "squash", "tung", "uwu",
        "boykisser 1", "boykisser 2", "boykisser 3", "boykisser 4", "boykisser 5", "boykisser 6",
        "click 1", "click 2", "click 3",
        "glass 1", "glass 2", "glass 3",
        "moan 1", "moan 2", "moan 3", "moan 4",
    }
    local SoundService = game:GetService("SoundService")
    local hitSnd = Instance.new("Sound"); hitSnd.Name = "KHitSnd"; hitSnd.Parent = SoundService
    local killSnd = Instance.new("Sound"); killSnd.Name = "KKillSnd"; killSnd.Parent = SoundService
    local lastHitAt, lastKillAt = 0, 0
    local function windowIsOpen()
        return window and window.GroupTransparency < 1
    end
    local function resolveSoundId(cfg)
        if cfg.CustomId and cfg.CustomId > 0 then
            return "rbxassetid://" .. tostring(cfg.CustomId)
        end
        if cfg.Preset and cfg.Preset ~= "" and getcustomasset then
            -- v0.10.0: koffee-assets ships mp3, the Takurin pack ships ogg. Probe
            -- both, and check isfile first so a missing file doesn't hand back a
            -- bogus content id that plays silence forever.
            for _, ext in ipairs({ ".mp3", ".ogg" }) do
                local path = "Koffee/sounds/" .. cfg.Preset .. ext
                if (not isfile) or isfile(path) then
                    local ok, id = pcall(getcustomasset, path)
                    if ok and type(id) == "string" and #id > 0 then return id end
                end
            end
        end
        return nil
    end
    local function playSound(snd, cfg, lastRef)
        if not cfg.Enabled then return lastRef end
        if windowIsOpen() then return lastRef end
        local now = os.clock()
        if (now - lastRef) * 1000 < cfg.Cooldown then return lastRef end
        local id = resolveSoundId(cfg)
        if not id then return lastRef end
        -- v0.0.91 REAL Overlap. v0.0.89's `:Play()` on the same Sound didn't
        -- overlap: Roblox restarts the sound from TimePosition instead of layering.
        -- Overlap ON now clones the Sound per play (parallel playback stacks),
        -- Ended:Once cleans the clone up. Overlap OFF stops+replays the shared
        -- instance (single-track, no layering).
        if Combat.HitSounds.Overlap then
            local clone = snd:Clone()
            clone.SoundId       = id
            clone.Volume        = cfg.Volume
            clone.PlaybackSpeed = cfg.Pitch
            clone.TimePosition  = 0
            clone.Parent        = SoundService
            pcall(function() clone:Play() end)
            clone.Ended:Once(function() clone:Destroy() end)
        else
            pcall(function() snd:Stop() end)
            snd.SoundId       = id
            snd.Volume        = cfg.Volume
            snd.PlaybackSpeed = cfg.Pitch
            snd.TimePosition  = 0
            pcall(function() snd:Play() end)
        end
        return now
    end
    -- mouse-target tracker: per-Heartbeat sweep of all enemies, pick the one whose
    -- screen point is closest to the mouse cursor within MouseRadius pixels.
    -- Only runs while LMB is held (accurate attribution for both single-shot AND
    -- auto weapons: per-shot in bursts each contributes its own held-LMB frame).
    SR.mouseTgt = nil
    -- v0.0.92 mouse-target lock. Replaces single SR.mouseTgt with a SET of recently-
    -- aimed-at enemies (SR.recentTargets[char] = timestamp). Any Health drop on a
    -- char in the set within AttrWindow seconds counts as YOUR hit. Fixes sniper
    -- case: fast-tap LMB, damage lands 200ms later after `lmbDown` already flipped
    -- back to false. Also handles multiple in-flight shots in FFA (each captured
    -- target ages independently).
    -- Sampling: `sampleMouseEnemy()` finds closest enemy to cursor in front of camera
    -- (no radius filter: v0.0.91). Called on Heartbeat while LMB held (auto-fire)
    -- + on LMB press edge (guaranteed sample at press moment even for sub-frame taps).
    SR.recentTargets = {}
    local function sampleMouseEnemy()
        local cam = Workspace.CurrentCamera
        if not cam then return nil end
        local ml = UserInputService:GetMouseLocation()
        local mx, my = ml.X, ml.Y
        local best, bestD = nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                local char = plr.Character
                if char and not Shared.friendIgnored(plr, "Visuals") then
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        local part = char:FindFirstChild("Head")
                                  or char:FindFirstChild("HumanoidRootPart")
                                  or char:FindFirstChild("UpperTorso")
                                  or char:FindFirstChild("Torso")
                        if part then
                            local sp = cam:WorldToViewportPoint(part.Position)
                            if sp.Z > 0 then
                                local dx, dy = sp.X - mx, sp.Y - my
                                local d = dx * dx + dy * dy
                                if d < bestD then best, bestD = char, d end
                            end
                        end
                    end
                end
            end
        end
        -- v0.85.0: NPC entities are enemies too, so PvE hits attribute like players.
        local npc = Shared.NPC
        if npc and npc.entities then
            for _, e in ipairs(npc.entities()) do
                local char, hum = e.char, e.hum
                if char and hum and hum.Health > 0 then
                    local part = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
                    if part then
                        local sp = cam:WorldToViewportPoint(part.Position)
                        if sp.Z > 0 then
                            local dx, dy = sp.X - mx, sp.Y - my
                            local d = dx * dx + dy * dy
                            if d < bestD then best, bestD = char, d end
                        end
                    end
                end
            end
        end
        return best
    end
    local function markMouseTarget()
        local char = sampleMouseEnemy()
        if char then SR.recentTargets[char] = os.clock() end
    end
    local function updateMouseTarget()
        if SR.sweepNpcHP then SR.sweepNpcHP() end
        if lmbDown then markMouseTarget() end
        -- cleanup stale entries so the table doesn't grow forever
        local now, window = os.clock(), Combat.HitSounds.AttrWindow
        for c, at in pairs(SR.recentTargets) do
            if now - at > window then SR.recentTargets[c] = nil end
        end
    end
    -- v0.0.93 MULTI-SOURCE HP WATCHER + damage-time buffer for pre-click attribution.
    -- Some games don't use standard Humanoid.Health for their real HP system:
    -- they store it in a NumberValue child ("Health"/"HP"), a character/humanoid
    -- attribute, or both. We scan for all known HP sources on character setup and
    -- watch each. ANY decrement is a hit event, dedup'd per-char (50ms cooldown so
    -- one damage tick that ripples through multiple sources fires ONE sound).
    -- SR.recentDamage[char] = last-drop timestamp. Used by the LMB press-edge
    -- handler to see if the target took damage in the last BeforeClick ms:
    -- bypasses the "you clicked but Koffee's input registered late" delay.
    SR.recentDamage = {}
    local plrHP = {}
    local HP_NUMBERVALUE_NAMES = { "Health", "HP", "Hp", "hp", "CurrentHealth", "health" }
    local HP_ATTRIBUTE_NAMES   = { "Health", "HP", "Hp", "hp", "CurrentHealth" }
    local function untrackHP(plr)
        local st = plrHP[plr]; if not st then return end
        for _, c in ipairs(st.conns) do pcall(function() c:Disconnect() end) end
        if plr.Character then SR.recentDamage[plr.Character] = nil end
        plrHP[plr] = nil
    end
    local function onHpDropped(char, dropped, nowZero)
        -- dedup: ignore if last hit event for this char was <50ms ago (multi-source ripple)
        local last = SR.recentDamage[char]
        local now = os.clock()
        if last and (now - last) < 0.05 then return end
        SR.recentDamage[char] = now

        -- normal attribution path (v0.0.92): check recentTargets + AttrWindow
        local at = SR.recentTargets[char]
        if at and (now - at) <= Combat.HitSounds.AttrWindow then
            SR.recentTargets[char] = nil
            if nowZero then lastKillAt = playSound(killSnd, Combat.HitSounds.Kill, lastKillAt)
            else lastHitAt = playSound(hitSnd, Combat.HitSounds.Hit, lastHitAt) end
            -- v0.5.0: hit indicators + crosshair pulse ride the same attribution
            -- gate as the sounds. Only fires for hits YOU landed (recentTargets +
            -- AttrWindow), not every game-wide damage event.
            if Shared.spawnHitNumber then
                local victim = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
                    or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
                if victim then Shared.spawnHitNumber(victim, dropped, nowZero) end
            end
            -- v0.7.0 hit / kill visual effect. Shares attribution + preset lookup.
            if Shared.spawnHitEffect then
                local cfg = nowZero and Combat.HitEffects.Kill or Combat.HitEffects.Hit
                Shared.spawnHitEffect(char, cfg)
            end
        end
    end
    local function bindHumanoid(plr, char)
        local st = plrHP[plr]; if not st then return end
        for i = #st.conns, 2, -1 do
            pcall(function() st.conns[i]:Disconnect() end); st.conns[i] = nil
        end
        st.lastHealth = 100    -- Humanoid.Health baseline; may be unused if the game uses another source
        st.altValues  = {}     -- [Instance] = last-observed .Value for NumberValue sources
        st.altAttrs   = {}     -- [name] = last-observed attribute value

        -- 1. Standard Humanoid.Health
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then
            task.spawn(function()
                hum = char:WaitForChild("Humanoid", 5)
                if hum and plrHP[plr] then bindHumanoid(plr, char) end
            end)
            return
        end
        st.lastHealth = hum.Health
        table.insert(st.conns, hum:GetPropertyChangedSignal("Health"):Connect(function()
            local nh, old = hum.Health, st.lastHealth
            st.lastHealth = nh
            if nh < old then onHpDropped(char, old - nh, nh <= 0) end
        end))

        -- 2. NumberValue / IntValue children named Health/HP/etc. (recursive scan)
        for _, name in ipairs(HP_NUMBERVALUE_NAMES) do
            local nv = char:FindFirstChild(name, true)
            if nv and (nv:IsA("NumberValue") or nv:IsA("IntValue")) then
                st.altValues[nv] = nv.Value
                table.insert(st.conns, nv:GetPropertyChangedSignal("Value"):Connect(function()
                    local newV = nv.Value
                    local oldV = st.altValues[nv] or newV
                    st.altValues[nv] = newV
                    if newV < oldV then onHpDropped(char, oldV - newV, newV <= 0) end
                end))
            end
        end

        -- 3. Character attributes named Health/HP/etc.
        for _, name in ipairs(HP_ATTRIBUTE_NAMES) do
            local v = char:GetAttribute(name)
            if type(v) == "number" then
                st.altAttrs[name] = v
                table.insert(st.conns, char:GetAttributeChangedSignal(name):Connect(function()
                    local newV = char:GetAttribute(name)
                    if type(newV) ~= "number" then return end
                    local oldV = st.altAttrs[name] or newV
                    st.altAttrs[name] = newV
                    if newV < oldV then onHpDropped(char, oldV - newV, newV <= 0) end
                end))
            end
        end

        -- 4. Humanoid attributes named Health/HP/etc.
        for _, name in ipairs(HP_ATTRIBUTE_NAMES) do
            local v = hum:GetAttribute(name)
            if type(v) == "number" then
                st.altAttrs["hum_" .. name] = v
                table.insert(st.conns, hum:GetAttributeChangedSignal(name):Connect(function()
                    local newV = hum:GetAttribute(name)
                    if type(newV) ~= "number" then return end
                    local oldV = st.altAttrs["hum_" .. name] or newV
                    st.altAttrs["hum_" .. name] = newV
                    if newV < oldV then onHpDropped(char, oldV - newV, newV <= 0) end
                end))
            end
        end
    end
    local function trackHP(plr)
        if plr == LocalPlayer or plrHP[plr] then return end
        plrHP[plr] = { lastHealth = 100, conns = {}, altValues = {}, altAttrs = {} }
        table.insert(plrHP[plr].conns, plr.CharacterAdded:Connect(function(char) bindHumanoid(plr, char) end))
        if plr.Character then bindHumanoid(plr, plr.Character) end
    end
    for _, plr in ipairs(Players:GetPlayers()) do trackHP(plr) end
    Players.PlayerAdded:Connect(trackHP)
    Players.PlayerRemoving:Connect(untrackHP)
    -- v0.85.0: NPC entities get the same HP watchers, keyed by model (the model is
    -- both key and char). 2Hz sweep binds new ones and drops destroyed ones.
    SR.npcSweepAt = 0
    SR.sweepNpcHP = function()
        local now = os.clock()
        if now - SR.npcSweepAt < 0.5 then return end
        SR.npcSweepAt = now
        for k, st in pairs(plrHP) do
            if st.npc and not k.Parent then
                for _, c in ipairs(st.conns) do pcall(function() c:Disconnect() end) end
                SR.recentDamage[k] = nil; SR.recentTargets[k] = nil
                plrHP[k] = nil
            end
        end
        local npc = Shared.NPC
        if not (npc and npc.entities) then return end
        for _, e in ipairs(npc.entities()) do
            local m = e.char
            if m and m.Parent and not plrHP[m] then
                plrHP[m] = { lastHealth = 100, conns = {}, altValues = {}, altAttrs = {}, npc = true }
                bindHumanoid(m, m)
            end
        end
    end
    -- v0.14.0: own deaths, for the Custom Features Counter block
    LocalPlayer.CharacterAdded:Connect(function(ch)
        local hum = ch:WaitForChild("Humanoid", 5)
        if not hum then return end
        hum.Died:Connect(function()
            local c = Shared._counters
            if not c then c = { Hits = 0, Kills = 0, Deaths = 0, Shots = 0 }; Shared._counters = c end
            c.Deaths = c.Deaths + 1
        end)
    end)
    RunService.Heartbeat:Connect(updateMouseTarget)

    -- silent aim: keep the redirect target FRESH every frame while active. v0.0.35:
    -- the RequireLMB check is NO LONGER here: silentPos is computed continuously
    -- (whenever enabled + armed-by-key + a target is acquirable) so it's already
    -- set the instant a weapon reads mouse.Hit. The LMB gate is applied at redirect
    -- time inside the hook (isArmed), which kills the one-frame "RequireLMB misses".
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        -- v0.0.36: authoritative LMB backfill: if InputBegan's edge was ever missed
        -- (input consumed / gpe ordering), the poll re-sets it so RequireLMB can't get
        -- stuck "not held" while you're firing. Release still comes from InputEnded.
        if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then lmbDown = true end
        -- v0.0.39: resolve PlayerModule here (namecall-safe) so isView never has to
        -- FindFirstChild inside a hook (a nested namecall would brick the weapon).
        if not SR.pm then
            local ps = LocalPlayer:FindFirstChild("PlayerScripts")
            SR.pm = ps and ps:FindFirstChild("PlayerModule")
        end
        -- v0.34.0: migrate the pre-rename method string off old saved configs.
        if Combat.Silent.Method == "Forced Magic-Bullet" then Combat.Silent.Method = "Forced Camera" end
        if not Combat.Silent.Enabled then silentTarget = nil; silentPos = nil; Combat.Silent._target = nil; Combat.Silent._lastGoodAt = nil; return end
        -- v0.0.34: if the user bound an arm key it must be held (per its mode);
        -- with no key bound (default) this gate is skipped entirely.
        if Combat.Silent.ActivationKey and not silentHeld then
            silentTarget = nil; silentPos = nil; Combat.Silent._target = nil; Combat.Silent._lastGoodAt = nil; return
        end
        local maxR = Combat.Silent.FOV.Enabled and Combat.Silent.FOV.Size or math.huge
        local plr, part
        -- v0.3.7: Silent Sticky (parity with aimbot). Hold the locked player
        -- across FOV/off-screen/occlusion misses; only drop when they die,
        -- respawn, or leave Distance. Fixes the External-method flake where
        -- brief picker nils blanked silentPos and the 30Hz /config push sent
        -- has_target=false, disarming the helper mid-fire.
        if Combat.Silent.Sticky and Combat.Silent._target then
            local t = Combat.Silent._target
            local char = t.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if char and hum and hum.Health > 0 then
                local p = aimPart(char, Combat.Silent.HitPart)
                if p then
                    local cam2 = Workspace.CurrentCamera
                    local distOk = (not Combat.Silent.Distance) or (cam2
                        and (p.Position - cam2.CFrame.Position).Magnitude <= Combat.Silent.Distance)
                    if distOk then plr, part = t, p end
                end
            end
        end
        if not (plr and part) then
            plr, part = getBestTarget(Combat.Silent, maxR, fovCenter(Combat.Silent.FOV))
            if plr then Combat.Silent._target = plr end
        end
        if plr and part then
            -- v0.79.2: bloom stamp. A fresh target (or the first frame back
            -- from a dropout) restarts lock age; Sticky holds keep it running.
            if Combat.Silent._bloomPlr ~= plr then
                Combat.Silent._bloomPlr, Combat.Silent._lockAt = plr, os.clock()
            end
            -- v0.50.0 Hit Chance. A failed roll fires clean this frame: clear
            -- the redirect with no grace window, so the shot truly misses.
            -- v0.51.1 Force Miss: same failed roll, but the lock holds and the
            -- redirect goes wide instead, so every method genuinely misses.
            local L = Combat.Silent.Legit
            local missed = false
            local hc = L.HitChance or 100
            if hc < 100 and math.random(100) > hc then
                if L.ForceMiss then
                    missed = true
                    silentTarget = part
                    silentPos = missPoint(part)
                else
                    silentTarget = nil; silentPos = nil
                    SR.camPos = nil; SR.screen = nil; SR.camLook = nil; SR.rootPos = nil
                    Combat.Silent._lastGoodAt = nil
                    return
                end
            end
            if not missed then
                silentTarget = part
                -- prediction shifts the redirect point for lead; the hooks read silentPos
                silentPos = predicted(plr, part, Combat.Silent.Predict)
                if Combat.Misc.Resolver then silentPos = dwellPos(plr, part, silentPos) end
            -- v0.50.0 silent jitter: scatter the redirect point by up to N studs.
            local sj = Combat.Silent.Legit.Jitter or 0
            if sj > 0 then
                silentPos = silentPos + Vector3.new(
                    (math.random() * 2 - 1) * sj,
                    (math.random() * 2 - 1) * sj,
                    (math.random() * 2 - 1) * sj)
            end
            -- v0.51.0 fake spread: lateral disc around the point, uniform area,
            -- so bursts walk like real spray instead of stacking one hole.
            -- v0.79.2: Degrees mode reinterprets the radius as angular error
            -- (studs = tan(rad) * distance), so far targets spread wide and
            -- close ones stay tight like real aim. Bloom multiplies the radius
            -- with lock age (recoil fatigue), ramping to full over 5s.
            local spread = Combat.Silent.Legit.Spread or 0
            local bloom = Combat.Silent.Legit.Bloom or 0
            if bloom > 0 and spread > 0 then
                local age = math.min(os.clock() - (Combat.Silent._lockAt or os.clock()), 5)
                spread = spread * (1 + (bloom / 100) * (age / 5) * 3)
            end
            if spread > 0 then
                local sc = Workspace.CurrentCamera
                if sc then
                    local cf = sc.CFrame
                    if (Combat.Silent.Legit.SpreadUnit or "Studs") == "Degrees" then
                        local dist = (silentPos - cf.Position).Magnitude
                        spread = math.tan(math.rad(spread)) * dist
                    end
                    local a = math.random() * math.pi * 2
                    local rr = math.sqrt(math.random()) * spread
                    silentPos = silentPos
                        + (cf.RightVector * math.cos(a) + cf.UpVector * math.sin(a)) * rr
                end
            end
            end
            -- v0.0.39: cache the real camera + target's screen point so the fire-read
            -- resolvers never re-read Camera.* inside the __index hook (recursion).
            local cam = Workspace.CurrentCamera
            local cf
            if cam then
                SR.cam = cam
                cf = cam.CFrame
                SR.camPos = cf.Position
                -- v0.1.6: real look direction, cached namecall-safe (outbound arg-rewrite)
                SR.camLook = cf.LookVector
                local sp = cam:WorldToViewportPoint(silentPos)
                SR.screen = Vector2.new(sp.X, sp.Y)
            end
            -- v0.0.64/65: cache the character + a SET of every part/attachment whose position
            -- reads Pos Spoof should fake (all character descendants incl. the equipped tool's
            -- muzzle parts + attachments: not just HRP, so guns that build their origin from
            -- the gun/muzzle land too). Built here (namecall-safe) so the hooks only do a table
            -- lookup, never a namecall.
            local ch = LocalPlayer.Character
            SR.char = ch
            -- v0.1.6: own root position cached namecall-safe (outbound arg-rewrite origin)
            local rt = ch and (ch:FindFirstChild("HumanoidRootPart") or (findTorso and findTorso(ch)))
            if rt then SR.rootPos = rt.Position else SR.rootPos = nil end
            local sp = {}
            if ch then
                for _, d in ipairs(ch:GetDescendants()) do
                    if d:IsA("BasePart") or d:IsA("Attachment") or d:IsA("Bone") then sp[d] = true end
                end
            end
            SR.spoofParts = sp
            Combat.Silent._lastGoodAt = os.clock()
        else
            -- v0.3.7: grace window. Keep the last known silentPos alive for
            -- ~150ms across brief picker nils (target one frame off-screen,
            -- occlusion flicker, respawn race). Without this, the 30Hz push
            -- to KoffeeHelper sends has_target=false the instant the picker
            -- burps, and the helper disarms mid-fire. Grace is short so a
            -- truly-gone target still releases quickly.
            local age = Combat.Silent._lastGoodAt and (os.clock() - Combat.Silent._lastGoodAt) or math.huge
            if age > 0.15 then
                silentTarget = nil; silentPos = nil
                SR.camPos = nil; SR.screen = nil
                SR.camLook = nil; SR.rootPos = nil
                Combat.Silent._lastGoodAt = nil
                Combat.Silent._bloomPlr = nil
                if not Combat.Silent.Sticky then Combat.Silent._target = nil end
            end
        end
    end)

    -- :: input: rebind capture + activation ::
    UserInputService.InputBegan:Connect(function(input, gpe)
        -- v0.0.35: track LMB regardless of gpe so the silent redirect's RequireLMB
        -- gate is accurate (this flag replaces IsMouseButtonPressed polling).
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            lmbDown = true; lmbClickAt = os.clock()
            local c = Shared._counters
            if not c then c = { Hits = 0, Kills = 0, Deaths = 0, Shots = 0 }; Shared._counters = c end
            c.Shots = c.Shots + 1
            -- v0.0.92 sample the mouse target IMMEDIATELY on press edge, not just
            -- on the next Heartbeat: catches sub-frame LMB taps (fast snipers)
            -- where the button's released before another Heartbeat can sample.
            if markMouseTarget then pcall(markMouseTarget) end
            -- v0.0.93 PRE-CLICK check: if the current mouse target has dropped
            -- Health in the last BeforeClick ms (bypasses the "your click
            -- registered after the game's own damage tick" delay), fire the
            -- sound on THIS press even though the drop already happened.
            if sampleMouseEnemy and playSound then
                local char = sampleMouseEnemy()
                if char and SR.recentDamage and SR.recentDamage[char] then
                    local ago = os.clock() - SR.recentDamage[char]
                    if ago <= (Combat.HitSounds.BeforeClick / 1000) then
                        SR.recentDamage[char] = nil   -- consume so heartbeat handler doesn't double-fire
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health <= 0 then
                            lastKillAt = playSound(killSnd, Combat.HitSounds.Kill, lastKillAt)
                        else
                            lastHitAt = playSound(hitSnd, Combat.HitSounds.Hit, lastHitAt)
                        end
                    end
                end
            end
        end
        if pendingActivation then
            local it = input.UserInputType
            -- v0.3.2: Escape UNBINDS (restored to v0.0.36 semantics).
            if it == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Escape then
                pendingActivation.cfg.ActivationKey = nil
                pendingActivation.refresh(); pendingActivation = nil; return
            end
            -- v0.27.0: bind mouse buttons even over the koffee UI. The pill is armed
            -- ("...") so the next press is the intended bind, and the arming click's
            -- edge already fired. (gpe-gating this read as "can't bind mouse buttons".)
            -- v0.0.36: accept ANY key + ANY button-like input (mouse 1/2/3 and
            -- whatever else the runtime surfaces through InputBegan, e.g. XButton1/2
            -- on executors that deliver them). Only movement/wheel/focus are ignored.
            local bind
            if it == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
                bind = input.KeyCode
            elseif it ~= Enum.UserInputType.Focus and it ~= Enum.UserInputType.MouseMovement
               and it ~= Enum.UserInputType.MouseWheel and it ~= Enum.UserInputType.None
               and it ~= Enum.UserInputType.TextInput and it ~= Enum.UserInputType.InputMethod then
                bind = it
            end
            if bind then
                pendingActivation.cfg.ActivationKey = bind
                pendingActivation.refresh()
                pendingActivation = nil
            end
            return
        end
        if gpe then return end
        -- v0.0.97 TARGET LOCK toggle key: armed + key pressed -> flip the lock.
        if Shared.TargetLock.Enabled and Keybinds["targetlock"]
        and inputMatches(input, Keybinds["targetlock"]) then
            Shared.TargetLock._active = not Shared.TargetLock._active
            return
        end
        if Combat.Aim.Enabled and inputMatches(input, Combat.Aim.ActivationKey) then
            if Combat.Aim.ActivationMode == "Toggle" then aimHeld = not aimHeld else aimHeld = true end
        end
        if Combat.Silent.Enabled and Combat.Silent.ActivationKey
        and inputMatches(input, Combat.Silent.ActivationKey) then
            if Combat.Silent.ActivationMode == "Toggle" then silentHeld = not silentHeld else silentHeld = true end
        end
        if Combat.Trigger.Enabled and inputMatches(input, Combat.Trigger.ActivationKey) then
            if Combat.Trigger.ActivationMode == "Toggle" then trigHeld = not trigHeld else trigHeld = true end
        end
        syncActPills()
    end)
    -- v0.0.69: a SECOND click signal off the PlayerMouse. It fires in a different order than
    -- UserInputService.InputBegan, so on games where the weapon's InputBegan runs before ours
    -- this may set lmbDown earlier (helps single-shot pistols/snipers where the game processes
    -- the click first). Not a full fix: true pre-arming needs the external program.
    pcall(function()
        local m = LocalPlayer:GetMouse()
        m.Button1Down:Connect(function() lmbDown = true; lmbClickAt = os.clock() end)
        m.Button1Up:Connect(function() lmbDown = false end)
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then lmbDown = false end
        if Combat.Aim.ActivationMode == "Hold" and inputMatches(input, Combat.Aim.ActivationKey) then
            aimHeld = false
        end
        if Combat.Silent.ActivationMode == "Hold" and Combat.Silent.ActivationKey
        and inputMatches(input, Combat.Silent.ActivationKey) then
            silentHeld = false
        end
        if Combat.Trigger.ActivationMode == "Hold" and inputMatches(input, Combat.Trigger.ActivationKey) then
            trigHeld = false
        end
        syncActPills()
    end)

    -- v0.0.37: VIRTUAL XBUTTON DRIVER. Roblox never fires InputBegan for mouse 4/5,
    -- so binds set to "XButton1"/"XButton2" are driven here off the Koffee Helper's
    -- polled state instead. Handles rebind capture (the helper sees the press Roblox
    -- can't) + hold/toggle activation for aim / silent / trigger.
    local pXB = { false, false }   -- last two locals this frame may hold
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local xb1, xb2 = Helper.XB1, Helper.XB2
        local e1, e2 = (xb1 and not pXB[1]), (xb2 and not pXB[2])   -- press edges
        local function down(k) return (k == "XButton1" and xb1) or (k == "XButton2" and xb2) or false end
        local function edge(k) return (k == "XButton1" and e1) or (k == "XButton2" and e2) or false end

        -- rebind capture: the activation pill is waiting -> bind the pressed XButton
        if pendingActivation then
            local k = (e2 and "XButton2") or (e1 and "XButton1") or nil
            if k then
                pendingActivation.cfg.ActivationKey = k
                pendingActivation.refresh(); pendingActivation = nil
            end
        end

        -- drive held-state for any context bound to a virtual XButton
        if type(Combat.Aim.ActivationKey) == "string" then
            if Combat.Aim.ActivationMode == "Toggle" then
                if edge(Combat.Aim.ActivationKey) then aimHeld = not aimHeld end
            else aimHeld = down(Combat.Aim.ActivationKey) end
        end
        if type(Combat.Silent.ActivationKey) == "string" then
            if Combat.Silent.ActivationMode == "Toggle" then
                if edge(Combat.Silent.ActivationKey) then silentHeld = not silentHeld end
            else silentHeld = down(Combat.Silent.ActivationKey) end
        end
        if type(Combat.Trigger.ActivationKey) == "string" then
            if Combat.Trigger.ActivationMode == "Toggle" then
                if edge(Combat.Trigger.ActivationKey) then trigHeld = not trigHeld end
            else trigHeld = down(Combat.Trigger.ActivationKey) end
        end
        syncActPills()
        -- v0.0.97 TARGET LOCK: toggle the lock on a virtual XButton edge
        if type(Keybinds["targetlock"]) == "string" then
            if Shared.TargetLock.Enabled and edge(Keybinds["targetlock"]) then
                Shared.TargetLock._active = not Shared.TargetLock._active
            end
        end

        pXB[2], pXB[1] = xb2, xb1
    end)

    -- :: modules (arraylist + master toggles) ::
    registerModule("aimbot", "Aimbot",
        function() Combat.Aim.Enabled = true end,
        function() Combat.Aim.Enabled = false; aimHeld = false; Combat.Aim._target = nil; Combat.Aim._rageLock = nil; syncActPills() end)
    -- v0.0.79: diagnostic prints on trigger enable/disable so we can see WHO is
    -- toggling it if the checkbox "immediately turns off": caller stack tells us
    -- if it's the click, a config load, a keybind, or something else.
    registerModule("triggerbot", "Trigger Bot",
        function()
            Combat.Trigger.Enabled = true
            if getgenv and getgenv().KoffeeTrigDebug then
                print("[koffee][trig] ENABLE @ " .. tostring(os.clock()) .. "  stack=" .. tostring(debug.traceback and debug.traceback("", 2) or "?"))
            end
        end,
        function()
            Combat.Trigger.Enabled = false; trigHeld = false; syncActPills()
            if getgenv and getgenv().KoffeeTrigDebug then
                print("[koffee][trig] DISABLE @ " .. tostring(os.clock()) .. "  stack=" .. tostring(debug.traceback and debug.traceback("", 2) or "?"))
            end
        end)
    -- v0.3.0 EXTERNAL METHOD BRIDGE. koffee.lua speaks to KoffeeHelper.exe
    -- (native C++ helper, source at helper/native/) over localhost HTTP.
    -- Under Silent Aim's "External" method, all Lua-side spoof paths short-
    -- circuit (see resolveIndex / resolveNamecall heads) and the helper does
    -- the actual work via a raycast inline hook inside the Roblox process.
    --
    -- Wire contract:
    --   * fixed local port 27374 (mirrored in helper/native/src/main.cpp).
    --   * dev key from Koffee.md's Round-1 auth section, sent as
    --     X-Koffee-Key on POST /config + POST /clear.
    --   * every ~2s while External is the active method AND Silent.Enabled,
    --     push the current silent config to /config as a keepalive. The
    --     helper auto-disarms if the keepalive stops arriving (its own 5s
    --     TTL: see aim/silentaim.cpp kKeepaliveMax).
    --   * on External -> non-External transition (or Silent disable), POST
    --     /clear so the helper drops the target immediately instead of
    --     waiting out its keepalive TTL.
    Koffee.External = (function()
        local M = {}
        -- v0.22.0: host/port/key moved onto the shared Helper table.
        local URL = Helper.Url(Helper.PortAim)

        local function pickReq()
            return (syn and syn.request) or (http and http.request)
                or http_request or request
        end

        local function call(method, path, body)
            local req = pickReq()
            if not req then return false, "no_http_api" end
            local ok, res = pcall(req, {
                Url = URL .. path,
                Method = method,
                Headers = Helper.Headers(),
                Body = body,
            })
            if not ok then return false, tostring(res) end
            local status = res and (res.StatusCode or res.status_code)
            local success = (status == 200) or (res and res.Success == true)
            return success, res and res.Body or ""
        end

        function M.healthOk()
            local ok = call("GET", "/health", nil)
            return ok == true
        end

        -- Build the JSON body from the current Combat.Silent state. Kept in
        -- lock-step with helper/native/src/http.cpp `parse_config` so adding
        -- a field is a one-side change per side.
        --
        -- v0.3.4:
        --   * `target` (nullable {x,y,z}): koffee.lua's own picker output.
        --     When present the helper uses it verbatim instead of running
        --     the native picker. Ships the same target the Lua-side hooks
        --     would rewrite to under the Raycast / Forced-MB methods,
        --     which is a much smarter pick than the helper's naive
        --     3D-distance-from-camera fallback.
        --   * `engaged` (bool): true only when the user is actively
        --     firing (silent enabled + activation-key gate + require-LMB
        --     gate). Helper only arms the thunk when this is true, so
        --     unrelated raycasts (IK, occlusion, footsteps) pass through
        --     unmodified. Fixes wallbang looking flaky on games that
        --     raycast heavily outside of shot windows.
        local function buildConfigBody()
            local s = Combat.Silent
            local HttpService = game:GetService("HttpService")

            local body = {
                silent = {
                    enabled      = s.Enabled == true,
                    wallbang     = s.Wallbang == true,
                    hit_part     = tostring(s.HitPart or "Head"),
                    team_check   = s.TeamCheck == true,
                    health_check = s.HealthCheck == true,
                    distance     = tonumber(s.Distance) or 1500,
                    fov_enabled  = s.FOV and s.FOV.Enabled or false,
                    fov_radius   = (s.FOV and s.FOV.Size) or 150,
                },
            }

            -- v0.3.6: dropped the RequireLMB gate entirely. External
            -- method is "always silent aim while target locked" now:
            -- matches semun's model, avoids the timing race where the
            -- fire raycast happens before the LMB-down flag has round-
            -- tripped through /config. RequireLMB only affects the
            -- Lua-side methods (Raycast / Forced MB / Second-Camera);
            -- under External the user's RequireLMB setting is ignored.
            local keyOk = (not s.ActivationKey) or (silentHeld == true)
            body.silent.engaged = (s.Enabled == true) and keyOk

            -- Target is the same silentPos the Lua-side hooks use for
            -- Mouse.Hit rewrites: includes prediction, priority, sticky,
            -- team/health/FOV gates from koffee.lua's own picker.
            if silentPos then
                body.silent.target = {
                    x = silentPos.X, y = silentPos.Y, z = silentPos.Z,
                }
            end

            return HttpService:JSONEncode(body)
        end

        function M.pushConfig()
            local body = buildConfigBody()
            local ok = call("POST", "/config", body)
            return ok
        end

        function M.clear() call("POST", "/clear", "") end

        -- Keepalive + target push loop. Fires while (Silent.Enabled AND
        -- Method == External). 30Hz tick keeps the target ~1.7 studs fresh
        -- at sprint speed. Executor request() bypasses HttpService rate
        -- limits so the throughput is fine. Also probes /health on the
        -- enable transition + POST /clear on the disable transition.
        --
        -- v0.3.6: reverted v0.3.5's Heartbeat-based push + in-flight
        -- guard: simpler is better while we chase the flake, and the
        -- LMB gate removal makes stale-target windows less painful
        -- (always-on aim doesn't need per-frame LMB freshness).
        local warned = false
        local wasActive = false
        task.spawn(function()
            while true do
                -- v0.22.0: was immortal. Unload left it pushing config at 30Hz and
                -- every re-exec stacked another pusher on top.
                if Koffee.dead() then M.clear(); break end
                local isActive = Combat.Silent.Enabled
                    and Combat.Silent.Method == "External"
                if isActive then
                    if not wasActive then
                        if not M.healthOk() then
                            if not warned then
                                warned = true
                                warn("[koffee] external method selected but helper is not reachable at " .. URL)
                            end
                        else
                            warned = false
                        end
                    end
                    M.pushConfig()
                elseif wasActive then
                    M.clear()
                    warned = false
                end
                wasActive = isActive
                task.wait(0.033)
            end
        end)

        -- Called by the Method dropdown on change. Immediate response so the
        -- helper disarms right away instead of on the next 2s keepalive tick.
        function M.onMethodChange(newMethod)
            if newMethod ~= "External" then M.clear() end
        end

        return M
    end)()

    registerModule("silentaim", "Silent Aim",
        function() installSilentHooks(); Combat.Silent.Enabled = true end,
        function()
            Combat.Silent.Enabled = false; silentHeld = false; syncActPills()
            silentTarget = nil
            -- If we were on External, tell the helper to disarm immediately.
            if Combat.Silent.Method == "External" and Koffee.External then
                Koffee.External.clear()
            end
        end)
    -- v0.0.73: arraylist "on" indicator: active = held by the activation key, OR (no key
    -- bound) always-active while enabled. Mirrors each feature's real arm gate.
    Modules.aimbot.IsActive     = function() return (not Combat.Aim.ActivationKey)    or aimHeld end
    Modules.triggerbot.IsActive = function() return (not Combat.Trigger.ActivationKey) or trigHeld end
    Modules.silentaim.IsActive  = function() return (not Combat.Silent.ActivationKey)  or silentHeld end
    -- v0.66.1: combat uses the single activation pill only. Drop any toggle
    -- bind left from the removed second pill so old configs cannot ghost toggle.
    for _, id in ipairs({ "aimbot", "silentaim", "triggerbot" }) do Keybinds[id] = nil end
    if Koffee._keybinds then
        for i = #Koffee._keybinds, 1, -1 do
            local id = Koffee._keybinds[i].id
            if id == "aimbot" or id == "silentaim" or id == "triggerbot" then table.remove(Koffee._keybinds, i) end
        end
    end
    -- FOV is an arraylist marker; the two per-context toggles (Aim.FOV / Silent.FOV)
    -- drive rendering. Detail shows "x2" when both circles are active.
    registerModule("fov", "FOV", function() end, function() end)
    Modules.fov.GetDetail = function()
        local n = (Combat.Aim.FOV.Enabled and 1 or 0) + (Combat.Silent.FOV.Enabled and 1 or 0)
        return n >= 2 and "    x2" or ""
    end
    local function syncFovModule()
        local want = Combat.Aim.FOV.Enabled or Combat.Silent.FOV.Enabled
        if want ~= (Modules.fov and Modules.fov.Enabled) then toggleModule("fov") end
    end

    -- :: small UI helpers scoped to this tab ::
    local function attachSwatch(row, initial, onChange, opts)
        local wrap = new("Frame", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.new(0, 14, 0, 16), BackgroundTransparency = 1, ZIndex = 38, Parent = row,
        })
        local o = { onChange = onChange }
        if opts then for k, v in pairs(opts) do o[k] = v end end
        return colorSwatch(wrap, initial, 14, o)
    end
    -- two swatches on one row (outline + fill-with-alpha) for a given FOV cfg
    local function attachFovSwatches(row, F)
        local wrap = new("Frame", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.new(0, 36, 0, 16), BackgroundTransparency = 1, ZIndex = 38, Parent = row,
        }, {
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Right, VerticalAlignment = Enum.VerticalAlignment.Center,
                Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
        })
        colorSwatch(wrap, F.Color, 14, { onChange = function(c) F.Color = c end })
        colorSwatch(wrap, F.FillColor, 14, { onChange = function(c) F.FillColor = c end })
    end
    local function attachHelp(row)
        new("TextLabel", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 14, 0, 14),
            Text = "?", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextFaint,
            BackgroundTransparency = 1, ZIndex = 38, Parent = row,
        })
    end

    -- shared FOV control set: built in both the left (aimbot -> Aim.FOV) and
    -- right (silent -> Silent.FOV) sub-tabs, each bound to its own config.
    local function buildFovTab(parent, F, cfg)
        local enRow = configCheckbox(parent, "Enabled", F.Enabled, function(v)
            F.Enabled = v
            syncFovModule()   -- keep the single "FOV" arraylist marker + x2 detail in sync
        end)
        attachFovSwatches(enRow.row, F)
        -- right-click the Fill row: Remove Outline / Custom Gradient / Spin / Moving.
        -- Fill state is preserved across Style switches: Dots just suppresses the
        -- fill visually (drawFov gates on `not dotsMode`), so flipping back to Smooth
        -- restores it without a re-toggle.
        local fillRow = configCheckbox(parent, "Filled", F.Filled, function(v) F.Filled = v end)
        rightClickSettings(fillRow.row, "Fill", function(api)
            -- v0.4.0: kill the visual entirely while keeping FOV as a targeting gate.
            api:toggle("Hide Visual", F.HideVisual, function(v) F.HideVisual = v end)
            api:toggle("Remove Outline", F.Fill.RemoveOutline, function(v) F.Fill.RemoveOutline = v end)
            api:toggle("Spin", F.Fill.Spin, function(v) F.Fill.Spin = v end)
            local cg = F.Fill.Custom
            api:toggle("Custom Gradient", cg.Enabled, function(v) cg.Enabled = v end)
            api:swatchRow(cg.Colors, function(i, c) cg.Colors[i] = c end)
            for i = 1, 4 do
                api:slider(i .. " Transparency", 0, 1, cg.Alphas[i], 2, function(v) cg.Alphas[i] = v end)
            end
            api:dropdown("Points", { "2", "3", "4" }, tostring(cg.Points), function(v)
                cg.Points = tonumber(v) or 2
                if cg.Points ~= 3 then cg.Triangle = false end
            end)
            api:toggle("Triangle", cg.Triangle, function(v)
                if cg.Points ~= 3 then return end
                cg.Triangle = v
                if v then cg.Moving.Enabled = false end
            end)
            api:toggle("Moving Gradient", cg.Moving.Enabled, function(v)
                if cg.Triangle then return end
                cg.Moving.Enabled = v
            end)
            api:slider("Speed", 0, 5, cg.Moving.Speed, 2, function(v) cg.Moving.Speed = v end)
            api:slider("Direction", 0, 360, cg.Moving.Direction, 0, function(v) cg.Moving.Direction = v end)
        end)
        configCheckbox(parent, "Spin", F.Spin, function(v) F.Spin = v end)
        slider(parent, "Fill Transparency", 0, 1, F.FillTransparency, 2, function(v) F.FillTransparency = v end)
        -- v0.10.2: floor is 1, not 20. A near-zero FOV is the whole point of a
        -- tight legit setup: it is the "only fire when the crosshair is basically
        -- on them" case: and 20px was already a generous cone at close range.
        slider(parent, "Size", 1, 500, F.Size, 0, function(v) F.Size = v end)
        dropdown(parent, "Origin", { "Center", "Mouse" }, F.Origin, function(v) F.Origin = v end)
        -- v0.50.0 target priority. Lives in the FOV tab but scores regardless
        -- of the ring: Crosshair picks nearest the center, Distance the nearest
        -- player in the world, Health the weakest player by health fraction.
        dropdown(parent, "Target Priority", { "Crosshair", "Distance", "Health" }, cfg.Priority, function(v) cfg.Priority = v end)
        -- v0.5.0: Follow Target: ring slides toward the current target's screen
        -- position. Right-click for Smoothness (0=snap, 0.98=very slow). Targeting
        -- gate follows the same center so the picker respects what the user sees.
        local followRow = configCheckbox(parent, "Follow Target", F.Follow.Enabled, function(v)
            F.Follow.Enabled = v
            if not v then F.Follow._screenX = nil; F.Follow._screenY = nil end
        end)
        rightClickSettings(followRow.row, "Follow", function(api)
            api:slider("Smoothness", 0, 0.98, F.Follow.Smoothness, 2, function(v) F.Follow.Smoothness = v end)
        end)
        local styleDd = dropdown(parent, "Style", { "Smooth", "Dots" }, F.Style, function(v)
            F.Style = v
        end)
        -- right-click the Style dropdown to tune Dots
        rightClickSettings(styleDd.frame, "Dots", function(api)
            api:slider("Dot Size", 1, 12, F.DotSize, 0, function(v) F.DotSize = v end)
            api:slider("Gap", 6, 60, F.DotGap, 0, function(v) F.DotGap = v end)
        end)
    end

    -- sub-tab pill switcher inside a card. Returns { name -> contentFrame }.
    local function subTabs(card, names)
        local bar = new("Frame", {
            Name = "SubTabs", Size = UDim2.new(1, 0, 0, 28),
            BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.35, BorderSizePixel = 0,
            LayoutOrder = 0, ZIndex = 34, Parent = card,
        }, {
            corner(6),
            new("UIPadding", { PaddingTop = UDim.new(0, 3), PaddingBottom = UDim.new(0, 3),
                PaddingLeft = UDim.new(0, 3), PaddingRight = UDim.new(0, 3) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 2),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }),
        })
        local buttons, content = {}, {}
        -- v0.0.32: fade content in on switch (CanvasGroup GroupTransparency).
        local function showCol(name)
            for n, b in pairs(buttons) do
                local on = (n == name)
                tween(b, Theme.Animation.Fast, {
                    BackgroundTransparency = on and 0.15 or 1,
                    TextColor3 = on and Theme.Palette.Text or Theme.Palette.TextMuted,
                })
                local cf = content[n]
                if on then
                    cf.Visible = true
                    cf.GroupTransparency = 0.4
                    tween(cf, Theme.Animation.Normal, { GroupTransparency = 0 })
                else
                    cf.Visible = false
                end
            end
        end
        for i, name in ipairs(names) do
            local b = new("TextButton", {
                Text = name, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0),
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 1, AutoButtonColor = false,
                FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body, TextColor3 = Theme.Palette.TextMuted,
                LayoutOrder = i, ZIndex = 35, Parent = bar,
            }, { corner(5), new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }) })
            buttons[name] = b
            local cf = new("CanvasGroup", {
                Name = name, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1, Visible = false, LayoutOrder = i, ZIndex = 33, Parent = card,
            }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder }) })
            content[name] = cf
            b.MouseButton1Click:Connect(function() showCol(name) end)
        end
        showCol(names[1])
        return content
    end

    -- :: tab UI ::
    addTab("Combat", function(cpanel)
        local cols = new("Frame", {
            Name = "Columns", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1, ZIndex = 33, Parent = cpanel,
        }, {
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 12),
                SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Left }),
        })
        local leftCol = new("Frame", {
            Name = "Left", Size = UDim2.new(0.5, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1, LayoutOrder = 1, ZIndex = 33, Parent = cols,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 12),
            SortOrder = Enum.SortOrder.LayoutOrder }) })
        local rightCol = new("Frame", {
            Name = "Right", Size = UDim2.new(0.5, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1, LayoutOrder = 2, ZIndex = 33, Parent = cols,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 12),
            SortOrder = Enum.SortOrder.LayoutOrder }) })

        -- snapline checkbox handles: captured so enabling one clears the other
        -- (only one snapline context may be active at a time).
        local aimSnapCtrl, silentSnapCtrl

        -- :: LEFT COLUMN ::
        local leftCard = panel(leftCol)
        local L = subTabs(leftCard, { "Aimbot", "Prediction", "Legit", "FOV" })

        -- Aimbot
        local aimRow = moduleCheckbox(L.Aimbot, "Enabled", "aimbot")
        activationPill(aimRow.row, Combat.Aim,
            function() return Combat.Aim.Enabled end,
            function() return (not Combat.Aim.ActivationKey) or aimHeld end)
        rightClickSettings(configCheckbox(L.Aimbot, "Team Check", Combat.Aim.TeamCheck, function(v) Combat.Aim.TeamCheck = v end).row, "Team Check", teamCheckSettings)
        configCheckbox(L.Aimbot, "Visible Check", Combat.Aim.VisibleCheck, function(v) Combat.Aim.VisibleCheck = v end)
        configCheckbox(L.Aimbot, "Behind Cam", Combat.Aim.BehindCam, function(v) Combat.Aim.BehindCam = v end)
        configCheckbox(L.Aimbot, "Health Check", Combat.Aim.HealthCheck, function(v) Combat.Aim.HealthCheck = v end)
        configCheckbox(L.Aimbot, "Sticky Aim", Combat.Aim.Sticky, function(v) Combat.Aim.Sticky = v end)
        -- v0.0.36: third-person cursor aim (move mouse, not camera). Bind aimbot to a
        -- non-RMB key (e.g. XButton2) so it doesn't clash with the game's shift-lock.
        configCheckbox(L.Aimbot, "Third Person", Combat.Aim.ThirdPerson, function(v) Combat.Aim.ThirdPerson = v end)
        slider(L.Aimbot, "Distance", 1, 5000, Combat.Aim.Distance, 0, function(v) Combat.Aim.Distance = v end, { infinite = true })
        slider(L.Aimbot, "Sensitivity", 0.01, 1, Combat.Aim.Sensitivity, 2, function(v) Combat.Aim.Sensitivity = v end)
        configCheckbox(L.Aimbot, "Perfect Lock", Combat.Aim.PerfectLock, function(v) Combat.Aim.PerfectLock = v end)
        dropdown(L.Aimbot, "Hit Part", HITPARTS, Combat.Aim.HitPart, function(v) Combat.Aim.HitPart = v end)
        dropdown(L.Aimbot, "Aim Type", { "Camera", "Mouse" }, Combat.Aim.AimType, function(v) Combat.Aim.AimType = v end)
        local rageRow = configCheckbox(L.Aimbot, "Ragebot", Combat.Aim.Rage, function(v) Combat.Aim.Rage = v end)
        attachHelp(rageRow.row)
        local rageTypeDd = dropdown(L.Aimbot, "Type", { "Camera Teleport", "Character Teleport" }, Combat.Aim.RageType,
            function(v) Combat.Aim.RageType = v end)
        -- right-click the Type dropdown to tune the Character Teleport vertical offset
        rightClickSettings(rageTypeDd.frame, "Character Teleport", function(api)
            api:slider("Y Offset", -10, 10, Combat.Aim.RageYOffset, 1, function(v) Combat.Aim.RageYOffset = v end)
        end)
        aimSnapCtrl = configCheckbox(L.Aimbot, "Snaplines", Combat.Aim.Snaplines, function(v)
            Combat.Aim.Snaplines = v
            if v then Combat.Silent.Snaplines = false; if silentSnapCtrl then silentSnapCtrl.setState(false) end end
        end)

        -- Prediction
        local predRow = configCheckbox(L.Prediction, "Enabled", Combat.Aim.Predict.Enabled,
            function(v) Combat.Aim.Predict.Enabled = v end)
        attachHelp(predRow.row)
        slider(L.Prediction, "X (Division)", 0.1, 10, Combat.Aim.Predict.X, 2, function(v) Combat.Aim.Predict.X = v end)
        slider(L.Prediction, "Y (Division)", 0.1, 10, Combat.Aim.Predict.Y, 2, function(v) Combat.Aim.Predict.Y = v end)

        -- v0.52.0 Legit tab. Master toggle gates the frailty kit + the part pool,
        -- so the Aimbot tab's single Hit Part and this tab's multi-part pool never
        -- both apply. Smoothness moved here (its own enable) as a legit behaviour.
        configCheckbox(L.Legit, "Enabled", Combat.Aim.Legit.Enabled, function(v) Combat.Aim.Legit.Enabled = v end)
        slider(L.Legit, "Jitter (deg)", 0, 5, Combat.Aim.Legit.Jitter, 1, function(v) Combat.Aim.Legit.Jitter = v end)
        slider(L.Legit, "Overshoot (deg)", 0, 10, Combat.Aim.Legit.Overshoot, 1, function(v) Combat.Aim.Legit.Overshoot = v end)
        slider(L.Legit, "Reaction (ms)", 0, 500, Combat.Aim.Legit.Reaction, 0, function(v) Combat.Aim.Legit.Reaction = v end)
        slider(L.Legit, "Deadzone (px)", 0, 50, Combat.Aim.Legit.Deadzone, 0, function(v) Combat.Aim.Legit.Deadzone = v end)
        configCheckbox(L.Legit, "Smoothing", Combat.Aim.Smooth.Enabled, function(v) Combat.Aim.Smooth.Enabled = v end)
        slider(L.Legit, "Smoothness X", 0.1, 20, Combat.Aim.Smooth.X, 1, function(v) Combat.Aim.Smooth.X = v end)
        slider(L.Legit, "Smoothness Y", 0.1, 20, Combat.Aim.Smooth.Y, 1, function(v) Combat.Aim.Smooth.Y = v end)
        dropdown(L.Legit, "Hit Part Mode", { "Single Part", "Closest Part", "Random Part" }, Combat.Aim.Legit.PartMode,
            function(v) Combat.Aim.Legit.PartMode = v end)
        for _, pname in ipairs(HITPARTS) do
            local nm = pname
            configCheckbox(L.Legit, nm, Combat.Aim.Legit.Parts[nm] ~= false, function(v)
                Combat.Aim.Legit.Parts[nm] = v
            end)
        end

        -- FOV (shared control set)
        buildFovTab(L.FOV, Combat.Aim.FOV, Combat.Aim)

        -- Misc
        local miscCard = panel(leftCol, "Misc")
        configCheckbox(miscCard, "Resolver", Combat.Misc.Resolver, function(v) Combat.Misc.Resolver = v end)
        -- v0.75.0: dwell cluster radius. Wider forgives jittery trails (locks the
        -- anchor through strafing); tighter only bites true stand-stills.
        slider(miscCard, "Dwell Radius", 4, 30, Combat.Misc.DwellRadius or 16, 0, function(v) Combat.Misc.DwellRadius = v end)
        -- v0.77.1: gun rows only show on the gun-mods place. Hitbox rows stay
        -- universal in Combat Misc. All gun flags default off and no-op unmatched.
        if Koffee._gunModsGame then
            configCheckbox(miscCard, "Anti-Spread", Combat.Gun.AntiSpread,
                function(v) Combat.Gun.AntiSpread = v end)
            configCheckbox(miscCard, "Shoot In Car", Combat.Gun.ShootInCar,
                function(v) Combat.Gun.ShootInCar = v end)
            configCheckbox(miscCard, "No Recoil", Combat.Gun.NoRecoil,
                function(v) Combat.Gun.NoRecoil = v end)
            configCheckbox(miscCard, "No Spread", Combat.Gun.NoSpread,
                function(v) Combat.Gun.NoSpread = v end)
            configCheckbox(miscCard, "Rapid Fire", Combat.Gun.RapidFire,
                function(v) Combat.Gun.RapidFire = v end)
            slider(miscCard, "Fire Rate", 0.01, 0.5, Combat.Gun.RapidFireRate or 0.05, 2,
                function(v) Combat.Gun.RapidFireRate = v end)
            configCheckbox(miscCard, "Fast Reload", Combat.Gun.FastReload,
                function(v) Combat.Gun.FastReload = v end)
            configCheckbox(miscCard, "Instant Equip", Combat.Gun.InstantEquip,
                function(v) Combat.Gun.InstantEquip = v end)
            configCheckbox(miscCard, "Infinite Ammo", Combat.Gun.InfiniteAmmo,
                function(v) Combat.Gun.InfiniteAmmo = v end)
        end
        configCheckbox(miscCard, "Hitbox Expander", Combat.Gun.HitboxExpander,
            function(v) Combat.Gun.HitboxExpander = v end)
        slider(miscCard, "Hitbox Size", 1, 30, Combat.Gun.HitboxSize or 10, 0,
            function(v) Combat.Gun.HitboxSize = v end)

        -- v0.0.88 Sounds panel. Hit + Kill each have Enabled, Preset dropdown,
        -- Custom Sound Id (0 = use preset), Volume, Pitch, Cooldown. Also a
        -- shared Mouse Radius slider that tunes the mouse-target lock threshold.
        -- v0.0.89: preset list = filenames from <exec>/Koffee/sounds/*.mp3.
        -- Loader ships these files (or user copies once). See getcustomasset resolver.
        local SND_PRESETS_LIST = SND_PRESETS   -- v0.10.0: single source, see above
        local soundCard = panel(leftCol, "Sounds")
        configCheckbox(soundCard, "Hit Sound", Combat.HitSounds.Hit.Enabled, function(v) Combat.HitSounds.Hit.Enabled = v end)
        dropdown(soundCard, "Hit Preset", SND_PRESETS_LIST, Combat.HitSounds.Hit.Preset, function(v) Combat.HitSounds.Hit.Preset = v end)
        slider(soundCard, "Hit Custom Id", 0, 9999999999, Combat.HitSounds.Hit.CustomId, 0, function(v) Combat.HitSounds.Hit.CustomId = math.floor(v) end)
        slider(soundCard, "Hit Volume",    0, 5,           Combat.HitSounds.Hit.Volume,   2, function(v) Combat.HitSounds.Hit.Volume   = v end)
        slider(soundCard, "Hit Pitch",     0.5, 2,         Combat.HitSounds.Hit.Pitch,    2, function(v) Combat.HitSounds.Hit.Pitch    = v end)
        slider(soundCard, "Hit Cooldown",  0, 1000,        Combat.HitSounds.Hit.Cooldown, 0, function(v) Combat.HitSounds.Hit.Cooldown = math.floor(v) end)
        configCheckbox(soundCard, "Kill Sound", Combat.HitSounds.Kill.Enabled, function(v) Combat.HitSounds.Kill.Enabled = v end)
        dropdown(soundCard, "Kill Preset", SND_PRESETS_LIST, Combat.HitSounds.Kill.Preset, function(v) Combat.HitSounds.Kill.Preset = v end)
        slider(soundCard, "Kill Custom Id", 0, 9999999999, Combat.HitSounds.Kill.CustomId, 0, function(v) Combat.HitSounds.Kill.CustomId = math.floor(v) end)
        slider(soundCard, "Kill Volume",    0, 5,           Combat.HitSounds.Kill.Volume,   2, function(v) Combat.HitSounds.Kill.Volume   = v end)
        slider(soundCard, "Kill Pitch",     0.5, 2,         Combat.HitSounds.Kill.Pitch,    2, function(v) Combat.HitSounds.Kill.Pitch    = v end)
        slider(soundCard, "Kill Cooldown",  0, 1000,        Combat.HitSounds.Kill.Cooldown, 0, function(v) Combat.HitSounds.Kill.Cooldown = math.floor(v) end)
        configCheckbox(soundCard, "Overlap Sounds", Combat.HitSounds.Overlap, function(v) Combat.HitSounds.Overlap = v end)
        slider(soundCard, "Attr Window (s)", 0.5, 5, Combat.HitSounds.AttrWindow, 2, function(v) Combat.HitSounds.AttrWindow = v end)
        slider(soundCard, "Before Click (ms)", 1, 500, Combat.HitSounds.BeforeClick, 0, function(v) Combat.HitSounds.BeforeClick = math.floor(v) end)

        -- v0.7.0 hit / kill VISUAL effects. Same attribution as the sounds.
        -- Both rows sit inside the Sounds card (kept together in the UI even
        -- though they draw pixels, not audio). Right-click each for the deep
        -- knobs (color, scale, duration, attach part).
        -- v0.9.0: 3D presets (was four flavours of the same expanding circle).
        -- v0.10.0: textured art + four more. Old configs naming Ring / Flash fall
        -- through to Impact.
        local HFX_PRESETS = { "Impact", "Sparks", "Blood", "Shockwave", "Nova", "Ember",
            "Snowburst", "Confetti", "Glass", "Starfall",
            "Rune", "Crystal", "Hearts", "Soul", "Shatter", "Lightning", "Pillar", "Coil", "Shapes" }   -- v0.85.0 layered
        local HFX_ATTACH  = { "Head", "HRP", "Torso" }
        -- v0.7.1 fix: attachSingleSwatch is a chunk-local declared BELOW the
        -- Combat IIFE (line ~10272) so the upvalue captured here is nil at
        -- addTab call time. Combat IIFE ships its own equivalent `attachSwatch`
        -- local (line ~9572) with the same colorSwatch-in-a-wrap shape.
        local heHitRow = configCheckbox(soundCard, "Hit Effect", Combat.HitEffects.Hit.Enabled,
            function(v) Combat.HitEffects.Hit.Enabled = v end)
        attachSwatch(heHitRow.row, Combat.HitEffects.Hit.Color,
            function(c) Combat.HitEffects.Hit.Color = c end)
        rightClickSettings(heHitRow.row, "Hit Effect", function(popup)
            popup:dropdown("Preset", HFX_PRESETS, Combat.HitEffects.Hit.Preset,
                function(v) Combat.HitEffects.Hit.Preset = v end)
            popup:slider("Scale",     0.2, 4, Combat.HitEffects.Hit.Scale,    2, function(v) Combat.HitEffects.Hit.Scale = v end)
            popup:slider("Duration",  0.05, 2, Combat.HitEffects.Hit.Duration, 2, function(v) Combat.HitEffects.Hit.Duration = v end)
            popup:dropdown("Attach",  HFX_ATTACH, Combat.HitEffects.Hit.Attach,
                function(v) Combat.HitEffects.Hit.Attach = v end)
            popup:toggle("Flash Target", Combat.HitEffects.Hit.Flash ~= false,
                function(v) Combat.HitEffects.Hit.Flash = v end)
        end)
        local heKillRow = configCheckbox(soundCard, "Kill Effect", Combat.HitEffects.Kill.Enabled,
            function(v) Combat.HitEffects.Kill.Enabled = v end)
        attachSwatch(heKillRow.row, Combat.HitEffects.Kill.Color,
            function(c) Combat.HitEffects.Kill.Color = c end)
        rightClickSettings(heKillRow.row, "Kill Effect", function(popup)
            popup:dropdown("Preset", HFX_PRESETS, Combat.HitEffects.Kill.Preset,
                function(v) Combat.HitEffects.Kill.Preset = v end)
            popup:dropdown("Kill Animation", { "Off", "Ghost Rise", "Soul Orb", "Dust", "Angel", "Portal" },
                Combat.HitEffects.Kill.Anim or "Off", function(v) Combat.HitEffects.Kill.Anim = v end)
            popup:slider("Scale",     0.2, 4, Combat.HitEffects.Kill.Scale,    2, function(v) Combat.HitEffects.Kill.Scale = v end)
            popup:slider("Duration",  0.05, 2, Combat.HitEffects.Kill.Duration, 2, function(v) Combat.HitEffects.Kill.Duration = v end)
            popup:dropdown("Attach",  HFX_ATTACH, Combat.HitEffects.Kill.Attach,
                function(v) Combat.HitEffects.Kill.Attach = v end)
            popup:toggle("Flash Target", Combat.HitEffects.Kill.Flash ~= false,
                function(v) Combat.HitEffects.Kill.Flash = v end)
        end)

        -- :: RIGHT COLUMN ::
        local rightCard = panel(rightCol)
        local R = subTabs(rightCard, { "Silent Aim", "Prediction", "Legit", "FOV" })

        -- Silent Aim
        local sRow = moduleCheckbox(R["Silent Aim"], "Enabled", "silentaim")
        activationPill(sRow.row, Combat.Silent,
            function() return Combat.Silent.Enabled end,
            function() return (not Combat.Silent.ActivationKey) or silentHeld end)
        rightClickSettings(configCheckbox(R["Silent Aim"], "Team Check", Combat.Silent.TeamCheck, function(v) Combat.Silent.TeamCheck = v end).row, "Team Check", teamCheckSettings)
        configCheckbox(R["Silent Aim"], "Visible Check", Combat.Silent.VisibleCheck, function(v) Combat.Silent.VisibleCheck = v end)
        configCheckbox(R["Silent Aim"], "Behind Cam", Combat.Silent.BehindCam, function(v) Combat.Silent.BehindCam = v end)
        configCheckbox(R["Silent Aim"], "Health Check", Combat.Silent.HealthCheck, function(v) Combat.Silent.HealthCheck = v end)
        configCheckbox(R["Silent Aim"], "Sticky Aim", Combat.Silent.Sticky, function(v) Combat.Silent.Sticky = v end)
        slider(R["Silent Aim"], "Distance", 1, 5000, Combat.Silent.Distance, 0, function(v) Combat.Silent.Distance = v end, { infinite = true })
        dropdown(R["Silent Aim"], "Hit Part", HITPARTS, Combat.Silent.HitPart, function(v) Combat.Silent.HitPart = v end)
        dropdown(R["Silent Aim"], "Method", { "Forced Camera", "Second-Camera", "Raycast", "External" }, Combat.Silent.Method,
            function(v) Combat.Silent.Method = v; if Koffee.External then Koffee.External.onMethodChange(v) end end)
        configCheckbox(R["Silent Aim"], "Require Left-Click", Combat.Silent.RequireLMB, function(v) Combat.Silent.RequireLMB = v end)
        -- v0.34.0: Wallbang works on every method now: Raycast + External (origin
        -- rewrite), Forced Camera (shifts the camera read = everything), Second-Camera
        -- (shifts the outbound ray origin = write scripts only).
        configCheckbox(R["Silent Aim"], "Wallbang", Combat.Silent.Wallbang, function(v) Combat.Silent.Wallbang = v end)
        -- v0.0.45: Forced Magic-Bullet is universal by default (fire-read always on):
        -- spoofs mouse.Hit + Camera.CFrame + camera-rays, scoped so the real view/Popper
        -- are never touched. Spoof Scope is the caller-identification strategy (both
        -- exclude the PlayerModule camera); Caller-Class is the plain fallback.
        dropdown(R["Silent Aim"], "Spoof Scope", { "Auto (Learn)", "Caller-Class" }, Combat.Silent.SpoofScope, function(v) Combat.Silent.SpoofScope = v end)
        silentSnapCtrl = configCheckbox(R["Silent Aim"], "Snaplines", Combat.Silent.Snaplines, function(v)
            Combat.Silent.Snaplines = v
            if v then Combat.Aim.Snaplines = false; if aimSnapCtrl then aimSnapCtrl.setState(false) end end
        end)

        -- Prediction (silent)
        configCheckbox(R.Prediction, "Enabled", Combat.Silent.Predict.Enabled, function(v) Combat.Silent.Predict.Enabled = v end)
        slider(R.Prediction, "X (Division)", 0.1, 10, Combat.Silent.Predict.X, 2, function(v) Combat.Silent.Predict.X = v end)
        slider(R.Prediction, "Y (Division)", 0.1, 10, Combat.Silent.Predict.Y, 2, function(v) Combat.Silent.Predict.Y = v end)

        -- v0.50.0 legit kit for silent. Jitter scatters the redirect point in
        -- studs; Hit Chance fires a clean shot on failed rolls. Both calm.
        slider(R.Legit, "Jitter (studs)", 0, 5, Combat.Silent.Legit.Jitter, 1, function(v) Combat.Silent.Legit.Jitter = v end)
        slider(R.Legit, "Hit Chance (%)", 1, 100, Combat.Silent.Legit.HitChance, 0, function(v) Combat.Silent.Legit.HitChance = v end)
        -- v0.51.1 Force Miss: failed Hit Chance rolls hold the lock and throw
        -- the redirect wide instead of firing clean.
        configCheckbox(R.Legit, "Force Miss", Combat.Silent.Legit.ForceMiss, function(v) Combat.Silent.Legit.ForceMiss = v end)
        -- v0.51.0 hit part pool. Single Part keeps the Hit Part dropdown;
        -- Closest and Random draw from the ticked pool below (unticked parts
        -- never picked).
        dropdown(R.Legit, "Hit Part Mode", { "Single Part", "Closest Part", "Random Part" }, Combat.Silent.Legit.PartMode,
            function(v) Combat.Silent.Legit.PartMode = v end)
        for _, pname in ipairs(HITPARTS) do
            local nm = pname
            configCheckbox(R.Legit, nm, Combat.Silent.Legit.Parts[nm] ~= false, function(v)
                Combat.Silent.Legit.Parts[nm] = v
            end)
        end
        slider(R.Legit, "Spread (studs)", 0, 5, Combat.Silent.Legit.Spread, 1, function(v) Combat.Silent.Legit.Spread = v end)
        -- v0.79.2: hit-position killcams read group shape. Degrees mode makes
        -- error angular (human), Bloom grows it with beam time (fatigue).
        dropdown(R.Legit, "Spread Unit", { "Studs", "Degrees" }, Combat.Silent.Legit.SpreadUnit or "Studs",
            function(v) Combat.Silent.Legit.SpreadUnit = v end)
        slider(R.Legit, "Bloom (%)", 0, 200, Combat.Silent.Legit.Bloom or 0, 0, function(v) Combat.Silent.Legit.Bloom = v end)

        -- FOV (same shared control set as the aimbot side)
        buildFovTab(R.FOV, Combat.Silent.FOV, Combat.Silent)

        -- Trigger Bot
        local trigCard = panel(rightCol, "Trigger Bot")
        local tRow = moduleCheckbox(trigCard, "Enabled", "triggerbot")
        activationPill(tRow.row, Combat.Trigger,
            function() return Combat.Trigger.Enabled end,
            function() return (not Combat.Trigger.ActivationKey) or trigHeld end)
        configCheckbox(trigCard, "Visible Check", Combat.Trigger.VisibleCheck, function(v) Combat.Trigger.VisibleCheck = v end)
        rightClickSettings(configCheckbox(trigCard, "Team Check", Combat.Trigger.TeamCheck, function(v) Combat.Trigger.TeamCheck = v end).row, "Team Check", teamCheckSettings)
        slider(trigCard, "Hitbox Mul", 1, 10, Combat.Trigger.HitboxMul, 2, function(v) Combat.Trigger.HitboxMul = v end)
        slider(trigCard, "Delay (ms)", 0, 500, Combat.Trigger.Delay, 0, function(v) Combat.Trigger.Delay = v end)
        slider(trigCard, "Release (ms)", 0, 500, Combat.Trigger.Release, 0, function(v) Combat.Trigger.Release = v end)
        -- v0.50.0 trigger range + discipline. Distance caps both fire paths;
        -- Head Only restricts to exact head hits; Reaction humanizes timing.
        slider(trigCard, "Distance", 50, 2000, Combat.Trigger.Distance, 0, function(v) Combat.Trigger.Distance = v end)
        configCheckbox(trigCard, "Head Only", Combat.Trigger.HeadOnly, function(v) Combat.Trigger.HeadOnly = v end)
        slider(trigCard, "Reaction (ms)", 0, 500, Combat.Trigger.Reaction, 0, function(v) Combat.Trigger.Reaction = v end)
        slider(trigCard, "Reaction Spread (ms)", 0, 500, Combat.Trigger.Spread, 0, function(v) Combat.Trigger.Spread = v end)
        slider(trigCard, "Hit Chance (%)", 1, 100, Combat.Trigger.HitChance, 0, function(v) Combat.Trigger.HitChance = v end)
    end)
    -- v0.1.0: the Options tab (built in this file's shared scope, outside this
    -- IIFE) reads Combat state + the sound instances during unload; hand them up
    -- through Shared so that path sees the same tables, not nil globals.
    Shared.Combat = Combat
    Shared.CombatSounds = { hit = hitSnd, kill = killSnd }
    -- v0.5.0: expose subTabs so the Visuals tab (and later World/Rules in wave 3)
    -- can reuse the same pill-switcher builder Combat pioneered. Chunk-scope
    -- would blow the 200-register ceiling; Shared is the natural handoff.
    Shared.subTabs = subTabs
end)();

-- v0.18.0 ANTI-SPREAD (now universal): pin SpreadRadius to 0. Attribute-signal
-- driven with slow sweep (handles swap/re-parent/re-attribute). Own IIFE.
(function()
    -- Combat is scoped to its own IIFE; Shared.Combat is the published handle
    local G = Shared.Combat.Gun
    local watched = setmetatable({}, { __mode = "k" })
    local conns = {}
    local nextSweep = 0

    local function pin(tool)
        if not (G.AntiSpread and tool and tool.Parent) then return end
        if not tool:IsA("Tool") then return end
        -- absent attribute: not a gun in this game, skip it.
        if tool:GetAttribute("SpreadRadius") == nil then return end
        if tool:GetAttribute("SpreadRadius") ~= 0 then
            pcall(function() tool:SetAttribute("SpreadRadius", 0) end)
        end
        if not watched[tool] then
            watched[tool] = tool:GetAttributeChangedSignal("SpreadRadius"):Connect(function()
                if G.AntiSpread and tool:GetAttribute("SpreadRadius") ~= 0 then
                    pcall(function() tool:SetAttribute("SpreadRadius", 0) end)
                end
            end)
        end
    end

    local function sweep()
        local ch = LocalPlayer.Character
        if ch then for _, c in ipairs(ch:GetChildren()) do pin(c) end end
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then for _, c in ipairs(bp:GetChildren()) do pin(c) end end
    end

    local function watch(container)
        if not container then return end
        conns[#conns + 1] = container.ChildAdded:Connect(function(c)
            task.defer(pin, c)
        end)
    end

    watch(LocalPlayer.Character)
    watch(LocalPlayer:FindFirstChildOfClass("Backpack"))
    LocalPlayer.CharacterAdded:Connect(function(ch)
        task.wait(0.5)
        watch(ch)
        watch(LocalPlayer:FindFirstChildOfClass("Backpack"))
        if G.AntiSpread then sweep() end
    end)

    RunService.Heartbeat:Connect(function()
        if Koffee.dead() or not G.AntiSpread then return end
        local now = os.clock()
        if now < nextSweep then return end
        nextSweep = now + 2
        sweep()
    end)
end)();

-- v0.77.0 GUN CATALOG (universal): name-matched weapon stat enforcement.
-- Covers both Arsenal-style tuning folders (ReplicatedStorage, 12s cached
-- scan) and tool-held values (character + backpack sweep, ChildAdded for
-- respawns and mid-fight pickups). Originals snapshot per value, restore on
-- toggle-off. Instant Equip also forces ready-state flags both ways.
(function()
    local G = Shared.Combat.Gun
    local RS = game:GetService("ReplicatedStorage")
    local WS = game:GetService("Workspace")
    local orig = setmetatable({}, { __mode = "k" })
    local watchedC = setmetatable({}, { __mode = "k" })
    local rsCache, rsAt, fullCache, fullAt, nextSweep, nextGC = nil, 0, nil, 0, 0, 0
    local NUM = {
        RapidFire  = { FireRate = true, BFireRate = true },
        FastReload = { ReloadTime = true, EReloadTime = true },
        NoSpread   = { MaxSpread = true, Spread = true, SpreadControl = true },
        NoRecoil   = { RecoilControl = true, Recoil = true },
    }
    local AUTO = { Auto = true, AutoFire = true, Automatic = true,
        AutoShoot = true, AutoGun = true }
    local EQ_A = { "equip", "draw", "switch", "deploy", "raise",
        "holster", "unsheath" }
    local EQ_B = { "time", "delay", "duration" }
    local EQ_FALSE = { equipping = true, isequipping = true, switching = true,
        isswitching = true, deploying = true, drawing = true,
        raising = true, holstering = true }
    local EQ_TRUE = { canshoot = true, canfire = true, canattack = true,
        readytofire = true }

    local function armed()
        return G.NoRecoil or G.NoSpread or G.RapidFire or G.FastReload or G.InstantEquip
    end
    local function hasFrag(nm, list)
        for _, f in ipairs(list) do
            if string.find(nm, f, 1, true) then return true end
        end
        return false
    end
    local function restore(inst)
        local v = orig[inst]
        if v ~= nil then
            orig[inst] = nil
            pcall(function() if inst.Parent then inst.Value = v end end)
        end
    end
    local function force(inst, want)
        if orig[inst] == nil then orig[inst] = inst.Value end
        if inst.Value ~= want then pcall(function() inst.Value = want end) end
    end
    local function route(inst)
        if not inst.Parent then orig[inst] = nil; return end
        local nm = string.lower(tostring(inst.Name))
        if inst:IsA("NumberValue") then
            for mod, set in pairs(NUM) do
                if set[inst.Name] then
                    if G[mod] then
                        local want = (mod == "RapidFire") and (G.RapidFireRate or 0.05)
                            or (mod == "FastReload" and 0.01 or 0)
                        force(inst, want)
                    else restore(inst) end
                    return
                end
            end
            if hasFrag(nm, EQ_A) and hasFrag(nm, EQ_B) then
                if G.InstantEquip then force(inst, 0.01) else restore(inst) end
            end
        elseif inst:IsA("BoolValue") then
            if AUTO[inst.Name] then
                if G.RapidFire then force(inst, true) else restore(inst) end
            elseif EQ_FALSE[nm] then
                if G.InstantEquip then force(inst, false) else restore(inst) end
            elseif EQ_TRUE[nm] then
                if G.InstantEquip then force(inst, true) else restore(inst) end
            end
        end
    end
    local function applyList(list)
        for _, d in ipairs(list) do
            if d:IsA("NumberValue") or d:IsA("BoolValue") then route(d) end
        end
    end
    -- v0.81.0 GC TABLE HUNTER: tuning that lives in Lua tables (required
    -- config modules, upvalue tables) instead of Values. getgc scans for
    -- tables holding 2+ catalog keys, then pins the fields in place. rawget
    -- reads never invent keys; restores run per-key on toggle-off and as a
    -- full flush when everything disarms. Case-insensitive: module keys are
    -- usually PascalCase, Value names are not.
    local TNUM, TAUTO = {}, {}
    for mod, set in pairs(NUM) do
        for nm in pairs(set) do TNUM[string.lower(nm)] = mod end
    end
    for nm in pairs(AUTO) do TAUTO[string.lower(nm)] = true end
    local OWN = {}
    local torig = setmetatable({}, { __mode = "k" })
    local function tsave(t, k)
        local o = torig[t]
        if not o then o = {}; torig[t] = o end
        if o[k] == nil then o[k] = rawget(t, k) end
    end
    local function trestore(t, k)
        local o = torig[t]
        if o and o[k] ~= nil then
            local v = o[k]; o[k] = nil
            pcall(function() t[k] = v end)
        end
    end
    local function tforce(t, k, want)
        tsave(t, k)
        pcall(function() if t[k] ~= want then t[k] = want end end)
    end
    local function scoreTable(t)
        local hits, n = 0, 0
        local seenEq = false
        local ok = pcall(function()
            for k in pairs(t) do
                n = n + 1
                if n > 60 or hits >= 2 then break end
                if type(k) == "string" then
                    local lk = string.lower(k)
                    if TNUM[lk] or TAUTO[lk] then hits = hits + 1 end
                    if not seenEq and hasFrag(lk, EQ_A) and hasFrag(lk, EQ_B) then
                        seenEq = true; hits = hits + 1
                    end
                end
            end
        end)
        if not ok then return 0 end
        return hits
    end
    local function routeTable(t)
        pcall(function()
            for k in pairs(t) do
                if type(k) == "string" then
                    local lk, rv = string.lower(k), rawget(t, k)
                    if rv ~= nil then
                        local mod = TNUM[lk]
                        if mod and type(rv) == "number" then
                            if G[mod] then
                                local want = (mod == "RapidFire") and (G.RapidFireRate or 0.05)
                                    or (mod == "FastReload" and 0.01 or 0)
                                tforce(t, k, want)
                            else trestore(t, k) end
                        elseif TAUTO[lk] and type(rv) == "boolean" then
                            if G.RapidFire then tforce(t, k, true) else trestore(t, k) end
                        elseif type(rv) == "number"
                            and hasFrag(lk, EQ_A) and hasFrag(lk, EQ_B) then
                            if G.InstantEquip then tforce(t, k, 0.01) else trestore(t, k) end
                        end
                    end
                end
            end
        end)
    end
    local function hunt()
        OWN[G] = true
        if Shared.Combat then
            local S = Shared.Combat.Silent
            local A = Shared.Combat.Aim
            if S and S.Legit then OWN[S.Legit] = true end
            if A and A.Legit then OWN[A.Legit] = true end
        end
        if type(getgc) ~= "function" then return end
        local ok, all = pcall(getgc, true)
        if not ok or type(all) ~= "table" then return end
        for _, v in ipairs(all) do
            if type(v) == "table" and not OWN[v] and scoreTable(v) >= 2 then
                routeTable(v)
            end
        end
    end
    -- v0.82.0 FULL RESULTS: Mods-tab picker over the whole game.
    -- v0.82.3: NO name filter. The catalog is for the auto-engine; the picker
    -- lists every parent holding tunables (any Number/Int/Bool Value, or any
    -- attributes on a Model/Tool/Folder), sorted by count. Capped, cached.
    Shared.GunMods = Shared.GunMods or {}
    do
        local gsCache, gsAt = nil, 0
        Shared.GunMods.fullScan = function()
            local now = os.clock()
            if gsCache and now - gsAt < 15 then return gsCache end
            local groups, order = {}, {}
            local function hit(p, n)
                if not groups[p] then
                    if #order >= 300 then return end
                    groups[p] = 0
                    order[#order + 1] = p
                end
                groups[p] = groups[p] + n
            end
            local ok, desc = pcall(function() return game:GetDescendants() end)
            if ok and desc then
                local pg = LocalPlayer:FindFirstChild("PlayerGui")
                for _, d in ipairs(desc) do
                    if #order >= 300 then break end
                    if not pg or not d:IsDescendantOf(pg) then
                        if d:IsA("NumberValue") or d:IsA("IntValue") or d:IsA("BoolValue") then
                            local p = d.Parent
                            if p then hit(p, 1) end
                        elseif d:IsA("Model") or d:IsA("Tool") or d:IsA("Folder") then
                            local okA, at = pcall(function() return d:GetAttributes() end)
                            if okA and at and next(at) ~= nil then
                                local n = 0
                                for _ in pairs(at) do n = n + 1 end
                                hit(d, n)
                            end
                        end
                    end
                end
            end
            table.sort(order, function(a, b) return (groups[a] or 0) > (groups[b] or 0) end)
            local out = {}
            for _, p in ipairs(order) do
                local path = ""
                pcall(function()
                    path = (Shared.pathOf and Shared.pathOf(p)) or p:GetFullName()
                end)
                out[#out + 1] = { inst = p, name = p.Name, count = groups[p], path = path }
            end
            gsCache, gsAt = out, now
            return out
        end
    end
    -- v0.81.2 AUTO RE-EQUIP: games that read tuning once at equip run on
    -- stale cache after we pin. On every armed-signature change, cycle the
    -- equipped tool backpack->character over two heartbeats so the game
    -- re-reads the forced values. No user re-equip needed.
    local prevSig, reeq, reeqPhase, reeqCool = "", nil, 0, 0
    local function sig()
        return (G.RapidFire and "R" or "") .. (G.FastReload and "F" or "")
            .. (G.NoSpread and "S" or "") .. (G.NoRecoil and "N" or "")
            .. (G.InstantEquip and "E" or "")
    end
    local function pumpReequip()
        if not reeq then return end
        local ch = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if not reeq.Parent or not ch or not bp then reeq = nil; return end
        if reeqPhase == 0 then
            if reeq.Parent == ch then
                pcall(function() reeq.Parent = bp end)
                reeqPhase = 1
            else reeq = nil end
        else
            if reeq.Parent == bp then
                pcall(function() reeq.Parent = ch end)
            end
            reeq = nil
        end
    end
    local function sweep()
        local now = os.clock()
        local scope = G.ScanScope or "Replicated"
        if scope == "Full Game" then
            -- whole game minus UI, 30s cache (big-map GetDescendants hitches).
            -- PlayerGui skipped: HUD counters are display copies, pinning them
            -- fights the HUD with zero effect on the gun.
            if not fullCache or now >= fullAt then
                fullCache, fullAt = {}, now + 30
                local ok, desc = pcall(function() return game:GetDescendants() end)
                if ok and desc then
                    local pg = LocalPlayer:FindFirstChild("PlayerGui")
                    for _, d in ipairs(desc) do
                        if not pg or not d:IsDescendantOf(pg) then
                            fullCache[#fullCache + 1] = d
                        end
                    end
                end
            end
            applyList(fullCache)
        elseif scope == "Replicated" then
            if not rsCache or now >= rsAt then
                local ok, desc = pcall(function() return RS:GetDescendants() end)
                rsCache, rsAt = (ok and desc) or {}, now + 12
            end
            applyList(rsCache)
        end
        -- live trees always ride along: respawns and pickups land between
        -- cache refreshes, and Character scope is live-only by definition.
        local ch = LocalPlayer.Character
        if ch then
            local ok, desc = pcall(function() return ch:GetDescendants() end)
            if ok and desc then applyList(desc) end
        end
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then
            local ok, desc = pcall(function() return bp:GetDescendants() end)
            if ok and desc then applyList(desc) end
        end
        -- ammo gui cache for the __index read spoof (fail open when absent).
        G._ammoGui = LocalPlayer:FindFirstChild("PlayerGui")
        -- signature change while armed: refresh the equipped tool's cache.
        -- Holds prevSig through cooldown/tool-less sweeps so it retries.
        local s = sig()
        if s ~= prevSig then
            if s ~= "" then
                local ch = LocalPlayer.Character
                local tool = ch and ch:FindFirstChildOfClass("Tool")
                if tool and now - reeqCool > 5 then
                    reeq, reeqPhase, reeqCool = tool, 0, now
                    prevSig = s
                end
            else prevSig = s end
        end
    end
    local function watch(container, fullOnly)
        if not container or watchedC[container] then return end
        watchedC[container] = true
        container.ChildAdded:Connect(function(c)
            if Koffee.dead() or not armed() then return end
            if fullOnly and (G.ScanScope or "Replicated") ~= "Full Game" then return end
            task.defer(function()
                if c:IsA("NumberValue") or c:IsA("BoolValue") then route(c) end
                local ok, desc = pcall(function() return c:GetDescendants() end)
                if ok and desc then applyList(desc) end
            end)
        end)
    end
    watch(LocalPlayer.Character)
    watch(LocalPlayer:FindFirstChildOfClass("Backpack"))
    watch(RS)
    watch(WS, true)
    LocalPlayer.CharacterAdded:Connect(function(ch)
        task.wait(0.5)
        if Koffee.dead() then return end
        watch(ch)
        watch(LocalPlayer:FindFirstChildOfClass("Backpack"))
        if armed() then sweep() end
    end)
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        pumpReequip()
        local now = os.clock()
        -- hunter cadence: 8s while armed (getgc walks are heavy), full
        -- restore flush once everything disarms.
        if now >= nextGC then
            nextGC = now + 8
            if armed() then hunt()
            else
                for t, o in pairs(torig) do
                    for k, v in pairs(o) do o[k] = nil; pcall(function() t[k] = v end) end
                    torig[t] = nil
                end
            end
        end
        if not armed() then return end
        if now < nextSweep then return end
        nextSweep = now + 2
        sweep()
    end)
end)();

-- v0.77.0 HITBOX EXPANDER (universal): grows enemy hit parts to HitboxSize
-- studs, invisible and non-colliding, for client-hitreg games. Team-gated
-- through aimAllowed (lock-gated too), dead-gated on Humanoid. 4Hz passes
-- with cached refs, never a per-frame FindFirstChild sweep. Tradeoff: grown
-- heads read headless on your screen while it runs. Restores on off/respawn.
(function()
    local G = Shared.Combat.Gun
    local Players = game:GetService("Players")
    local PARTS = { "HeadHB", "Head", "UpperTorso", "Torso" }
    local snap, conn, nextPass = {}, nil, 0
    -- v0.77.1: live grown-player set for the ESP Hitbox toggle. Cleared by
    -- forget() on every exit path, so ESP never reads a stale entry.
    Shared.Hitbox = {}
    local function forget(plr, restoreIt)
        local rec = snap[plr]
        if not rec then return end
        snap[plr] = nil
        Shared.Hitbox[plr] = nil
        if restoreIt then
            for inst, o in pairs(rec.parts) do
                pcall(function()
                    if inst.Parent then
                        inst.CanCollide = o.c
                        inst.Transparency = o.t
                        inst.Size = o.s
                    end
                end)
            end
        end
    end
    Players.PlayerRemoving:Connect(function(plr) forget(plr, false) end)
    conn = RunService.Heartbeat:Connect(function()
        if Koffee.dead() then
            for plr in pairs(snap) do forget(plr, true) end
            if conn then conn:Disconnect() end
            return
        end
        if not G.HitboxExpander then
            for plr in pairs(snap) do forget(plr, true) end
            return
        end
        local now = os.clock()
        if now < nextPass then return end
        nextPass = now + 0.25
        local want = math.clamp(tonumber(G.HitboxSize) or 10, 1, 30)
        local size = Vector3.new(want, want, want)
        for _, plr in ipairs(Players:GetPlayers()) do
            local ch = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if plr == LocalPlayer or not ch or not hum or hum.Health <= 0
               or hum:GetState() == Enum.HumanoidStateType.Dead
               or not Shared.aimAllowed(plr, true) then
                forget(plr, true)
            else
                local rec = snap[plr]
                if not rec or rec.char ~= ch then
                    forget(plr, true)
                    rec = { char = ch, parts = {} }
                    snap[plr] = rec
                end
                Shared.Hitbox[plr] = want
                for _, nm in ipairs(PARTS) do
                    local p = ch:FindFirstChild(nm)
                    if p and p:IsA("BasePart") then
                        if rec.parts[p] == nil then
                            rec.parts[p] = { c = p.CanCollide, t = p.Transparency, s = p.Size }
                        end
                        pcall(function()
                            p.CanCollide = false
                            p.Transparency = 1
                            if (p.Size - size).Magnitude > 0.01 then p.Size = size end
                        end)
                    end
                end
            end
        end
    end)
end)()

-- helper: attach two color swatches (visible + hidden) to a Visible Check row
local function attachDualSwatch(row, visColor, hidColor, onVis, onHid)
    local wrap = new("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, 0, 0.5, 0),
        Size = UDim2.new(0, 36, 0, 16),
        BackgroundTransparency = 1,
        ZIndex = 38,
        Parent = row,
    }, {
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalAlignment = Enum.HorizontalAlignment.Right,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 4),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }),
    })
    colorSwatch(wrap, visColor, 14, { onChange = onVis })
    colorSwatch(wrap, hidColor, 14, { onChange = onHid })
end

-- v0.0.18: single-swatch variant for rows that own one color (Outline accent).
-- Same right-aligned placement pattern as attachDualSwatch, just one swatch.
local function attachSingleSwatch(row, initialColor, onChange)
    local wrap = new("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, 0, 0.5, 0),
        Size = UDim2.new(0, 14, 0, 16),
        BackgroundTransparency = 1,
        ZIndex = 38,
        Parent = row,
    }, {
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalAlignment = Enum.HorizontalAlignment.Right,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
        }),
    })
    colorSwatch(wrap, initialColor, 14, { onChange = onChange })
end

-- v0.5.0: CROSSHAIR + HIT NUMBERS render layer. Container Frame parents both
-- surfaces; lives directly under `screen` at ZIndex 14 (above ESP/dim but well
-- below the Koffee window at ZIndex 30+). Everything is GUI-based so kernel-
-- driver runtimes render it under our own UI, unlike Drawing.new.
-- v0.5.1: WRAPPED IN IIFE (was a do-block). Luau's 200-local ceiling is
-- per FUNCTION; a do-block shares the chunk's register pool and this block
-- pushed the chunk over the limit at STYLE_ARMS. IIFE = own budget, same
-- trick Combat uses. Nothing inside changed.
;(function()
    -- Workspace / RunService already at chunk scope (see line ~923); reusing them
    -- here saves two of the IIFE's local registers.

    -- one shared layer for both crosshair + damage-number pool.
    local layer = new("Frame", {
        Name = KID.name("xhair"), Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 14,
        Parent = screen,
    })

    -- :: crosshair ::
    -- v0.11.2 DOUBLE CROSSHAIRS. Everything below is built per-INSTANCE now. With
    -- Double off there is one crosshair (config table `Crosshair`, "A"); with it on
    -- A follows the aimbot's FOV rules and a second crosshair `Crosshair.S` follows
    -- Silent Aim's. Same renderer, two frame sets, two config tables.
    local ARM_SEG_MAX = 96
    local ARMS = 6            -- most any style needs (the hexagram's six edges)

    local function mkSeg(parent, z, col)
        return new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            Size = UDim2.new(0, 2, 0, 4), BorderSizePixel = 0, Visible = false,
            BackgroundColor3 = col, ZIndex = z, Parent = parent,
        }, { new("UICorner", { CornerRadius = UDim.new(0, 0) }) })
    end

    -- Build one complete crosshair. The CanvasGroup wrap lets Opacity drive the whole
    -- thing at once; KGrad piggybacks the shared ESP gradient master.
    --
    -- v0.9.0 OUTLINE MODEL, unchanged: v0.8 put a Border UIStroke on every segment,
    -- and a stroke traces all FOUR sides of its box, so an arm came out looking like
    -- a ladder. The outline is its own geometry: a second segment chain, each piece
    -- othick wider/longer than its fill twin, under a lower-ZIndex root. Two ROOTS
    -- rather than per-arm layers because Sibling ZIndex breaks ties by ancestry.
    local function mkXH(name)
        local canvas = new("CanvasGroup", {
            Name = "XHair" .. name, AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.new(0, 64, 0, 64),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            BackgroundTransparency = 1, GroupTransparency = 1, Visible = false,
            ZIndex = 15, Parent = layer,
        }, { new("UIGradient", { Name = "KGrad", Enabled = false }) })
        local outlineRoot = new("Frame", {
            Name = "Outline", Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 14, Parent = canvas,
        })
        local fillRoot = new("Frame", {
            Name = "Fill", Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 15, Parent = canvas,
        })
        local arms = {}
        for i = 1, ARMS do
            arms[i] = {
                out  = new("Frame", { Name = "A" .. i .. "O", Size = UDim2.new(1, 0, 1, 0),
                         BackgroundTransparency = 1, BorderSizePixel = 0,
                         ZIndex = 14, Parent = outlineRoot }),
                fill = new("Frame", { Name = "A" .. i, Size = UDim2.new(1, 0, 1, 0),
                         BackgroundTransparency = 1, BorderSizePixel = 0,
                         ZIndex = 15, Parent = fillRoot }),
                fills = {}, outs = {},
            }
        end
        local dot = new("Frame", {
            Name = "Dot", AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            Size = UDim2.new(0, 4, 0, 4), BorderSizePixel = 0, Visible = false,
            ZIndex = 16, Parent = canvas,
        }, { new("UICorner", { CornerRadius = UDim.new(1, 0) }),
             new("UIStroke", { Thickness = 1, Enabled = false }) })
        local outer = new("Frame", {
            Name = "Outer", AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            Size = UDim2.new(0, 24, 0, 24), BackgroundTransparency = 1,
            BorderSizePixel = 0, Visible = false, ZIndex = 15, Parent = canvas,
        }, { new("UICorner", { CornerRadius = UDim.new(0, 4) }),
             new("UIStroke", { Thickness = 2, Enabled = true }) })
        return { canvas = canvas, arms = arms, dot = dot, outer = outer }
    end

    -- grown on demand: 96 segs x 2 chains x 6 arms up front is real cost for a
    -- crosshair most people leave straight.
    local function growArm(a, want)
        for i = #a.fills + 1, math.min(want, ARM_SEG_MAX) do
            a.outs[i]  = mkSeg(a.out,  14, Color3.new(0, 0, 0))
            a.fills[i] = mkSeg(a.fill, 15, Color3.new(1, 1, 1))
        end
    end

    -- v0.9.0: segment count follows the geometry instead of sitting at 14. Straight
    -- arms get ONE segment. Curved arms: neighbouring segments sit sweep/n apart, so
    -- on the outside of a bend they gap by ~(thickness/2)*(sweep/n): which is why
    -- more Thickness meant less smooth. Budget that notch at ~0.5px and solve for n.
    local function segmentsFor(thickness, curvierDeg)
        local sweep = math.rad(math.abs(curvierDeg or 0))
        if sweep <= 0 then return 1 end
        local n = math.ceil(thickness * sweep) + math.ceil(sweep * 6)
        return math.clamp(n, 10, ARM_SEG_MAX)
    end

    -- double-sided gradient sampler: colour for a segment `dist` px out from centre,
    -- folded A -> B -> A so every arm carries the same outward ramp.
    local function segColorAt(dist, reach, a, b, spacing, off)
        local t = ((dist / math.max(reach, 1)) - off) % 1
        local f
        if t <= spacing then f = t / math.max(spacing, 0.01)
        else f = 1 - (t - spacing) / math.max(1 - spacing, 0.01) end
        return a:Lerp(b, math.clamp(f, 0, 1))
    end

    -- v0.11.2: paint one arm from an EXPLICIT start point and heading, rather than
    -- always radiating from the centre. That is what lets a style be an arbitrary set
    -- of line segments: the hexagram is six chords between ring vertices, not six
    -- spokes. P carries the style params so the signature stays readable.
    -- curveDeg goes on the segment's rotation, never the walk heading.
    local function paintArm(a, x0, y0, theta0, length, dist0, P)
        growArm(a, P.segN)
        local segLen = length / P.segN
        local theta  = theta0
        local turn   = math.rad(P.curvier or 0) / P.segN
        local x, y   = x0, y0
        local drawOutline = P.outline and P.othick > 0
        -- outline twin: othick wider per side, othick longer per end
        local ow = P.thickness + P.othick * 2
        local ol = segLen + 1 + P.othick * 2
        local fillR = math.floor(P.thickness * 0.5 * P.smooth + 0.5)
        local outR  = math.floor(ow * 0.5 * P.smooth + 0.5)
        local dist  = dist0
        for i = 1, P.segN do
            local dx = math.sin(theta) * segLen * 0.5
            local dy = -math.cos(theta) * segLen * 0.5
            x = x + dx; y = y + dy
            local pos = UDim2.new(0.5, x, 0.5, y)
            local rot = math.deg(theta) + P.curve
            -- v0.86.0: axis-aligned arms draw unrotated on whole pixels. A 180 degree
            -- rotation about a half-pixel centre rasterised mirrored arms 1px apart.
            local w, h = P.thickness, segLen + 1
            local q = rot / 90
            if P.curvier == 0 and math.abs(q - math.floor(q + 0.5)) < 0.001 then
                if math.floor(q + 0.5) % 2 == 1 then w, h = h, w end
                rot = 0
                pos = UDim2.new(0.5, math.floor(x + 0.5), 0.5, math.floor(y + 0.5))
            end
            local f = a.fills[i]
            f.Visible = true
            f.Position = pos
            -- +1px overlap kills seams between segments
            f.Size = UDim2.new(0, w, 0, h)
            f.Rotation = rot
            f.BackgroundColor3 = P.grad and P.grad(dist + segLen * 0.5) or P.color
            f.BackgroundTransparency = 0
            local fc = f:FindFirstChildOfClass("UICorner")
            if fc then fc.CornerRadius = UDim.new(0, fillR) end
            local o = a.outs[i]
            o.Visible = drawOutline
            if drawOutline then
                o.Position = pos
                if rot == 0 and w ~= P.thickness then
                    o.Size = UDim2.new(0, ol, 0, ow)
                else
                    o.Size = UDim2.new(0, ow, 0, ol)
                end
                o.Rotation = rot
                o.BackgroundColor3 = P.ocol
                local oc = o:FindFirstChildOfClass("UICorner")
                if oc then oc.CornerRadius = UDim.new(0, outR) end
            end
            x = x + dx; y = y + dy
            dist = dist + segLen
            theta = theta + turn
        end
        for i = P.segN + 1, #a.fills do
            a.fills[i].Visible = false
            a.outs[i].Visible = false
        end
    end

    -- v0.11.2 STYLE TABLE.
    --   spokes: degrees, measured CW from up; each is an arm radiating outward.
    --   chords: {from, to} vertex angles on a ring of radius Gap+Length; the arm
    --               runs BETWEEN them. Used for closed shapes.
    --   gap0: force Gap to 0 (Plus).
    --   dot / outer / outerRot: the non-arm pieces.
    local STYLES = {
        Cross       = { spokes = { 0, 90, 180, 270 } },
        Plus        = { spokes = { 0, 90, 180, 270 }, gap0 = true },
        ["T-Cross"] = { spokes = { 90, 180, 270 } },
        X           = { spokes = { 45, 135, 225, 315 } },
        Chevron     = { spokes = { 135, 225 } },
        Arrow       = { spokes = { 180 } },
        -- closed shapes, drawn as chords between ring vertices
        Triangle    = { chords = { { 0, 120 }, { 120, 240 }, { 240, 0 } } },
        Diamond     = { chords = { { 0, 90 }, { 90, 180 }, { 180, 270 }, { 270, 0 } } },
        -- two overlapping triangles: a six-point star outline
        Star        = { chords = { { 0, 120 }, { 120, 240 }, { 240, 0 },
                                   { 60, 180 }, { 180, 300 }, { 300, 60 } } },
        Dot         = { dot = true },
        Circle      = { outer = true },
        Square      = { outer = true, square = true },
    }
    -- exported so the tab's dropdown can't drift from the renderer
    Shared._xhStyles = { "Cross", "Plus", "T-Cross", "X", "Chevron", "Arrow",
                         "Triangle", "Diamond", "Star", "Dot", "Circle", "Square" }

    -- v0.9.0: Follow Target used to read Combat.Aim._target only, which exists solely
    -- while the aimbot is enabled AND held: so it did nothing for anyone not running
    -- one. Own search now, gated by `which`'s FOV rules. Throttled to 20Hz: it walks
    -- every player and raycasts, and the lerp smooths between picks anyway.
    local function followPart(cfg, which)
        local partName = cfg.Follow.Part or "HumanoidRootPart"
        local function partOf(plr)
            local ch = plr and plr.Character
            if not ch then return nil end
            return ch:FindFirstChild(partName)
                or ch:FindFirstChild("HumanoidRootPart")
                or ch:FindFirstChild("Head")
        end
        local combat = Shared.Combat
        if combat and which ~= "Silent" then
            local p = partOf(combat.Aim._rageLock or combat.Aim._target)
            if p then cfg._followCache = p; return p end
        end
        local now = os.clock()
        if now - (cfg._followAt or 0) >= 0.05 then
            cfg._followAt = now
            cfg._followCache = Shared.crosshairTarget
                and partOf(Shared.crosshairTarget(which)) or nil
        end
        if cfg._followCache and cfg._followCache.Parent then return cfg._followCache end
        cfg._followCache = nil
        return nil
    end

    -- fetch the viewport for follow / offset math.
    local function vp()
        local cam = Workspace.CurrentCamera
        if cam then return cam.ViewportSize end
        return Vector2.new(1280, 720)
    end

    local function drawXH(cfg, g, dt, which)
        if not cfg.Enabled then g.canvas.Visible = false; return end
        g.canvas.Visible = true

        -- base center from Origin (Center | Mouse) + user Offset. Priority chain:
        -- LockToPart > Follow Target > Origin.
        local size = vp()
        -- framerate-independent lerp: `s` = fraction of the gap left after one 60Hz
        -- frame, so 144Hz and 60Hz feel the same. Collapses to (1 - s) at 60fps.
        local function lerpF(s)
            if s <= 0 then return 1 end
            return 1 - s ^ (math.max(dt, 0.0001) * 60)
        end
        local cx, cy
        if cfg.Origin == "Mouse" then
            local m = UserInputService:GetMouseLocation()
            local tx, ty = m.X + cfg.OffsetX, m.Y + cfg.OffsetY
            local a = lerpF(math.clamp(cfg.MouseSmoothness or 0, 0, 0.98))
            local lx = cfg._mouseX or tx
            local ly = cfg._mouseY or ty
            cx = lx + (tx - lx) * a
            cy = ly + (ty - ly) * a
            cfg._mouseX, cfg._mouseY = cx, cy
        else
            cfg._mouseX, cfg._mouseY = nil, nil
            cx, cy = size.X * 0.5 + cfg.OffsetX, size.Y * 0.5 + cfg.OffsetY
        end
        local locked = false
        if cfg.LockToPart.Enabled then
            if not cfg.LockToPart._target and cfg.LockToPart.InstancePath then
                cfg.LockToPart._target = Shared.resolvePath
                    and Shared.resolvePath(cfg.LockToPart.InstancePath) or nil
            end
            local lt = cfg.LockToPart._target
            local pos
            if lt and lt:IsA("BasePart") then pos = lt.Position
            elseif lt and lt:IsA("Model") then
                local ok, cf = pcall(function() return lt:GetPivot().Position end)
                if ok then pos = cf end
            end
            if pos then
                local cam = Workspace.CurrentCamera
                if cam then
                    local sp = cam:WorldToViewportPoint(pos)
                    -- occlusion was never the problem (WorldToViewportPoint doesn't
                    -- raycast). Behind the CAMERA was: the projection is mirrored
                    -- through the origin there, so flip it back and clamp to the edge.
                    if sp.Z > 0 then
                        cx, cy = sp.X, sp.Y
                        locked = true
                    elseif cfg.LockToPart.ClampOffscreen then
                        cx, cy = size.X - sp.X, size.Y - sp.Y
                        locked = true
                    end
                    if locked and cfg.LockToPart.ClampOffscreen then
                        cx = math.clamp(cx, 2, math.max(2, size.X - 2))
                        cy = math.clamp(cy, 2, math.max(2, size.Y - 2))
                    end
                end
            end
        end
        if not locked and cfg.Follow.Enabled then
            local part = followPart(cfg, which)
            local tx, ty = cx, cy
            if part then
                local cam = Workspace.CurrentCamera
                if cam then
                    local sp = cam:WorldToViewportPoint(part.Position)
                    if sp.Z > 0 then tx, ty = sp.X, sp.Y end
                end
            end
            local a = lerpF(math.clamp(cfg.Follow.Smoothness or 0, 0, 0.98))
            local lx = cfg.Follow._screenX or cx
            local ly = cfg.Follow._screenY or cy
            lx = lx + (tx - lx) * a
            ly = ly + (ty - ly) * a
            cfg.Follow._screenX, cfg.Follow._screenY = lx, ly
            cx, cy = lx, ly
        end

        -- sqrt(2) covers the rotated diagonal; Thickness / OutlineThickness join the
        -- margin budget so a fat outlined arm at a big sweep isn't clipped.
        local reach = (cfg.Length + cfg.Gap) * 2
            + cfg.Thickness * 2 + cfg.OutlineThickness * 4 + 32
        -- even integer size + whole-pixel position keeps the canvas centre on a pixel
        local baseSize = math.floor(math.max(reach * 1.42, 24) / 2 + 0.5) * 2
        g.canvas.Size = UDim2.new(0, baseSize, 0, baseSize)
        g.canvas.Position = UDim2.new(0, math.floor(cx + 0.5), 0, math.floor(cy + 0.5))
        g.canvas.GroupTransparency = 1 - math.clamp(cfg.Opacity, 0, 1)

        local spinDeg = 0
        if cfg.Spin then
            local speed = cfg.SpinSpeed * (cfg.SpinDir == "CCW" and -1 or 1)
            cfg._spinAcc = ((cfg._spinAcc or 0) + speed * dt) % 360
            spinDeg = cfg._spinAcc
        end
        g.canvas.Rotation = (cfg.Rotation or 0) + spinDeg

        -- gradient master, shared with ESP.Config.Gradient. Canvas mode = one
        -- UIGradient over the CanvasGroup. Double-sided = per-segment colour by
        -- distance from centre, which a single linear UIGradient can't express.
        local gradOn = ESP.Config.Gradient == true
        local doubleGrad = gradOn and cfg.DoubleGradient == true
        local kg = g.canvas:FindFirstChild("KGrad")
        if kg then
            kg.Enabled = gradOn and not doubleGrad
            if kg.Enabled then
                kg.Color = lineGradSeq(ESP.Config.GradientColorA2,
                    ESP.Config.GradientColorB2, ESP.Config.GradientSpacing)
                kg.Rotation = ESP.Config.GradientRotation
                kg.Offset = gradOffset()
            end
        end
        local armGrad = nil
        if doubleGrad then
            local ga, gb = ESP.Config.GradientColorA2, ESP.Config.GradientColorB2
            local gs = math.clamp(ESP.Config.GradientSpacing or 0.5, 0.05, 0.95)
            local goff = gradOffset().X
            local span = math.max(cfg.Length + cfg.Gap, 1)
            armGrad = function(d) return segColorAt(d, span, ga, gb, gs, goff) end
        end
        local armColor = (gradOn and not doubleGrad) and Color3.new(1, 1, 1) or cfg.Color
        local dotBase = (cfg.Style == "Dot") and cfg.Color or cfg.Dot.Color
        local dotColor = (gradOn and not doubleGrad) and Color3.new(1, 1, 1)
            or (armGrad and armGrad(0) or dotBase)

        local st = STYLES[cfg.Style] or STYLES.Cross
        g.outer.Visible = st.outer == true
        g.dot.Visible = (st.dot == true) or cfg.Dot.Enabled

        local gap = st.gap0 and 0 or cfg.Gap
        local P = {
            thickness = cfg.Thickness, color = armColor,
            outline = cfg.Outline, ocol = cfg.OutlineColor, othick = cfg.OutlineThickness,
            curve = cfg.CurveAngle or 0, curvier = cfg.CurvierAngle or 0,
            smooth = math.clamp(cfg.CornerSmoothing or 0, 0, 1),
            segN = segmentsFor(cfg.Thickness, cfg.CurvierAngle or 0),
            grad = armGrad,
        }
        -- Star's two triangles are generated, not table-literal, so StarOffset can
        -- slide the second one around the ring.
        local chords = st.chords
        if cfg.Style == "Star" then
            local o = cfg.StarOffset or 60
            chords = { { 0, 120 }, { 120, 240 }, { 240, 360 },
                       { o, o + 120 }, { o + 120, o + 240 }, { o + 240, o + 360 } }
        end
        local used = 0
        if st.spokes then
            for _, deg in ipairs(st.spokes) do
                used = used + 1
                local th = math.rad(deg)
                paintArm(g.arms[used], math.sin(th) * gap, -math.cos(th) * gap,
                         th, cfg.Length, gap, P)
            end
        elseif chords then
            -- ring vertices sit at Gap + Length so the shape's size still tracks both
            local R = gap + cfg.Length
            for _, e in ipairs(chords) do
                used = used + 1
                local a1, a2 = math.rad(e[1]), math.rad(e[2])
                local x1, y1 = math.sin(a1) * R, -math.cos(a1) * R
                local x2, y2 = math.sin(a2) * R, -math.cos(a2) * R
                local dx, dy = x2 - x1, y2 - y1
                paintArm(g.arms[used], x1, y1, math.atan2(dx, -dy),
                         math.sqrt(dx * dx + dy * dy), R, P)
            end
        end
        for i = 1, ARMS do
            local on = i <= used
            g.arms[i].fill.Visible = on
            g.arms[i].out.Visible = on
        end

        if g.dot.Visible then
            local dsz = (cfg.Style == "Dot") and math.max(cfg.Length, 2) or cfg.Dot.Size
            g.dot.Size = UDim2.new(0, dsz * 2, 0, dsz * 2)
            g.dot.BackgroundColor3 = dotColor
            local ds = g.dot:FindFirstChildOfClass("UIStroke")
            if ds then
                ds.Thickness = cfg.OutlineThickness
                ds.Color = cfg.OutlineColor
                ds.Enabled = cfg.Outline and cfg.OutlineThickness > 0
            end
        end

        if g.outer.Visible then
            local d = math.max(cfg.Length * 2, 8)
            g.outer.Size = UDim2.new(0, d, 0, d)
            local uc = g.outer:FindFirstChildOfClass("UICorner")
            if uc then uc.CornerRadius = st.square and UDim.new(0, 4) or UDim.new(1, 0) end
            local os_ = g.outer:FindFirstChildOfClass("UIStroke")
            if os_ then
                os_.Thickness = math.max(cfg.Thickness, 1)
                os_.Color = armColor
                os_.Enabled = true
            end
        end
    end

    local XA, XS = mkXH("A"), mkXH("S")

    -- v0.11.2 SYNC. The buttons set Crosshair._sync; consumed here so the copy lands
    -- between frames rather than mid-render. Matches TOTAL angle (static Rotation +
    -- live spin), because two crosshairs at different Rotation offsets are not "in
    -- the same rotation" even when their spin accumulators agree.
    local function drawCrosshair(dt)
        local sync = Crosshair._sync
        if sync then
            Crosshair._sync = nil
            -- _sync names the card whose button was pressed; that card is the one
            -- that MOVES to match the other.
            local A, S = Crosshair, Crosshair.S
            local dst = (sync == "A") and A or S
            local src = (sync == "A") and S or A
            dst._spinAcc = ((src.Rotation or 0) + (src._spinAcc or 0)
                            - (dst.Rotation or 0)) % 360
        end
        drawXH(Crosshair, XA, dt, "Aim")
        if Crosshair.Double then
            drawXH(Crosshair.S, XS, dt, "Silent")
        else
            XS.canvas.Visible = false
        end
    end

    -- v0.9.0: "Pulse on Hit" removed: state, render branch, UI row and the
    -- Shared.crosshairPulse hook. The scale rode on the CanvasGroup, so it resized
    -- the same canvas Follow Target lerps across and the crosshair lurched on hits.

    -- :: hit nums ::
    -- pool: reusable TextLabels for damage numbers. Each entry:
    --   { lbl, victim, total, startAt, y0 }
    local hitCfg = ESP.Indicators.HitNumbers
    hitCfg._pool = {}
    hitCfg._layer = layer
    -- v0.9.0: resolved font + the name it was resolved from (see spawnHit).
    local hitNumFont, hitNumFontName = nil, nil

    local function acquireHitLabel()
        for _, e in ipairs(hitCfg._pool) do
            if not e._alive then e.isKill = false; return e end
        end
        local lbl = new("TextLabel", {
            AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1,
            FontFace = Theme.Fonts.Bold, TextSize = 16, TextColor3 = Color3.new(1, 1, 1),
            Text = "", TextTransparency = 1, Visible = false, ZIndex = 17,
            Size = UDim2.new(0, 120, 0, 24), Parent = layer,
        }, { new("UIStroke", { Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 1,
            LineJoinMode = Enum.LineJoinMode.Miter }) })
        local e = { lbl = lbl }
        table.insert(hitCfg._pool, e)
        return e
    end

    -- spawn a fresh number OR add to an existing merged one for the same victim.
    local function spawnHit(victim, dmg, isKill)
        -- v0.14.0: feed the Custom Features Counter block
        local c = Shared._counters
        if not c then c = { Hits = 0, Kills = 0, Deaths = 0, Shots = 0 }; Shared._counters = c end
        c.Hits = c.Hits + 1
        if isKill then c.Kills = c.Kills + 1 end
        if not hitCfg.Enabled then return end
        local now = os.clock()
        local mc = hitCfg.Preset == "Minecraft"
        local e
        if hitCfg.Stack == "Merged" and not mc then
            -- reuse the most recent live entry for this victim within Window
            for _, cand in ipairs(hitCfg._pool) do
                if cand._alive and cand.victim == victim
                   and (now - cand.startAt) <= (hitCfg.Window or 0.6) then
                    e = cand; break
                end
            end
        end
        if not e then
            e = acquireHitLabel()
            e.victim = victim
            e.total  = 0
            e.startAt = now
            e.y0     = 0
            -- v0.10.1: RESET isKill. Labels come from a pool and nothing cleared
            -- this on reuse, so the first kill of the round permanently poisoned
            -- that slot: every later hit it was recycled for rendered "KILL" on a
            -- target standing there at full health.
            e.isKill = false
            e._alive = true
            e.lbl.Visible = true
            if mc then
                local sp = hitCfg.McSpread or 1.6
                e.off = Vector3.new((math.random() - 0.5) * 2 * sp,
                                    (math.random() - 0.5) * 2 * sp,
                                    (math.random() - 0.5) * 2 * sp)
                local r = hitCfg.McRotation or 70
                e.rot = (math.random() - 0.5) * 2 * r
            else
                e.off, e.rot = nil, nil
            end
        else
            -- restart the fade so the merged number sticks around fresh
            e.startAt = now
        end
        e.total = e.total + math.floor(dmg + 0.5)
        e.isKill = e.isKill or isKill
        -- text: "-24" or "-24 KILL"
        local tag = "-" .. e.total
        if e.isKill and hitCfg.ShowKill then tag = tag .. "  KILL" end
        e.lbl.Text = tag
        e.lbl.TextSize = hitCfg.TextSize
        e.lbl.Rotation = e.rot or 0
        local col = e.isKill and hitCfg.KillColor
            or ((hitCfg.Crits and e.total >= hitCfg.CritThreshold) and hitCfg.CritColor
                or hitCfg.Color)
        e.lbl.TextColor3 = col
        -- v0.9.0: per-feature font. Resolved OFF this thread: loadFeiFont can
        -- download and this runs inside the damage handler, which must never block.
        -- Falls back to Bold for the frame or two before the face lands (usually
        -- zero, since the preloader already cached every catalog font).
        local fname = hitCfg.Font or "None"
        if mc and fname == "None" then fname = "Minecraft Regular" end
        if fname ~= hitNumFontName then
            hitNumFontName = fname
            hitNumFont = Theme.Fonts.Bold
            if fname ~= "None" and Theme.loadFeiFont then
                task.spawn(function()
                    local f = Theme.loadFeiFont(fname)
                    if f and hitNumFontName == fname then hitNumFont = f end
                end)
            end
        end
        if hitNumFont then e.lbl.FontFace = hitNumFont end
        local s = e.lbl:FindFirstChildOfClass("UIStroke")
        if s then
            s.Thickness = hitCfg.OutlineThickness
            s.Enabled = hitCfg.OutlineThickness > 0
        end
    end
    Shared.spawnHitNumber = spawnHit

    -- per-frame render for live damage numbers
    local function drawHitNumbers()
        if not hitCfg.Enabled then
            for _, e in ipairs(hitCfg._pool) do
                if e._alive then e._alive = false; e.lbl.Visible = false end
            end
            return
        end
        local now = os.clock()
        local cam = Workspace.CurrentCamera
        for _, e in ipairs(hitCfg._pool) do
            if e._alive then
                local mc = hitCfg.Preset == "Minecraft"
                local age = now - e.startAt
                local life = mc and (hitCfg.McLife or 3) or (hitCfg.HoldTime or 0.8)
                if age >= life or (e.victim and e.victim.Parent == nil) then
                    e._alive = false; e.lbl.Visible = false
                else
                    local t = age / life
                    -- Koffee fades across the whole life; Minecraft holds solid and
                    -- only fades over the last McFade seconds
                    local fade = t
                    if mc then
                        local fw = math.max(hitCfg.McFade or 1, 0.01)
                        fade = math.clamp((age - (life - fw)) / fw, 0, 1)
                    end
                    e.lbl.TextTransparency = math.clamp(fade, 0, 1)
                    local s = e.lbl:FindFirstChildOfClass("UIStroke")
                    if s then s.Transparency = math.clamp(fade, 0, 1) end
                    if cam and e.victim and e.victim.Parent then
                        local at = e.victim.Position + (e.off or Vector3.zero)
                        local sp = cam:WorldToViewportPoint(at)
                        if sp.Z > 0 then
                            local rise = mc and 0 or ((hitCfg.RiseDistance or 40) * t)
                            e.lbl.Position = UDim2.new(0, sp.X, 0, sp.Y - rise)
                            e.lbl.Visible = true
                        else
                            e.lbl.Visible = false
                        end
                    end
                end
            end
        end
    end

    RunService.RenderStepped:Connect(function(dt)
        if Koffee.dead() then return end
        drawCrosshair(dt)
        drawHitNumbers()
    end)
end)()

-- v0.6.0 WORLD RULES + INSTANCE PICKER. Own IIFE so its many locals don't touch
-- the chunk register ceiling (learned the hard way in v0.5.1). Exposes via
-- Shared: openInstancePicker, addRule, removeRule, renameRule, WorldRules.
;(function()
    local WorldRules = { List = {}, _nextId = 1 }
    registerConfig("world_rules", WorldRules)
    Shared.WorldRules = WorldRules

    -- :: path helpers ::
    -- Serialize an Instance to a "game.workspace.Folder.Part" style string so
    -- rules survive configs. Only stops at `game`; anything above is a no-op.
    local function pathOf(inst)
        if not inst then return nil end
        local parts = {}
        local n = inst
        while n and n ~= game do
            table.insert(parts, 1, n.Name)
            n = n.Parent
        end
        return "game." .. table.concat(parts, ".")
    end
    local function resolvePath(path)
        if not path or type(path) ~= "string" then return nil end
        local n = game
        local first = true
        for name in path:gmatch("[^%.]+") do
            if first and name == "game" then
                first = false
            else
                first = false
                if not n then return nil end
                local nxt = n:FindFirstChild(name)
                if not nxt then return nil end
                n = nxt
            end
        end
        return n ~= game and n or nil
    end
    Shared.pathOf = pathOf
    Shared.resolvePath = resolvePath

    -- :: filter/icons ::
    local function isPhysical(inst)
        -- v0.10.0: Tool counts. A held weapon is the single most common offset
        -- target and it was invisible to the explorer before.
        return inst:IsA("BasePart") or inst:IsA("Model") or inst:IsA("UnionOperation")
            or inst:IsA("MeshPart") or inst:IsA("NegateOperation")
            or inst:IsA("IntersectOperation") or inst:IsA("Tool")
    end
    local function containsPhysical(inst)
        -- Cap depth so expansion cost stays bounded on big trees. 6 is enough
        -- for typical roblox game layouts (workspace.folder.folder.model.part).
        local function scan(node, depth)
            if depth <= 0 then return false end
            for _, d in ipairs(node:GetChildren()) do
                if isPhysical(d) then return true end
                if d:IsA("ScriptBase") or d:IsA("ModuleScript")
                   or d:IsA("ValueBase") then
                    -- skip: scripts + values never hold physicals we care about
                else
                    if scan(d, depth - 1) then return true end
                end
            end
            return false
        end
        return scan(inst, 6)
    end
    local function iconColor(inst)
        if inst:IsA("MeshPart")       then return Color3.fromRGB(160, 130, 220) end  -- purple
        if inst:IsA("UnionOperation") or inst:IsA("NegateOperation")
           or inst:IsA("IntersectOperation") then return Color3.fromRGB(240, 160, 90) end -- orange
        if inst:IsA("BasePart")       then return Color3.fromRGB(140, 210, 150) end  -- green
        if inst:IsA("Model")          then return Color3.fromRGB(130, 200, 240) end  -- cyan
        return Color3.fromRGB(235, 200, 120) -- yellow: folder/service
    end
    local function isSelectableAsTarget(inst)
        return inst:IsA("BasePart") or inst:IsA("Model") or inst:IsA("MeshPart")
            or inst:IsA("UnionOperation") or inst:IsA("NegateOperation")
            or inst:IsA("IntersectOperation") or inst:IsA("Tool")
    end
    local function shouldShow(inst)
        -- Physical always. Anything else only if it holds a physical descendant.
        -- Cheap descent through any container class: Player/Backpack/PlayerScripts
        -- included so LocalPlayer.Character surfaces under Players.
        if isPhysical(inst) then return true end
        if #inst:GetChildren() == 0 then return false end
        return containsPhysical(inst)
    end

    -- :: modal helper (dim) ::
    -- Center a modal on popupScreen with a scale-in animation. Returns
    -- { root, dim, box, close } where `close` fades everything out + destroys.
    local function openModal(width, height)
        local dim = new("Frame", {
            Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0,
            ZIndex = 200, Parent = popupScreen,
        })
        -- v0.10.0: a Frame doesn't absorb input, so clicks landed on the window
        -- behind the modal: you could drive the UI underneath a dialog. A
        -- full-bleed transparent button under the box eats everything that misses.
        new("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 1, 0), ZIndex = 200, Parent = dim,
        })
        tween(dim, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            { BackgroundTransparency = 0.5 })
        local box = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            Size = UDim2.new(0, width, 0, height),
            BackgroundColor3 = Theme.Palette.Panel, BorderSizePixel = 0,
            -- v0.9.0: modal contents stay inside the modal. Frames don't clip by
            -- default, so any over-wide label silently drew past the popup edge.
            ClipsDescendants = true,
            ZIndex = 201, Parent = dim,
        }, { corner(Theme.Radius.Medium), stroke(Theme.Palette.BorderSubtle) })
        local uscale = new("UIScale", { Scale = 0.94, Parent = box })
        -- v0.48.0: modal open honours Popups; off shows at rest instantly.
        -- (The dim fade above already snaps itself when the master is off.)
        if Koffee.Anim.spot("AnimPopups") then
            tween(uscale, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                { Scale = 1 })
        else
            uscale.Scale = 1
        end
        local function close()
            -- v0.48.0: master off destroys now instead of fading out first.
            if not Koffee.Anim.spot("AnimPopups") then
                if dim then dim:Destroy() end
                return
            end
            tween(dim, TweenInfo.new(0.16), { BackgroundTransparency = 1 })
            tween(uscale, TweenInfo.new(0.16), { Scale = 0.94 })
            task.delay(Koffee.Anim.wait(0.18), function() if dim then dim:Destroy() end end)
        end
        return { dim = dim, box = box, close = close }
    end

    -- :: instance picker ::
    -- Modal explorer. Roots list = common containers people target. Lazy
    -- expansion; filtered to physical instances + containers with physical
    -- descendants. Color-coded 8px square icon next to each row.
    local function openInstancePicker(onSelect, opts)
        opts = opts or {}
        -- v0.31.0: anyInstance mode shows and lets you pick NON-physical instances
        -- (RemoteEvent / RemoteFunction / Values) for the Custom Features game blocks.
        local anyInst = opts.anyInstance == true
        local function showP(inst) return anyInst or shouldShow(inst) end
        local function pickP(inst) return anyInst or isSelectableAsTarget(inst) end
        local m = openModal(520, 460)
        -- header
        new("TextLabel", {
            Text = opts.title or "Select an Instance", FontFace = Theme.Fonts.Bold,
            TextSize = Theme.Text.Header, TextColor3 = Theme.Palette.Text,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.new(0, 16, 0, 12), Size = UDim2.new(1, -32, 0, 18),
            ZIndex = 202, Parent = m.box,
        })
        new("TextLabel", {
            Text = opts.subtitle or "Expand a container, click a physical instance, and click submit.",
            FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.new(0, 16, 0, 34), Size = UDim2.new(1, -32, 0, 14),
            ZIndex = 202, Parent = m.box,
        })
        -- scroll body
        local scroll = new("ScrollingFrame", {
            Position = UDim2.new(0, 12, 0, 56), Size = UDim2.new(1, -24, 1, -104),
            BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.35,
            BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.Palette.TextFaint,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ZIndex = 202, Parent = m.box,
        }, { corner(6), new("UIListLayout", { Padding = UDim.new(0, 2),
            SortOrder = Enum.SortOrder.LayoutOrder }) })

        local selected = nil     -- current selected Instance
        local selectedRow = nil  -- current selected row Frame
        -- v0.9.0: Instance -> { expand, pick, wrapper } for every row built so far.
        -- Click Part needs to walk down to an arbitrary instance and open the tree
        -- on the way; `force` lets that walk surface a node shouldShow would filter.
        local nodes, force = {}, {}
        local ROOTS = {
            game:GetService("Workspace"),
            game:GetService("Players"),
            game:GetService("ReplicatedStorage"),
            game:GetService("StarterPack"),
            game:GetService("StarterGui"),
            game:GetService("StarterPlayer"),
            game:GetService("Lighting"),
        }

        local buildRow -- forward-decl
        local function pickRow(row, inst)
            -- v0.9.0: the previous row may have been destroyed by a collapse.
            if selectedRow and selectedRow.Parent then
                selectedRow.BackgroundColor3 = Theme.Palette.PanelElevated
                selectedRow.BackgroundTransparency = 1
            end
            selectedRow = row
            selected = inst
            row.BackgroundTransparency = 0.15
            row.BackgroundColor3 = Theme.Palette.Accent
        end

        -- v0.9.0 TREE RESTRUCTURE. Each entry is now a WRAPPER holding its own row
        -- plus its own children container, instead of the row and the children being
        -- flat siblings ordered by LayoutOrder. The old shape was the "expanding a
        -- folder drops its contents at the bottom of the list" bug: no row was ever
        -- assigned a LayoutOrder, so every sibling sat at 0 while the child container
        -- was created at 0 + 1: which sorted it after every row in the list rather
        -- than under its own parent. Nesting makes the ordering structural: children
        -- physically live inside the parent entry, so they cannot land anywhere else.
        buildRow = function(inst, depth, parentContainer)
            -- v0.31.0: in anyInstance mode any node with children can expand (remotes
            -- often nest under plain non-Folder containers).
            local expandable = (anyInst and #inst:GetChildren() > 0)
                or ((inst:IsA("Folder") or inst:IsA("Configuration") or inst:IsA("Model")
                or inst:IsA("Tool") or inst:IsA("Backpack")
                or inst == game:GetService("Workspace")
                or inst:IsA("ServiceProvider") or inst.ClassName:find("Service", 1, true))
                and #inst:GetChildren() > 0)
            local wrapper = new("Frame", {
                Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1, BorderSizePixel = 0,
                ZIndex = 203, Parent = parentContainer,
            }, { new("UIListLayout", { Padding = UDim.new(0, 2),
                SortOrder = Enum.SortOrder.LayoutOrder }) })
            local row = new("Frame", {
                Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 1,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 1,
                BorderSizePixel = 0, ZIndex = 203, Parent = wrapper,
            }, { corner(4) })
            local x = depth * 14
            local btn = new("TextButton", {
                Text = "", BackgroundTransparency = 1, AutoButtonColor = false,
                Size = UDim2.new(1, 0, 1, 0), ZIndex = 204, Parent = row,
            })
            -- depth guide: a hairline at each ancestor level so deep trees stay
            -- readable instead of being a wall of indented text.
            for d = 1, depth do
                new("Frame", {
                    Position = UDim2.new(0, (d - 1) * 14 + 7, 0, 0),
                    Size = UDim2.new(0, 1, 1, 0),
                    BackgroundColor3 = Theme.Palette.BorderSubtle, BackgroundTransparency = 0.55,
                    BorderSizePixel = 0, ZIndex = 204, Parent = row,
                })
            end
            local isOpen = false
            local caretImg = nil
            if expandable then
                caretImg = Koffee.lucideIcon(row, "chevron-right", 12, Theme.Palette.TextMuted, 205)
                caretImg.Position = UDim2.new(0, x + 2, 0.5, 0)
            end
            local function setCaret(open)
                if not caretImg then return end
                local d = open and Koffee.LUCIDE["chevron-down"] or Koffee.LUCIDE["chevron-right"]
                caretImg.Image = "rbxassetid://" .. d[1]
                caretImg.ImageRectOffset = Vector2.new(d[2], d[3])
            end
            local clsIcon = (inst:IsA("Folder") or inst:IsA("Configuration")) and "folder"
                or (inst:IsA("BasePart") and "box")
                or (inst:IsA("LuaSourceContainer") and "file") or nil
            if clsIcon then
                local ci = Koffee.lucideIcon(row, clsIcon, 12, Theme.Palette.TextMuted, 205)
                if ci then ci.Position = UDim2.new(0, x + 16, 0.5, 0) end
            else
                new("Frame", {
                    Position = UDim2.new(0, x + 18, 0.5, -4), Size = UDim2.new(0, 8, 0, 8),
                    BackgroundColor3 = iconColor(inst), BorderSizePixel = 0,
                    ZIndex = 205, Parent = row,
                }, { corner(2) })
            end
            new("TextLabel", {
                Text = inst.Name, FontFace = Theme.Fonts.Medium,
                TextSize = Theme.Text.Body, TextColor3 = Theme.Palette.Text,
                BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                Position = UDim2.new(0, x + 32, 0, 0), Size = UDim2.new(1, -x - 108, 1, 0),
                TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 205, Parent = row,
            })
            -- class as a quiet pill on the right rather than loose text
            new("TextLabel", {
                Text = inst.ClassName, FontFace = Theme.Fonts.Mono,
                TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextFaint,
                BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.55,
                BorderSizePixel = 0, TextTruncate = Enum.TextTruncate.AtEnd,
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -6, 0.5, 0), Size = UDim2.new(0, 68, 0, 15),
                ZIndex = 205, Parent = row,
            }, { corner(3) })

            local kidsBox            -- lazy
            local builtKids = {}     -- what this node put into `nodes`
            local collapse           -- fwd-decl (nodes[inst].dispose recurses through it)
            local function expand()
                if kidsBox then return end
                isOpen = true
                setCaret(true)
                kidsBox = new("Frame", {
                    Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1, LayoutOrder = 2,
                    ZIndex = 203, Parent = wrapper,
                }, { new("UIListLayout", { Padding = UDim.new(0, 2),
                    SortOrder = Enum.SortOrder.LayoutOrder }) })
                local kids = {}
                for _, c in ipairs(inst:GetChildren()) do
                    if showP(c) or force[c] then table.insert(kids, c) end
                end
                table.sort(kids, function(a, b) return a.Name:lower() < b.Name:lower() end)
                for _, c in ipairs(kids) do
                    buildRow(c, depth + 1, kidsBox)
                    table.insert(builtKids, c)
                end
            end
            -- collapse tears the subtree out of `nodes` as well as out of the tree:
            -- otherwise a later Click Part reveal would expand() through a record
            -- whose Frames were already destroyed and build orphans.
            collapse = function()
                isOpen = false
                setCaret(false)
                for _, c in ipairs(builtKids) do
                    local n = nodes[c]
                    if n then n.dispose() end
                    nodes[c] = nil
                end
                builtKids = {}
                if kidsBox then kidsBox:Destroy(); kidsBox = nil end
            end

            btn.MouseEnter:Connect(function()
                if selectedRow ~= row then row.BackgroundTransparency = 0.75 end
            end)
            btn.MouseLeave:Connect(function()
                if selectedRow ~= row then row.BackgroundTransparency = 1 end
            end)
            btn.MouseButton1Click:Connect(function()
                if expandable then
                    if isOpen then collapse() else expand() end
                end
                if pickP(inst) then pickRow(row, inst) end
            end)

            nodes[inst] = {
                expand = expand, wrapper = wrapper, dispose = collapse,
                pick = function() if pickP(inst) then pickRow(row, inst) end end,
            }
        end

        for _, r in ipairs(ROOTS) do buildRow(r, 0, scroll) end

        -- v0.9.0: open the tree down to `target` and select it. Ancestors are marked
        -- `force` first so the shouldShow filter can't hide a link in the chain.
        local function revealInstance(target)
            if not target then return false end
            local chain, cur = {}, target
            while cur and not nodes[cur] do
                table.insert(chain, 1, cur)
                force[cur] = true
                cur = cur.Parent
            end
            if not cur then return false end          -- not under any listed root
            local node = nodes[cur]
            for _, step in ipairs(chain) do
                if not node then return false end
                node.expand()
                node = nodes[step]
            end
            if not node then return false end
            node.pick()
            -- scroll the revealed row into view
            task.defer(function()
                if not node.wrapper.Parent then return end
                local dy = node.wrapper.AbsolutePosition.Y - scroll.AbsolutePosition.Y
                scroll.CanvasPosition = Vector2.new(0,
                    math.max(0, scroll.CanvasPosition.Y + dy - 60))
            end)
            return true
        end

        -- footer buttons
        -- v0.9.0 CLICK PART. Hides the whole suite, raycasts through the cursor so
        -- you can point at the thing in-game, then restores and reveals whatever you
        -- clicked in this same tree. A raycast (not Mouse.Target) because the click
        -- sink below is a GUI element, and Mouse.Target goes nil under GUI.
        local clickPart = new("TextButton", {
            Text = "Click Part", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.Text,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.15,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 14, 1, -14),
            Size = UDim2.new(0, 96, 0, 28), ZIndex = 202, Parent = m.box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        clickPart.MouseButton1Click:Connect(function()
            local cam = Workspace.CurrentCamera
            if not cam then return end
            screen.Enabled = false
            popupScreen.Enabled = false
            -- v0.10.0: hiding the ScreenGuis doesn't touch the BlurEffect or the
            -- dim: they live on the camera and on `screen` respectively, driven by
            -- the window-open state. Picking a part through a blurred, dimmed world
            -- is useless, so drop the whole background treatment for the duration.
            setBackgroundActive(false)
            local hud = KID.track(new("ScreenGui", {
                Name = KID.name("worldpick"), ResetOnSpawn = false, IgnoreGuiInset = true,
                ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
                DisplayOrder = popupScreen.DisplayOrder + 1, Parent = guiParent(),
            }))
            protectGuiSafe(hud)
            -- v0.10.0: NO full-screen sink button. A GuiButton covering the screen
            -- swallows right-click too, which kills the camera drag: you could not
            -- turn around to find the thing you wanted to click. ContextActionService
            -- sinks MouseButton1 ONLY, at high priority, so the selecting click never
            -- reaches the game while RMB camera control stays completely untouched.
            local hint = new("TextLabel", {
                Text = "Left click to select. Right click drag to look. Esc to cancel.",
                FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.Text, TextTruncate = Enum.TextTruncate.AtEnd,
                BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.15,
                BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0), ClipsDescendants = true,
                Position = UDim2.new(0.5, 0, 0, 24), Size = UDim2.new(0, 520, 0, 30),
                ZIndex = 2, Parent = hud,
            }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
            local hl = Instance.new("Highlight")
            hl.Name = KID.name("pickhl")
            hl.FillColor = Theme.Palette.Accent
            hl.OutlineColor = Theme.Palette.Accent
            hl.FillTransparency = 0.75
            pcall(function() hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop end)
            hl.Parent = cam
            local conns = {}
            local hover = nil
            local CAS = game:GetService("ContextActionService")
            local ACT = KID.name("pickact")
            local function finish(inst)
                for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
                pcall(function() CAS:UnbindAction(ACT) end)
                hl:Destroy(); hud:Destroy()
                screen.Enabled = true
                popupScreen.Enabled = true
                setBackgroundActive(true)
                if inst then revealInstance(inst) end
            end
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            -- v0.10.0: exclude our own camera-parented FX hosts too, or a snow slab
            -- floating over your head is the first thing every ray hits.
            local baseIgnore = { cam }
            for _, c in ipairs(cam:GetChildren()) do
                if c:IsA("BasePart") then table.insert(baseIgnore, c) end
            end
            rp.FilterDescendantsInstances = baseIgnore
            -- v0.12.2: your own character is pickable now. Excluding it wholesale
            -- also excluded any equipped Tool (tools parent under the character), so
            -- your own weapon could never be selected. First person still sits the
            -- camera inside your head, so only YOUR parts hugging the lens are
            -- skipped and the ray carries on past them.
            local function pickRay(origin, dir)
                rp.FilterDescendantsInstances = baseIgnore
                local myChar = LocalPlayer.Character
                for _ = 1, 6 do
                    local hit = Workspace:Raycast(origin, dir, rp)
                    if not hit then return nil end
                    if not (myChar and hit.Distance < 1.2
                            and hit.Instance:IsDescendantOf(myChar)) then
                        return hit
                    end
                    local list = rp.FilterDescendantsInstances
                    table.insert(list, hit.Instance)
                    rp.FilterDescendantsInstances = list
                end
                return nil
            end
            conns[#conns + 1] = RunService.RenderStepped:Connect(function()
                local mp = UserInputService:GetMouseLocation()
                local ray = cam:ViewportPointToRay(mp.X, mp.Y)
                local hit = pickRay(ray.Origin, ray.Direction * 5000)
                hover = hit and hit.Instance or nil
                -- v0.12.3: no modifier. Tool handles and viewmodel parts are routinely
                -- CanQuery=false, so no raycast can ever reach them. Your own parts get
                -- a screen-space pass instead, and win only when they're both near the
                -- cursor AND in front of whatever the ray found: so pointing past
                -- yourself at the world still resolves to the world.
                local myChar = LocalPlayer.Character
                if myChar and not (hover and hover:IsDescendantOf(myChar)) then
                    local best, bestD = nil, 34
                    local limit = hit and hit.Distance or math.huge
                    local eye = cam.CFrame.Position
                    for _, d in ipairs(myChar:GetDescendants()) do
                        if d:IsA("BasePart") and (d.Position - eye).Magnitude < limit then
                            local sp, on = cam:WorldToViewportPoint(d.Position)
                            if on and sp.Z > 0 then
                                local dd = (Vector2.new(sp.X, sp.Y) - mp).Magnitude
                                if dd < bestD then best, bestD = d, dd end
                            end
                        end
                    end
                    hover = best or hover
                end
                -- v0.10.0: adorn (and select) the TOOL when the part belongs to one,
                -- then the Model, then the bare part. Clicking a held weapon should
                -- offset the weapon, not the single mesh you happened to hit.
                local adorn = nil
                if hover then
                    local tool = hover:FindFirstAncestorOfClass("Tool")
                    -- Highlight only adorns Models and BaseParts, so a Tool shows
                    -- through its Handle rather than losing the hover feedback.
                    adorn = (tool and (tool:FindFirstChild("Handle") or hover))
                        or hover:FindFirstAncestorOfClass("Model") or hover
                end
                hl.Adornee = adorn
                hint.Text = hover and (hover:GetFullName())
                    or "left click to select   right click drag to look   esc to cancel"
            end)
            conns[#conns + 1] = UserInputService.InputBegan:Connect(function(input)
                if input.KeyCode == Enum.KeyCode.Escape then finish(nil) end
            end)
            CAS:BindActionAtPriority(ACT, function(_, state)
                if state == Enum.UserInputState.Begin then
                    local pick = hover
                    if pick then
                        pick = pick:FindFirstAncestorOfClass("Tool") or pick
                    end
                    finish(pick)
                end
                return Enum.ContextActionResult.Sink
            end, false, Enum.ContextActionPriority.High.Value + 1000,
                Enum.UserInputType.MouseButton1)
        end)

        local cancel = new("TextButton", {
            Text = "Cancel", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.15,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -108, 1, -14),
            Size = UDim2.new(0, 88, 0, 28), ZIndex = 202, Parent = m.box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        local submit = new("TextButton", {
            Text = "Submit", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.Text,
            BackgroundColor3 = Theme.Palette.Accent, BackgroundTransparency = 0.15,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -14, 1, -14),
            Size = UDim2.new(0, 88, 0, 28), ZIndex = 202, Parent = m.box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        cancel.MouseButton1Click:Connect(function() m.close() end)
        submit.MouseButton1Click:Connect(function()
            if selected then onSelect(selected, pathOf(selected)) end
            m.close()
        end)
    end
    Shared.openModal = openModal
