    local hitCfgUI = ESP.Indicators.HitNumbers
    local hitRow = configCheckbox(indPanel, "Hit Numbers", hitCfgUI.Enabled, function(v) hitCfgUI.Enabled = v end)
    attachSingleSwatch(hitRow.row, hitCfgUI.Color, function(c) hitCfgUI.Color = c end)
    rightClickSettings(hitRow.row, "Hit Numbers", function(popup)
        popup:dropdown("Preset", { "Koffee", "Minecraft" }, hitCfgUI.Preset,
            function(v) hitCfgUI.Preset = v end)
        popup:slider("MC Scatter", 0, 6, hitCfgUI.McSpread, 2, function(v) hitCfgUI.McSpread = v end)
        popup:slider("MC Max Tilt", 0, 180, hitCfgUI.McRotation, 0, function(v) hitCfgUI.McRotation = v end)
        popup:slider("MC Life (s)", 0.2, 10, hitCfgUI.McLife, 2, function(v) hitCfgUI.McLife = v end)
        popup:slider("MC Fade (s)", 0.05, 5, hitCfgUI.McFade, 2, function(v) hitCfgUI.McFade = v end)
        popup:dropdown("Stack Mode", { "Merged", "Literal" }, hitCfgUI.Stack, function(v) hitCfgUI.Stack = v end)
        popup:slider("Merge Window (s)", 0.1, 3, hitCfgUI.Window, 2, function(v) hitCfgUI.Window = v end)
        popup:slider("Rise Distance", 0, 200, hitCfgUI.RiseDistance, 0, function(v) hitCfgUI.RiseDistance = v end)
        popup:slider("Hold Time (s)", 0.1, 3, hitCfgUI.HoldTime, 2, function(v) hitCfgUI.HoldTime = v end)
        popup:slider("Text Size", 8, 40, hitCfgUI.TextSize, 0, function(v) hitCfgUI.TextSize = v end)
        popup:slider("Outline", 0, 6, hitCfgUI.OutlineThickness, 0, function(v) hitCfgUI.OutlineThickness = v end)
        -- v0.9.0: same catalog every other font dropdown uses.
        popup:dropdown("Font", Theme.FontNames, hitCfgUI.Font, function(v) hitCfgUI.Font = v end)
        -- v0.9.0: crits are a toggle, not an always-on threshold.
        popup:toggle("Crits", hitCfgUI.Crits, function(v) hitCfgUI.Crits = v end)
        popup:slider("Crit Threshold", 1, 500, hitCfgUI.CritThreshold, 0, function(v) hitCfgUI.CritThreshold = v end)
        popup:swatch("Crit Color", hitCfgUI.CritColor, function(c) hitCfgUI.CritColor = c end)
        popup:toggle("Show KILL", hitCfgUI.ShowKill, function(v) hitCfgUI.ShowKill = v end)
        popup:swatch("Kill Color", hitCfgUI.KillColor, function(c) hitCfgUI.KillColor = c end)
    end)

    -- v0.90.0 off-screen arrows
    local oaCfg = ESP.Indicators.OffscreenArrows
    local oaRow = configCheckbox(indPanel, "Off-Screen Arrows", oaCfg.Enabled, function(v) oaCfg.Enabled = v end)
    attachSingleSwatch(oaRow.row, oaCfg.Color, function(c) oaCfg.Color = c end)
    rightClickSettings(oaRow.row, "Off-Screen Arrows", function(popup)
        popup:slider("Size", 8, 48, oaCfg.Size, 0, function(v) oaCfg.Size = v end)
        popup:slider("Radius", 50, 450, oaCfg.Radius, 0, function(v) oaCfg.Radius = v end)
        popup:toggle("Use ESP Colour", oaCfg.UseEspColor ~= false, function(v) oaCfg.UseEspColor = v end)
        popup:toggle("Show Distance", oaCfg.Distance == true, function(v) oaCfg.Distance = v end)
        popup:toggle("Pulse", oaCfg.Pulse ~= false, function(v) oaCfg.Pulse = v end)
    end)

    -- :: Health ::
    local healthPanel = panel(rightCol, "Health")
    local hbRow = configCheckbox(healthPanel, "Health Bar", ESP.Health.Bar.Enabled, function(v) ESP.Health.Bar.Enabled = v end)
    attachSingleSwatch(hbRow.row, ESP.Health.Bar.Color, function(c) ESP.Health.Bar.Color = c end)
    configCheckbox(healthPanel, "Health Based", ESP.Health.Based, function(v) ESP.Health.Based = v end)
    configCheckbox(healthPanel, "Health Text", ESP.Health.Text, function(v) ESP.Health.Text = v end)
    dropdown(healthPanel, "Text Pos", { "Above Name", "On Health Bar" }, ESP.Health.TextPos, function(v) ESP.Health.TextPos = v end)

    -- :: Tracer ::
    local tracerPanel = panel(rightCol, "Tracers")
    local trRow = configCheckbox(tracerPanel, "Enabled", ESP.Tracer.Enabled, function(v) ESP.Tracer.Enabled = v end)
    attachSingleSwatch(trRow.row, ESP.Tracer.Color, function(c) ESP.Tracer.Color = c end)
    dropdown(tracerPanel, "Origin", { "Mouse", "Bottom", "Middle", "Top" }, ESP.Tracer.Origin, function(v) ESP.Tracer.Origin = v end)
    dropdown(tracerPanel, "Location", { "Below", "Middle", "Above" }, ESP.Tracer.Location, function(v) ESP.Tracer.Location = v end)

    -- :: Bullet Tracers ::
    -- v0.17.0. Separate from the ESP tracer above: that one is a snap-line to a
    -- player, this one draws where somebody's shot actually went. The panel title
    -- carries the detector state (scanning / watching n / locked on <remote>) so a
    -- game whose shots we can't read is obvious instead of silent.
    -- :: Chams :: v0.88.0. Colours, team check, friends and distance follow the ESP
    -- settings (the NPC ESP bundle for NPCs) unless Custom Colors is on.
    ;(function()
        local CH = Koffee.Chams
        local cp = panel(rightCol, "Chams")
        local row = moduleCheckbox(cp, "Enabled", "chams")
        keybindPill(row.row, "chams", nil, "Chams")
        dropdown(cp, "Style", { "Pattern", "Lit", "Wireframe" }, CH.Style, function(v) CH.Style = v end)
        dropdown(cp, "Pattern", { "Hex", "Stripes", "Dots", "Circuit" }, CH.Pattern, function(v) CH.Pattern = v end)
        slider(cp, "Scroll Speed", 0, 4, CH.Scroll, 2, function(v) CH.Scroll = v end)
        slider(cp, "Transparency", 0, 0.95, CH.Alpha, 2, function(v) CH.Alpha = v end)
        configCheckbox(cp, "Split By Visibility", CH.Split, function(v) CH.Split = v end)
        dropdown(cp, "Behind Walls Style", { "Pattern", "Lit", "Wireframe" }, CH.HiddenStyle,
            function(v) CH.HiddenStyle = v end)
        configCheckbox(cp, "Wire Glow", CH.Glow, function(v) CH.Glow = v end)
        configCheckbox(cp, "Include NPCs", CH.NPCs, function(v) CH.NPCs = v end)
        local cc = configCheckbox(cp, "Custom Colors", CH.CustomColors, function(v) CH.CustomColors = v end)
        attachDualSwatch(cc.row, CH.Color, CH.Color2, function(c) CH.Color = c end, function(c) CH.Color2 = c end)
    end)()

    local btPanel = panel(rightCol, "Bullet Tracers")
    local btTitle = btPanel:FindFirstChildOfClass("TextLabel")
    Shared._bulletSetStatus = function(s)
        if btTitle and btTitle.Parent then
            btTitle.Text = (s and s ~= "") and ("Bullet Tracers  " .. s) or "Bullet Tracers"
        end
    end
    Shared._bulletSetStatus(Shared._bulletStatus or "")
    local btRow = configCheckbox(btPanel, "Enabled", Koffee.Bullets.Enabled,
        function(v) Koffee.Bullets.Enabled = v end)
    attachSingleSwatch(btRow.row, Koffee.Bullets.Color, function(c) Koffee.Bullets.Color = c end)
    rightClickSettings(btRow.row, "Bullet Tracers", function(popup)
        popup:toggle("Team Check", Koffee.Bullets.TeamCheck, function(v) Koffee.Bullets.TeamCheck = v end)
        popup:toggle("Show Own Shots", Koffee.Bullets.ShowOwn, function(v) Koffee.Bullets.ShowOwn = v end)
        popup:toggle("Shooter Team Color", Koffee.Bullets.TeamColor, function(v) Koffee.Bullets.TeamColor = v end)
        popup:toggle("Fade Out", Koffee.Bullets.Fade, function(v) Koffee.Bullets.Fade = v end)
        popup:toggle("Impact Dot", Koffee.Bullets.Impact, function(v) Koffee.Bullets.Impact = v end)
        -- some games hop the shot through a BindableEvent so a LocalScript draws it.
        -- Off by default: it roughly doubles the connection count for a rarer case.
        popup:toggle("Watch Bindables", Koffee.Bullets.Bindables, function(v)
            Koffee.Bullets.Bindables = v
            if Shared._bulletRelearn then Shared._bulletRelearn() end
        end)
        popup:slider("Max On Screen", 1, 64, Koffee.Bullets.MaxLive, 0, function(v) Koffee.Bullets.MaxLive = v end)
        popup:action("Relearn Source", function()
            if Shared._bulletRelearn then Shared._bulletRelearn() end
        end)
        -- v0.19.1: learning pins the first remote that looks like a gun, and a
        -- movement or aim-sync remote can look exactly like one. Blacklisting kicks
        -- that pin out permanently and relearns so the next candidate gets a go.
        -- v0.19.3: one button per pin, because inbound and outbound pin separately.
        local pins = (Shared._bulletPins and Shared._bulletPins()) or {}
        if #pins == 0 then
            new("TextLabel", {
                Text = "Nothing Locked Yet", FontFace = Theme.Fonts.Medium,
                TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
                BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 16),
                TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 212,
                Parent = popup.frame,
            })
        end
        for _, pin in ipairs(pins) do
            local key = pin.key
            local label = (pin.tag == "both") and ("Blacklist " .. pin.short)
                or ("Blacklist " .. pin.tag .. ": " .. pin.short)
            popup:action(label, function()
                if Shared._bulletBlacklistKey then Shared._bulletBlacklistKey(key) end
            end)
        end
        -- this popup is dynamic (see the last arg), so the list below is rebuilt
        -- every time it opens rather than frozen at first build
        local bl = (Shared._bulletBlNames and Shared._bulletBlNames()) or {}
        if #bl > 0 then
            -- full names are far wider than the popup, so show the tail and map back
            local shorts, byShort = {}, {}
            for i, full in ipairs(bl) do
                local short = full:match("([^%.]+%.[^%.]+)$") or full
                if byShort[short] then short = short .. " #" .. i end
                shorts[#shorts + 1] = short
                byShort[short] = full
            end
            local pick = shorts[1]
            popup:dropdown("Blacklisted", shorts, pick, function(v) pick = v end)
            popup:action("Un-blacklist", function()
                if Shared._bulletUnBlacklist and byShort[pick] then
                    Shared._bulletUnBlacklist(byShort[pick])
                end
            end)
        end
    end, false, true)
    -- v0.19.0: Through Walls off costs five rays a tracer, cached at ~15Hz, so the
    -- line is cut where geometry hides it instead of painting over the wall.
    local btWallRow = configCheckbox(btPanel, "Through Walls", Koffee.Bullets.ThroughWalls,
        function(v) Koffee.Bullets.ThroughWalls = v end)
    rightClickSettings(btWallRow.row, "Shape", function(popup)
        popup:toggle("Taper", Koffee.Bullets.Taper, function(v) Koffee.Bullets.Taper = v end)
        popup:toggle("Gradient", Koffee.Bullets.Gradient, function(v) Koffee.Bullets.Gradient = v end)
        popup:toggle("Origin Dot", Koffee.Bullets.OriginDot, function(v) Koffee.Bullets.OriginDot = v end)
        popup:toggle("Impact Dot", Koffee.Bullets.Impact, function(v) Koffee.Bullets.Impact = v end)
        popup:slider("Dot Size", 2, 20, Koffee.Bullets.ImpactSize, 0, function(v) Koffee.Bullets.ImpactSize = v end)
    end)
    local btStyleDd = dropdown(btPanel, "Style", { "Instant", "Travel", "Grow", "Retract" },
        Koffee.Bullets.Style, function(v) Koffee.Bullets.Style = v end)
    rightClickSettings(btStyleDd.frame, "Style", function(popup)
        popup:toggle("Fade Out", Koffee.Bullets.Fade, function(v) Koffee.Bullets.Fade = v end)
        -- Travel only: how much of the shot the moving dash covers
        popup:slider("Dash Length", 0.02, 1, Koffee.Bullets.TravelLen, 2, function(v) Koffee.Bullets.TravelLen = v end)
    end)
    dropdown(btPanel, "Colour Mode", { "Static", "Shooter Team", "Distance", "Random Per Shot" },
        Koffee.Bullets.ColorMode, function(v) Koffee.Bullets.ColorMode = v end)
    local btOutRow = configCheckbox(btPanel, "Outline", Koffee.Bullets.Outline,
        function(v) Koffee.Bullets.Outline = v end)
    attachSingleSwatch(btOutRow.row, Koffee.Bullets.OutlineColor, function(c) Koffee.Bullets.OutlineColor = c end)
    rightClickSettings(btOutRow.row, "Outline", function(popup)
        popup:slider("Thickness", 0.5, 6, Koffee.Bullets.OutlineThickness, 2,
            function(v) Koffee.Bullets.OutlineThickness = v end)
    end)
    slider(btPanel, "Thickness", 1, 10, Koffee.Bullets.Thickness, 1, function(v) Koffee.Bullets.Thickness = v end)
    slider(btPanel, "Duration", 0.1, 3, Koffee.Bullets.Duration, 2, function(v) Koffee.Bullets.Duration = v end)
    slider(btPanel, "Max Distance", 1, 6000, Koffee.Bullets.MaxDistance, 0, function(v) Koffee.Bullets.MaxDistance = v end)

    -- :: Crosshair ::
    -- v0.11.2: one builder used twice. "Double Crosshairs" (card A only) retitles A
    -- to "Crosshair (A)" and reveals card S. A follows the AIMBOT's FOV rules, S
    -- follows Silent Aim's: and with that FOV switched off there is no radius gate
    -- at all. Each card ends in a Sync button that moves THAT card's rotation to
    -- match the other, for when spin has drifted them apart.
    local xhCardS
    local function buildXH(parent, cfg, title, tag)
        local card = panel(parent, title)
        local titleLbl = card:FindFirstChildOfClass("TextLabel")

        local enRow = configCheckbox(card, "Enabled", cfg.Enabled, function(v) cfg.Enabled = v end)
        attachSingleSwatch(enRow.row, cfg.Color, function(c) cfg.Color = c end)

        if tag == "A" then
            configCheckbox(card, "Double Crosshairs", Crosshair.Double, function(v)
                Crosshair.Double = v
                if titleLbl then titleLbl.Text = v and "Crosshair (A)" or "Crosshair" end
                if xhCardS then xhCardS.Visible = v end
            end)
        end

        local styleDd = dropdown(card, "Style", Shared._xhStyles, cfg.Style,
            function(v) cfg.Style = v end)
        rightClickSettings(styleDd.frame, "Style", function(popup)
            -- tilts each arm SEGMENT about its own centre, leaving the arm's heading
            -- alone: v0.8 folded it into the heading, which was just Rotation again.
            popup:slider("Curve Angle", -180, 180, cfg.CurveAngle, 0, function(v) cfg.CurveAngle = v end)
            popup:slider("Curvier Angle", -360, 360, cfg.CurvierAngle, 0, function(v) cfg.CurvierAngle = v end)
            popup:slider("Corner Smoothing", 0, 1, cfg.CornerSmoothing, 2, function(v) cfg.CornerSmoothing = v end)
            popup:slider("Star Offset", 0, 120, cfg.StarOffset, 0, function(v) cfg.StarOffset = v end)
            popup:toggle("Double-sided Gradient", cfg.DoubleGradient, function(v) cfg.DoubleGradient = v end)
        end)

        local originDd = dropdown(card, "Origin", { "Center", "Mouse" }, cfg.Origin,
            function(v) cfg.Origin = v end)
        rightClickSettings(originDd.frame, "Origin", function(popup)
            popup:slider("Mouse Smoothness", 0, 0.98, cfg.MouseSmoothness, 2,
                function(v) cfg.MouseSmoothness = v end)
        end)

        local outRow = configCheckbox(card, "Outline", cfg.Outline, function(v) cfg.Outline = v end)
        attachSingleSwatch(outRow.row, cfg.OutlineColor, function(c) cfg.OutlineColor = c end)
        rightClickSettings(outRow.row, "Outline", function(popup)
            -- the outline is geometry, and its width lands in an integer UDim offset,
            -- so the honest granularity here is 0.5 rather than 0.01.
            popup:slider("Thickness", 0, 6, cfg.OutlineThickness, 2, function(v) cfg.OutlineThickness = v end)
        end)

        slider(card, "Thickness", 1, 40, cfg.Thickness, 0, function(v) cfg.Thickness = v end)
        slider(card, "Length",    2, 1000, cfg.Length,  0, function(v) cfg.Length    = v end)
        slider(card, "Gap",       0, 800, cfg.Gap,      0, function(v) cfg.Gap       = v end)
        slider(card, "Opacity",   0, 1,  cfg.Opacity,   2, function(v) cfg.Opacity   = v end)
        slider(card, "Offset X",  -2000, 2000, cfg.OffsetX, 0, function(v) cfg.OffsetX = v end)
        slider(card, "Offset Y",  -2000, 2000, cfg.OffsetY, 0, function(v) cfg.OffsetY = v end)
        slider(card, "Rotation",  0, 360, cfg.Rotation, 0, function(v) cfg.Rotation = v end)

        local spinRow = configCheckbox(card, "Spin", cfg.Spin, function(v) cfg.Spin = v end)
        rightClickSettings(spinRow.row, "Spin", function(popup)
            popup:slider("Speed (deg/s)", 0, 8640, cfg.SpinSpeed, 0, function(v) cfg.SpinSpeed = v end)
            popup:dropdown("Direction", { "CW", "CCW" }, cfg.SpinDir, function(v) cfg.SpinDir = v end)
        end)

        local followRow = configCheckbox(card, "Follow Target", cfg.Follow.Enabled, function(v)
            cfg.Follow.Enabled = v
            if not v then cfg.Follow._screenX = nil; cfg.Follow._screenY = nil end
        end)
        rightClickSettings(followRow.row, "Follow", function(popup)
            popup:slider("Smoothness", 0, 0.98, cfg.Follow.Smoothness, 2, function(v) cfg.Follow.Smoothness = v end)
            popup:dropdown("Body Part", { "Head", "HumanoidRootPart", "UpperTorso", "Torso",
                "LeftHand", "RightHand", "LeftFoot", "RightFoot" }, cfg.Follow.Part,
                function(v) cfg.Follow.Part = v end)
        end)

        local dotRow = configCheckbox(card, "Center Dot", cfg.Dot.Enabled, function(v) cfg.Dot.Enabled = v end)
        attachSingleSwatch(dotRow.row, cfg.Dot.Color, function(c) cfg.Dot.Color = c end)
        rightClickSettings(dotRow.row, "Center Dot", function(popup)
            popup:slider("Size", 1, 12, cfg.Dot.Size, 0, function(v) cfg.Dot.Size = v end)
        end)

        -- Lock To Part: overrides Follow Target + Origin. "open" reopens the picker.
        local lockRow = new("Frame", {
            Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1,
            ZIndex = 33, Parent = card,
        })
        local lockCB = configCheckbox(lockRow, "Lock To Part", cfg.LockToPart.Enabled,
            function(v)
                cfg.LockToPart.Enabled = v
                if not v then cfg.LockToPart._target = nil end
            end)
        rightClickSettings(lockCB.row, "Lock To Part", function(popup)
            popup:toggle("Track Off-screen", cfg.LockToPart.ClampOffscreen,
                function(v) cfg.LockToPart.ClampOffscreen = v end)
        end)
        local openBtn = new("TextButton", {
            Text = "Open", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.Text,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 60, 0, 20),
            ZIndex = 38, Parent = lockCB.row,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        openBtn.MouseButton1Click:Connect(function()
            if not Shared.openInstancePicker then return end
            Shared.openInstancePicker(function(inst, path)
                cfg.LockToPart.InstancePath = path
                cfg.LockToPart._target = inst
            end, { title = "lock crosshair to part", subtitle = "pick any physical instance." })
        end)

        local syncBtn = new("TextButton", {
            Text = "Sync", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.Text,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 24),
            ZIndex = 34, Parent = card,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        popFx(syncBtn)
        syncBtn.MouseButton1Click:Connect(function() Crosshair._sync = tag end)

        return card
    end

    buildXH(crosshairSub, Crosshair, Crosshair.Double and "Crosshair (A)" or "Crosshair", "A")
    xhCardS = buildXH(crosshairSub, Crosshair.S, "Crosshair (S)", "S")
    xhCardS.Visible = Crosshair.Double == true
end)
addTab("World", function(root)
    -- v0.6.0: World is now subtab-driven. Same content as before goes into the
    -- Lighting / Effects sub-tabs; new Rules sub-tab is a full list UI with
    -- plus/delete/rename + rule creation flow (type picker -> per-type popups).
    local wCard = panel(root)
    local W = Shared.subTabs and Shared.subTabs(wCard, { "Lighting", "Effects", "Rules", "Camera" })
        or { Lighting = root, Effects = root, Rules = root, Camera = root }

    local lighting = panel(W.Lighting, "World Lighting")
    moduleCheckbox(lighting, "Fullbright",  "fullbright")
    moduleCheckbox(lighting, "No Fog",      "nofog")
    moduleCheckbox(lighting, "Custom Time", "customtime")
    -- v0.85.0: one pick sets time, grading, ambient/fog, post FX and weather.
    dropdown(lighting, "Ambience", Shared.AmbienceNames, World.Ambience.Preset,
        function(v) Shared.applyAmbience(v) end)
    slider(lighting, "Clock Time", 0, 24, World.Time.Target, 1, function(v)
        World.Time.Target = v
        if Modules.customtime and Modules.customtime.Enabled then
            Lighting.ClockTime = v
        end
    end)

    -- v0.0.100: effects batch
    local fx = panel(W.Effects, "Effects")
    local cc = moduleCheckbox(fx, "Color Correction", "colorcorrection")
    attachSingleSwatch(cc.row, World.CC.Tint, function(c) World.CC.Tint = c end)
    slider(fx, "Saturation", -1, 1, World.CC.Saturation, 2, function(v) World.CC.Saturation = v end)
    slider(fx, "Contrast",   -1, 1, World.CC.Contrast,   2, function(v) World.CC.Contrast   = v end)
    slider(fx, "Brightness", -1, 1, World.CC.Brightness, 2, function(v) World.CC.Brightness = v end)
    local amb = moduleCheckbox(fx, "Ambient Color", "ambientcolor")
    attachSingleSwatch(amb.row, World.Light.Color, function(c) World.Light.Color = c end)
    -- v0.10.0: split indoor / outdoor ambient. The row swatch stays the single
    -- colour used while Split is off.
    rightClickSettings(amb.row, "Ambient Color", function(popup)
        popup:toggle("Split Indoor / Outdoor", World.Light.Split, function(v) World.Light.Split = v end)
        popup:swatch("Indoor Ambient",  World.Light.Indoor,  function(c) World.Light.Indoor = c end)
        popup:swatch("Outdoor Ambient", World.Light.Outdoor, function(c) World.Light.Outdoor = c end)
        popup:slider("Brightness", 0, 10, World.Light.Brightness, 1, function(v) World.Light.Brightness = v end)
        popup:slider("Exposure", -3, 3, World.Light.Exposure, 2, function(v) World.Light.Exposure = v end)
        popup:toggle("Custom Fog", World.Light.Fog, function(v) World.Light.Fog = v end)
        popup:swatch("Fog Color", World.Light.FogColor, function(c) World.Light.FogColor = c end)
        popup:slider("Fog Start", 0, 2000, World.Light.FogStart, 0, function(v) World.Light.FogStart = v end)
        popup:slider("Fog End", 0, 5000, World.Light.FogEnd, 0, function(v) World.Light.FogEnd = v end)
    end)
    slider(fx, "Ambient Intensity", 0, 2, World.Light.Intensity, 2, function(v) World.Light.Intensity = v end)
    -- v0.10.0: custom skybox. Downloads on first pick, cached after. v0.16.2: the
