    end
    configCheckbox(animPanel, "Animations", KoffeeOptions.AnimOn ~= false, function(v)
        KoffeeOptions.AnimOn = v
    end)
    slider(animPanel, "Speed", 0.5, 2, KoffeeOptions.AnimSpeed or 1, 1, function(v)
