    local ifr = configCheckbox(card, "Ignore Friends", Shared.IgnoreFriends, function(v)
        Shared.IgnoreFriends = v
    end)
    rightClickSettings(ifr.row, "Ignore Friends", function(popup)
        popup:dropdown("Applies To", { "Everything", "Combat Only", "Visuals Only" },
            ({ Everything = "Everything", Combat = "Combat Only", Visuals = "Visuals Only" })[Shared.IgnoreFriendsScope or "Everything"],
            function(v) Shared.IgnoreFriendsScope = ({ ["Combat Only"] = "Combat", ["Visuals Only"] = "Visuals" })[v] or "Everything" end)
    end)

    -- v0.0.95 UNLOAD KOFFEE. Confirm popup then a clean tear-down: disables
    -- every module (their OnDisable fires so state restores), destroys the UI
    -- + toast + hud + background (blur/dim/snow), destroys sound instances,
    -- restores camera + mouse, unbinds our RenderStep binds, and flips a
    -- global unloaded flag so any residual loops early-return.
    local function unloadKoffee()
        -- 1. flip every enabled module OFF so their OnDisable cleanup runs
        for id, m in pairs(Modules) do
            if m.Enabled then pcall(toggleModule, id) end
        end
        -- 2. explicit combat state reset (silent hook stays installed for the
        -- session: can't un-hookmetamethod: but its body early-returns on
        -- Combat.Silent.Enabled = false, so it becomes a no-op).
        -- v0.1.0: Combat lives in its own IIFE; reach it via the Shared export.
        local combat = Shared.Combat
        if combat then
            combat.Silent.Enabled  = false
            combat.Aim.Enabled     = false
            combat.Trigger.Enabled = false
        end
        -- 3. unbind our RenderStep bindings
        pcall(function() RunService:UnbindFromRenderStep(KID.ctx.bind) end)
        pcall(function() RunService:UnbindFromRenderStep("KSpinbot") end)
        pcall(function() RunService:UnbindFromRenderStep("KThirdPerson") end)
        -- 4. destroy every UI surface we own
        pcall(function() screen:Destroy() end)
        pcall(function() popupScreen:Destroy() end)
        pcall(function() blur:Destroy() end)
        -- v0.9.0: the world-FX / hit-FX hosts live on the Camera, not under
        -- `screen`, so those three Destroys miss them. Sweep everything KID tracked
        -- (the same list a re-exec clears) instead of naming surfaces one by one.
        pcall(function()
            for _, inst in ipairs(KID.ctx.instances or {}) do
                pcall(function() inst:Destroy() end)
            end
            KID.ctx.instances = {}
        end)
        -- 5. destroy any sound instances we created
        local combatSounds = Shared.CombatSounds
        pcall(function() if combatSounds then combatSounds.hit:Destroy() end end)
        pcall(function() if combatSounds then combatSounds.kill:Destroy() end end)
        -- 6. restore camera + mouse to game defaults
        pcall(function()
            local cam = Workspace.CurrentCamera
            if cam then cam.CameraType = Enum.CameraType.Custom end
        end)
        UserInputService.MouseBehavior    = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
        -- 7. kill every surviving loop. v0.22.0: bumping the generation ends the
        -- ones a re-exec would otherwise leave running against a dead run too.
        if getgenv then getgenv().KoffeeUnloaded = true end
        Koffee._unloaded = true
        KID.ctx.gen = (KID.ctx.gen or 0) + 1
    end
    -- confirm popup: centered on popupScreen so it survives the window fade
    -- + can be seen even if the user closes the menu underneath.
    local function showUnloadConfirm()
        local pS = popupScreen
        if not (pS and pS.Parent) then return end
        local dim = new("Frame", {
            Name = "KUnloadDim",
            Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0),
            BackgroundTransparency = 0.55, BorderSizePixel = 0,
            ZIndex = 100, Parent = pS,
        })
        local box = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0),
            Size = UDim2.new(0, 320, 0, 148),
            BackgroundColor3 = Theme.Palette.Panel, BorderSizePixel = 0,
            ZIndex = 101, Parent = dim,
        }, { corner(Theme.Radius.Medium), stroke(Theme.Palette.BorderSubtle) })
        new("TextLabel", {
            Text = "Unload Koffee?", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Header,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            Position = UDim2.new(0, 16, 0, 12), Size = UDim2.new(1, -32, 0, 18),
            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 102, Parent = box,
        })
        new("TextLabel", {
            Text = "Every feature disables, the UI is removed. Re-run the loader to bring Koffee back.",
            FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Position = UDim2.new(0, 16, 0, 36), Size = UDim2.new(1, -32, 0, 44),
            TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
            TextWrapped = true, ZIndex = 102, Parent = box,
        })
        local cancel = new("TextButton", {
            Text = "Cancel", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -108, 1, -14),
            Size = UDim2.new(0, 88, 0, 28), ZIndex = 102, Parent = box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        local confirm = new("TextButton", {
            Text = "Unload", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
            AutoButtonColor = false, TextColor3 = Theme.Palette.Danger or Color3.fromRGB(220, 90, 90),
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -14, 1, -14),
            Size = UDim2.new(0, 88, 0, 28), ZIndex = 102, Parent = box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        cancel.MouseButton1Click:Connect(function() dim:Destroy() end)
        confirm.MouseButton1Click:Connect(function() dim:Destroy(); pcall(unloadKoffee) end)
    end
    local unloadBtn = new("TextButton", {
            Text = "Unload Koffee", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
        AutoButtonColor = false, TextColor3 = Theme.Palette.Danger or Color3.fromRGB(220, 90, 90),
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
        BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 30), ZIndex = 36, Parent = card,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
    unloadBtn.MouseButton1Click:Connect(showUnloadConfirm)
end)

-- CONFIGS TAB (v0.0.34): save / load / delete / auto-load per game
-- CUSTOM FEATURES (v0.14.0). User-wired node graph: blocks read game state,
-- transform it, draw it. Read-only and depth-capped, so a bad graph is a visual
-- bug, never a crash. Evaluation carries a context so a subgraph under For Each
-- Player runs once per player with its own cached values and its own GUI copies.
Koffee.Custom = { Enabled = true, Scale = "1x", Nodes = {} }
registerConfig("custom", Koffee.Custom)
;(function()
    local CF = Koffee.Custom
    local layer, vis, st = nil, {}, {}
    -- v0.22.0: key -> frameId a GUI first went unused. Grace period before Destroy.
    local visGone = {}
    -- v0.24.0: live layer scale. Pixel offsets are DESIGN pixels: this is what
    -- keeps a 12px gap looking like 12px on a 1440p or 4K screen.
    local lscale = 1
    local GCTX = { key = "g", player = nil }

    local SCALE_NAMES = { "1x", "Auto", "0.75x", "1.25x", "1.5x", "2x" }
    local function wantScale()
        local s = CF.Scale or "1x"
        if s == "Auto" then
            local vp = viewport()
            return math.clamp((vp and vp.Y or 1080) / 1080, 0.5, 2.5)
        end
        return tonumber(s:match("^([%d%.]+)")) or 1
    end

    local function ensureLayer()
        if layer and layer.Parent then return layer end
        layer = new("Frame", {
            Name = "CustomLayer", Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0,
            ZIndex = 16, Parent = screen,
        }, { new("UIScale", { Scale = 1 }) })
        return layer
    end
    -- v0.22.0: id -> node index. This was a linear scan of CF.Nodes, hit once per
    -- wire per node per context per frame: six figures of table steps on a
    -- 40-node graph under For Each Player. Miss falls back to a reindex so a
    -- freshly added or deleted node can never read stale.
    local NIDX = {}
    local function reindex()
        table.clear(NIDX)
        for _, n in ipairs(CF.Nodes) do NIDX[n.id] = n end
    end
    local function nodeById(id)
        local n = NIDX[id]
        if n then return n end
        reindex()
        return NIDX[id]
    end
    -- v0.22.0: memoised "id|ctx" keys. Built three times per node per context per
    -- frame (alive set, slot, guiFor): ~2900 throwaway strings a frame at 40
    -- nodes x 24 players. Cleared on graph edit and swept periodically.
    local KEYC = {}
    local function ckey(node, ctx)
        local a = KEYC[node.id]
        if not a then a = {}; KEYC[node.id] = a end
        local k = a[ctx.key]
        if not k then k = node.id .. "|" .. ctx.key; a[ctx.key] = k end
        return k
    end
    local function playerAt(plr)
        local ch = plr and plr.Character
        local part = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChild("Head"))
        local cam = Workspace.CurrentCamera
        if not (part and cam) then return nil, nil end
        return (part.Position - cam.CFrame.Position).Magnitude, part
    end
    -- per-(block, context) scratch for the blocks that remember things
    local frameId = 0
    local function slot(node, ctx)
        local k = ckey(node, ctx)
        local v = st[k]
        if not v then v = {}; st[k] = v end
        v._f = frameId
        return v
    end

    local FPS, fpsAcc, fpsN = 60, 0, 0

    local guiFor   -- assigned below; Group's eval hands its frame to children
    local KINDS = {}
    local ORDER = {
        "Target", "Self", "Part", "Number", "Text Value", "Colour", "Time",
        "Key Held", "Module State", "Game Info", "Camera", "Mouse", "Counter",
        "Button", "Text Input", "Stopwatch", "Snapshot",
        "Find Instance", "Read Value", "Find Child", "Player Part", "Raycast", "Interval",
        "For Each Player",
        "Visible", "Info", "Compare", "Math", "Logic", "Map Range", "Smooth",
        "Delay", "Format", "Colour Mix", "Colour Cycle", "Pick Number",
        "Pick Colour", "Switch",
        "Screen Position", "Offset", "World Position", "Vector",
        "Text", "Box", "Bar", "Line", "Circle", "Ring", "Image", "Group",
        "3D Ring", "3D Box",
        "Sound", "Notify", "Adorn Part", "Fire Remote", "Set Value",
        "Teleport", "Set Humanoid", "Target Status", "Velocity", "TP Walk", "Click",
        "Koffee Toggle", "Koffee Set", "Build Buffer", "Note",
    }
    -- v0.32.0: shared scripting helpers. rayParams reused across Raycast evals;
    -- doClick drives the Click action off executor globals with a VIM fallback.
    local scriptRayParams = RaycastParams.new()
    scriptRayParams.FilterType = Enum.RaycastFilterType.Exclude
    local VIM_ok, VIM = pcall(function() return game:GetService("VirtualInputManager") end)
    if not VIM_ok then VIM = nil end
    local function doClick(button)
        local right = button == "Right"
        if right then
            if mouse2click then return pcall(mouse2click) end
            if mouse2press then pcall(mouse2press); return pcall(mouse2release) end
        else
            if mouse1click then return pcall(mouse1click) end
            if mouse1press then pcall(mouse1press); return pcall(mouse1release) end
        end
        if VIM then
            local m = UserInputService:GetMouseLocation()
            local mb = right and 1 or 0
            pcall(function()
                VIM:SendMouseButtonEvent(m.X, m.Y, mb, true, game, 0)
                VIM:SendMouseButtonEvent(m.X, m.Y, mb, false, game, 0)
            end)
        end
    end

    -- :: sources ::
    KINDS.Target = {
        blurb = "Finds a player, and says whether it found one",
        -- v0.17.2: bool means we found someone (avoids Screen Position's confusion).
        ins = {}, outs = { player = true, bool = true },
        opts = { Source = "Aimbot Target", Filter = "Any", MaxDistance = 0 },
        eval = function(o)
            local C, s, plr = Shared.Combat, o.Source, nil
            if s == "Aimbot Target" then plr = C and (C.Aim._rageLock or C.Aim._target)
            elseif s == "Silent Aim Target" then plr = C and C.Silent._target
            elseif s == "Crosshair Target" then
                plr = Shared.crosshairTarget and Shared.crosshairTarget("Aim") or nil
            elseif s == "Closest Player" then
                local bd = math.huge
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer then
                        local d = playerAt(p)
                        if d and d < bd then plr, bd = p, d end
                    end
                end
            end
            if plr and o.Filter ~= "Any" then
                local ally = isTeammate and isTeammate(plr) or false
                if o.Filter == "Enemies Only" and ally then plr = nil end
                if o.Filter == "Team Only" and not ally then plr = nil end
            end
            if plr and (o.MaxDistance or 0) > 0 then
                local d = playerAt(plr)
                if not d or d > o.MaxDistance then plr = nil end
            end
            return { player = plr, bool = plr ~= nil }
        end,
        ui = function(api, o)
            api:dropdown("Source", { "Aimbot Target", "Silent Aim Target",
                "Crosshair Target", "Closest Player" }, o.Source, function(v) o.Source = v end)
            api:dropdown("Filter", { "Any", "Enemies Only", "Team Only" }, o.Filter,
                function(v) o.Filter = v end)
            api:slider("Max Distance", 0, 5000, o.MaxDistance, 0, function(v) o.MaxDistance = v end)
        end,
    }

    KINDS.Self = {
        blurb = "You",
        ins = {}, outs = { player = true }, opts = {},
        eval = function() return { player = LocalPlayer } end,
    }

    KINDS.Part = {
        blurb = "A part or model you pick in game",
        ins = {}, outs = { part = true },
        opts = { Path = "" },
        eval = function(o)
            local inst = o._inst
            if (not inst or not inst.Parent) and o.Path ~= "" and Shared.resolvePath then
                inst = Shared.resolvePath(o.Path)
                o._inst = inst
            end
            return { part = inst }
        end,
        ui = function(api, o)
            api:label(o.Path ~= "" and o.Path or "Nothing picked")
            api:button("pick a part", function(done)
                if not Shared.openInstancePicker then return end
                Shared.openInstancePicker(function(inst, path)
                    o.Path, o._inst = path or "", inst
                    done()
                end, { title = "pick a part" })
            end)
        end,
    }

    -- v0.31.0: game-specific blocks. Find Instance grabs ANY instance; Read Value
    -- pulls a number/text/bool off one; Fire Remote + Set Value (below) push back.
    -- Together they let a graph drive a game's own remotes with no code.
    KINDS["Find Instance"] = {
        blurb = "Pick or type a path to ANY instance: a remote, a value, a part",
        ins = {}, outs = { part = true, text = true },
        opts = { Path = "" },
        eval = function(o)
            local inst = o._inst
            if (not inst or not inst.Parent) and o.Path ~= "" and Shared.resolvePath then
                inst = Shared.resolvePath(o.Path)
                o._inst = inst
            end
            return { part = inst, text = inst and inst.Name or "" }
        end,
        ui = function(api, o)
            api:label(o.Path ~= "" and o.Path or "Nothing picked")
            api:button("pick any instance", function(done)
                if not Shared.openInstancePicker then return end
                Shared.openInstancePicker(function(inst, path)
                    o.Path, o._inst = path or "", inst
                    done()
