    -- :: evaluation ::
    local frameDt = 1 / 60
    local resolveIns, evalNode
    resolveIns = function(node, K, cache, depth, ctx)
        local ins = {}
        for _, s in ipairs(K.ins) do
            local ref = node.wires and node.wires[s.key]
            local src = ref and nodeById(ref)
            if src then ins[s.key] = evalNode(src, cache, depth + 1, ctx) end
        end
        return ins
    end
    -- memoized per context, depth-capped so a wire loop returns empty instead of
    -- hanging the client
    evalNode = function(node, cache, depth, ctx)
        local bag = cache[ctx.key]
        if not bag then bag = {}; cache[ctx.key] = bag end
        local hit = bag[node.id]
        if hit ~= nil then return hit end
        if depth > 16 then return {} end
        local K = KINDS[node.kind]
        if not K then return {} end
        bag[node.id] = {}
        local ins = resolveIns(node, K, cache, depth, ctx)
        local out = ins
        if K.eval then
            local ok, r = pcall(K.eval, node.opts, ins, ctx, node, frameDt)
            out = (ok and type(r) == "table") and r or {}
        end
        bag[node.id] = out
        return out
    end

    -- which For Each block, if any, a sink hangs off. Memoized per frame.
    local function feOf(node, memo, depth)
        if depth > 16 then return nil end
        local hit = memo[node.id]
        if hit ~= nil then return hit or nil end
        memo[node.id] = false
        if node.kind == "For Each Player" then memo[node.id] = node; return node end
        local K = KINDS[node.kind]
        if K then
            for _, s in ipairs(K.ins) do
                local ref = node.wires and node.wires[s.key]
                local src = ref and nodeById(ref)
                if src then
                    local f = feOf(src, memo, depth + 1)
                    if f then memo[node.id] = f; return f end
                end
            end
        end
        return nil
    end
    local function playersFor(o)
        local out = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                local ally = isTeammate and isTeammate(p) or false
                local ok = true
                if o.Filter == "Enemies Only" and ally then ok = false end
                if o.Filter == "Team Only" and not ally then ok = false end
                local d = playerAt(p)
                if ok and o.AliveOnly then
                    local hum = p.Character and p.Character:FindFirstChildOfClass("Humanoid")
                    if not (hum and hum.Health > 0) then ok = false end
                end
                if ok and (o.MaxDistance or 0) > 0 and (not d or d > o.MaxDistance) then ok = false end
                if ok then out[#out + 1] = { key = tostring(p.UserId), player = p, d = d or 1e9 } end
            end
        end
        table.sort(out, function(a, b) return a.d < b.d end)
        while #out > math.max(math.floor(o.MaxCount or 24), 1) do table.remove(out) end
        return out
    end

    guiFor = function(node, K, ctx)
        local key = ckey(node, ctx)
        local g = vis[key]
        if g and g.Parent then
            -- v0.22.0: revived inside its grace window: unhide. paint runs after
            -- this and re-hides if the block's own logic wants it hidden.
            if visGone[key] then
                visGone[key] = nil
                pcall(function() g.Visible = true end)
            end
            return g
        end
        local ok, made = pcall(K.make)
        if not ok then return nil end
        vis[key] = made
        visGone[key] = nil
        return made
    end

    -- :: design mode ::
    -- v0.25.0: direct manipulation of the live output. Click a drawn widget,
    -- then drag to move, pull a handle to resize, or use the arc to rotate.
    -- Writes back into node.opts, so gizmo and sliders are two views of one value.
    local DM = { on = false, sel = nil, key = nil, drag = nil }

    -- what a resize handle edits, per block kind. Kinds absent here move and
    -- rotate but do not resize.
    local DM_SIZE = {
        Box   = { w = "W", h = "H" },  Group = { w = "W", h = "H" },
        Bar   = { w = "W", h = "H" },  Image = { w = "W", h = "H" },
        Circle = { r = "Radius" },     Ring  = { r = "Radius" },
        Text  = { s = "Size" },
    }
    local DM_HANDLES = { "nw", "n", "ne", "w", "e", "sw", "s", "se" }
    local dmGui, dmBox, dmDots, dmRot, dmTip, dmBan = nil, nil, {}, nil, nil, nil

    local function dmBuild()
        if dmGui and dmGui.Parent then return end
        dmGui = KID.track(new("Frame", {
            Name = KID.name("dm"), Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, Visible = false, ZIndex = 60, Parent = screen,
        }))
        dmBox = new("Frame", {
            BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 61, Parent = dmGui,
        }, { stroke(Theme.Palette.Accent) })
        for _, h in ipairs(DM_HANDLES) do
            dmDots[h] = new("Frame", {
                Name = h, Size = UDim2.new(0, 8, 0, 8),
                AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0,
                BackgroundColor3 = Theme.Palette.Accent, ZIndex = 62, Parent = dmGui,
            }, { corner(2) })
        end
        dmRot = new("Frame", {
            Size = UDim2.new(0, 10, 0, 10), AnchorPoint = Vector2.new(0.5, 0.5),
            BorderSizePixel = 0, BackgroundColor3 = Theme.Palette.Success,
            ZIndex = 62, Parent = dmGui,
        }, { pillCorner() })
        dmTip = new("TextLabel", {
            FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundColor3 = Theme.Palette.Panel,
            BackgroundTransparency = 0.15, BorderSizePixel = 0, Text = "",
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 16),
            AnchorPoint = Vector2.new(0.5, 1), ZIndex = 63, Parent = dmGui,
        }, { corner(4), new("UIPadding", { PaddingLeft = UDim.new(0, 5),
             PaddingRight = UDim.new(0, 5) }) })
        -- v0.26.1: banner. Without it, design mode with nothing selected looked
        -- identical to design mode being off, which read as "it does nothing".
        dmBan = new("TextLabel", {
            Text = "Design Mode: Click a widget to select it, Esc to exit",
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundColor3 = Theme.Palette.Panel,
            BackgroundTransparency = 0.1, BorderSizePixel = 0,
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 22),
            AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 44),
            ZIndex = 63, Parent = dmGui,
        }, { corner(6), stroke(Theme.Palette.Accent),
             new("UIPadding", { PaddingLeft = UDim.new(0, 10),
                                PaddingRight = UDim.new(0, 10) }) })
    end

    -- v0.26.1: a full-screen frame at Position 0,0 does NOT report AbsolutePosition
    -- (0,0) here: IgnoreGuiInset drift, same trap popupOffsetFor works around.
    -- Everything below works in LAYER-LOCAL pixels, which is also GetMouseLocation's
    -- space, so hit tests and gizmo placement agree. This was the "clicks miss" bug.
    local function dmOrigin()
        local f = dmGui or layer
        return f and f.AbsolutePosition or Vector2.new(0, 0)
    end

    -- node id out of a "id|ctx" vis key
    local function dmNodeOf(key)
        local id = tonumber(key:match("^(%d+)|"))
        return id and nodeById(id) or nil
    end
    local function dmRect(g)
        if not (g and g.Parent) then return nil end
        local p, s, o = g.AbsolutePosition, g.AbsoluteSize, dmOrigin()
        return p.X - o.X, p.Y - o.Y, s.X, s.Y
    end
    local function dmInside(x, y, rx, ry, rw, rh, pad)
        pad = pad or 0
        return x >= rx - pad and x <= rx + rw + pad and y >= ry - pad and y <= ry + rh + pad
    end

    -- topmost drawn widget under the cursor. Hit test is the UNROTATED rect:
    -- AbsolutePosition/Size ignore Rotation, so a spun block grabs by its box.
    local function dmPick(x, y)
        local bk, bz = nil, -1
        for key, g in pairs(vis) do
            if g and g.Parent and g.Visible then
                local rx, ry, rw, rh = dmRect(g)
                if rx and dmInside(x, y, rx, ry, rw, rh) then
                    local z = g.ZIndex or 0
                    if z >= bz then bk, bz = key, z end
                end
            end
        end
        return bk
    end

    local function dmSelGui()
        return DM.key and vis[DM.key] or nil
    end
    local function dmClear()
        DM.sel, DM.key, DM.drag = nil, nil, nil
        if dmGui then dmGui.Visible = false end
    end

    -- follow the selected widget. Runs at the end of the frame, after paint.
    local function dmSync()
        if not DM.on then if dmGui then dmGui.Visible = false end return end
        dmBuild()
        -- v0.26.1: the frame stays visible for the banner even with no selection.
        -- Only the box, handles and readout follow a selected widget.
        dmGui.Visible = true
        local g = dmSelGui()
        local node = DM.sel and nodeById(DM.sel) or nil
        local rx, ry, rw, rh = dmRect(g)
        local has = (g and g.Parent and node and rx) and true or false
        dmBox.Visible = has
        dmRot.Visible = has
        dmTip.Visible = has
        for _, d in pairs(dmDots) do d.Visible = has end
        dmBan.Text = has and "Design Mode: Drag to move, dots resize, Esc to deselect"
            or "design mode: click a widget to select it, esc to exit"
        if not has then return end
        dmBox.Position = UDim2.new(0, rx, 0, ry)
        dmBox.Size = UDim2.new(0, rw, 0, rh)
        local mx, my = rx + rw * 0.5, ry + rh * 0.5
        local px = { nw = { rx, ry }, n = { mx, ry }, ne = { rx + rw, ry },
                     w = { rx, my }, e = { rx + rw, my },
                     sw = { rx, ry + rh }, s = { mx, ry + rh }, se = { rx + rw, ry + rh } }
        local sz = DM_SIZE[node.kind]
        for h, d in pairs(dmDots) do
            d.Visible = sz ~= nil
            d.Position = UDim2.new(0, px[h][1], 0, px[h][2])
        end
        dmRot.Position = UDim2.new(0, mx, 0, ry - 20)
        dmTip.Position = UDim2.new(0, mx, 0, ry - 30)
        dmTip.Text = ("%s  %d,%d"):format(node.kind,
            math.floor(node.opts.OffX or 0), math.floor(node.opts.OffY or 0))
    end

    -- which gizmo part is under the cursor, if any. Handles are anchor-centred,
    -- so their rect is offset by half their size.
    local function dmHandleAt(x, y)
        if not (dmGui and dmGui.Visible) then return nil end
        local o = dmOrigin()
        for h, d in pairs(dmDots) do
            if d.Visible then
                local p = d.AbsolutePosition
                if dmInside(x, y, p.X - o.X, p.Y - o.Y, 8, 8, 5) then return h end
            end
        end
        if dmRot.Visible then
            local rp = dmRot.AbsolutePosition
            if dmInside(x, y, rp.X - o.X, rp.Y - o.Y, 10, 10, 6) then return "rot" end
        end
        return nil
    end

    -- snap the widget's centre to the screen centre lines
    local function dmSnap(v, target)
        return (math.abs(v - target) <= 6) and target or v
    end

    local function dmBegin(x, y)
        local h = dmHandleAt(x, y)
        local node = DM.sel and nodeById(DM.sel) or nil
        if h and node then
            local g = dmSelGui()
            local rx, ry, rw, rh = dmRect(g)
            DM.drag = { mode = (h == "rot") and "rot" or "size", h = h, x = x, y = y,
                        ox = node.opts.OffX or 0, oy = node.opts.OffY or 0,
                        w = node.opts.W, hh = node.opts.H, r = node.opts.Radius,
                        ts = node.opts.Size, rot = node.opts.Rotation or 0,
                        cx = (rx or 0) + (rw or 0) * 0.5, cy = (ry or 0) + (rh or 0) * 0.5 }
            return true
        end
        local g = dmSelGui()
        if g then
            local rx, ry, rw, rh = dmRect(g)
            if rx and dmInside(x, y, rx, ry, rw, rh) and node then
                DM.drag = { mode = "move", x = x, y = y,
                            ox = node.opts.OffX or 0, oy = node.opts.OffY or 0 }
                return true
            end
        end
        local key = dmPick(x, y)
        if key then
            local n = dmNodeOf(key)
            if n then
                DM.sel, DM.key, DM.drag = n.id, key, nil
                -- v0.26.1: point the editor's inspector at whatever you clicked,
                -- so selecting on screen and selecting in the graph are one action
                if Koffee._cfSelect then pcall(Koffee._cfSelect, n.id) end
                return true
            end
        end
        dmClear()
        return false
    end

    local function dmMove(x, y)
        local d = DM.drag
        if not d then return end
        local node = DM.sel and nodeById(DM.sel)
        if not node then return end
        local o = node.opts
        local dx, dy = (x - d.x) / lscale, (y - d.y) / lscale
        if d.mode == "move" then
            local g = dmSelGui()
            o.OffX, o.OffY = d.ox + dx, d.oy + dy
            -- snap the widget's centre to the middle of the screen
            local vp = viewport()
            local rx, ry, rw, rh = dmRect(g)
            if rx and vp then
                local cx, cy = rx + rw * 0.5, ry + rh * 0.5
                o.OffX = o.OffX + (dmSnap(cx, vp.X * 0.5) - cx) / lscale
                o.OffY = o.OffY + (dmSnap(cy, vp.Y * 0.5) - cy) / lscale
            end
            o.OffX, o.OffY = math.floor(o.OffX + 0.5), math.floor(o.OffY + 0.5)
        elseif d.mode == "rot" then
            local a0 = math.atan2(d.y - d.cy, d.x - d.cx)
            local a1 = math.atan2(y - d.cy, x - d.cx)
            o.Rotation = math.floor(d.rot + math.deg(a1 - a0) + 0.5)
        else
            local sz = DM_SIZE[node.kind]
            if not sz then return end
            local h = d.h
            if sz.w then
                -- east/west handles push width, north/south push height. Anchor is
                -- the block's own pivot, so a drag grows around it, not from a corner.
                local sx = (h == "e" or h == "ne" or h == "se") and 1
                    or ((h == "w" or h == "nw" or h == "sw") and -1 or 0)
                local sy = (h == "s" or h == "sw" or h == "se") and 1
                    or ((h == "n" or h == "nw" or h == "ne") and -1 or 0)
                if sx ~= 0 then o.W = math.max(1, math.floor((d.w or 1) + dx * sx + 0.5)) end
                if sy ~= 0 then o.H = math.max(1, math.floor((d.hh or 1) + dy * sy + 0.5)) end
            elseif sz.r then
                local m = (math.abs(dx) > math.abs(dy)) and dx or dy
                local sgn = (h == "e" or h == "se" or h == "s" or h == "ne") and 1 or -1
                o.Radius = math.max(1, math.floor((d.r or 1) + m * sgn + 0.5))
            elseif sz.s then
                o.Size = math.clamp(math.floor((d.ts or 12) + dy * -1 + 0.5), 8, 96)
            end
        end
    end

    Koffee._designMode = function(on)
        DM.on = on == true
        if not DM.on then dmClear(); return end
        dmBuild()            -- build now so the banner shows the instant it's on
        dmGui.Visible = true
        if Shared.setWindowOpen then Shared.setWindowOpen(false) end
    end

    UserInputService.InputBegan:Connect(function(input, gpe)
        if Koffee.dead() or not DM.on or gpe then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            local m = UserInputService:GetMouseLocation()
            dmBegin(m.X, m.Y)
        elseif input.KeyCode == Enum.KeyCode.Escape then
            dmClear()
        elseif DM.sel then
            local node = nodeById(DM.sel)
            local step = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) and 10 or 1
            local k = input.KeyCode
            if node then
                local o = node.opts
                if k == Enum.KeyCode.Left  then o.OffX = (o.OffX or 0) - step
                elseif k == Enum.KeyCode.Right then o.OffX = (o.OffX or 0) + step
                elseif k == Enum.KeyCode.Up    then o.OffY = (o.OffY or 0) - step
                elseif k == Enum.KeyCode.Down  then o.OffY = (o.OffY or 0) + step end
            end
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if Koffee.dead() or not DM.on or not DM.drag then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement then
            local m = UserInputService:GetMouseLocation()
            dmMove(m.X, m.Y)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then DM.drag = nil end
    end)

    RunService.RenderStepped:Connect(function(dt)
        if Koffee.dead() then return end
        frameDt, frameId = dt, frameId + 1
        fpsAcc, fpsN = fpsAcc + dt, fpsN + 1
        if fpsAcc >= 0.25 then FPS = fpsN / fpsAcc; fpsAcc, fpsN = 0, 0 end
        -- v0.24.0: push the design-pixel scale onto the layer once per frame.
        lscale = wantScale()
        local lsc = layer and layer:FindFirstChildOfClass("UIScale")
        if lsc and lsc.Scale ~= lscale then lsc.Scale = lscale end
        local alive = {}
        if CF.Enabled then
            reindex()
            -- v0.22.0: ctxMemo. playersFor ran once per SINK, so five draw blocks
            -- under one For Each Player meant five identical Players sweeps +
            -- distance passes + sorts per frame. Memoised by the For Each node.
            local cache, memo, ctxMemo = {}, {}, {}
            for _, node in ipairs(CF.Nodes) do
                local K = KINDS[node.kind]
                if K and K.sink then
                    local fe = feOf(node, memo, 0)
                    local ctxs
                    if fe then
                        ctxs = ctxMemo[fe.id]
                        if not ctxs then ctxs = playersFor(fe.opts); ctxMemo[fe.id] = ctxs end
                        -- v0.25.0: nothing renders in an empty lobby, so there is
                        -- nothing to grab. Design Mode forces one preview context.
                        if DM.on and #ctxs == 0 then ctxs = { GCTX } end
                    else
                        ctxs = { GCTX }
                    end
                    for _, ctx in ipairs(ctxs) do
                        alive[ckey(node, ctx)] = true
                        -- action blocks (Sound) have no GUI of their own
                        local g = K.make and guiFor(node, K, ctx) or nil
                        if g or not K.make then
                            local ins = resolveIns(node, K, cache, 0, ctx)
                            pcall(K.paint, g, node.opts, ins, node, ctx, dt)
                        end
                    end
                end
            end
        end
        -- v0.22.0: hide first, Destroy after a grace window. A target that blinks
        -- out for one frame (dies, clips out of FOV) used to tear its whole GUI
        -- subtree down and rebuild it next frame: the cost AND the visual pop.
        for key, g in pairs(vis) do
            if alive[key] then
                visGone[key] = nil
            else
                local since = visGone[key]
                if not since then
                    visGone[key] = frameId
                    pcall(function() g.Visible = false end)
                elseif frameId - since > 120 then
                    g:Destroy(); vis[key] = nil; visGone[key] = nil
                end
            end
        end
        for key, v in pairs(st) do
            if v._f ~= frameId then st[key] = nil end
        end
        -- v0.22.0: KEYC keys off UserId, so a long session with lots of unique
        -- players would creep. Full clear every ~10s; rebuild cost is one concat.
        if frameId % 600 == 0 then table.clear(KEYC) end
        dmSync()
    end)

    -- :: graph edits ::
    -- the Text block's single "text" slot became "a" in v0.13.3
    local OPMAP = {
        ["less than"] = "Less Than", ["more than"] = "More Than",
        ["equal to"] = "Equal To", add = "Add", subtract = "Subtract",
        multiply = "Multiply", divide = "Divide", smallest = "Smallest",
        largest = "Largest", difference = "Difference", ["and"] = "And",
        ["or"] = "Or", ["not A"] = "Not A", ["only one"] = "Only One",
        ["becomes yes"] = "Becomes Yes", ["becomes no"] = "Becomes No",
        ["while yes"] = "While Yes", ["Turn On (edge)"] = "Turn On (Edge)",
        ["Turn Off (edge)"] = "Turn Off (Edge)", ["(none)"] = "(None)",
    }
    local function migrate()
        for _, n in ipairs(CF.Nodes) do
            -- v0.41.0: Set Velocity renamed to Velocity, old saves follow.
            if n.kind == "Set Velocity" then n.kind = "Velocity" end
            -- v0.47.0: option strings went professional-case. Map the old
            -- ones so saved graphs keep their behavior instead of falling
            -- into default branches.
            if n.opts then
                for _, k in ipairs({ "Op", "Edge", "Mode",
                    "Arg1", "Arg2", "Arg3", "Arg4" }) do
                    local v = n.opts[k]
                    if OPMAP[v] then n.opts[k] = OPMAP[v] end
                end
            end
            local w = n.wires
            if w and w.text and not w.a then w.a = w.text; w.text = nil end
        end
        -- v0.22.0: config load swaps CF.Nodes contents; NIDX has to follow.
        reindex()
        table.clear(KEYC)
    end

    local function enc(v)
        local t = typeof(v)
        if t == "number" or t == "boolean" then return tostring(v) end
        if t == "string" then return string.format("%q", v) end
        if t == "Color3" then
            return string.format("Color3.new(%.5f,%.5f,%.5f)", v.R, v.G, v.B)
        end
        if t == "table" then
            local parts = {}
            for k, val in pairs(v) do
                if not (type(k) == "string" and k:sub(1, 1) == "_") then
                    local e = enc(val)
                    if e then
                        local ek = (type(k) == "number") and ("[" .. k .. "]")
                            or ("[" .. string.format("%q", k) .. "]")
                        parts[#parts + 1] = ek .. "=" .. e
                    end
                end
            end
            return "{" .. table.concat(parts, ",") .. "}"
        end
        return nil
    end

    local function graphText() return "KOFFEEGRAPH" .. enc(CF.Nodes) end

    -- v0.21.2: plenty of executors ship no clipboard API at all, so both directions
    -- fall back to a popup: copy shows the text to select by hand, paste takes it in.
    local function copyGraph()
        local set = setclipboard or toclipboard or (syn and syn.setclipboard)
        local txt = graphText()
        if set and pcall(set, txt) then return true, "copied" end
        if Shared.openTextPopup then
            Shared.openTextPopup("copy graph", txt,
                "", function() end, true)
            return true, "select all and copy"
        end
        return false, "no clipboard access"
    end

    -- Pasting runs loadstring on clipboard text, so the payload is scrubbed first:
    -- strip strings and the only call we allow, then reject anything with letters
    -- left. That leaves no way to smuggle a function call in through a shared graph.
    local function pasteGraph(txt)
        if type(txt) ~= "string" or txt == "" then return false, "nothing pasted" end
        local body = txt:match("KOFFEEGRAPH(.+)$")
        if not body then return false, "not a koffee graph" end
        local scrub = body:gsub("\\\"", ""):gsub('"[^"]*"', "")
        scrub = scrub:gsub("Color3%.new", ""):gsub("true", ""):gsub("false", ""):gsub("nil", "")
        if scrub:find("%a") then return false, "graph looks tampered with" end
        local ldr = loadstring or load
        local fn = ldr and ldr("return " .. body)
        if not fn then return false, "graph is malformed" end
        local ok2, data = pcall(fn)
        if not (ok2 and type(data) == "table") then return false, "graph is malformed" end
        local base = 0
        for _, n in ipairs(CF.Nodes) do if n.id > base then base = n.id end end
        local map = {}
        for _, n in ipairs(data) do
            if n.kind == "Set Velocity" then n.kind = "Velocity" end
            if type(n) == "table" and tonumber(n.id) and KINDS[n.kind] then
                base = base + 1
                map[n.id] = base
            end
        end
        local added = 0
        for _, n in ipairs(data) do
            if map[n.id] then
                local w = {}
                for k, ref in pairs(n.wires or {}) do w[k] = map[ref] end
                local o = {}
                for k, v in pairs(KINDS[n.kind].opts or {}) do o[k] = v end
                for k, v in pairs(n.opts or {}) do o[k] = v end
                table.insert(CF.Nodes, { id = map[n.id], kind = n.kind, opts = o, wires = w,
                    x = (tonumber(n.x) or 24) + 26, y = (tonumber(n.y) or 24) + 26 })
                added = added + 1
            end
        end
        reindex()
        return added > 0, added > 0 and ("pasted " .. added) or "nothing to paste"
    end

    local function addNode(kind, x, y)
        local K = KINDS[kind]
        if not K then return nil end
        local id = 1
        for _, n in ipairs(CF.Nodes) do if n.id >= id then id = n.id + 1 end end
        local o = {}
        for k, v in pairs(K.opts or {}) do o[k] = v end
        table.insert(CF.Nodes, { id = id, kind = kind, opts = o, wires = {},
                                 x = x or 24, y = y or 24 })
        reindex()
        return id
    end
    local function removeNode(id)
        for i, n in ipairs(CF.Nodes) do
            if n.id == id then table.remove(CF.Nodes, i); break end
        end
        for _, n in ipairs(CF.Nodes) do          -- drop wires pointing at it
            for k, ref in pairs(n.wires or {}) do
                if ref == id then n.wires[k] = nil end
            end
        end
        -- v0.22.0: NIDX would keep handing out the deleted node otherwise.
        reindex()
        KEYC[id] = nil
    end

    -- headers keyed off ORDER's own grouping, so the reference below is generated
    -- from the block registry and can never drift out of date
    local DOC_HEADS = {
        ["Target"]          = "Sources: these find things",
        ["For Each Player"] = "Repeating: runs everything after it once per player",
        ["Visible"]         = "Logic: these decide and reshape",
        ["Screen Position"] = "Position: these make things follow",
        ["Text"]            = "Drawing: these put things on your screen",
        ["3D Ring"]         = "In the World: real geometry, not screen overlay",
        ["Sound"]           = "Actions: these fire when something happens",
    }
    local DOC_BODY = {
        { h = "The Idea" },
        { p = "Blocks do one small job each and pass the answer along. On their own they do nothing. You connect them, and the connection is where the feature comes from." },
        { p = "A block that finds a player, a block that asks a question about them, a block that draws the answer. That is a feature you built without writing code." },
        { h = "Wiring" },
        { p = "Click the dot on the RIGHT of one block, then the dot on the LEFT of another. The source dot lights up while you are mid connection." },
        { p = "Click an input dot with nothing pending to unplug it. Drag a block by its header. Drag empty space to pan. Minus folds a block, X deletes it." },
        { p = "You can only connect things that fit. A block that produces a player will not plug into a slot that wants a colour, so a wire that looks refused is telling you something." },
        { h = "Three Rules Worth Knowing" },
        { p = "1. An input you do NOT wire falls back to that block's own setting. So a Text block on its own is just a label you place anywhere. Wire something in and it takes over." },
        { p = "2. Switch is the 'otherwise'. It holds both answers at once: text and colour for yes, text and colour for no: so you never need two blocks that can drift apart." },
        { p = "3. In a Text block, {a} {b} {c} get replaced by its three value inputs. So \"health is {a}\" with Info wired into Value A is one block, not two sitting next to each other." },
        { h = "Show When" },
        { p = "Every drawing block has a Show When input. Wire a yes/no into it and the block only appears when that is true. Leave it empty and it is always on." },
        { h = "Position" },
        { p = "Every drawing block has a Position input. Leave it empty and it sits where its X/Y sliders say. Wire Screen Position into it and it follows a part or a player through the world." },
        { h = "Sharing" },
        { p = "Copy Graph puts the whole thing on your clipboard as text. Paste adds it back, renumbering so it never collides with blocks you already have. That is how you send a setup to someone." },
    }

    -- worked examples, built as real graphs so they can be opened and taken apart
    local function wire(id, key, src) local n = nodeById(id); if n then n.wires[key] = src end end
    local function opt(id, k, v) local n = nodeById(id); if n then n.opts[k] = v end end

    local EXAMPLES = {
        {
            name = "Target Visible Readout",
            note = "Says VISIBLE in green or NOT VISIBLE in red, wherever your target is",
            build = function()
                local t = addNode("Target", 24, 24)
                local v = addNode("Visible", 24, 150)
                local s = addNode("Switch", 244, 150)
                local x = addNode("Text", 464, 150)
                opt(t, "Source", "Silent Aim Target")
                wire(v, "player", t)
                wire(s, "bool", v)
                wire(x, "a", s); wire(x, "color", s)
                opt(x, "Text", "{a}"); opt(x, "Y", 62); opt(x, "Size", 26)
            end,
        },
        {
            name = "Name + Health Over Every Enemy",
            note = "Per player, so this is a full custom ESP made of five blocks",
            build = function()
                local fe = addNode("For Each Player", 24, 24)
                local sp = addNode("Screen Position", 244, 24)
                local nm = addNode("Info", 244, 168)
                local hp = addNode("Info", 244, 300)
                local tx = addNode("Text", 500, 24)
                local br = addNode("Bar", 500, 210)
                opt(sp, "Anchor", "Above")
                wire(sp, "player", fe)
                opt(nm, "Field", "Name");       wire(nm, "player", fe)
                opt(hp, "Field", "Health 0-1"); wire(hp, "player", fe)
                wire(tx, "pos", sp); wire(tx, "a", nm)
                opt(tx, "Text", "{a}"); opt(tx, "Size", 14)
                local off = addNode("Offset", 500, 380)
                wire(off, "point", sp); opt(off, "Y", 16)
                wire(br, "pos", off); wire(br, "value", hp)
                opt(br, "W", 60); opt(br, "H", 5)
            end,
        },
        {
            name = "Label Over Your Target",
            note = "Follows the target and disappears the moment you are not on one",
            build = function()
                local t  = addNode("Target", 24, 24)
                local sp = addNode("Screen Position", 244, 24)
                local sw = addNode("Switch", 244, 190)
                local x  = addNode("Text", 500, 24)
                opt(sp, "Anchor", "Above")
                wire(sp, "player", t)
                -- Target's bool is "did it find anybody", which is what drives both
                -- the wording and whether the label exists at all
                wire(sw, "bool", t)
                opt(sw, "TrueText", "TARGET"); opt(sw, "FalseText", "")
                wire(x, "pos", sp); wire(x, "a", sw)
                wire(x, "color", sw); wire(x, "show", t)
                opt(x, "Text", "{a}"); opt(x, "Size", 15)
            end,
        },
        {
            name = "3D Scanning Ring On Your Target",
            note = "Real geometry in the world, eased, rides up and down the body",
            build = function()
                local t  = addNode("Target", 24, 24)
                local wp = addNode("World Position", 260, 24)
                local tm = addNode("Time", 24, 200)
                local mr = addNode("Map Range", 24, 310)
                local rg = addNode("3D Ring", 520, 24)
                wire(wp, "player", t)
                opt(wp, "Anchor", "Feet")
                -- Sine is already an ease: it slows at both ends of the travel where
                -- Ping-Pong would turn around hard
                opt(tm, "Mode", "Sine"); opt(tm, "Speed", 1.4)
                wire(mr, "number", tm)
                opt(mr, "InMin", -1); opt(mr, "InMax", 1)
                opt(mr, "OutMin", 0); opt(mr, "OutMax", 5.5)
                -- studs, so the ring stays on the body at any range with no maths
                wire(wp, "height", mr)
                wire(rg, "at", wp); wire(rg, "show", t)
                opt(rg, "Radius", 3.2); opt(rg, "Thickness", 0.15)
            end,
        },
    }

    local function docsModal(onBuilt)
        if not Shared.openModal then return end
        local vp = viewport()
        local m = Shared.openModal(math.min(600, vp.X - 60), math.min(560, vp.Y - 60))
        new("TextLabel", {
            Text = "Custom Features", FontFace = Theme.Fonts.Bold,
            TextSize = Theme.Text.Header, TextColor3 = Theme.Palette.Text,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.new(0, 16, 0, 12), Size = UDim2.new(1, -32, 0, 18),
            ZIndex = 202, Parent = m.box,
        })
        local body = new("ScrollingFrame", {
            Position = UDim2.new(0, 10, 0, 38), Size = UDim2.new(1, -20, 1, -84),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.Palette.Border,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ZIndex = 202, Parent = m.box,
        }, { new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 10) }),
             new("UIListLayout", { Padding = UDim.new(0, 5),
                 SortOrder = Enum.SortOrder.LayoutOrder }) })
        local order = 0
        local function head(t)
            order = order + 1
            new("TextLabel", {
                Text = t, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
                TextColor3 = Theme.Palette.Accent, BackgroundTransparency = 1,
                TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y,
                Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = order, ZIndex = 203, Parent = body,
            }, { new("UIPadding", { PaddingTop = UDim.new(0, 8) }) })
        end
        local function para(t, muted)
            order = order + 1
            new("TextLabel", {
                Text = t, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = muted and Theme.Palette.TextMuted or Theme.Palette.Text,
                BackgroundTransparency = 1, TextWrapped = true,
                AutomaticSize = Enum.AutomaticSize.Y, LineHeight = 1.25,
                Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = order, ZIndex = 203, Parent = body,
            })
        end
        for _, e in ipairs(DOC_BODY) do
            if e.h then head(e.h) else para(e.p) end
        end
        head("Try One")
        for _, e in ipairs(EXAMPLES) do
            order = order + 1
            local b = new("TextButton", {
                Text = "Build: " .. e.name, AutoButtonColor = false,
                FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextMuted,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 26),
                LayoutOrder = order, ZIndex = 203, Parent = body,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
            b.MouseButton1Click:Connect(function()
                e.build()
                m.close()
                if onBuilt then onBuilt() end
            end)
            para(e.note, true)
        end
        para("These add to whatever is already on the canvas, they do not replace it", true)
        head("Every Block")
        for _, name in ipairs(ORDER) do
            if DOC_HEADS[name] then para(DOC_HEADS[name], true) end
            local K = KINDS[name]
            if K then para(name .. ": " .. (K.blurb or "")) end
        end
        local close = new("TextButton", {
            Text = "Close", AutoButtonColor = false, FontFace = Theme.Fonts.Medium,
            TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 1),
            Position = UDim2.new(1, -14, 1, -12), Size = UDim2.new(0, 88, 0, 26),
            ZIndex = 202, Parent = m.box,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        close.MouseButton1Click:Connect(m.close)
        return m
    end

