    -- analytic node geometry: port centres never wait on a layout pass
    local NODE_W, HEAD_H, ROW_H, WIRE_SEG = 172, 24, 20, 12
    local TOOL_H, INSP_W, CANVAS_W, CANVAS_H = 90, 202, 2600, 1800
    local function nodeH(K, node)
        if node and node.fold then return HEAD_H + 4 end
        return HEAD_H + math.max(#K.ins, 1) * ROW_H + 6
    end
    local function portY(node, i)
        if node.fold then return HEAD_H * 0.5 end
        return HEAD_H + (i - 0.5) * ROW_H
    end
    local function bez(x1, y1, ax, ay, bx, by, x2, y2, t)
        local u = 1 - t
        local a, b, c, d = u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t
        return a * x1 + b * ax + c * bx + d * x2, a * y1 + b * ay + c * by + d * y2
    end
    local function toolBtn(parent, text, width, order, onClick, h)
        local b = new("TextButton", {
            Text = text, AutoButtonColor = false,
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(0, width, 0, h or 24),
            LayoutOrder = order, ZIndex = 36, Parent = parent,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        b.MouseEnter:Connect(function()
            tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
        end)
        b.MouseLeave:Connect(function()
            tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
        end)
        b.MouseButton1Click:Connect(onClick)
        popFx(b)   -- v0.48.3: toolbar buttons squash on press like the rest
        Koffee.attachBtnHover(b, 0, 0.2)
        return b
    end

    -- one implementation, used both inline in the tab and inside the expanded
    -- modal. `extra` puts a single button at the toolbar's right edge.
    local function makeEditor(parent, connList, extra)
        local canvas = new("ScrollingFrame", {
            Position = UDim2.new(0, 6, 0, TOOL_H),
            Size = UDim2.new(1, -(INSP_W + 22), 1, -(TOOL_H + 26)),
            BackgroundTransparency = 1, BorderSizePixel = 0,
            CanvasSize = UDim2.new(0, CANVAS_W, 0, CANVAS_H),
            ScrollingDirection = Enum.ScrollingDirection.XY,
            ScrollBarThickness = 6, ScrollBarImageColor3 = Theme.Palette.Border,
            ClipsDescendants = true, Active = true, ZIndex = 34, Parent = parent,
        })
        local wireLayer = new("Frame", {
            Size = UDim2.new(0, CANVAS_W, 0, CANVAS_H), BackgroundTransparency = 1,
            ZIndex = 34, Parent = canvas,
        })
        local hint = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Position = UDim2.new(0, 8, 1, -17), Size = UDim2.new(1, -(INSP_W + 20), 0, 14),
            TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 39, Parent = parent,
        })
        local insp = new("ScrollingFrame", {
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, TOOL_H),
            Size = UDim2.new(0, INSP_W, 1, -(TOOL_H + 26)),
            BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.02,
            BorderSizePixel = 0, ScrollBarThickness = 4,
            ScrollBarImageColor3 = Theme.Palette.Border,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ZIndex = 40, Parent = parent,
        }, { corner(6), stroke(Theme.Palette.Border),
            new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10),
                PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }),
            new("UIListLayout", { Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder }) })

        local sel, pending, dragId = nil, nil, nil
        local note, noteAt = nil, 0
        local panning, lastMX, lastMY = false, 0, 0
        local nodeFrames, wirePool = {}, {}
        local rebuildAll
        -- v0.48.0: remembers which node ids already had a frame so only
        -- genuinely new blocks pop in (add / paste) instead of every rebuild.
        local nodeSeenIds = {}

        local function inspApi(p)
            local a = {}
            function a:slider(l, mn, mx, i, pr, cb) slider(p, l, mn, mx, i, pr, cb) end
            function a:toggle(l, i, cb) configCheckbox(p, l, i, cb) end
            function a:dropdown(l, o, i, cb) dropdown(p, l, o, i, cb) end
            function a:text(l, i, cb) textRow(p, l, i, cb) end
            function a:swatch(l, i, cb) swatchRow(p, l, i, cb) end
            function a:label(t) labelRow(p, t) end
            function a:section(t) sectionRow(p, t) end
            function a:button(t, fn) buttonRow(p, t, function() fn(rebuildAll) end) end
            return a
        end

        local function buildInspector()
            for _, c in ipairs(insp:GetChildren()) do
                if c:IsA("GuiObject") then c:Destroy() end
            end
            local node = sel and nodeById(sel)
            if not (node and KINDS[node.kind]) then
                new("TextLabel", {
                    Text = "Click a block to edit it", FontFace = Theme.Fonts.Regular,
                    TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextFaint,
                    BackgroundTransparency = 1, TextWrapped = true,
                    Size = UDim2.new(1, 0, 0, 30), TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 41, Parent = insp,
                })
                return
            end
            local K = KINDS[node.kind]
            new("TextLabel", {
                Text = node.kind .. " #" .. node.id, FontFace = Theme.Fonts.Bold,
                TextSize = Theme.Text.Header, TextColor3 = Theme.Palette.Text,
                BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 18),
                TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 41, Parent = insp,
            })
            new("TextLabel", {
                Text = K.blurb, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
                TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y,
                Size = UDim2.new(1, 0, 0, 14), TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 41, Parent = insp,
            })
            if K.ui then K.ui(inspApi(insp), node.opts) end
        end

        local function seg(i)
            local f = wirePool[i]
            if not f then
                f = new("Frame", {
                    BackgroundColor3 = Theme.Palette.Accent, BorderSizePixel = 0,
                    AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 34, Parent = wireLayer,
                })
                wirePool[i] = f
            end
            return f
        end
        local function redrawWires()
            local n = 0
            for _, node in ipairs(CF.Nodes) do
                local K = KINDS[node.kind]
                if K then
                    for i, slot in ipairs(K.ins) do
                        local src = node.wires and node.wires[slot.key]
                        src = src and nodeById(src)
                        if src and KINDS[src.kind] then
                            local x2, y2 = node.x, node.y + portY(node, i)
                            local x1, y1 = src.x + NODE_W, src.y + portY(src, 1)
                            local off = math.max(40, math.abs(x2 - x1) * 0.5)
                            local px, py = x1, y1
                            for s = 1, WIRE_SEG do
                                local qx, qy = bez(x1, y1, x1 + off, y1, x2 - off, y2, x2, y2,
                                                   s / WIRE_SEG)
                                n = n + 1
                                local f = seg(n)
                                local dx, dy = qx - px, qy - py
                                f.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy) + 1.5, 0, 2)
                                f.Position = UDim2.new(0, (px + qx) * 0.5, 0, (py + qy) * 0.5)
                                f.Rotation = math.deg(math.atan2(dy, dx))
                                f.Visible = true
                                px, py = qx, qy
                            end
                        end
                    end
                end
            end
            for i = n + 1, #wirePool do wirePool[i].Visible = false end
        end

        local function buildNodes()
            for _, f in pairs(nodeFrames) do f:Destroy() end
            nodeFrames = {}
            for _, node in ipairs(CF.Nodes) do
                local K = KINDS[node.kind]
                if K then
                    node.x, node.y = node.x or 24, node.y or 24
                    local picked = (sel == node.id)
                    local f = new("Frame", {
                        Position = UDim2.new(0, node.x, 0, node.y),
                        Size = UDim2.new(0, NODE_W, 0, nodeH(K, node)),
                        BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.02,
                        BorderSizePixel = 0, Active = true, ZIndex = 35, Parent = canvas,
                    }, { corner(6),
                        stroke(picked and Theme.Palette.Accent or Theme.Palette.Border) })
                    nodeFrames[node.id] = f
                    -- v0.48.0: new blocks pop onto the canvas; Lists off (or
                    -- master off, inside popIn) shows them at rest instead.
                    if Koffee.Anim.spot("AnimLists") and not nodeSeenIds[node.id] then
                        Koffee.popIn(f)
                    end

                    local head = new("TextButton", {
                        Text = "  " .. (node.kind == "Note"
                            and (node.opts.Text ~= "" and node.opts.Text or "Note")
                            or node.kind),
                        AutoButtonColor = false,
                        FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
                        TextColor3 = picked and Theme.Palette.Accent or Theme.Palette.Text,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        BackgroundColor3 = Theme.Palette.PanelElevated,
                        BackgroundTransparency = 0.15, BorderSizePixel = 0,
                        Size = UDim2.new(1, 0, 0, HEAD_H), ZIndex = 36, Parent = f,
                    }, { corner(6) })
                    local del = new("TextButton", {
                        Text = "X", AutoButtonColor = false, FontFace = Theme.Fonts.Bold,
                        TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextFaint,
                        BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -5, 0.5, 0), Size = UDim2.new(0, 16, 0, 16),
                        ZIndex = 37, Parent = head,
                    })
                    local fold = new("TextButton", {
                        Text = node.fold and "+" or "-", AutoButtonColor = false,
                        FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
                        TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -21, 0.5, 0), Size = UDim2.new(0, 16, 0, 16),
                        ZIndex = 37, Parent = head,
                    })
                    fold.MouseButton1Click:Connect(function()
                        node.fold = not node.fold or nil
                        rebuildAll()
                    end)
                    del.MouseButton1Click:Connect(function()
                        removeNode(node.id)
                        if sel == node.id then sel = nil end
                        if pending == node.id then pending = nil end
                        rebuildAll()
                    end)
                    head.MouseButton1Click:Connect(function() sel = node.id; rebuildAll() end)
                    head.InputBegan:Connect(function(inp)
                        if inp.UserInputType == Enum.UserInputType.MouseButton1 then
                            -- delta dragging: immune to canvas scroll offset entirely
                            local m = UserInputService:GetMouseLocation()
                            dragId, lastMX, lastMY = node.id, m.X, m.Y
                        end
                    end)

                    for i, slot in ipairs(K.ins) do
                        local y = HEAD_H + (i - 1) * ROW_H
                        if not node.fold then
                        new("TextLabel", {
                            Text = slot.label, FontFace = Theme.Fonts.Regular,
                            TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
                            BackgroundTransparency = 1, Position = UDim2.new(0, 13, 0, y),
                            Size = UDim2.new(1, -26, 0, ROW_H),
                            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 36, Parent = f,
                        })
                        end
                        local lit = node.wires and node.wires[slot.key] ~= nil
                        local p = new("TextButton", {
                            Text = "", AutoButtonColor = false, BorderSizePixel = 0,
                            BackgroundColor3 = lit and Theme.Palette.Accent
                                or Theme.Palette.PanelElevated,
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            Position = UDim2.new(0, 0, 0, portY(node, i)),
                            Size = UDim2.new(0, node.fold and 7 or 11, 0, node.fold and 7 or 11),
                            ZIndex = 38, Parent = f,
                        }, { pillCorner(), stroke(Theme.Palette.Border) })
                        p.MouseButton1Click:Connect(function()
                            node.wires = node.wires or {}
                            if pending then
                                local src = nodeById(pending)
                                local SK = src and KINDS[src.kind]
                                if src and SK and SK.outs[slot.type] and src.id ~= node.id then
                                    node.wires[slot.key] = pending
                                end
                                pending = nil
                            else
                                node.wires[slot.key] = nil   -- click a wired dot to unplug
                            end
                            rebuildAll()
                        end)
                    end

                    if next(K.outs) then
                        local op = new("TextButton", {
                            Text = "", AutoButtonColor = false, BorderSizePixel = 0,
                            BackgroundColor3 = (pending == node.id) and Theme.Palette.Accent
                                or Theme.Palette.PanelElevated,
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            Position = UDim2.new(1, 0, 0, portY(node, 1)),
                            Size = UDim2.new(0, 11, 0, 11), ZIndex = 38, Parent = f,
                        }, { pillCorner(), stroke(Theme.Palette.Border) })
                        op.MouseButton1Click:Connect(function()
                            pending = (pending == node.id) and nil or node.id
                            sel = node.id
                            rebuildAll()
                        end)
                    end
                end
            end
            -- v0.48.0: everything alive counts as seen, so the next rebuild
            -- only pops brand-new ids (deleted ids drop out, and pop again
            -- if ever re-added: correct).
            local fresh = {}
            for _, node in ipairs(CF.Nodes) do fresh[node.id] = true end
            nodeSeenIds = fresh
        end

        -- v0.26.1: Design Mode selects the node whose widget you clicked, so the
        -- inspector follows the screen. Last editor built wins, which is the open one.
        Koffee._cfSelect = function(id)
            sel = id
            if rebuildAll then rebuildAll() end
        end
        rebuildAll = function()
            migrate()
            buildNodes()
            redrawWires()
            buildInspector()
            if pending then
                local s = nodeById(pending)
                hint.Text = "Connecting from " .. (s and s.kind or "?")
                    .. ": click a matching input dot"
            elseif note and os.clock() - noteAt < 3 then
                hint.Text = note
            elseif #CF.Nodes == 0 then
                hint.Text = "Add a block above to start"
            else
                hint.Text = "Drag headers to move: output dot, then input dot, to connect"
            end
        end

        local function freeSpot()
            for row = 0, 24 do
                for col = 0, 7 do
                    local x, y = 24 + col * 210, 24 + row * 104
                    local taken = false
                    for _, n in ipairs(CF.Nodes) do
                        if n.x and math.abs(n.x - x) < 8 and math.abs(n.y - y) < 8 then
                            taken = true; break
                        end
                    end
                    if not taken then return x, y end
                end
            end
            return 24, 24
        end

        local function barAt(y, h)
            return new("Frame", {
                Position = UDim2.new(0, 6, 0, y), Size = UDim2.new(1, -12, 0, h or 24),
                BackgroundTransparency = 1, ZIndex = 35, Parent = parent,
            }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
                Padding = UDim.new(0, 5), VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder }) })
        end
        local bar, bar2 = barAt(8, 48), barAt(60)
        -- v0.37.0: bottom-align the top row so "add block" lines up with the dropdown's
        -- box instead of centering against the taller dropdown (it read as "too high").
        local barLayout = bar:FindFirstChildOfClass("UIListLayout")
        if barLayout then barLayout.VerticalAlignment = Enum.VerticalAlignment.Bottom end
        local function say(msg) note, noteAt = msg, os.clock() end
        local pick = ORDER[1]
        local ddw = new("Frame", {
            Size = UDim2.new(0, 216, 0, 48), BackgroundTransparency = 1,
            LayoutOrder = 1, ZIndex = 36, Parent = bar,
        })
        -- v0.42.0: filterable block picker. Typing rebuilds the dropdown
        -- from matching ORDER names (plain substring); empty = full list.
        local searchBox = new("TextBox", {
            Size = UDim2.new(0, 110, 0, 26),
            Text = "", PlaceholderText = "Search",
            ClearTextOnFocus = false, FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, LayoutOrder = 0, ZIndex = 36, Parent = bar,
        }, { corner(4), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingLeft = UDim.new(0, 24) }) })
        local searchIcon = Koffee.lucideIcon(searchBox, "search", 12, Theme.Palette.TextFaint, 37)
        if searchIcon then
            searchIcon.AnchorPoint = Vector2.new(0, 0.5)
            searchIcon.Position = UDim2.new(0, 7, 0.5, 0)
        end
        local pickDD = nil
        local function rebuildPick()
            local q = (searchBox.Text or ""):lower()
            local opts = {}
            for _, n in ipairs(ORDER) do
                if q == "" or n:lower():find(q, 1, true) then opts[#opts + 1] = n end
            end
            if #opts == 0 then opts = { "(no match)" } end
            local keep = false
            for _, n in ipairs(opts) do if n == pick then keep = true break end end
            pick = keep and pick or opts[1]
            if pickDD then pickDD.destroy() end
            pickDD = dropdown(ddw, "Block", opts, pick, function(v) pick = v end)
        end
        searchBox:GetPropertyChangedSignal("Text"):Connect(rebuildPick)
        rebuildPick()
        toolBtn(bar, "Add Block", 110, 2, function()
            if not KINDS[pick] then say("Nothing matches"); return end
            local x, y = freeSpot()
            sel = addNode(pick, x, y)
            rebuildAll()
        end, 30)   -- v0.48.3: the primary action runs larger than its neighbours
        toolBtn(bar2, "Duplicate", 78, 1, function()
            local n = sel and nodeById(sel)
            if not n then say("Select a block first"); rebuildAll(); return end
            local id = 1
            for _, m in ipairs(CF.Nodes) do if m.id >= id then id = m.id + 1 end end
            local o, w = {}, {}
            for k, v in pairs(n.opts or {}) do o[k] = v end
            for k, v in pairs(n.wires or {}) do w[k] = v end
            table.insert(CF.Nodes, { id = id, kind = n.kind, opts = o, wires = w,
                x = (n.x or 24) + 22, y = (n.y or 24) + 22 })
            sel = id
            rebuildAll()
        end)
        toolBtn(bar2, "Copy Graph", 84, 2, function()
            local _, msg = copyGraph(); say(msg); rebuildAll()
        end)
        toolBtn(bar2, "Paste", 60, 3, function()
            -- straight to the popup: reading the clipboard needs an API most
            -- executors do not have, and a silent "no clipboard access" reads as broken
            if not Shared.openTextPopup then say("No text input"); return end
            Shared.openTextPopup("paste graph", "", "paste the KOFFEEGRAPH text here",
                function(txt)
                    local _, msg = pasteGraph(txt)
                    say(msg)
                    rebuildAll()
                end, true)
        end)
        toolBtn(bar2, "Docs", 56, 5, function() docsModal(rebuildAll) end)
        toolBtn(bar2, "Clear", 58, 4, function()
            for i = #CF.Nodes, 1, -1 do CF.Nodes[i] = nil end
            sel, pending = nil, nil
            say("Cleared"); rebuildAll()
        end)
        if extra then toolBtn(bar2, extra.text, 74, 99, extra.fn) end

        canvas.InputBegan:Connect(function(inp)
            if inp.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            local m = UserInputService:GetMouseLocation()
            panning, lastMX, lastMY = true, m.X, m.Y
            if pending or sel then pending, sel = nil, nil; rebuildAll() end
        end)
        connList[#connList + 1] = UserInputService.InputChanged:Connect(function(inp)
            if inp.UserInputType ~= Enum.UserInputType.MouseMovement then return end
            if not canvas.Parent then return end
            local m = UserInputService:GetMouseLocation()
            local dx, dy = m.X - lastMX, m.Y - lastMY
            lastMX, lastMY = m.X, m.Y
            if dragId then
                local node = nodeById(dragId)
                if node then
                    node.x, node.y = math.max(0, node.x + dx), math.max(0, node.y + dy)
                    local f = nodeFrames[dragId]
                    if f then f.Position = UDim2.new(0, node.x, 0, node.y) end
                    redrawWires()
                end
            elseif panning then
                local c = canvas.CanvasPosition
                canvas.CanvasPosition = Vector2.new(c.X - dx, c.Y - dy)
            end
        end)
        connList[#connList + 1] = UserInputService.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 then
                dragId, panning = nil, false
            end
        end)

        rebuildAll()
        return rebuildAll
    end

    local tabConns = {}

    -- v0.37.0 BUFFER LAB (paste + inspect + schema): grab a buffer from an external
    -- spy (Turtle Spy / Cobalt), paste it, decode it, then label its fields into a
    -- reusable schema. Stage 3 (build + fire from a schema) is still to come.
    local function buildBufferLab(parent)
        local RTYPES = { "u8", "i8", "u16", "i16", "u32", "i32", "f32", "f64", "string" }
        local SDIR = "Koffee/buffers"
        local HttpService = game:GetService("HttpService")
        local curBytes = ""
        local fields = {}   -- { { off, type, name } }
        local addType = "f32"
        local refreshFields   -- fwd decl (used by the add-field button below)
        local lastGuesses = {}   -- auto-detected fields, materialized by "auto fields"
        local saneMax = 50000    -- v0.39.0: customizable "plausible float" ceiling for auto-detect

        local function mkBtn(p, text, w, order, fn)
            local b = new("TextButton", {
                Text = text, AutoButtonColor = false, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                Size = UDim2.fromOffset(w, 24), TextColor3 = Theme.Palette.TextMuted,
                LayoutOrder = order, ZIndex = 36, Parent = p,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
            b.MouseEnter:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text }) end)
            b.MouseLeave:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted }) end)
            b.MouseButton1Click:Connect(fn)
            Koffee.attachBtnHover(b, 0, 0.2)   -- v0.48.0: background eases in with the text
            return b
        end
        local function inputBox(p, place, w, order)
            return new("TextBox", {
                Text = "", PlaceholderText = place, ClearTextOnFocus = false,
                FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                Size = w, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = order, ZIndex = 36, Parent = p,
            }, { corner(5), stroke(Theme.Palette.BorderSubtle),
                new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
        end

        local function unescape(s)
            s = s:gsub("\\x(%x%x)", function(h) return string.char(tonumber(h, 16)) end)
            s = s:gsub("\\(%d%d?%d?)", function(d) local n = tonumber(d); return (n and n < 256) and string.char(n) or "" end)
            s = s:gsub("\\n", "\n"):gsub("\\t", "\t"):gsub("\\r", "\r")
            s = s:gsub('\\"', '"'):gsub("\\\\", "\\")
            return s
        end
        local function parsePaste(txt)
            if not txt or txt == "" then return nil, "nothing pasted" end
            local lit = txt:match('fromstring%s*%(%s*"(.-)"') or txt:match("fromstring%s*%(%s*'(.-)'")
            if lit then return unescape(lit) end
            local stripped = txt:gsub("0[xX]", ""):gsub("[%s,]", "")
            if #stripped >= 2 and stripped:match("^%x+$") then
                if #stripped % 2 ~= 0 then stripped = stripped:sub(1, #stripped - 1) end
                local out = {}
                for h in stripped:gmatch("..") do out[#out + 1] = string.char(tonumber(h, 16)) end
                return table.concat(out)
            end
            return txt
        end
        local function readField(off, ty)
            if curBytes == "" then return nil end
            local ok, b = pcall(buffer.fromstring, curBytes)
            if not ok then return nil end
            local n = buffer.len(b)
            local ok2, v = pcall(function()
                if ty == "u8" then return buffer.readu8(b, off) end
                if ty == "i8" then return buffer.readi8(b, off) end
                if ty == "u16" then return buffer.readu16(b, off) end
                if ty == "i16" then return buffer.readi16(b, off) end
                if ty == "u32" then return buffer.readu32(b, off) end
                if ty == "i32" then return buffer.readi32(b, off) end
                if ty == "f32" then return buffer.readf32(b, off) end
                if ty == "f64" then return buffer.readf64(b, off) end
                if ty == "string" then return buffer.readstring(b, off, math.max(0, math.min(16, n - off))) end
            end)
            return ok2 and v or nil
        end

        -- schema files (guarded)
        local function filesOk() return writefile and readfile and isfile and listfiles end
        local function ensureDir()
            if isfolder and makefolder then
                if not isfolder("Koffee") then pcall(makefolder, "Koffee") end
                if not isfolder(SDIR) then pcall(makefolder, SDIR) end
            end
        end
        local function listSchemas()
            local out = {}
            if not filesOk() then return out end
            ensureDir()
            local ok, files = pcall(listfiles, SDIR)
            if ok and type(files) == "table" then
                for _, p in ipairs(files) do
                    local nm = tostring(p):match("([^/\\]+)%.json$")
                    if nm then out[#out + 1] = nm end
                end
            end
            table.sort(out)
            return out
        end

        -- === paste card ===
        local card = panel(parent, "Buffer Lab")
        labelRow(card, "grab a remote's buffer from Turtle Spy / Cobalt and paste it below")
        labelRow(card, "hex, a buffer.fromstring(\"...\") snippet, or raw bytes")
        local box = new("TextBox", {
            Text = "", PlaceholderText = "Paste buffer bytes / fromstring code / hex...",
            ClearTextOnFocus = false, MultiLine = true, TextWrapped = true,
            FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
            BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.15,
            Size = UDim2.new(1, 0, 0, 80), TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top, LayoutOrder = 20, ZIndex = 36, Parent = card,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
                PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
        local pRow = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, LayoutOrder = 21, ZIndex = 36, Parent = card,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
            VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        -- v0.39.0: customizable sanity ceiling: floats bigger than this are treated
        -- as garbage by auto-detect (raise it for big-coordinate maps, lower to be strict).
        local saneBox = inputBox(card, "auto-detect max |value| (default 50000)", UDim2.new(1, 0, 0, 24), 22)

        -- === inspector card ===
        local icard = panel(parent, "Inspector")
        local header = new("TextLabel", {
            Text = "Paste a buffer and hit Decode", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 16), TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1, ZIndex = 36, Parent = icard,
        })
        local ibody = new("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 210), BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.2,
            ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.Palette.TextFaint,
            CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y, LayoutOrder = 2, ZIndex = 35, Parent = icard,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle),
            new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
                PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder }) })
        local dump = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
            AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.fromScale(1, 0), LayoutOrder = 1, ZIndex = 36, Parent = ibody,
        })
        local guess = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Accent,
            BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
            AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.fromScale(1, 0), LayoutOrder = 2, ZIndex = 36, Parent = ibody,
        })

        local function inspect()
            local blen = #curBytes
            header.Text = (blen > 0) and (blen .. " bytes") or "Paste a buffer and hit Decode"
            local lines, shown = {}, math.min(blen, 256)
            for off = 0, shown - 1, 16 do
                local parts = {}
                for j = 0, 15 do
                    local k = off + j
                    if k < shown then parts[#parts + 1] = ("%02X"):format(curBytes:byte(k + 1)) end
                end
                lines[#lines + 1] = ("%04X  %s"):format(off, table.concat(parts, " "))
            end
            if blen > shown then lines[#lines + 1] = ("... (%d more bytes)"):format(blen - shown) end
            dump.Text = table.concat(lines, "\n")
            -- auto-detect: sane f32s (finite, not garbage-huge), Vector3 triplets first.
            -- This is the sanity check: 9e19 as an X, 0 as Y is NOT a position, so
            -- absurd floats are rejected instead of being suggested as fields.
            local guesses = {}
            lastGuesses = {}
            local ok, b = pcall(buffer.fromstring, curBytes)
            if ok and blen > 0 then
                local n = buffer.len(b)
                local function rf(o) local okk, v = pcall(buffer.readf32, b, o); return okk and v or nil end
                local function sane(f)
                    return f ~= nil and f == f and math.abs(f) ~= math.huge
                        and (f == 0 or (math.abs(f) >= 1e-3 and math.abs(f) < saneMax))
                end
                local off = 0
                while off <= n - 4 and #guesses < 40 do
                    if off <= n - 12 then
                        local x, y, z = rf(off), rf(off + 4), rf(off + 8)
                        if sane(x) and sane(y) and sane(z) and not (x == 0 and y == 0 and z == 0) then
                            guesses[#guesses + 1] = ("off %-4d  vec3? (%.1f, %.1f, %.1f)"):format(off, x, y, z)
                            lastGuesses[#lastGuesses + 1] = { off = off, type = "f32", name = "x@" .. off }
                            lastGuesses[#lastGuesses + 1] = { off = off + 4, type = "f32", name = "y@" .. off }
                            lastGuesses[#lastGuesses + 1] = { off = off + 8, type = "f32", name = "z@" .. off }
                            off = off + 12
                            continue
                        end
                    end
                    local x = rf(off)
                    if sane(x) and x ~= 0 then
                        guesses[#guesses + 1] = ("off %-4d  f32 = %.3f"):format(off, x)
                        lastGuesses[#lastGuesses + 1] = { off = off, type = "f32", name = "f32@" .. off }
                    else
                        local oku, u = pcall(buffer.readu32, b, off)
                        if oku and u > 0 and u < 100000 then
                            guesses[#guesses + 1] = ("off %-4d  u32 = %d"):format(off, u)
                            lastGuesses[#lastGuesses + 1] = { off = off, type = "u32", name = "u32@" .. off }
                        end
                    end
                    off = off + 4
                end
            end
            guess.Text = (#guesses > 0) and ("auto-detected (guesses):\n" .. table.concat(guesses, "\n"))
                or "no obvious fields: add them by hand"
        end

        -- === fields / schema card (stage 2) ===
        local fcard = panel(parent, "Fields")
        labelRow(fcard, "label the bytes: an offset + type + name becomes a reusable schema")
        local offBox = inputBox(fcard, "offset (e.g. 4)", UDim2.new(1, 0, 0, 24), 10)
        offBox.LayoutOrder = 10
        local tHold = new("Frame", { Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, LayoutOrder = 11, ZIndex = 36, Parent = fcard })
            dropdown(tHold, "Type", RTYPES, addType, function(v) addType = v end)
        local nameBox = inputBox(fcard, "name (e.g. targetX)", UDim2.new(1, 0, 0, 24), 12)
        nameBox.LayoutOrder = 12
        mkBtn(fcard, "Add Field", 84, 13, function()
            local off = tonumber((offBox.Text or ""):match("%d+"))
            if not off then return end
            local nm = (nameBox.Text ~= "" and nameBox.Text) or (addType .. "@" .. off)
            fields[#fields + 1] = { off = off, type = addType, name = nm }
            offBox.Text, nameBox.Text = "", ""
            refreshFields()
        end).LayoutOrder = 13

        local fieldList = new("Frame", {
            Size = UDim2.fromScale(1, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
            LayoutOrder = 20, ZIndex = 36, Parent = fcard,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 3),
            SortOrder = Enum.SortOrder.LayoutOrder }) })
        local fieldRows = {}
        refreshFields = function()
            for _, r in ipairs(fieldRows) do pcall(function() r:Destroy() end) end
            table.clear(fieldRows)
            for i, fd in ipairs(fields) do
                local v = readField(fd.off, fd.type)
                local vs = (v == nil) and "?" or (type(v) == "number" and (fd.type == "f32" or fd.type == "f64") and ("%.3f"):format(v) or tostring(v))
                local rr = new("Frame", {
                    Size = UDim2.new(1, 0, 0, 20), BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.3,
                    LayoutOrder = i, ZIndex = 36, Parent = fieldList,
                }, { corner(4) })
                new("TextLabel", {
                    Text = ("%s   %s@%d = %s"):format(fd.name, fd.type, fd.off, vs),
                    FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
                    BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
                    Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -34, 1, 0), ZIndex = 37, Parent = rr,
                })
                local xb = new("TextButton", {
                    Text = "X", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Danger,
                    BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -6, 0.5, 0),
                    Size = UDim2.fromOffset(16, 16), ZIndex = 37, Parent = rr,
                })
                xb.MouseButton1Click:Connect(function() table.remove(fields, i); refreshFields() end)
                fieldRows[#fieldRows + 1] = rr
                -- v0.48.0: labeled rows cascade in like Mods rows do; Lists
                -- off (or master off, inside popIn) shows them at rest.
                if Koffee.Anim.spot("AnimLists") then
                    local sc, target, d = uScaleOf(rr), rr, math.min(i * 0.02, 0.3)
                    sc.Scale = 0.96
                    task.delay(d, function()
                        if target.Parent then
                            tween(sc, Theme.Animation.Fast, { Scale = 1 })
                        end
                    end)
                end
            end
        end

        -- schema save / load
        local schemaBox = inputBox(fcard, "schema name...", UDim2.new(1, -160, 0, 24), 30)
        local sRow = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, LayoutOrder = 33, ZIndex = 36, Parent = fcard,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
            VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        local loadHold = new("Frame", { Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, LayoutOrder = 32, ZIndex = 36, Parent = fcard })
        local pickSchema, loadDd = (listSchemas()[1] or ""), nil
        local function rebuildLoadDd()
            if loadDd then pcall(loadDd.destroy) end
            local names = listSchemas()
            if #names == 0 then names = { "no schemas" } end
            loadDd = dropdown(loadHold, "Saved Schemas", names, pickSchema ~= "" and pickSchema or names[1],
                function(v) pickSchema = v end)
        end

        mkBtn(fcard, "Save Schema", 96, 31, function()
            local nm = (schemaBox.Text or ""):gsub("[^%w _%-]", ""):gsub("^%s+", ""):gsub("%s+$", "")
            if nm == "" or not filesOk() then return end
            ensureDir()
            -- v0.39.0: store the pasted bytes as a hex TEMPLATE too, so Build Buffer
            -- can start from this known-good buffer and patch only the labeled fields.
            local tmplHex = {}
            for i = 1, #curBytes do tmplHex[i] = ("%02x"):format(curBytes:byte(i)) end
            local ok = pcall(function()
                writefile(SDIR .. "/" .. nm .. ".json",
                    HttpService:JSONEncode({ fields = fields, template = table.concat(tmplHex) }))
            end)
            if ok then pickSchema = nm; rebuildLoadDd() end
        end).LayoutOrder = 31
        mkBtn(sRow, "Load", 60, 1, function()
            if not filesOk() or pickSchema == "" then return end
            local p = SDIR .. "/" .. pickSchema .. ".json"
            if not isfile(p) then return end
            local ok, txt = pcall(readfile, p)
            if not ok then return end
            local dok, data = pcall(function() return HttpService:JSONDecode(txt) end)
            if dok and type(data) == "table" then
                -- v0.39.0: new format is { fields, template }; old was a bare fields array.
                local flds = (type(data.fields) == "table") and data.fields or data
                fields = {}
                for _, fd in ipairs(flds) do
                    if type(fd) == "table" and fd.off and fd.type then
                        fields[#fields + 1] = { off = fd.off, type = fd.type, name = fd.name or (fd.type .. "@" .. fd.off) }
                    end
                end
                refreshFields()
            end
        end)
        mkBtn(sRow, "Delete", 66, 2, function()
            if not (filesOk() and delfile) or pickSchema == "" then return end
            local p = SDIR .. "/" .. pickSchema .. ".json"
            if isfile(p) then pcall(delfile, p) end
            pickSchema = ""
            rebuildLoadDd()
        end)

        -- decode / clear in the paste card
        mkBtn(pRow, "Decode", 84, 1, function()
            local bytes, err = parsePaste(box.Text)
            if not bytes then header.Text = err or "Nothing to decode"; return end
            saneMax = tonumber((saneBox.Text or ""):match("[%d%.]+")) or 50000
            curBytes = bytes
            inspect()
            refreshFields()
        end)
        mkBtn(pRow, "Auto Fields", 92, 2, function()
            if #lastGuesses == 0 then return end
            fields = {}
            for _, g in ipairs(lastGuesses) do fields[#fields + 1] = { off = g.off, type = g.type, name = g.name } end
            refreshFields()
        end)
        mkBtn(pRow, "Clear", 60, 3, function()
            box.Text = ""; curBytes = ""; inspect(); refreshFields()
        end)

        inspect()
        refreshFields()
        rebuildLoadDd()
    end

    addTab("Custom", function(root)
        for _, c in ipairs(tabConns) do pcall(function() c:Disconnect() end) end
        tabConns = {}

        -- v0.35.0: Features (node graph) + Buffers (Buffer Lab) as sub-tabs.
        local switchCard = panel(root)
        local subs = Shared.subTabs(switchCard, { "Features", "Buffers" })
        local feat, buffs = subs.Features, subs.Buffers

        local card = panel(feat, "Custom Features")
        configCheckbox(card, "Enabled", CF.Enabled, function(v) CF.Enabled = v end)
        -- v0.24.0: design-pixel scale. Auto tracks screen height off a 1080p base.
        dropdown(card, "UI Scale", SCALE_NAMES, CF.Scale, function(v) CF.Scale = v end)
        labelRow(card, "scales every custom widget together. Auto follows screen height")
        -- v0.25.0: not persisted: design mode is a session tool, never a saved state
        configCheckbox(card, "Design Mode", false, function(v) Koffee._designMode(v) end)
        labelRow(card, "closes the window. click a widget to select, drag to move")
        labelRow(card, "corner dots resize, green dot rotates, arrows nudge, esc deselects")

        local frame = new("Frame", {
            Size = UDim2.new(1, 0, 0, 452), BackgroundColor3 = Theme.Palette.Background,
            BackgroundTransparency = 0.2, BorderSizePixel = 0, ClipsDescendants = true,
            Active = true, LayoutOrder = 50, ZIndex = 33, Parent = feat,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle) })

        local refresh
            refresh = makeEditor(frame, tabConns, { text = "Expand", fn = function()
            local vp = viewport()
            if not Shared.openModal then return end
            local m = Shared.openModal(math.max(620, vp.X - 80), math.max(460, vp.Y - 80))
            local mConns = {}
            makeEditor(m.box, mConns, { text = "Close", fn = function()
                for _, c in ipairs(mConns) do pcall(function() c:Disconnect() end) end
                m.close()
                refresh()          -- pick up whatever was edited in the big view
            end })
        end })

        buildBufferLab(buffs)
    end)
end)()

addTab("Configs", function(root)
    local CIO = Koffee.Config

    -- v0.0.47: pill button whose resting colour can flip at runtime (the `auto`
    -- button toggles accent/muted). Base colour is stored as an attribute so the
    -- MouseLeave handler always restores the CURRENT base, not the creation-time one.
    local function mkBtn(parent, text, width, onClick, accent)
        local b = new("TextButton", {
            Text = text, AutoButtonColor = false,
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(0, width, 0, 26),
            ZIndex = 36, Parent = parent,
        }, { corner(5), stroke(Theme.Palette.BorderSubtle) })
        b:SetAttribute("accentBase", accent and true or false)
        local function base()
            return b:GetAttribute("accentBase") and Theme.Palette.Accent or Theme.Palette.TextMuted
        end
        b.TextColor3 = base()
        b.MouseEnter:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text }) end)
        b.MouseLeave:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = base() }) end)
        b.MouseButton1Click:Connect(onClick)
        Koffee.attachBtnHover(b, 0, 0.2)   -- v0.48.0: background eases in with the text
        return b
    end

    -- :: manager card ::
    local card = panel(root, "Config Manager")

    local status = new("TextLabel", {
            Text = "Select a config, or type a name to create one",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1, ZIndex = 35, Parent = card,
    })
    local function setStatus(msg, ok)
        status.Text = msg
        status.TextColor3 = ok and Theme.Palette.Success or Theme.Palette.Danger
    end

    -- selected-config state. The dropdown is REBUILT from disk on any data change
    -- (create / delete / refresh) so it always mirrors what's actually saved.
    local selectedName, hasConfigs, currentDD = nil, false, nil
    local rebuildManager   -- fwd decl
    local refreshCloud     -- v0.29.0 fwd decl: cloud card reacts to selection changes
    local refreshAuto      -- v0.56.0 fwd decl: auto-load card reacts to selection changes

    local ddHolder = new("Frame", {
        Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1,
        LayoutOrder = 2, ZIndex = 35, Parent = card,
    })

    -- action row for the SELECTED config
    local actionRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
        LayoutOrder = 3, ZIndex = 35, Parent = card,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder }) })

    -- new-config row
    local newRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1,
        LayoutOrder = 4, ZIndex = 35, Parent = card,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local nameBox = new("TextBox", {
            Text = "", PlaceholderText = "New config name...", ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
        BorderSizePixel = 0, Size = UDim2.new(1, -150, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, ZIndex = 36, Parent = newRow,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }) })

    -- the `auto` button reflects whether the selected config is the auto-load one
    local autoBtn
    local function refreshAutoLabel()
        if not autoBtn then return end
        local isAuto = selectedName ~= nil and CIO.getAuto() == selectedName
            autoBtn.Text = isAuto and "Auto*" or "Auto"
        autoBtn:SetAttribute("accentBase", isAuto)
        autoBtn.TextColor3 = isAuto and Theme.Palette.Accent or Theme.Palette.TextMuted
    end

    local function needSel()
        if hasConfigs and selectedName then return true end
        setStatus("No config selected", false)
        return false
    end

    -- selected-config actions (read selectedName live)
    mkBtn(actionRow, "Load", 60, function()
        if not needSel() then return end
        local ok, msg = CIO.load(selectedName)
            if ok then setStatus("Loaded: " .. tostring(selectedName), true)
            else setStatus("Load failed: " .. tostring(msg), false) end
    end, true).LayoutOrder = 1
    mkBtn(actionRow, "Overwrite", 90, function()
        if not needSel() then return end
        local ok, msg = CIO.save(selectedName)   -- same filename -> overwrites in place
            if ok then setStatus("Overwrote: " .. tostring(selectedName), true)
            else setStatus("Overwrite failed: " .. tostring(msg), false) end
    end).LayoutOrder = 2
    mkBtn(actionRow, "Rename", 72, function()
        if not needSel() then return end
        if not Shared.openTextPopup then return end
        local from = selectedName
        Shared.openTextPopup("rename config", from, "new name", function(txt)
            local ok, msg = CIO.rename(from, txt)
            if not ok then setStatus("Rename failed: " .. tostring(msg), false); return end
            -- carry any auto-load rules across, or they point at a file that is gone
            CIO.autoRename(from, msg)
            CIO.cloudMetaRename(from, msg)   -- v0.29.0: keep the cloud link on the new name
            selectedName = msg
            rebuildManager()
            setStatus("Renamed: " .. from .. " -> " .. msg, true)
        end)
    end).LayoutOrder = 3
    mkBtn(actionRow, "Delete", 66, function()
        if not needSel() then return end
        local nm = selectedName
        -- v0.0.50 fix (two bugs):
        --   1. CIO.delete's return was discarded: a failed/unavailable delfile
        --      still reported "deleted", and the name stayed on disk.
        --   2. deleting the auto-load config left the _auto_<PlaceId> marker
        --      pointing at a file that no longer exists, so auto-load silently
        --      did nothing every session with no way to notice from the UI.
        local ok = CIO.delete(nm)
        if ok then CIO.autoDrop(nm) end   -- clear any auto-load rules pointing at it
        if ok then CIO.cloudMetaDrop(nm) end   -- v0.29.0: drop the local cloud link (cloud entry stays)
        selectedName = nil
        rebuildManager()
            if ok then setStatus("Deleted: " .. nm, true)
            else setStatus("Delete failed: " .. nm, false) end
    end).LayoutOrder = 4
    autoBtn = mkBtn(actionRow, "Auto", 58, function()
        if not needSel() then return end
            if CIO.getAuto() == selectedName then CIO.setAuto(nil); setStatus("Auto-load cleared", true)
            else CIO.setAuto(selectedName); setStatus("Auto-load: " .. selectedName, true) end
        refreshAutoLabel()
        if refreshAuto then refreshAuto() end
    end)
    autoBtn.LayoutOrder = 5

    -- new-config actions
    mkBtn(newRow, "Create", 66, function()
        local ok, msg = CIO.save(nameBox.Text)
        if ok then
            selectedName = msg
            nameBox.Text = ""
            rebuildManager()
            setStatus("Created: " .. tostring(msg), true)
            else setStatus("Create failed: " .. tostring(msg), false) end
    end, true).LayoutOrder = 2
    mkBtn(newRow, "Refresh", 66, function() rebuildManager(); setStatus("Refreshed", true) end).LayoutOrder = 3

    -- (re)build the selector from disk, keeping the current selection valid.
    rebuildManager = function()
        local names = CIO.list()
        hasConfigs = (#names > 0)
        if selectedName then
            local found = false
            for _, n in ipairs(names) do if n == selectedName then found = true; break end end
            if not found then selectedName = nil end
        end
        if not selectedName and hasConfigs then selectedName = names[1] end

        if currentDD then currentDD.destroy(); currentDD = nil end
        local options = hasConfigs and names or { "no saved configs" }
            currentDD = dropdown(ddHolder, "Saved Configs", options,
            selectedName or "no saved configs", function(v)
                if hasConfigs then selectedName = v; refreshAutoLabel(); if refreshCloud then refreshCloud() end; if refreshAuto then refreshAuto() end end
            end)
        refreshAutoLabel()
        if refreshCloud then refreshCloud() end
        if refreshAuto then refreshAuto() end
    end

    -- :: cloud configs card (v0.29.0) ::
    -- Share/sync configs through the cloud. Operates on the SELECTED config above.
    -- Upload creates (you become owner) or overwrites (owner only); download pulls
    -- any 8-char id into a local config; delete/rename hit the cloud (owner only).
    local cloudCard = panel(root, "Cloud Configs")
    local cloudStatus = new("TextLabel", {
            Text = "Select a config above, then upload, or paste an ID to download",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 16), TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1, ZIndex = 35, Parent = cloudCard,
    })
    local function setCloud(msg, ok)
        cloudStatus.Text = msg
        cloudStatus.TextColor3 = ok and Theme.Palette.Success or Theme.Palette.Danger
    end

    -- download row: id box + button
    local dlRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1,
        LayoutOrder = 2, ZIndex = 35, Parent = cloudCard,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local idBox = new("TextBox", {
            Text = "", PlaceholderText = "Cloud ID (8 chars)...", ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
        BorderSizePixel = 0, Size = UDim2.new(1, -130, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, ZIndex = 36, Parent = dlRow,
    }, { corner(5), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }) })

    -- cloud action rows (buttons created up front, visibility toggled by refreshCloud)
    local function cloudActionRow(order)
        return new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
            LayoutOrder = order, ZIndex = 35, Parent = cloudCard,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder }) })
    end
    local cloudRow  = cloudActionRow(3)   -- upload + copy id
    local cloudRow2 = cloudActionRow(4)   -- delete cloud + rename cloud (owner only)

    local busyCloud = false
    local function guard() if busyCloud then return false end busyCloud = true return true end

    local dlBtn = mkBtn(dlRow, "Download", 118, function()
        if not guard() then return end
        local id = idBox.Text
            setCloud("Downloading " .. tostring(id):upper():gsub("%s+", "") .. "...", true)
        task.spawn(function()
            local name, err = CIO.cloudDownload(id)
            if name then
                idBox.Text = ""
                selectedName = name
                rebuildManager()
                setCloud('Downloaded "' .. name .. '"', true)
            else
                setCloud("Download failed: " .. tostring(err), false)
            end
            busyCloud = false
        end)
    end, true)
    dlBtn.LayoutOrder = 2

    local upBtn = mkBtn(cloudRow, "Upload", 100, function()
            if not (hasConfigs and selectedName) then setCloud("No config selected", false); return end
        if not guard() then return end
        local nm = selectedName
        setCloud('uploading "' .. nm .. '"...', true)
        task.spawn(function()
            local id, err = CIO.cloudUpload(nm)
            if id then
                if setclipboard then pcall(setclipboard, id) end
                setCloud("Cloud ID: " .. id .. (setclipboard and " (copied)" or ""), true)
            else
                setCloud("Upload failed: " .. tostring(err), false)
            end
            rebuildManager()
            busyCloud = false
        end)
    end, true)
    upBtn.LayoutOrder = 1

    local copyBtn = mkBtn(cloudRow, "Copy ID", 78, function()
        local meta = selectedName and CIO.cloudMetaFor(selectedName)
            if not (meta and meta.id) then setCloud("Not cloud-linked", false); return end
            if setclipboard and pcall(setclipboard, meta.id) then setCloud("Copied " .. meta.id, true)
            else setCloud("ID: " .. meta.id .. " (no clipboard)", true) end
    end)
    copyBtn.LayoutOrder = 2

    local delBtn = mkBtn(cloudRow2, "Delete Cloud", 108, function()
        if not (hasConfigs and selectedName) then return end
        if not guard() then return end
        local nm = selectedName
            setCloud("Deleting from cloud...", true)
        task.spawn(function()
            local ok, err = CIO.cloudDelete(nm)
            if ok then setCloud("Deleted from cloud (local kept)", true)
            else setCloud("Delete failed: " .. tostring(err), false) end
            rebuildManager()
            busyCloud = false
        end)
    end)
    delBtn.LayoutOrder = 3

    local rnBtn = mkBtn(cloudRow2, "Rename Cloud", 108, function()
        if not (hasConfigs and selectedName) then return end
        if not guard() then return end
        local nm = selectedName
            setCloud("Renaming cloud entry...", true)
        task.spawn(function()
            local ok, err = CIO.cloudRename(nm)   -- pushes the local name up to the cloud
            if ok then setCloud('cloud renamed to "' .. nm .. '"', true)
            else setCloud("Rename failed: " .. tostring(err), false) end
            busyCloud = false
        end)
    end)
    rnBtn.LayoutOrder = 4

    -- upload always shows; copy/delete/rename are contextual (linked / owner-only)
    refreshCloud = function()
        local has   = hasConfigs and selectedName ~= nil
        local meta  = has and CIO.cloudMetaFor(selectedName) or nil
        local owner = has and CIO.cloudIsOwner(selectedName)
        upBtn.Text        = (meta and owner) and "Overwrite" or "Upload"
        copyBtn.Visible   = meta ~= nil
        delBtn.Visible    = has and owner and meta ~= nil
        rnBtn.Visible     = has and owner and meta ~= nil
    end

    -- :: auto-load rules card (v0.56.0) ::
    -- Pin a config to load on join. ONE global rule loads in every game; per-game
    -- rules load only in their own game and beat the global there. Each rule has
    -- its own on/off switch. Operates on the SELECTED config above.
    local autoCard = panel(root, "Auto-Load")
    new("TextLabel", {
        Text = "Pin a config to load on join. A per-game rule beats the global one in its game.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left,
        AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 14), LayoutOrder = 1, ZIndex = 35, Parent = autoCard,
    })
    local autoStatusLbl = new("TextLabel", {
        Text = "", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
        Size = UDim2.new(1, 0, 0, 14), LayoutOrder = 2, ZIndex = 35, Parent = autoCard,
    })
    local function setAutoStatus(msg, ok)
        autoStatusLbl.Text = msg
        autoStatusLbl.TextColor3 = ok and Theme.Palette.Success or Theme.Palette.Danger
    end

    -- compact add row: a scope pill (toggles This Game / Global), a fixed Add Rule
    -- button, and a muted label naming the config the button will pin.
    local addRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, LayoutOrder = 3, ZIndex = 35, Parent = autoCard,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8),
        VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
    local scopeVal = "This Game"
    local scopePill = new("TextButton", {
        Text = "This Game", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Accent, BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true,
        Size = UDim2.fromOffset(104, 26), LayoutOrder = 1, ZIndex = 36, Parent = addRow,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
    scopePill.MouseButton1Click:Connect(function()
        scopeVal = (scopeVal == "This Game") and "Global" or "This Game"
        scopePill.Text = scopeVal
    end)
    local addBtn = mkBtn(addRow, "Add Rule", 84, function()
        if not (hasConfigs and selectedName) then setAutoStatus("Select a config above first", false); return end
        if scopeVal == "Global" then CIO.autoSetGlobal(selectedName); setAutoStatus("Global auto-load: " .. selectedName, true)
        else CIO.autoSetGame(selectedName); setAutoStatus("This game auto-load: " .. selectedName, true) end
        refreshAuto()
        refreshAutoLabel()
    end, true)
    addBtn.LayoutOrder = 2
    local selInfo = new("TextLabel", {
        Text = "", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
        Size = UDim2.new(1, -204, 1, 0), LayoutOrder = 3, ZIndex = 35, Parent = addRow,
    })

    local rulesList = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
        LayoutOrder = 4, ZIndex = 35, Parent = autoCard,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 5),
        SortOrder = Enum.SortOrder.LayoutOrder }) })

    refreshAuto = function()
        selInfo.Text = (hasConfigs and selectedName) and ("-> " .. selectedName) or "(select a config above)"
        for _, c in ipairs(rulesList:GetChildren()) do
            if not c:IsA("UIListLayout") then c:Destroy() end
        end
        local rules = CIO.autoRules()
        if #rules == 0 then
            new("TextLabel", {
                Text = "No auto-load rules yet.", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                Size = UDim2.new(1, 0, 0, 16), ZIndex = 36, Parent = rulesList,
            })
            return
        end
        for i, r in ipairs(rules) do
            local row = new("Frame", {
                Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.4,
                BorderSizePixel = 0, LayoutOrder = i, ZIndex = 36, Parent = rulesList,
            }, { corner(6), stroke(Theme.Palette.BorderSubtle),
                new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 6) }),
                new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
                    VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
            -- on/off pill
            local toggle = new("TextButton", {
                Text = r.on and "ON" or "OFF", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
                TextColor3 = r.on and Theme.Palette.Success or Theme.Palette.TextMuted,
                BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true,
                Size = UDim2.fromOffset(40, 22), LayoutOrder = 1, ZIndex = 37, Parent = row,
            }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
            local badge = (r.scope == "global") and "Global"
                or (r.place .. (r.current and " (current)" or ""))
            new("TextLabel", {
                Text = badge .. "  ->  " .. r.name, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = (r.scope == "global") and Theme.Palette.Text or Theme.Palette.Accent,
                BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
                Size = UDim2.new(1, -74, 1, 0), LayoutOrder = 2, ZIndex = 37, Parent = row,
            })
