-- v0.52.0: NPC subsystem. Adds custom models (or whole directories) as targets
-- so aimbot, silent aim and a dedicated ESP treat them like players. Own IIFE
-- for its register budget; publishes Shared.NPC for the Combat engine to read.
;(function()
-- v0.57.0: ExcludeNames/ExcludeSigs feed the Username auto-scan (persist between
-- configs); _excludeSel is a session-only instance set (underscore -> not saved).
local NPC = { Entries = {}, Folders = {}, _nid = 0, _fid = 0, _gen = 0,
    ExcludeNames = {}, ExcludeSigs = {}, _excludeSel = {} }
Shared.NPC = NPC
-- v0.54.0: persist entries + folders. The serializer skips underscore keys
-- (_inst/_wrappers/_cache/_nid/_fid) and functions, so only kind/path/sig/name/
-- method/parentPath/folderId/moduleId + folder name/settings save. Lists REPLACE on load.
registerConfig("npc", NPC)
function NPC.reconcile(savedModules)
    -- after a config load: hand every loaded entry a fresh session-unique module
    -- id, so two configs never share one npc_* row for different NPCs (rapid A/B
    -- swaps with overlapping counters used to collide). Saved on/off rides along
    -- via the passed modules snapshot, keyed by each entry's OLD module id.
    -- v0.67.0: ids are npc_g<load gen>_<entry id>. Stale npc_* modules are first
    -- disabled, then dropped from the registry so ghosts never pile up.
    NPC._gen = (NPC._gen or 0) + 1
    local gen = NPC._gen
    local present, drop = {}, {}
    local maxN, maxF = NPC._nid or 0, NPC._fid or 0
    for _, e in ipairs(NPC.Entries) do
        local oldId = e.moduleId
        e.moduleId = "npc_g" .. gen .. "_" .. (e.id or 0)
        present[e.moduleId] = true
        registerModule(e.moduleId, "npc: " .. (e.name or "?"), function() end, function() end)
        local want = savedModules and savedModules[oldId]
        if want then toggleModule(e.moduleId) end
        if (e.id or 0) > maxN then maxN = e.id end
    end
    for id, m in pairs(Modules) do
        if type(id) == "string" and id:sub(1, 4) == "npc_" and not present[id] then
            if m.Enabled then toggleModule(id) end
            drop[#drop + 1] = id
        end
    end
    for _, id in ipairs(drop) do Modules[id] = nil end
    for _, f in ipairs(NPC.Folders) do if (f.id or 0) > maxF then maxF = f.id end end
    NPC._nid, NPC._fid = maxN, maxF
end
local UIS = game:GetService("UserInputService")

local function newFolderSettings()
    -- v0.53.0: styling now lives in the global NPC ESP tab (Shared.NPCESP). Folder
    -- settings are the per-group knobs: name override, per-feature exclusions, rules.
    return {
        DisplayName = "",
        Exclude = { ESP = false, Aimbot = false, Silent = false },
        Rules = {},
        AutoUsername = false,   -- v0.57.0: scan the workspace for player usernames
        AutoRules = {},         -- v0.90.0: auto-add anything whose name matches a rule
    }
end
local DEFAULTS = newFolderSettings()

-- :: re-acquire ::
-- v0.57.0: learning captures a name-INDEPENDENT structural fingerprint so a rig
-- can be re-found after it is renamed / re-added, even when a game randomizes the
-- names of Workspace's children on a timer (directory obfuscation). The signature
-- never contains a name: it is the instance's class, its children's class counts,
-- a Humanoid flag, and (for bare parts) a rounded size. Enrichment lowers the
-- false-match rate of a deep scan without leaning on any name.
local function signature(inst)
    if not inst then return "" end
    local counts = {}
    for _, ch in ipairs(inst:GetChildren()) do
        counts[ch.ClassName] = (counts[ch.ClassName] or 0) + 1
    end
    local keys = {}
    for k in pairs(counts) do keys[#keys + 1] = k end
    table.sort(keys)
    local parts = { inst.ClassName }
    if inst:FindFirstChildOfClass("Humanoid") then parts[#parts + 1] = "H" end
    if inst:IsA("BasePart") then
        parts[#parts + 1] = "S" .. math.floor(inst.Size.X + 0.5) .. "x"
            .. math.floor(inst.Size.Y + 0.5) .. "x" .. math.floor(inst.Size.Z + 0.5)
    end
    for _, k in ipairs(keys) do parts[#parts + 1] = k .. ":" .. counts[k] end
    return table.concat(parts, ",")
end
local function eligible(inst)
    return (inst:IsA("Model") or inst:IsA("BasePart")) and npcAnchor(inst) ~= nil
end

-- cached Workspace descendant snapshot shared by every deep scan in a frame, so a
-- burst of missing entries costs one GetDescendants, not one each. Capped so a
-- pathological workspace can never stall a frame.
local _wsSnap, _wsAt = nil, 0
local function wsDescendants()
    local now = os.clock()
    if _wsSnap and (now - _wsAt) < 0.4 then return _wsSnap end
    local ok, d = pcall(function() return Workspace:GetDescendants() end)
    _wsSnap = (ok and type(d) == "table") and d or {}
    _wsAt = now
    return _wsSnap
end
local function deepFindBySig(sig)
    if not sig or sig == "" then return nil end
    for _, inst in ipairs(wsDescendants()) do
        if eligible(inst) and signature(inst) == sig then return inst end
    end
    return nil
end
local function deepFindByName(name)
    if not name or name == "" then return nil end
    local ln = name:lower()
    for _, inst in ipairs(wsDescendants()) do
        if eligible(inst) and inst.Name:lower() == ln then return inst end
    end
    return nil
end

-- capture (or refresh) an entry's fingerprint from its current live instance.
function NPC.learn(entry, inst)
    inst = inst or entry._inst
    if not (inst and inst.Parent) then return false end
    entry.path = Shared.pathOf(inst)
    entry.parentPath = inst.Parent and Shared.pathOf(inst.Parent) or nil
    entry.sig = signature(inst)
    entry.name = inst.Name
    entry._inst = inst
    return true
end

local function folderById(id)
    for _, f in ipairs(NPC.Folders) do if f.id == id then return f end end
    return nil
end
local function settingsFor(entry)
    local f = entry.folderId and folderById(entry.folderId)
    return (f and f.settings) or DEFAULTS
end

-- method-aware instance resolution. Live pointer first (free); then the entry's
-- chosen method; then a name-independent signature deep scan as a universal safety
-- net so even a Path entry recovers under obfuscation. Throttled when nothing is
-- found so a genuinely-gone entry does not deep-scan every frame.
local function resolveInstance(entry)
    local inst = entry._inst
    if inst and inst.Parent then return inst end
    local now = os.clock()
    if now < (entry._nextTry or 0) then return nil end
    local method = entry.method or "Path"
    inst = nil
    if method == "Name" then
        inst = deepFindByName(entry.name)
    elseif method == "Signature" then
        inst = deepFindBySig(entry.sig)
    else   -- Path
        inst = Shared.resolvePath(entry.path)
        if not (inst and inst.Parent) then inst = nil end
    end
    -- universal fallbacks (in method order of cheapness) so any method survives
    if not inst then inst = Shared.resolvePath(entry.path); if not (inst and inst.Parent) then inst = nil end end
    if not inst then inst = deepFindBySig(entry.sig) end
    entry._inst = inst
    if inst then
        entry._nextTry = 0
        entry.path = Shared.pathOf(inst); entry.name = inst.Name
    else
        entry._nextTry = now + 0.5
    end
    return inst
end

local function resolveEntry(entry)
    local inst = resolveInstance(entry)
    if not inst then return {} end
    -- v0.90.0: a single entry that points at a Folder (or any non-model container)
    -- is really a directory of NPCs; drawing the container itself errored every frame
    if entry.kind == "dir" or not (inst:IsA("Model") or inst:IsA("BasePart")) then
        -- v0.53.0: any child with a usable anchor part counts (Model or BasePart),
        -- no Humanoid required, so a folder of props / mobs / parts all work.
        local out = {}
        for _, ch in ipairs(inst:GetChildren()) do
            if eligible(ch) then out[#out + 1] = ch end
        end
        return out
    end
    return { inst }
end

-- :: exclusions + username auto-scan (v0.57.0) ::
-- Global filter lists feed the per-folder Username scan: an instance is skipped if
-- it is in the session selection set, its name contains an excluded name, or its
-- fingerprint matches a learned exclusion. Names + learned sigs persist; the
-- selection set is session-only.
local function isExcludedInst(inst)
    if NPC._excludeSel[inst] then return true end
    local lname = inst.Name:lower()
    for _, n in ipairs(NPC.ExcludeNames) do
        if n ~= "" and lname:find(n:lower(), 1, true) then return true end
    end
    if #NPC.ExcludeSigs > 0 then
        local sig = signature(inst)
        for _, s in ipairs(NPC.ExcludeSigs) do if s == sig then return true end end
    end
    return false
end
-- live usernames in the server (Name + DisplayName), minus our own.
local function serverUsernames()
    local set = {}
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            if p.Name and p.Name ~= "" then set[#set + 1] = p.Name:lower() end
            if p.DisplayName and p.DisplayName ~= "" and p.DisplayName:lower() ~= p.Name:lower() then
                set[#set + 1] = p.DisplayName:lower()
            end
        end
    end
    return set
end
-- scan the workspace for anything whose NAME CONTAINS a live username (v0.57.0
-- decision: contains, case-insensitive), not excluded. Cached ~1.2s: cheap enough
-- to re-run so new spawns appear and left players drop, without per-frame cost.
local _uScan, _uScanAt = nil, 0
local function usernameMatches()
    local now = os.clock()
    if _uScan and (now - _uScanAt) < 1.2 then return _uScan end
    local names = serverUsernames()
    local out = {}
    if #names > 0 then
        for _, inst in ipairs(wsDescendants()) do
            if inst:IsA("Model") and npcAnchor(inst) and not isExcludedInst(inst) then
                local lname = inst.Name:lower()
                for _, u in ipairs(names) do
                    if lname:find(u, 1, true) then out[#out + 1] = inst; break end
                end
            end
        end
    end
    _uScan, _uScanAt = out, now
    return out
end
-- v0.82.0: every workspace Humanoid model nobody owns. Same 1.2s cache shape
-- as the username scan. Player characters never match (owned), corpses do
-- (combat death-gates them; ESP shows them like dead players).
local _aScan, _aScanAt = nil, 0
local function allHumanoids()
    local now = os.clock()
    if _aScan and (now - _aScanAt) < 1.2 then return _aScan end
    local out = {}
    for _, inst in ipairs(wsDescendants()) do
        if inst:IsA("Model") and inst:FindFirstChildOfClass("Humanoid")
            and npcAnchor(inst) and not isExcludedInst(inst)
            and not Players:GetPlayerFromCharacter(inst) then
            out[#out + 1] = inst
        end
    end
    _aScan, _aScanAt = out, now
    return out
end
NPC.allHumanoids = allHumanoids

-- v0.90.0 AUTO-ADD RULES: a folder's rules pull matching workspace instances in on
-- their own. A rule matches by name (contains / is / starts with / ends with /
-- pattern), optionally only inside an ancestor whose name contains `inside`, and
-- takes the match itself, its children, or Auto (models / parts are NPCs, anything
-- else hands over its children). Stored on NPC (not locals) for the register budget.
-- a label-less dropdown still reserves its label row above the button; flatten it
-- so it sits in a single 26px row beside a text box
function NPC._flatDD(d)
    for _, c in ipairs(d.frame:GetChildren()) do
        if c:IsA("TextLabel") then c.Visible = false
        elseif c:IsA("TextButton") then c.Position = UDim2.new(0, 0, 0, 0) end
    end
end
function NPC._nameMatch(rule, name)
    local v = rule.value or ""
    if v == "" then return false end
    local m = rule.match or "contains"
    if m == "pattern" then
        local ok, r = pcall(string.find, name, v)
        return ok and r ~= nil
    end
    local n, lv = name:lower(), v:lower()
    if m == "is" then return n == lv end
    if m == "starts with" then return n:sub(1, #lv) == lv end
    if m == "ends with" then return n:sub(-#lv) == lv end
    return n:find(lv, 1, true) ~= nil
end
function NPC.ruleMatches(rule)
    local out = {}
    if rule.on == false or (rule.value or "") == "" then return out end
    local inside = (rule.inside or ""):lower()
    local take = rule.take or "Auto"
    local myChar = LocalPlayer.Character
    local function ok(inst)
        if not eligible(inst) or isExcludedInst(inst) then return false end
        if rule.humanoid and not (inst:IsA("Model") and inst:FindFirstChildOfClass("Humanoid")) then return false end
        if inst == myChar or Players:GetPlayerFromCharacter(inst) then return false end
        return true
    end
    for _, inst in ipairs(wsDescendants()) do
        if NPC._nameMatch(rule, inst.Name) then
            local within = inside == ""
            if not within then
                local a = inst.Parent
                while a and a ~= game do
                    if a.Name:lower():find(inside, 1, true) then within = true; break end
                    a = a.Parent
                end
            end
            if within then
                local self = take == "Itself" or (take == "Auto" and (inst:IsA("Model") or inst:IsA("BasePart")))
                if self then
                    if ok(inst) then out[#out + 1] = inst end
                else
                    for _, ch in ipairs(inst:GetChildren()) do
                        if ok(ch) then out[#out + 1] = ch end
                    end
                end
            end
        end
    end
    return out
end
-- every rule of a folder, cached ~1.2s and invalidated the moment a rule changes
function NPC.folderRuleMatches(f)
    local rules = f.settings and f.settings.AutoRules
    if not rules or #rules == 0 then return {} end
    local parts = {}
    for _, r in ipairs(rules) do
        parts[#parts + 1] = table.concat({ tostring(r.on), r.match or "", r.value or "", r.take or "",
            r.inside or "", tostring(r.humanoid) }, "\1")
    end
    local key = table.concat(parts, "\2")
    local now = os.clock()
    if f._rScan and f._rKey == key and (now - (f._rAt or 0)) < 1.2 then return f._rScan end
    local out, seen = {}, {}
    for _, r in ipairs(rules) do
        for _, inst in ipairs(NPC.ruleMatches(r)) do
            if not seen[inst] then seen[inst] = true; out[#out + 1] = inst end
        end
    end
    f._rScan, f._rKey, f._rAt = out, key, now
    return out
end

-- read a value off a model for a Name or Health rule (child value, attribute,
-- or a direct property). Missing reads return nil so the default is kept.
local function readByRule(model, rule)
    if not (model and rule and rule.key and rule.key ~= "") then return nil end
    local src = rule.src or "child"
    if src == "attribute" then
        return model:GetAttribute(rule.key)
    elseif src == "property" then
        local ok, v = pcall(function() return model[rule.key] end)
        return ok and v or nil
    end
    local ch = model:FindFirstChild(rule.key, true)
    if not ch then return nil end
    local ok, v = pcall(function() return ch.Value end)
    if ok and v ~= nil then return v end
    return ch.Name
end

local function wrapperFor(entry, model)
    entry._wrappers = entry._wrappers or {}
    local w = entry._wrappers[model]
    if not w then
        w = { Character = model, Name = model.Name, DisplayName = model.Name, _npc = true }
        entry._wrappers[model] = w
    end
    return w
end

-- flat list of live NPC entities, TTL-memoised so aim + silent + trigger + ESP
-- share one resolve per frame. Each row quacks like a player for the engine.
function NPC.entities()
    local now = os.clock()
    if NPC._cache and (now - (NPC._cacheAt or 0)) < 0.03 then return NPC._cache end
    local out = {}
    local seen = {}   -- v0.57.0: a model appears once, whoever finds it first
    -- one entity from a resolved model, applying a settings bundle's name/health
    -- rules and display-name override. `holder` owns the wrapper cache.
    local function emit(holder, model, st)
        if seen[model] or not (model:IsA("Model") or model:IsA("BasePart")) or not npcAnchor(model) then return end
        seen[model] = true
        local hum = model:FindFirstChildOfClass("Humanoid")
        local nm = st.DisplayName ~= "" and st.DisplayName or model.Name
        local hp = hum and hum.Health or 0
        for _, rule in ipairs(st.Rules) do
            if rule.kind == "Name" then
                local v = readByRule(model, rule)
                if v ~= nil then nm = tostring(v) end
            elseif rule.kind == "Health" then
                local v = tonumber(readByRule(model, rule))
                if v then hp = v end
            end
        end
        local w = wrapperFor(holder, model)
        w.Name, w.DisplayName = nm, nm
        out[#out + 1] = { wrapper = w, char = model, hum = hum, name = nm, health = hp, exclude = st.Exclude }
    end
    -- manually learned entries + directories
    for _, entry in ipairs(NPC.Entries) do
        local m = Modules[entry.moduleId]
        if m and m.Enabled then
            local st = settingsFor(entry)
            for _, model in ipairs(resolveEntry(entry)) do emit(entry, model, st) end
        end
    end
    -- v0.57.0: per-folder Username auto-scan. Matches are attributed to the first
    -- AutoUsername folder (dedupe means later folders take whatever is left), and
    -- carry that folder's settings/exclusions like any of its entries.
    for _, f in ipairs(NPC.Folders) do
        if f.settings and f.settings.AutoUsername then
            f._uHolder = f._uHolder or { _wrappers = setmetatable({}, { __mode = "k" }) }
            for _, model in ipairs(usernameMatches()) do emit(f._uHolder, model, f.settings) end
        end
    end
    -- v0.90.0: auto-add rules, attributed to their folder like the username scan
    for _, f in ipairs(NPC.Folders) do
        local rules = f.settings and f.settings.AutoRules
        if rules and #rules > 0 then
            f._rHolder = f._rHolder or { _wrappers = setmetatable({}, { __mode = "k" }) }
            for _, model in ipairs(NPC.folderRuleMatches(f)) do emit(f._rHolder, model, f.settings) end
        end
    end
    -- v0.82.0: Include all Humanoids (Options, off default). Manual entries
    -- emit first so they win the dedupe; the all-feed takes the leftovers
    -- with default settings and no per-feature exclusions.
    if KoffeeOptions.IncludeHumanoids then
        NPC._allHolder = NPC._allHolder or { _wrappers = setmetatable({}, { __mode = "k" }) }
        for _, model in ipairs(allHumanoids()) do emit(NPC._allHolder, model, DEFAULTS) end
    end
    NPC._cache, NPC._cacheAt = out, now
    return out
end
function NPC.targetEntities(feature)
    local out = {}
    for _, e in ipairs(NPC.entities()) do
        if not (e.exclude and e.exclude[feature]) then out[#out + 1] = e end
    end
    return out
end

-- v0.53.0: the standalone NPC ESP renderer was replaced by the shared player
-- renderer (Shared.updateNpcRigs + espDrawRig), so NPCs get full ESP parity with
-- their own Shared.NPCESP config. Nothing to draw here now.

-- :: model preview + profile viewport ::
-- Only Models (not Workspace) and bare Parts are previewable, and only up to a
-- descendant cap, so selecting a service / huge container never clones the world.
local function previewable(inst)
    if inst:IsA("BasePart") then return true end
    if inst:IsA("Model") and inst ~= Workspace then
        local ok, d = pcall(function() return #inst:GetDescendants() end)
        return ok and d <= 2000
    end
    return false
end
local function boundsOf(inst)
    if inst:IsA("Model") then
        local ok, cf, size = pcall(function() return inst:GetBoundingBox() end)
        if ok and cf then return cf, size end
    end
    if inst:IsA("BasePart") then return inst.CFrame, inst.Size end
    return CFrame.new(), Vector3.new(4, 4, 4)
end
-- v0.56.0: clone into a viewport, anchor everything so nothing droops, and frame
-- the camera off the CLONE's own bounds (the source can sit anywhere in the world).
-- Returns vp plus an `orbit` controller { look, setDist } when interactive; opts:
--   size/round/z/order  : layout    top : bias framing to the upper body (pfp)
--   spin                : auto-rotate    interactive : expose orbit + no auto-spin
local function fillViewport(vp, model, opts)
    local cam = new("Camera", { Parent = vp })
    vp.CurrentCamera = cam
    local okc, clone = pcall(function() return model:Clone() end)
    if not okc or not clone then
        new("TextLabel", {
            Text = "no preview", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
            ZIndex = (opts.z or 11) + 1, Parent = vp,
        })
        return cam, nil
    end
    pcall(function()
        for _, d in ipairs(clone:IsA("BasePart") and { clone } or clone:GetDescendants()) do
            if d:IsA("BasePart") then d.Anchored = true end
        end
    end)
    clone.Parent = vp
    -- soft key light so meshes/parts read clearly against the dark panel
    vp.LightColor = Color3.fromRGB(255, 255, 255)
    vp.Ambient    = Color3.fromRGB(150, 150, 150)
    local cf, size
    if clone:IsA("Model") then
        local ok, bcf, bsize = pcall(function() return clone:GetBoundingBox() end)
        if ok and bcf then cf, size = bcf, bsize end
    elseif clone:IsA("BasePart") then
        cf, size = clone.CFrame, clone.Size
    end
    if not cf then cf, size = boundsOf(model) end
    local center = cf.Position
    local radius = math.max(size.X, size.Y, size.Z, 1)
    if opts.top then
        center = cf.Position + Vector3.new(0, size.Y * 0.30, 0)
        radius = math.max(size.X, size.Y * 0.55, 1)
    end
    local baseDist = radius * (opts.zoom or 1.6) + 2
    local yaw, pitch, dist = opts.angle or 0, 0.15, baseDist
    local function look()
        pitch = math.clamp(pitch, -1.45, 1.45)
        local off = Vector3.new(
            math.cos(pitch) * math.sin(yaw),
            math.sin(pitch),
            math.cos(pitch) * math.cos(yaw)) * dist
        cam.CFrame = CFrame.lookAt(center + off, center)
    end
    look()
    local orbit = {
        rotate = function(dx, dy) yaw = yaw - dx; pitch = pitch + dy; look() end,
        zoom   = function(f) dist = math.clamp(dist * f, radius * 0.6, radius * 6 + 4); look() end,
    }
    if opts.spin then
        local conn
        conn = RunService.RenderStepped:Connect(function(dt)
            if Koffee.dead() or not vp.Parent then conn:Disconnect(); return end
            yaw = yaw + dt * 1.2
            look()
        end)
    end
    return cam, orbit
end
local function makeViewport(parent, model, opts)
    opts = opts or {}
    local vp = new("ViewportFrame", {
        BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.2,
        Size = opts.size or UDim2.fromOffset(40, 40), LayoutOrder = opts.order or 0,
        ZIndex = opts.z or 11, Parent = parent,
    }, { corner(opts.round or 6), stroke(Theme.Palette.BorderSubtle) })
    if not previewable(model) then
        new("TextLabel", {
            Text = "no preview", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
            ZIndex = (opts.z or 11) + 1, Parent = vp,
        })
        return vp
    end
    fillViewport(vp, model, opts)
    return vp
end
-- v0.84.0: popup-space cursor. GetMouseLocation includes the topbar inset and
-- popup space does not (same drift the v0.72.3 settings popups fixed).
local GuiService = game:GetService("GuiService")
local function cursorXY()
    local mp = UIS:GetMouseLocation()
    local inset = GuiService:GetGuiInset()
    return mp.X - inset.X, mp.Y - inset.Y
end
local function screenSize()
    local cam = Workspace.CurrentCamera
    return cam and cam.ViewportSize or Vector2.new(1280, 720)
end
local function placePopup(frame, x, y, w, h)
    local s = screenSize()
    x = math.clamp(x, 4, math.max(4, s.X - w - 4))
    y = math.clamp(y, 4, math.max(4, s.Y - h - 4))
    local ox, oy = popupOffsetFor(frame, x, y)
    frame.Position = UDim2.fromOffset(ox, oy)
end
-- recreate an icon under the same parent with a new glyph (lucideIcon has no setter)
local function swapIcon(ic, name)
    local n = Koffee.lucideIcon(ic.Parent, name, ic.Size.X.Offset, ic.ImageColor3, ic.ZIndex)
    n.AnchorPoint, n.Position, n.LayoutOrder = ic.AnchorPoint, ic.Position, ic.LayoutOrder
    ic:Destroy()
    return n
end
local function instIcon(inst)
    if inst.Parent == game then return "folder-tree" end
    if inst:FindFirstChildOfClass("Humanoid") then return "user" end
    if inst:IsA("Model") then return "package" end
    if inst:IsA("BasePart") then return "box" end
    if inst:IsA("Folder") then return "folder" end
    return "file"
end
Shared.npcInstIcon = instIcon

-- world position + size of anything physical; nil for containers with no parts.
local function posOf(inst)
    if not (inst and inst.Parent) then return nil end
    if inst:IsA("BasePart") then return inst.Position, inst.Size end
    local p = inst:FindFirstChildWhichIsA("BasePart", true)
    if not p then return nil end
    if inst:IsA("Model") then
        local cf, size = boundsOf(inst)
        return cf.Position, size
    end
    return p.Position, p.Size
end

-- v0.84.0: lands on top of the target's bounds. The old bbox-centre + 3 put you
-- inside anything over 6 studs tall, and folders sent you to the world origin.
local function teleportTo(inst)
    local char = LocalPlayer and LocalPlayer.Character
    local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char.PrimaryPart)
    local pos, size = posOf(inst)
    if not pos then
        Koffee.notify("Teleport", "Nothing physical to land on", { severity = "error" })
        return false
    end
    if not hrp then return false end
    pcall(function()
        hrp.CFrame = CFrame.new(pos + Vector3.new(0, size.Y / 2 + 3, 0)) * hrp.CFrame.Rotation
        hrp.AssemblyLinearVelocity = Vector3.zero
    end)
    return true
end

-- v0.84.0: View puts the camera on the target (its Humanoid, else an anchor part),
-- Unview hands it back. The picker loop auto-unviews once the target is gone.
local viewing = nil
local function isViewing(inst) return viewing ~= nil and viewing == inst end
local function unview()
    viewing = nil
    local cam = Workspace.CurrentCamera
    local c = LocalPlayer.Character
    local h = c and c:FindFirstChildOfClass("Humanoid")
    if cam and h then pcall(function() cam.CameraSubject = h end) end
end
local function view(inst)
    local subj = (inst:IsA("Model") and inst:FindFirstChildOfClass("Humanoid")) or npcAnchor(inst)
    local cam = Workspace.CurrentCamera
    if not (subj and cam) then
        Koffee.notify("View", "Nothing physical to look at", { severity = "error" })
        return false
    end
    viewing = inst
    pcall(function() cam.CameraSubject = subj end)
    return true
end
local function toggleView(inst)
    if isViewing(inst) then unview() else view(inst) end
    if NPC._onViewChanged then NPC._onViewChanged() end
end
NPC.viewTick = function() if viewing and not viewing.Parent then unview() end end

-- v0.56.0: interactive preview window. v0.84.0: drags follow the global mouse so
-- fast moves never drop, wheel zoom works (MouseWheel arrives on InputChanged, it
-- never fired from InputBegan), spawn is inset-correct, and the title bar gained
-- Teleport + View. One window per instance: re-opening moves it to the cursor.
local previews = {}
local function openPreview(model)
    local SMALL = Vector2.new(280, 320)
    local existing = previews[model]
    if existing and existing.Parent then
        local cx, cy = cursorXY()
        placePopup(existing, cx + 12, cy + 12, existing.AbsoluteSize.X, existing.AbsoluteSize.Y)
        return
    end
    local holder = new("Frame", {
        Size = UDim2.fromOffset(SMALL.X, SMALL.Y), BackgroundColor3 = Theme.Palette.Panel,
        ZIndex = 250, Parent = popupScreen, Active = true,
    }, { corner(10), stroke(Theme.Palette.BorderSubtle) })
    previews[model] = holder
    local cx, cy = cursorXY()
    placePopup(holder, cx + 12, cy + 12, SMALL.X, SMALL.Y)

    local bar = new("Frame", {
        BackgroundTransparency = 1, Active = true, Size = UDim2.new(1, -118, 0, 34), ZIndex = 251, Parent = holder,
    })
    local tIc = Koffee.lucideIcon(bar, instIcon(model), 13, Theme.Palette.TextMuted, 252)
    tIc.AnchorPoint = Vector2.new(0, 0.5); tIc.Position = UDim2.new(0, 12, 0, 17)
    new("TextLabel", {
        Text = model.Name, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Position = UDim2.new(0, 32, 0, 9), Size = UDim2.new(1, -36, 0, 16), ZIndex = 252, Parent = bar,
    })
    local function chip(x, icon, onClick)
        local b = new("TextButton", {
            Text = "", BackgroundColor3 = Theme.Palette.Pill, Size = UDim2.fromOffset(22, 22),
            Position = UDim2.new(1, x, 0, 6), ZIndex = 252, Parent = holder, AutoButtonColor = true,
        }, { corner(6) })
        local rec = { btn = b, ic = Koffee.lucideIcon(b, icon, 13, Theme.Palette.TextMuted, 253) }
        b.MouseButton1Click:Connect(function() onClick(rec) end)
        return rec
    end
    local vp = new("ViewportFrame", {
        BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.2,
        Position = UDim2.fromOffset(10, 34), Size = UDim2.new(1, -20, 1, -64),
        ZIndex = 251, Parent = holder, Active = true,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
    new("TextLabel", {
        Text = "Drag to orbit, scroll to zoom", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
        TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
        Position = UDim2.new(0, 12, 1, -26), Size = UDim2.new(1, -24, 0, 20), ZIndex = 252, Parent = holder,
    })
    local orbit = nil
    if previewable(model) then
        local _
        _, orbit = fillViewport(vp, model, { z = 251, interactive = true })
    else
        new("TextLabel", {
            Text = "No preview", FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
            ZIndex = 252, Parent = vp,
        })
    end

    local conns, mode, last = {}, nil, nil
    local function isPress(io)
        return io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch
    end
    vp.InputBegan:Connect(function(io) if isPress(io) then mode, last = "orbit", io.Position end end)
    bar.InputBegan:Connect(function(io) if isPress(io) then mode, last = "move", io.Position end end)
    vp.InputChanged:Connect(function(io)
        if io.UserInputType == Enum.UserInputType.MouseWheel and orbit then
            orbit.zoom(io.Position.Z > 0 and 0.88 or 1.14)
        end
    end)
    conns[#conns + 1] = UIS.InputChanged:Connect(function(io)
        if not mode or Koffee.dead() then return end
        local t = io.UserInputType
        if t ~= Enum.UserInputType.MouseMovement and t ~= Enum.UserInputType.Touch then return end
        local d = io.Position - last; last = io.Position
        if mode == "orbit" then
            if orbit then orbit.rotate(d.X * 0.01, d.Y * 0.01) end
        else
            holder.Position = holder.Position + UDim2.fromOffset(d.X, d.Y)
        end
    end)
    conns[#conns + 1] = UIS.InputEnded:Connect(function(io) if isPress(io) then mode = nil end end)
    holder.Destroying:Connect(function()
        for _, c in ipairs(conns) do c:Disconnect() end
        if previews[model] == holder then previews[model] = nil end
    end)

    chip(-106, "navigation", function() teleportTo(model) end)
    chip(-80, isViewing(model) and "eye-off" or "eye", function(rec)
        toggleView(model)
        rec.ic = swapIcon(rec.ic, isViewing(model) and "eye-off" or "eye")
    end)
    local full = false
    chip(-54, "maximize-2", function(rec)
        full = not full
        local s = screenSize()
        if full then
            local w, h = math.floor(s.X * 0.72), math.floor(s.Y * 0.78)
            placePopup(holder, math.floor((s.X - w) / 2), math.floor((s.Y - h) / 2), w, h)
            tween(holder, Theme.Animation.Fast, { Size = UDim2.fromOffset(w, h) })
        else
            local a = holder.AbsolutePosition
            placePopup(holder, a.X, a.Y, SMALL.X, SMALL.Y)
            tween(holder, Theme.Animation.Fast, { Size = UDim2.fromOffset(SMALL.X, SMALL.Y) })
        end
        -- v0.84.0: swap, not stack. The old toggle added a second glyph each click.
        rec.ic = swapIcon(rec.ic, full and "minimize-2" or "maximize-2")
    end)
    chip(-28, "x", function() holder:Destroy() end)
end

-- v0.56.0 (grown v0.57.0, v0.84.0): right-click menu at the cursor. Select (when
-- the caller can), Preview, Teleport To, View / Unview, Learn as NPC, and the two
-- Username-scan exclusions. Any click outside (either button) dismisses it.
local ctxMenu = nil
local function closeContextMenu()
    if ctxMenu then ctxMenu:Destroy(); ctxMenu = nil end
end
local function openContextMenu(inst, extra)
    closeContextMenu()
    if not (inst and inst.Parent) then return end
    local items = {}
    if extra and extra.onSelect then items[#items + 1] = { "mouse-pointer-click", "Select", extra.onSelect } end
    items[#items + 1] = { "rotate-3d", "Preview", function() openPreview(inst) end }
    items[#items + 1] = { "navigation", "Teleport To", function() teleportTo(inst) end }
    if isViewing(inst) then
        items[#items + 1] = { "eye-off", "Unview", function() toggleView(inst) end }
    else
        items[#items + 1] = { "eye", "View", function() toggleView(inst) end }
    end
    items[#items + 1] = { "user-plus", "Learn as NPC", function()
        if NPC._learnInst then NPC._learnInst(inst, "model") end
    end }
    items[#items + 1] = { "ban", "Exclude (session)", function()
        NPC._excludeSel[inst] = true
        if NPC._refreshExcl then NPC._refreshExcl() end
    end }
    -- v0.86.0: item models from anything in the world
    items[#items + 1] = { "package", "Copy as Item Model", function()
        if Shared.ItemSkins then Shared.ItemSkins.copyInst(inst) end
    end }
    items[#items + 1] = { "box", "Use as Item Model", function()
        if Shared.ItemSkins then Shared.ItemSkins.useInst(inst) end
    end }
    items[#items + 1] = { "fingerprint", "Exclude (learn)", function()
        local sig = signature(inst)
        if sig ~= "" then
            local dup = false
            for _, s in ipairs(NPC.ExcludeSigs) do if s == sig then dup = true break end end
            if not dup then NPC.ExcludeSigs[#NPC.ExcludeSigs + 1] = sig end
        end
        if NPC._refreshExcl then NPC._refreshExcl() end
    end }

    local W, rowH, N = 184, 28, #items
    local catcher = new("TextButton", {
        Text = "", BackgroundTransparency = 1, Active = true, AutoButtonColor = false,
        Size = UDim2.fromScale(1, 1), ZIndex = 258, Parent = popupScreen,
    })
    ctxMenu = catcher
    catcher.MouseButton1Click:Connect(closeContextMenu)
    catcher.MouseButton2Click:Connect(closeContextMenu)
    local cardH = rowH * N + (N - 1) * 4 + 10
    local card = new("Frame", {
        BackgroundColor3 = Theme.Palette.Panel, Size = UDim2.fromOffset(W, cardH), ZIndex = 259, Parent = catcher,
    }, { corner(8), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
            PaddingLeft = UDim.new(0, 5), PaddingRight = UDim.new(0, 5) }),
        new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }) })
    local cx, cy = cursorXY()
    placePopup(card, cx, cy, W, cardH)
    for i, it in ipairs(items) do
        local b = new("TextButton", {
            Text = "", BackgroundColor3 = Theme.Palette.Pill, BackgroundTransparency = 0.25,
            AutoButtonColor = true, Size = UDim2.new(1, 0, 0, rowH), LayoutOrder = i, ZIndex = 260, Parent = card,
        }, { corner(6) })
        local ic = Koffee.lucideIcon(b, it[1], 14, Theme.Palette.TextMuted, 261)
        ic.AnchorPoint = Vector2.new(0, 0.5); ic.Position = UDim2.new(0, 10, 0.5, 0)
        new("TextLabel", {
            Text = it[2], FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.new(0, 32, 0, 0), Size = UDim2.new(1, -38, 1, 0), ZIndex = 261, Parent = b,
        })
        local cb = it[3]
        b.MouseButton1Click:Connect(function() closeContextMenu(); cb() end)
    end
end
NPC.openContextMenu = openContextMenu

-- :: entry / folder mutation ::
local function addEntry(inst, kind, method)
    NPC._nid = NPC._nid + 1
    local id = NPC._nid
    local entry = {
        id = id, kind = kind, path = Shared.pathOf(inst),
        parentPath = inst.Parent and Shared.pathOf(inst.Parent) or nil,
        sig = signature(inst), name = inst.Name, folderId = nil, _inst = inst,
        method = method or "Path",   -- v0.57.0: Path | Signature | Name
        -- v0.67.0: generation-unique module id, so entries learned under one
        -- config can never collide with another config's rows.
        moduleId = "npc_g" .. (NPC._gen or 0) .. "_" .. id,
    }
    registerModule(entry.moduleId, "npc: " .. inst.Name, function() end, function() end)
    NPC.Entries[#NPC.Entries + 1] = entry
    toggleModule(entry.moduleId)   -- active by default (also lists it in the arraylist)
    return entry
end
local function removeEntry(entry)
    local m = Modules[entry.moduleId]
    if m and m.Enabled then toggleModule(entry.moduleId) end
    for i, e in ipairs(NPC.Entries) do if e == entry then table.remove(NPC.Entries, i) break end end
end
local function addFolder(name)
    NPC._fid = NPC._fid + 1
    local f = { id = NPC._fid, name = name or ("Folder " .. NPC._fid), settings = newFolderSettings() }
    NPC.Folders[#NPC.Folders + 1] = f
    return f
end
local function removeFolder(f)
    for _, e in ipairs(NPC.Entries) do if e.folderId == f.id then e.folderId = nil end end
    for i, x in ipairs(NPC.Folders) do if x == f then table.remove(NPC.Folders, i) break end end
end

