end

-- :: mouse select (v0.84.0) ::
-- Arm it in the Picker, close the menu, click anything in the world: it becomes
-- the Picker selection (tree revealed on reopen) with an accent outline. State is
-- chunk-level so a config rebuild of the tab keeps the selection. Session-only.
local PICK = { On = false, Level = "Smart", Outline = true, sel = nil, hover = nil, bound = false }
NPC._pick = PICK
local CAS = game:GetService("ContextActionService")
local PICK_ACT = KID.name("npcpick")
local function hlGet(key, color, fillT)
    local h = PICK[key]
    if not (h and h.Parent) then
        if h then pcall(function() h:Destroy() end) end
        h = Instance.new("Highlight")
        h.Name = KID.name("npchl")
        h.FillColor, h.OutlineColor = color, color
        h.FillTransparency, h.OutlineTransparency = fillT, 0
        pcall(function() h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop end)
        h.Enabled = false
        KID.track(h)
        PICK[key] = h
    end
    local cam = Workspace.CurrentCamera
    if cam and h.Parent ~= cam then h.Parent = cam end
    return h
end
local function outlineable(inst)
    return inst and inst.Parent and inst ~= Workspace and inst.Parent ~= game
        and (inst:IsA("Model") or inst:IsA("BasePart"))
end
local function syncOutline()
    local s = PICK.sel
    local on = PICK.Outline and outlineable(s)
    if not on and not PICK.selHL then return end
    local h = hlGet("selHL", Theme.Palette.Accent, 1)
    h.Adornee = on and s or nil
    h.Enabled = on and true or false
end
-- CAS sinks MouseButton1 only while picking, so the selecting click never fires a
-- gun, and right-drag camera look stays free (same as the instance-picker modal).
local function pickBind(on)
    if PICK.bound == on then return end
    PICK.bound = on
    if on then
        CAS:BindActionAtPriority(PICK_ACT, function(_, state)
            if state == Enum.UserInputState.Begin and PICK.hover and PICK.onPick then PICK.onPick(PICK.hover) end
            return Enum.ContextActionResult.Sink
        end, false, Enum.ContextActionPriority.High.Value + 1000, Enum.UserInputType.MouseButton1)
    else
        pcall(function() CAS:UnbindAction(PICK_ACT) end)
    end
end
-- Smart: the nearest Humanoid rig, else the nearest Model, else the part.
local function resolvePick(part)
    if not part then return nil end
    if PICK.Level == "Part" then return part end
    local a, top = part.Parent, nil
    while a and a ~= Workspace and a ~= game do
        if a:IsA("Model") then
            if PICK.Level ~= "Top Model" and a:FindFirstChildOfClass("Humanoid") then return a end
            top = a
        end
        a = a.Parent
    end
    if PICK.Level == "Top Model" then return top or part end
    return part:FindFirstAncestorOfClass("Model") or part
end
local function pickHint()
    if PICK.hint and PICK.hint.Parent then return PICK.hint end
    local f = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 12),
        Size = UDim2.fromOffset(0, 30), AutomaticSize = Enum.AutomaticSize.X,
        BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.12,
        ZIndex = 240, Visible = false, Parent = popupScreen,
    }, { corner(8), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }),
        new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8),
            VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
    local ic = Koffee.lucideIcon(f, "mouse-pointer-click", 14, Theme.Palette.Accent, 241)
    ic.AnchorPoint = Vector2.new(0, 0); ic.LayoutOrder = 0
    PICK.hintText = new("TextLabel", {
        Text = "", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
        BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0),
        LayoutOrder = 1, ZIndex = 241, Parent = f,
    })
    PICK.hint = f
    return f
end
local function clipName(s) return #s > 40 and (s:sub(1, 38) .. "..") or s end
local function richEsc(s) return (s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")) end

-- :: PICKER sub-tab :: search + an inline instance browser (left), selection +
-- actions + Mouse Select (right). The tree only expands on the arrow, not on select.
-- v0.84.0: right-click now forwards from every button covering a row. The row
-- frame's own InputBegan never saw it: the name button sat on top and sank it.
local function buildPicker(host, onChange)
    local cols = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local left = vlist(cols, 6, 1, UDim2.new(0.6, -5, 0, 0))
    local right = vlist(cols, 6, 2, UDim2.new(0.4, -5, 0, 0))

    -- search row: box with a magnifier, clear button, refresh
    local sRow = new("Frame", { Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, LayoutOrder = 0, Parent = left })
    local sBox = new("TextBox", {
        Text = "", PlaceholderText = "Search models and parts", ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.Text,
        PlaceholderColor3 = Theme.Palette.TextFaint, BackgroundColor3 = Theme.Palette.Background,
        BackgroundTransparency = 0.15, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
        Size = UDim2.new(1, -34, 1, 0), ZIndex = 1, Parent = sRow,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 28), PaddingRight = UDim.new(0, 26) }) })
    local sIc = Koffee.lucideIcon(sRow, "search", 13, Theme.Palette.TextMuted, 2)
    sIc.Position = UDim2.new(0, 15, 0.5, 0)
    local clearQ = new("TextButton", {
        Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Visible = false,
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, -47, 0.5, 0),
        Size = UDim2.fromOffset(20, 20), ZIndex = 2, Parent = sRow,
    })
    Koffee.lucideIcon(clearQ, "x", 12, Theme.Palette.TextMuted, 3)
    local refreshBtn = new("TextButton", {
        Text = "", BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true,
        AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(28, 28), Parent = sRow,
    }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
    Koffee.lucideIcon(refreshBtn, "refresh-cw", 13, Theme.Palette.TextMuted)

    local function scroller(order)
        return new("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 320), BackgroundColor3 = Theme.Palette.Background, BackgroundTransparency = 0.35,
            ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.Palette.TextFaint,
            CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y, LayoutOrder = order, Parent = left,
        }, { corner(6), new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4) }),
            new("UIListLayout", { Padding = UDim.new(0, 1), SortOrder = Enum.SortOrder.LayoutOrder }) })
    end
    local tree = scroller(1)
    local results = scroller(2)
    results.Visible = false
    local status = hintRow(left, "", 3)
    status.Visible = false

    local rebuildTree, updateRight, choose, runSearch
    local expanded, rowIndex, pendingFocus, wantScrollY = {}, 0, nil, nil
    local ROOTS = {}
    for _, svc in ipairs({ "Workspace", "ReplicatedStorage", "Lighting", "Players", "StarterPack" }) do
        local ok, s = pcall(function() return game:GetService(svc) end)
        if ok and s then ROOTS[#ROOTS + 1] = s end
    end
    local function ctxFor(inst)
        openContextMenu(inst, { onSelect = function() choose(inst, true) end })
    end
    local function clearList(f)
        for _, c in ipairs(f:GetChildren()) do
            if not c:IsA("UIListLayout") and not c:IsA("UIPadding") then c:Destroy() end
        end
    end
    -- depth >= 0: tree row. depth -1: flat search result with its parent path.
    local function nodeRow(parent, inst, depth)
        rowIndex = rowIndex + 1
        local isSel = PICK.sel == inst
        local d = math.max(depth, 0)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 24), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = isSel and 0.2 or 1, LayoutOrder = rowIndex, Parent = parent,
        }, { corner(4), new("UIPadding", { PaddingLeft = UDim.new(0, 6 + d * 14), PaddingRight = UDim.new(0, 6) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        if depth >= 0 then
            if #inst:GetChildren() > 0 then
                local arrow = iconBtn(row, expanded[inst] and "chevron-down" or "chevron-right", "", function()
                    expanded[inst] = not expanded[inst]; rebuildTree()
                end, 0)
                arrow.BackgroundTransparency = 1; arrow.Size = UDim2.fromOffset(16, 16)
                local st = arrow:FindFirstChildOfClass("UIStroke"); if st then st.Enabled = false end
                arrow.MouseButton2Click:Connect(function() ctxFor(inst) end)
            else
                new("Frame", { Size = UDim2.fromOffset(16, 16), BackgroundTransparency = 1, LayoutOrder = 0, Parent = row })
            end
        end
        local ic = Koffee.lucideIcon(row, instIcon(inst), 13, isSel and Theme.Palette.Accent or Theme.Palette.TextMuted)
        ic.AnchorPoint = Vector2.new(0, 0); ic.LayoutOrder = 1   -- layout child: top-left anchor
        local text = richEsc(inst.Name)
        if depth < 0 and inst.Parent then
            text = text .. '  <font color="#8E8174">' .. richEsc(inst.Parent:GetFullName()) .. "</font>"
        end
        local nameBtn = new("TextButton", {
            Text = text, RichText = true, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = isSel and Theme.Palette.Accent or Theme.Palette.Text, BackgroundTransparency = 1,
            AutoButtonColor = false, TextTruncate = Enum.TextTruncate.AtEnd, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, -(46 + d * 14), 1, 0), LayoutOrder = 2, Parent = row,
        })
        nameBtn.MouseButton1Click:Connect(function() choose(inst, false) end)
        nameBtn.MouseButton2Click:Connect(function() ctxFor(inst) end)
        row.InputBegan:Connect(function(io)
            if io.UserInputType == Enum.UserInputType.MouseButton2 then ctxFor(inst) end
        end)
        return rowIndex
    end
    -- rows are 24px + 1px list padding + 4px top pad, so a row's y is known without
    -- reading AbsolutePosition (which is stale while the window is hidden).
    local function applyScroll()
        if not wantScrollY then return end
        local y = wantScrollY
        task.defer(function() tree.CanvasPosition = Vector2.new(0, y) end)
        task.delay(0.1, function() if tree.Parent then tree.CanvasPosition = Vector2.new(0, y) end end)
    end
    rebuildTree = function()
        clearList(tree)
        rowIndex = 0
        local chain = {}   -- the selection's ancestors: shown even past the 300 cap
        local a = PICK.sel
        while a do chain[a] = true; a = a.Parent end
        local focusIdx
        local function walk(inst, depth)
            local idx = nodeRow(tree, inst, depth)
            if inst == pendingFocus then focusIdx = idx end
            if expanded[inst] then
                local n = 0
                for _, ch in ipairs(inst:GetChildren()) do
                    n = n + 1
                    if n <= 300 or chain[ch] then walk(ch, depth + 1) end
                end
            end
        end
        for _, r in ipairs(ROOTS) do walk(r, 0) end
        if focusIdx then
            pendingFocus = nil
            wantScrollY = math.max(0, 4 + (focusIdx - 1) * 25 - 120)
            applyScroll()
        end
    end

    runSearch = function()
        clearList(results)
        local q = sBox.Text:lower():gsub("^%s+", ""):gsub("%s+$", "")
        if q == "" then
            results.Visible, status.Visible, tree.Visible = false, false, true
            return
        end
        tree.Visible, results.Visible, status.Visible = false, true, true
        local CAP = 150
        local models, parts = {}, {}
        local function scan(list)
            for _, d in ipairs(list) do
                if #models >= CAP then return end
                local isM = d:IsA("Model")
                if (isM or (#parts < CAP and d:IsA("BasePart"))) and d.Name:lower():find(q, 1, true) then
                    if isM then models[#models + 1] = d else parts[#parts + 1] = d end
                end
            end
        end
        scan(wsDescendants())
        local ok, rs = pcall(function() return game:GetService("ReplicatedStorage"):GetDescendants() end)
        if ok then scan(rs) end
        rowIndex = 0
        local shown = 0
        for _, m in ipairs(models) do nodeRow(results, m, -1); shown = shown + 1 end
        for _, p in ipairs(parts) do
            if shown >= CAP then break end
            nodeRow(results, p, -1); shown = shown + 1
        end
        if shown == 0 then
            status.Text = "No models or parts match \"" .. q .. "\"."
        else
            status.Text = shown .. (shown == 1 and " result" or " results")
                .. (shown >= CAP and " (first " .. CAP .. ", refine the search)" or "")
                .. ". Models first. Right-click for Preview, Teleport and View."
        end
    end
    local searchTok = 0
    sBox:GetPropertyChangedSignal("Text"):Connect(function()
        clearQ.Visible = sBox.Text ~= ""
        searchTok = searchTok + 1
        local my = searchTok
        task.delay(0.2, function()
            if my == searchTok and not Koffee.dead() and sBox.Parent then runSearch() end
        end)
    end)
    clearQ.MouseButton1Click:Connect(function() sBox.Text = "" end)
    refreshBtn.MouseButton1Click:Connect(function()
        _wsSnap = nil
        if results.Visible then runSearch() else rebuildTree() end
    end)

    -- right column: selection, preview, actions, learn, Mouse Select
    hintRow(right, "Click a name to select, the arrow to expand. Right-click anything for Preview, Teleport, View and more.", 0)
    local head = hrow(right, 20, 1)
    local selLabel = new("TextLabel", {
        Text = "Nothing selected", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, -28, 1, 0), LayoutOrder = 0, Parent = head,
    })
    local clearSel = iconBtn(head, "x", "", function() choose(nil) end, 1)
    local previewHolder = new("Frame", {
        Size = UDim2.new(1, 0, 0, 90), BackgroundTransparency = 1, LayoutOrder = 2, Parent = right,
    })
    local actRow = hrow(right, 26, 3)
    local third = UDim2.new(1 / 3, -4, 0, 26)
    iconTextBtn(actRow, "rotate-3d", "Preview", function() if PICK.sel then openPreview(PICK.sel) end end, 0, third)
    iconTextBtn(actRow, "navigation", "Teleport", function() if PICK.sel then teleportTo(PICK.sel) end end, 1, third)
    local viewBtn = iconTextBtn(actRow, "eye", "View", function() if PICK.sel then toggleView(PICK.sel) end end, 2, third)
    viewBtn._icon = "eye"
    local function refreshViewBtn()
        local on = PICK.sel and isViewing(PICK.sel)
        local want = on and "eye-off" or "eye"
        viewBtn.lbl.Text = on and "Unview" or "View"
        if viewBtn._icon ~= want then viewBtn._icon = want; viewBtn.ic = swapIcon(viewBtn.ic, want) end
    end
    NPC._onViewChanged = refreshViewBtn
    -- v0.57.0: how this target is re-found. Signature is name-independent (survives
    -- directory obfuscation); Path is exact + fastest; Name matches anywhere.
    local learnMethod = "Signature"
    local methodHolder = new("Frame", {
        Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, LayoutOrder = 4, Parent = right,
    })
    dropdown(methodHolder, "Learn method", { "Signature", "Path", "Name" }, learnMethod, function(v) learnMethod = v end)
    local function learnInst(inst, kind)
        if not (inst and inst.Parent) then return end
        if learnedEntry(inst, kind) then
            Koffee.notify("Already learned", inst.Name, { duration = 2 })
            return
        end
        addEntry(inst, kind, learnMethod)
        if onChange then onChange() end
        Koffee.notify("Learned", inst.Name .. " (" .. learnMethod .. ")", { severity = "success", duration = 2 })
        updateRight()
    end
    NPC._learnInst = learnInst
    local addRow = hrow(right, 26, 5)
    local addBtn = iconTextBtn(addRow, "user-plus", "Learn as NPC", function() learnInst(PICK.sel, "model") end, 0)
    local addDirBtn = iconTextBtn(addRow, "folder-plus", "Learn as Directory", function() learnInst(PICK.sel, "dir") end, 1)

    new("TextLabel", {
        Text = "Mouse Select", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 6, Parent = right,
    })
    local msCb = configCheckbox(right, "Mouse Select", PICK.On, function(v)
        PICK.On = v
        if v then Koffee.notify("Mouse Select on", "Close the menu and click anything in the world.", { duration = 3 }) end
    end)
    msCb.row.LayoutOrder = 7
    hintRow(right, "Close the menu, then click anything. It is selected here when you reopen. Right-drag still looks around.", 8)
    local lvlHolder = new("Frame", {
        Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1, LayoutOrder = 9, Parent = right,
    })
    dropdown(lvlHolder, "Select as", { "Smart", "Part", "Top Model" }, PICK.Level, function(v) PICK.Level = v end)
    local olCb = configCheckbox(right, "Outline selection", PICK.Outline, function(v) PICK.Outline = v; syncOutline() end)
    olCb.row.LayoutOrder = 10

    updateRight = function()
        for _, c in ipairs(previewHolder:GetChildren()) do c:Destroy() end
        local s = PICK.sel
        if s and not s.Parent then PICK.sel = nil; s = nil end
        local has = s ~= nil
        clearSel.Visible, previewHolder.Visible, actRow.Visible, addRow.Visible = has, has, has, has
        syncOutline()
        if not has then selLabel.Text = "Nothing selected"; return end
        selLabel.Text = s.ClassName .. ": " .. s.Name
        addBtn.lbl.Text = learnedEntry(s, "model") and "Learned" or "Learn as NPC"
        addDirBtn.btn.Visible = #s:GetChildren() > 0
        makeViewport(previewHolder, s, { size = UDim2.new(1, 0, 1, 0), top = true })
        refreshViewBtn()
    end
    choose = function(inst, reveal)
        PICK.sel = inst
        if reveal and inst then
            local a = inst.Parent
            while a and a ~= game do expanded[a] = true; a = a.Parent end
            pendingFocus = inst
        end
        updateRight(); rebuildTree()
        if results.Visible then runSearch() end
    end
    PICK.onPick = function(inst)
        choose(inst, true)
        Koffee.notify("Selected", clipName(inst.Name) .. " (" .. inst.ClassName .. ")", { severity = "success", duration = 2 })
    end

    -- one loop per built picker; a config rebuild hands ownership to the new one.
    local token = {}
    PICK.owner = token
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local wasOpen, tickAt, lastHint = true, 0, nil
    local conn
    conn = RunService.RenderStepped:Connect(function()
        if Koffee.dead() or PICK.owner ~= token or not tree.Parent then
            conn:Disconnect()
            if PICK.owner == token then pickBind(false); if PICK.hint then PICK.hint.Visible = false end end
            return
        end
        local now = os.clock()
        if now >= tickAt then
            tickAt = now + 0.5
            NPC.viewTick()
            if PICK.sel and not PICK.sel.Parent then updateRight() end
        end
        local W = Koffee.Windows
        local open = not (W and W.primaryOpen) or W.primaryOpen()
        if open and not wasOpen then applyScroll() end
        wasOpen = open
        local active = PICK.On and not open
        pickBind(active)
        if not active then
            if PICK.hover then PICK.hover = nil end
            if PICK.hoverHL and PICK.hoverHL.Enabled then PICK.hoverHL.Enabled = false; PICK.hoverHL.Adornee = nil end
            if PICK.hint and PICK.hint.Visible then PICK.hint.Visible = false end
            return
        end
        local cam = Workspace.CurrentCamera
        if not cam then return end
        local mp = UIS:GetMouseLocation()
        local ray = cam:ViewportPointToRay(mp.X, mp.Y)
        rp.FilterDescendantsInstances = { cam, LocalPlayer.Character }
        local ok, hit = pcall(function() return Workspace:Raycast(ray.Origin, ray.Direction * 5000, rp) end)
        local inst = (ok and hit) and resolvePick(hit.Instance) or nil
        PICK.hover = inst
        local h = hlGet("hoverHL", Theme.Palette.Snow, 0.85)
        local adorn = (inst and inst ~= PICK.sel) and inst or nil   -- the selection keeps its accent outline
        if h.Adornee ~= adorn then h.Adornee = adorn end
        h.Enabled = adorn ~= nil
        pickHint().Visible = true
        local txt = inst and ("Click to select " .. clipName(inst.Name) .. " (" .. inst.ClassName .. ")")
            or "Mouse Select: point at something and click"
        if txt ~= lastHint then lastHint = txt; PICK.hintText.Text = txt end
    end)

    updateRight()
    if PICK.sel then choose(PICK.sel, true) else rebuildTree() end
end

-- :: MANAGER sub-tab ::
local function buildManager(host)
    local selected = nil   -- selected folder (settings target)
    local expanded = {}
    local cols = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder }) })
    local left = vlist(cols, 6, 1, UDim2.new(0.52, -5, 0, 0))
    local right = vlist(cols, 6, 2, UDim2.new(0.48, -5, 0, 0))
    local listBox = nil
    local rebuild, showSettings

    local function entryRow(parent, entry, indent)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.5, BorderSizePixel = 0, Parent = parent,
        }, { corner(6), new("UIPadding", { PaddingLeft = UDim.new(0, indent or 8), PaddingRight = UDim.new(0, 6) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        -- v0.84.0: icon follows what the entry is; a name dims while it is not in
        -- the game; right-click opens the same menu as the Picker.
        local live = entry._inst and entry._inst.Parent and entry._inst or nil
        local eIc = Koffee.lucideIcon(row, entry.kind == "dir" and "folder-open" or (live and instIcon(live) or "user"),
            14, Theme.Palette.TextMuted)
        eIc.AnchorPoint = Vector2.new(0, 0); eIc.LayoutOrder = 0   -- layout child: top-left anchor
        new("TextLabel", {
            Text = entry.name, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = live and Theme.Palette.Text or Theme.Palette.TextFaint, BackgroundTransparency = 1,
            TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, -150, 1, 0), LayoutOrder = 1, Parent = row,
        })
        row.InputBegan:Connect(function(io)
            if io.UserInputType ~= Enum.UserInputType.MouseButton2 then return end
            local inst = resolveInstance(entry)
            if inst then openContextMenu(inst)
            else Koffee.notify("Not found", entry.name .. " is not in the game right now", { duration = 2 }) end
        end)
        -- v0.57.0: method pill (cycles Path -> Signature -> Name) + a Re-Learn button
        -- that recaptures the fingerprint from the live instance.
        local METHODS = { "Path", "Signature", "Name" }
        local methodPill = new("TextButton", {
            Text = entry.method or "Path", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Accent, BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true,
            Size = UDim2.fromOffset(58, 22), LayoutOrder = 2, Parent = row,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
        methodPill.MouseButton1Click:Connect(function()
            local cur = entry.method or "Path"
            local i = 1
            for k, m in ipairs(METHODS) do if m == cur then i = k break end end
            entry.method = METHODS[(i % #METHODS) + 1]
            entry._inst, entry._nextTry = nil, 0   -- force a fresh resolve with the new method
            methodPill.Text = entry.method
        end)
        iconBtn(row, "refresh-cw", "re-learn", function()
            if NPC.learn(entry) then rebuild() end
        end, 3)
        -- assign to / remove from a folder. Its own wrapper so rightClickSettings
        -- (which grabs the first TextButton it finds) targets exactly this button.
        local assignWrap = new("Frame", {
            Size = UDim2.fromOffset(22, 22), BackgroundTransparency = 1, LayoutOrder = 4, Parent = row,
        })
        local assignBtn = new("TextButton", {
            Text = "", BackgroundColor3 = Theme.Palette.Pill, AutoButtonColor = true, Size = UDim2.fromScale(1, 1), Parent = assignWrap,
        }, { corner(6), stroke(Theme.Palette.BorderSubtle) })
        Koffee.lucideIcon(assignBtn, "folder", 13, Theme.Palette.TextMuted)
        rightClickSettings(assignWrap, "Assign folder", function(api)
            local names = { "None" }
            for _, f in ipairs(NPC.Folders) do names[#names + 1] = f.name end
            local cur = "None"
            if entry.folderId then local f = folderById(entry.folderId); if f then cur = f.name end end
            api:dropdown("Folder", names, cur, function(v)
                if v == "None" then entry.folderId = nil
                else
                    for _, f in ipairs(NPC.Folders) do if f.name == v then entry.folderId = f.id break end end
                end
                rebuild()
            end)
        end, true)
        iconBtn(row, "trash-2", "remove", function() removeEntry(entry); rebuild() end, 5)
    end

    local function folderHeader(parent, folder)
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Theme.Palette.Pill,
            BackgroundTransparency = (selected == folder) and 0.1 or 0.5, BorderSizePixel = 0, Parent = parent,
        }, { corner(6), new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }),
            new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        local chev = iconBtn(row, expanded[folder.id] and "chevron-down" or "chevron-right", "", function()
            expanded[folder.id] = not expanded[folder.id]; rebuild()
        end, 0)
        chev.BackgroundTransparency = 1
        -- name is a button so the whole label selects the folder (no overlay button,
        -- which a horizontal UIListLayout would lay out inline instead of stacking).
        local nameBtn = new("TextButton", {
            Text = folder.name, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextTruncate = Enum.TextTruncate.AtEnd,
            AutoButtonColor = false, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, -96, 1, 0), LayoutOrder = 1, Parent = row,
        })
        nameBtn.MouseButton1Click:Connect(function() selected = folder; showSettings(); rebuild() end)
        iconBtn(row, "pencil", "rename", function()
            nameBtn.Visible = false
            local tb = textInput(row, "folder name", folder.name, 1, function(t)
                if t ~= "" then folder.name = t end
                rebuild()
            end)
            tb.Size = UDim2.new(1, -96, 0, 22)
            tb:CaptureFocus()
        end, 2)
        iconBtn(row, "trash-2", "delete folder", function()
            if selected == folder then selected = nil; showSettings() end
            removeFolder(folder); rebuild()
        end, 3)
    end

    rebuild = function()
        clearKids(left)
        iconTextBtn(left, "folder-plus", "New Folder", function() local f = addFolder(); expanded[f.id] = true; rebuild() end, 0)
        listBox = vlist(left, 4, 1)
        for _, folder in ipairs(NPC.Folders) do
            folderHeader(listBox, folder)
            if expanded[folder.id] then
                local any = false
                for _, e in ipairs(NPC.Entries) do
                    if e.folderId == folder.id then entryRow(listBox, e, 20); any = true end
                end
                -- v0.90.0: NPCs pulled in by this folder's auto-add rules
                local auto = #NPC.folderRuleMatches(folder)
                if auto > 0 then hintRow(listBox, "  + " .. auto .. " added by rules", 0) end
                if not any and auto == 0 then hintRow(listBox, "  (empty, assign NPCs from Ungrouped)", 0) end
            end
        end
        -- ungrouped
        local ung = {}
        for _, e in ipairs(NPC.Entries) do if not e.folderId then ung[#ung + 1] = e end end
        if #ung > 0 then
            new("TextLabel", {
                Text = "Ungrouped", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                Size = UDim2.new(1, 0, 0, 16), Parent = listBox,
            })
            for _, e in ipairs(ung) do entryRow(listBox, e, 8) end
        end
        if #NPC.Entries == 0 and #NPC.Folders == 0 then
            hintRow(listBox, "No NPCs yet. Add some in the Picker tab, or make a folder with auto-add rules.", 0)
        end
    end

    -- v0.57.0: global Username-scan exclusion editor, shown when no folder is
    -- selected. Names + learned sigs persist; tree selections are session-only.
    local function drawExclusions()
        new("TextLabel", {
            Text = "Username Scan Exclusions", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 16), Parent = right,
        })
        hintRow(right, "Filters what the folder Username scan and auto-add rules pick up. Right-click a tree row (Picker) to add a session or learned exclusion.", 0)
        hintRow(right, "Select a folder to give it auto-add rules (add NPCs by name, no picking needed).", 0)
        -- names (persist): text + add, then a removable list
        local nameAdd = hrow(right, 26, 0)
        local nameTB = textInput(nameAdd, "exclude name (contains)", "", 0, function() end)
        nameTB.Size = UDim2.new(1, -60, 0, 26)
        textBtn(nameAdd, "Add", function()
            local t = nameTB.Text:gsub("^%s+", ""):gsub("%s+$", "")
            if t ~= "" then NPC.ExcludeNames[#NPC.ExcludeNames + 1] = t; showSettings() end
        end, 1)
        local function chipRow(label, onRemove)
            local r = hrow(right, 24, 0)
            r.BackgroundColor3 = Theme.Palette.PanelElevated; r.BackgroundTransparency = 0.5
            new("UICorner", { CornerRadius = UDim.new(0, 6), Parent = r })
            new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 4), Parent = r })
            new("TextLabel", {
                Text = label, FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, -26, 1, 0), LayoutOrder = 0, Parent = r,
            })
            iconBtn(r, "trash-2", "remove", onRemove, 1)
        end
        if #NPC.ExcludeNames > 0 then hintRow(right, "By name (saved):", 0) end
        for i = #NPC.ExcludeNames, 1, -1 do
            local idx = i
            chipRow("name: " .. NPC.ExcludeNames[idx], function() table.remove(NPC.ExcludeNames, idx); showSettings() end)
        end
        if #NPC.ExcludeSigs > 0 then hintRow(right, "By learned fingerprint (saved):", 0) end
        for i = #NPC.ExcludeSigs, 1, -1 do
            local idx = i
            local s = NPC.ExcludeSigs[idx]
            chipRow("learned: " .. (s:sub(1, 22)) .. (#s > 22 and "..." or ""),
                function() table.remove(NPC.ExcludeSigs, idx); showSettings() end)
        end
        local selCount = 0
        for _ in pairs(NPC._excludeSel) do selCount = selCount + 1 end
        if selCount > 0 then hintRow(right, "By selection (this session):", 0) end
        for inst in pairs(NPC._excludeSel) do
            local ok, nm = pcall(function() return inst.Name end)
            chipRow("session: " .. (ok and nm or "(gone)"), function() NPC._excludeSel[inst] = nil; showSettings() end)
        end
    end

    showSettings = function()
        clearKids(right)
        if not selected then
            drawExclusions()
            return
        end
        local f, st = selected, selected.settings
        new("TextLabel", {
            Text = "Folder: " .. f.name, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 0, Parent = right,
        })
        -- right panel uses pure creation order (all LayoutOrder 0), like the rest
        -- of the file: sliders never set LayoutOrder, so mixing explicit orders in
        -- would jump them to the top.
        hintRow(right, "Display name (blank uses the model name):", 0)
        textInput(right, "override name", st.DisplayName, 0, function(t) st.DisplayName = t end)
        hintRow(right, "ESP styling lives in the ESP tab; these exclude this folder per feature:", 0)
        configCheckbox(right, "Exclude from ESP", st.Exclude.ESP, function(v) st.Exclude.ESP = v end)
        configCheckbox(right, "Exclude from Aimbot", st.Exclude.Aimbot, function(v) st.Exclude.Aimbot = v end)
        configCheckbox(right, "Exclude from Silent", st.Exclude.Silent, function(v) st.Exclude.Silent = v end)
        -- v0.57.0: auto-populate this folder by scanning the workspace for models
        -- whose name contains a live player's username (respects the exclusions
        -- shown when no folder is selected).
        configCheckbox(right, "Auto: Usernames (scan workspace)", st.AutoUsername, function(v) st.AutoUsername = v end)
        -- v0.90.0: auto-add rules. Anything matching joins this folder on its own
        st.AutoRules = st.AutoRules or {}
        new("TextLabel", {
            Text = "Auto-Add Rules", FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 0, Parent = right,
        })
        hintRow(right, "Anything in the workspace whose name matches is added to this folder automatically, and new ones join as they spawn.", 0)
        local autoBox = vlist(right, 4, 0)
        local autoAdd = hrow(right, 26, 0)
        local function drawAuto()
            clearKids(autoBox)
            for _, rule in ipairs(st.AutoRules) do
                local card = vlist(autoBox, 4, 0)
                card.BackgroundColor3 = Theme.Palette.PanelElevated
                card.BackgroundTransparency = 0.5
                new("UICorner", { CornerRadius = UDim.new(0, 6), Parent = card })
                new("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
                    PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), Parent = card })
                local head = hrow(card, 20, 0)
                local count = new("TextLabel", {
                    Text = "", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                    TextColor3 = Theme.Palette.Accent, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                    Size = UDim2.new(1, -26, 1, 0), LayoutOrder = 0, Parent = head,
                })
                local function recount()
                    local n = #NPC.ruleMatches(rule)
                    count.Text = (rule.on == false and "Rule (off)  " or "Rule  ") .. n .. (n == 1 and " match" or " matches")
                end
                iconBtn(head, "trash-2", "remove rule", function()
                    for i, x in ipairs(st.AutoRules) do if x == rule then table.remove(st.AutoRules, i) break end end
                    drawAuto()
                end, 1)
                local r1 = hrow(card, 26, 1)
                local dm = dropdown(r1, "", { "contains", "is", "starts with", "ends with", "pattern" }, rule.match or "contains",
                    function(v) rule.match = v; recount() end)
                dm.frame.Size = UDim2.fromOffset(96, 26)
                dm.frame.LayoutOrder = 0
                NPC._flatDD(dm)
                local tv = textInput(r1, "name", rule.value, 1, function(t) rule.value = t; recount() end)
                tv.Size = UDim2.new(1, -102, 0, 26)
                local r2 = hrow(card, 26, 2)
                local dt = dropdown(r2, "", { "Auto", "Itself", "Children" }, rule.take or "Auto",
                    function(v) rule.take = v; recount() end)
                dt.frame.Size = UDim2.fromOffset(96, 26)
                dt.frame.LayoutOrder = 0
                NPC._flatDD(dt)
                local ti = textInput(r2, "inside (optional)", rule.inside, 1, function(t) rule.inside = t; recount() end)
                ti.Size = UDim2.new(1, -102, 0, 26)
                local r3 = vlist(card, 2, 3)
                configCheckbox(r3, "Needs a Humanoid", rule.humanoid == true, function(v) rule.humanoid = v; recount() end)
                configCheckbox(r3, "Enabled", rule.on ~= false, function(v) rule.on = v; recount() end)
                recount()
            end
            if #st.AutoRules == 0 then hintRow(autoBox, "No auto-add rules yet.", 0) end
        end
        iconTextBtn(autoAdd, "plus", "Auto-Add Rule", function()
            st.AutoRules[#st.AutoRules + 1] = { match = "contains", value = "", take = "Auto", inside = "", humanoid = false, on = true }
            drawAuto()
        end, 0)
        drawAuto()
        hintRow(right, "Rules read a value off each model (child .Value, attribute, or property):", 0)
        local ruleBox = vlist(right, 4, 0)
        local addRow = hrow(right, 26, 0)
        -- v0.53.0: each rule is a two-line card (header + source/key row) so it
        -- fits the narrow settings column instead of overlapping the dropdown.
        local function drawRules()
            clearKids(ruleBox)
            for _, rule in ipairs(st.Rules) do
                local card = vlist(ruleBox, 3, 0)
                card.BackgroundColor3 = Theme.Palette.PanelElevated
                card.BackgroundTransparency = 0.5
                card:FindFirstChildOfClass("UIListLayout").Padding = UDim.new(0, 4)
                new("UICorner", { CornerRadius = UDim.new(0, 6), Parent = card })
                new("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
                    PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), Parent = card })
                local head = hrow(card, 20, 0)
                new("TextLabel", {
                    Text = rule.kind .. " rule", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                    TextColor3 = Theme.Palette.Accent, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
                    Size = UDim2.new(1, -26, 1, 0), LayoutOrder = 0, Parent = head,
                })
                iconBtn(head, "trash-2", "remove rule", function()
                    for i, x in ipairs(st.Rules) do if x == rule then table.remove(st.Rules, i) break end end
                    drawRules()
                end, 1)
                local body = hrow(card, 26, 1)
                local dd = dropdown(body, "", { "child", "attribute", "property" }, rule.src or "child",
                    function(v) rule.src = v end)
                dd.frame.Size = UDim2.fromOffset(96, 26)
                dd.frame.LayoutOrder = 0
                NPC._flatDD(dd)
                local ti = textInput(body, "key / name", rule.key, 1, function(t) rule.key = t end)
                ti.Size = UDim2.new(1, -102, 0, 26)
            end
        end
        iconTextBtn(addRow, "plus", "Name Rule", function()
            st.Rules[#st.Rules + 1] = { kind = "Name", src = "child", key = "" }; drawRules()
        end, 0)
        iconTextBtn(addRow, "plus", "Health Rule", function()
            st.Rules[#st.Rules + 1] = { kind = "Health", src = "child", key = "" }; drawRules()
        end, 1)
        drawRules()
    end

    rebuild()
    showSettings()
    -- v0.57.0: let the Picker's exclude actions refresh this panel when it is showing
    -- the exclusion editor (no folder selected).
    NPC._refreshExcl = function() if not selected then showSettings() end end
    return rebuild
end

-- :: ESP sub-tab :: full-featured NPC ESP, its own settings (Shared.NPCESP)
-- so NPCs look independent from players. Renderer is shared (Shared.espDrawRig).
local function buildEspTab(host)
    local N = Shared.NPCESP
    local function colorRow(label, get, set)
        local r = hrow(host, 20, 0)
        new("TextLabel", {
            Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1, TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, -30, 1, 0), LayoutOrder = 0, Parent = r,
        })
        colorSwatch(r, get(), 16, { onChange = set })
    end
    configCheckbox(host, "Enabled (NPC ESP master)", N.Config.MasterOn, function(v) N.Config.MasterOn = v end)
    hintRow(host, "NPC ESP mirrors player ESP with its own independent settings.", 0)
    configCheckbox(host, "Box", N.Boxes.Enabled, function(v) N.Boxes.Enabled = v end)
    dropdown(host, "Box Type", { "2D", "Cube" }, N.Boxes.BoxType, function(v) N.Boxes.BoxType = v end)
    configCheckbox(host, "Fill Box", N.Boxes.FillBox, function(v) N.Boxes.FillBox = v end)
    configCheckbox(host, "Through Walls", N.Boxes.ThroughWalls, function(v) N.Boxes.ThroughWalls = v end)
    configCheckbox(host, "Outline", N.Config.Outline, function(v) N.Config.Outline = v end)
    colorRow("Box Color", function() return N.Boxes.Color end, function(c) N.Boxes.Color = c end)
    dropdown(host, "Color Mode", { "Static", "Health", "Distance", "Rainbow", "Gradient", "Team" }, N.Config.ColorMode,
        function(v) N.Config.ColorMode = v end)
    colorRow("Gradient A", function() return N.Config.GradientColorA2 end, function(c) N.Config.GradientColorA2 = c end)
    colorRow("Gradient B", function() return N.Config.GradientColorB2 end, function(c) N.Config.GradientColorB2 = c end)
    configCheckbox(host, "Names", N.Names.Enabled, function(v) N.Names.Enabled = v end)
    configCheckbox(host, "Names Gradient", N.Config.TextGradient, function(v) N.Config.TextGradient = v end)
    configCheckbox(host, "Distance", N.Indicators.Distance.Enabled, function(v) N.Indicators.Distance.Enabled = v end)
    configCheckbox(host, "Health Bar", N.Health.Bar.Enabled, function(v) N.Health.Bar.Enabled = v end)
    configCheckbox(host, "Health Color By %", N.Health.Based, function(v) N.Health.Based = v end)
    configCheckbox(host, "Health Text", N.Health.Text, function(v) N.Health.Text = v end)
    dropdown(host, "Health Text Pos", { "Above Name", "On Health Bar" }, N.Health.TextPos,
        function(v) N.Health.TextPos = v end)
    configCheckbox(host, "Head Dot", N.Indicators.HeadDot.Enabled, function(v) N.Indicators.HeadDot.Enabled = v end)
    configCheckbox(host, "Skeleton", N.Indicators.Skeleton.Enabled, function(v) N.Indicators.Skeleton.Enabled = v end)
    configCheckbox(host, "Profile Picture", N.Indicators.ProfilePicture.Enabled,
        function(v) N.Indicators.ProfilePicture.Enabled = v end)
    configCheckbox(host, "Tracer", N.Tracer.Enabled, function(v) N.Tracer.Enabled = v end)
    dropdown(host, "Tracer Origin", { "Bottom", "Middle", "Top", "Mouse" }, N.Tracer.Origin,
        function(v) N.Tracer.Origin = v end)
    slider(host, "Render Distance", 50, 5000, N.Config.RenderDistance, 0, function(v) N.Config.RenderDistance = v end)
end

function NPC.buildTab(root)
    local card = panel(root)
    local S = Shared.subTabs(card, { "Picker", "Manager", "ESP" })
    local managerRebuild
    buildPicker(S.Picker, function() if managerRebuild then managerRebuild() end end)
    managerRebuild = buildManager(S.Manager)
    buildEspTab(S.ESP)
end
end)()

-- v0.45.2: Teams is now Extra. NPC now has a real builder (v0.52.0); the IIFE
-- above owns the subsystem and publishes Shared.NPC.buildTab.
addTab("NPC", function(root) Shared.NPC.buildTab(root) end)
-- v0.46.0: Extra grows its first sub-tab, Mods: the universal stat mod
-- from gun research. Pick a source (held tool / any instance), tick values,
-- pin them held or set-once. Session-only, unpin to restore.
-- v0.60.0: ANTICHEATS. Two features that fight rubberbanding (an AC teleporting you
-- back to where you were). Own IIFE for its register budget; publishes
-- Shared.Anticheat for the Extra tab. Both detect a "backward snap": a jump this
-- frame too big to be movement (>= SnapThreshold) that lands on a spot you were at
-- >0.15s ago (within MatchRadius). Normal teleports (spawns, seats) go somewhere
-- NEW, so they never match the history and are ignored.
;(function()
local AC = { SnapThreshold = 16, MatchRadius = 7, Window = 0.5 }
registerConfig("anticheat", AC)
Shared.Anticheat = AC
local RS = RunService
local KEEP = 1.5   -- seconds of position history kept

local hist = {}
local histN = 0        -- ring buffer count (avoids table.remove's O(n) shift per frame)
local histHead = 1     -- index of the oldest live entry
local lastPos, lastCF, lastVel, lastT = nil, nil, nil, nil
local fightCF, fightUntil, nextRec = nil, 0, 0
local function reset()
    hist = {}; histN = 0; histHead = 1
    lastPos, lastCF, lastVel, lastT = nil, nil, nil, nil
    fightCF, fightUntil, nextRec = nil, 0, 0
end
local function hrp()
    local c = LocalPlayer.Character
    return c and c:FindFirstChild("HumanoidRootPart") or nil
end
local function slamTo(r, cf)
    pcall(function()
        r.CFrame = cf
        r.AssemblyLinearVelocity = Vector3.zero
    end)
end
-- mark the current spot as legit (last-good), tracking velocity + time so the next
-- frame can tell a position teleport apart from plain high velocity.
local function markGood(r, now)
    lastPos, lastCF, lastVel, lastT = r.Position, r.CFrame, r.AssemblyLinearVelocity, now
end
-- did we land on a spot we occupied a moment ago? (the signature of a rubberband)
local function matchesHistory(cur, now)
    local rad = AC.MatchRadius or 7
    for i = histN, histHead, -1 do
        local h = hist[i]
        if not h or now - h.t > KEEP then break end
        if (now - h.t) > 0.15 and (h.pos - cur).Magnitude <= rad then return true end
    end
    return false
end
-- shared responder: while a brute fight is live keep slamming; otherwise detect a
-- backward snap and slam back to the pre-snap CFrame. Returns true if it acted.
-- v0.60.1: a jump only counts as a TELEPORT if position moved further than the
-- player's own velocity could carry it (excess = displacement - vel*dt). Plain high
-- velocity (speed) explains its own displacement, so it never reads as a teleport.
local function respond(r, now, brute)
    if brute and now < fightUntil and fightCF then
        slamTo(r, fightCF)
        lastPos, lastCF, lastVel, lastT = fightCF.Position, fightCF, Vector3.zero, now
        return true
    end
    if not lastPos then return false end
    local dt = math.max(now - (lastT or now), 0)
    local disp = (r.Position - lastPos).Magnitude
    local vel = lastVel and lastVel.Magnitude or 0
    local excess = disp - vel * dt * 1.25   -- 1.25 = jitter tolerance on the velocity term
    if excess < (AC.SnapThreshold or 16) then return false end
    if not matchesHistory(r.Position, now) then return false end
    local back = lastCF or CFrame.new(lastPos)
    if brute then fightCF, fightUntil = back, now + (AC.Window or 0.5) end
    slamTo(r, back)
    lastPos, lastCF, lastVel, lastT = back.Position, back, Vector3.zero, now
    return true
end
-- Heartbeat owns history + drives the brute response (fast, physics-timed).
-- v0.60.1: last-good refs update every frame (cheap assignments), but the history
-- ring is only appended ~25x/s -- enough to know "were you here a moment ago",
-- without a table churn every frame.
local function hbTick()
    local r = hrp(); if not r then reset(); return end
    local now = os.clock()
    local brute = Modules.bruteforce_rb and Modules.bruteforce_rb.Enabled
    local anti  = Modules.anti_rb and Modules.anti_rb.Enabled
    if (brute or anti) and respond(r, now, brute) then return end   -- acted: don't log the bad pos
    markGood(r, now)
    if now >= nextRec then
        nextRec = now + 0.04
        histN = histN + 1
        hist[histN] = { t = now, pos = lastPos }
        -- advance the head past entries older than KEEP; compact only when the dead
        -- prefix grows large, so this is amortized O(1) per append, never per frame.
        while histHead < histN and (now - hist[histHead].t) > KEEP do
            hist[histHead] = nil; histHead = histHead + 1
        end
        if histHead > 64 then
            local moved = 0
            for i = histHead, histN do moved = moved + 1; hist[moved] = hist[i]; hist[i] = nil end
            histHead, histN = 1, moved
        end
    end
end
-- RenderStepped adds a second correction pass so a local teleport-back script is
-- caught whichever point in the frame it fires from, and the brute fight gets an
-- extra slam per frame ("really fast").
local function rsTick()
    local r = hrp(); if not r then return end
    local brute = Modules.bruteforce_rb and Modules.bruteforce_rb.Enabled
    local anti  = Modules.anti_rb and Modules.anti_rb.Enabled
    if brute or anti then respond(r, os.clock(), brute) end
end
local connHB, connRS
local function anyOn()
    return (Modules.bruteforce_rb and Modules.bruteforce_rb.Enabled)
        or (Modules.anti_rb and Modules.anti_rb.Enabled)
end
local function startLoops()
    if connHB then return end
    reset()
    connHB = RS.Heartbeat:Connect(hbTick)
    connRS = RS.RenderStepped:Connect(rsTick)
end
local function stopLoops()
    if anyOn() then return end   -- the other feature is still using the loops
    if connHB then connHB:Disconnect(); connHB = nil end
    if connRS then connRS:Disconnect(); connRS = nil end
    reset()
end
LocalPlayer.CharacterAdded:Connect(reset)
registerModule("bruteforce_rb", "Brute-force Rubberbands", startLoops, stopLoops)
registerModule("anti_rb",       "Anti-rubberbands",        startLoops, stopLoops)

function AC.buildPanel(host)
    new("TextLabel", {
        Text = "Fights anti-cheat rubberbands (getting teleported back). Brute-force wins the position war vs a server pull; Anti-rubberbands blocks a local teleport-back script.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left,
        AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 14), Parent = host,
    })
    local cbBrute = moduleCheckbox(host, "Brute-force Rubberbands", "bruteforce_rb")
    local cbAnti  = moduleCheckbox(host, "Anti-rubberbands", "anti_rb")
    slider(host, "Snap Threshold (studs)", 4, 60, AC.SnapThreshold, 0, function(v) AC.SnapThreshold = v end)
    slider(host, "Match Radius (studs)", 1, 75, AC.MatchRadius, 0, function(v) AC.MatchRadius = v end)
    slider(host, "Fight Window (s)", 0.1, 2, AC.Window, 1, function(v) AC.Window = v end)
    -- v0.60.2 fix: the Extra tab is built once and is NOT in rebuildConfigTabs'
    -- list, but rebuildConfigTabs wipes EVERY module's Watchers globally. That
    -- orphaned these checkboxes (a config load, e.g. an auto-load, cleared their
    -- watcher, so toggling the module updated the arraylist but never the box).
    -- Re-subscribe + resync to the live module state whenever the config rebuilds.
    Shared._acResync = function()
        for _, pr in ipairs({ { cbBrute, "bruteforce_rb" }, { cbAnti, "anti_rb" } }) do
            local ctrl, id = pr[1], pr[2]
            local m = Modules[id]
            ctrl.setState(m and m.Enabled or false)
            subscribeModule(id, function(s) ctrl.setState(s) end)
        end
    end
end
end)()

-- v0.68.0: HVH. Manual blink escape plus a return trip: arm it, hold the key
-- to stream shell jumps around the anchor, release to snap back where you
-- started. Own IIFE for its register budget; publishes Shared.Hvh for Extra.
;(function()
local HV = {
    BlinkDist = 500, FaceTarget = true,
    BlinkKeyMode = "Hold", BlinkRate = 0.25, BlinkReturn = true,
    SpamMode = "Hold", SpamDist = 300, SpamRate = 0.25,
    DrawName = "", DrawSpawn = true, DrawLock = true, DrawLand = true,
}
registerConfig("hvh", HV)
Shared.Hvh = HV
Keybinds["hvh_flash"] = nil
local UIS = UserInputService
-- v0.68.5: debug channel. Set getgenv().KoffeeHvhDebug = true and the console
-- narrates every blink fire plus key edges, so a dead Blink answers why.
local function hvhDbg(msg)
    local g = getgenv and getgenv()
    if g and g.KoffeeHvhDebug then print("[koffee][hvh] " .. tostring(msg)) end
end
-- v0.68.2: Get-Up, Panic, and Flash need an engaged Target Lock. Manual Blink
-- is exempt: it fires lock-free. Escapes and flashes answer a locked fight.
local function lockOn()
    return Shared.TargetLock.Enabled and Shared.TargetLock._active
end
local Plrs = game:GetService("Players")

local function myRoot()
    local c = LocalPlayer.Character
    return c and c:FindFirstChild("HumanoidRootPart") or nil
end
-- nearest living enemy root. Stale ghosts are fine: blink direction only.
local function nearestFoe()
    local r = myRoot(); if not r then return nil end
    local best, bd = nil, math.huge
    for _, p in ipairs(Plrs:GetPlayers()) do
        if p ~= LocalPlayer and p.Character then
            local h = p.Character:FindFirstChildOfClass("Humanoid")
            local hr = p.Character:FindFirstChild("HumanoidRootPart")
            if h and h.Health > 0 and hr then
                local d = (hr.Position - r.Position).Magnitude
                if d < bd then bd, best = d, hr end
            end
        end
    end
    return best
end
local function faceFoe()
    if not HV.FaceTarget then return end
    local foe = nearestFoe()
    local cam = Workspace.CurrentCamera
    if foe and cam then pcall(function() cam.CFrame = CFrame.new(cam.CFrame.Position, foe.Position) end) end
end
-- same-tick aim snap onto the live aim target. The aimbot loop would fix this
-- next frame; doing it here means a blink never donates a frame of free damage.
local function snapAim()
    local combat = Shared.Combat
    local t = combat and combat.Aim.Enabled and combat.Aim._target or nil
    local ch = t and t.Character
    local part = ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))
    local cam = Workspace.CurrentCamera
    if part and cam then pcall(function() cam.CFrame = CFrame.new(cam.CFrame.Position, part.Position) end) end
end
-- v0.68.6: random escape vector, fresh entropy every shot. v0.69.2: uniform
-- over the full sphere (sides included, not just up): the shell only works if
-- every direction is live, and void-ward picks are caught by safeSpot below.
local function randomDir()
    local rng = Random.new()
    local z = rng:NextNumber(-1, 1)
    local a = rng:NextNumber(0, math.pi * 2)
    local r = math.sqrt(math.max(1 - z * z, 0))
    return Vector3.new(r * math.cos(a), z, r * math.sin(a))
end
-- v0.69.0: void-safe landing. A blind far jump must never land under the kill
-- plane or over open void (both end at destroy height). Clamp above the plane,
-- confirm ground below, retry a few vectors, else straight Up and fall home.
local function killY()
    local ok, y = pcall(function() return Workspace.FallenPartsDestroyHeight end)
    return (ok and tonumber(y)) or -500
end
local function groundBelow(pos, depth)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { LocalPlayer.Character }
    local ok, hit = pcall(function()
        return Workspace:Raycast(pos, Vector3.new(0, -1, 0) * depth, rp)
    end)
    return ok and hit or nil
end
local function safeSpot(origin, dir, dist)
    local floor = killY() + 100
    local d = dir
    for _ = 1, 6 do
        local cand = origin + d * dist
        if cand.Y < floor then cand = Vector3.new(cand.X, floor, cand.Z) end
        if groundBelow(cand, 2000) then return cand end
        d = randomDir()
    end
    return origin + Vector3.new(0, math.min(dist, 2000), 0)
end
-- v0.73.0: Fast Draw. Equips the named tool the instant it matters (spawn,
-- lock engage, blink landing) instead of after fumbling for a number key.
-- Skips when something is already out, substring match, case-insensitive.
local function drawWeapon()
    local want = HV.DrawName
    if not want or want == "" then return end
    want = string.lower(tostring(want))
    local ch = LocalPlayer.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    for _, c in ipairs(ch:GetChildren()) do
        if c:IsA("Tool") then return end
    end
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and string.find(string.lower(t.Name), want, 1, true) then
                pcall(function() hum:EquipTool(t) end)
                return
            end
        end
    end
end
-- v0.69.2: the sphere is anchored where the key first went active and stays
-- there. Every shot picks a fresh random point on its SHELL around the anchor
-- (never a step from where you stand, which ratchets upward). Radius is
-- BlinkDist in every direction: height, width, and length alike.
-- v0.84.0: declared before fireBlink. Declared below it, this read resolved to
-- nil globals, so every shot re-centred on you and the v0.69.2 anchor never held.
local anchorCF, anchorChar = nil, nil
local function fireBlink()
    local r = myRoot()
    if not r then return end
    local center = r.Position
    if anchorCF and LocalPlayer.Character == anchorChar then center = anchorCF.Position end
    local dest = safeSpot(center, randomDir(), HV.BlinkDist or 500)
    pcall(function()
        r.CFrame = r.CFrame - r.Position + dest
        r.AssemblyLinearVelocity = Vector3.zero
    end)
    if lockOn() then faceFoe(); snapAim() end
    local dm = Modules.hvh_draw
    if dm and dm.Enabled and HV.DrawLand ~= false then drawWeapon() end
    hvhDbg("blink fired dist=" .. tostring(HV.BlinkDist))
end
-- v0.70.0: keyed activation registry. Blink + Spam TP share one pill builder,
-- one input edge handler, one XB poll, one tint sync. Entries read bind + mode
-- live off HV so configs apply without rebuilds. Nil bind means never, not always.
local keyReg = {}
local pendingKey = nil   -- { e, pill, refresh } while arming a rebind
local function newKey(modId, keyF, modeF)
    local e = { mod = modId, k = keyF, m = modeF, held = false, latch = false, pill = nil, cache = nil }
    keyReg[#keyReg + 1] = e
    return e
end
local BlinkK = newKey("hvh_blink", "BlinkKey", "BlinkKeyMode")
local SpamK = newKey("hvh_spam", "SpamKey", "SpamMode")
local function keyActive(e)
    if HV[e.k] == nil then return false end
    if (HV[e.m] or "Hold") == "Toggle" then return e.latch end
    return e.held
end
-- event-driven pill tint (accent while firing). Cached so per-frame callers pay
-- a boolean compare instead of property writes.
local function syncKeyPill(e, force)
    local pill = e.pill
    if not pill or (pendingKey and pendingKey.pill == pill) then return end
    local m = Modules[e.mod]
    local on = (m and m.Enabled and keyActive(e)) and true or false
    if force or e.cache ~= on then
        e.cache = on
        pill.TextColor3 = on and Theme.Palette.Accent or Theme.Palette.TextMuted
    end
end
-- Hold/Toggle chooser popup (right-click), same pattern as every activation pill.
local keyChooser = nil
local function closeKeyChooser()
    if keyChooser then
        pcall(function() keyChooser.frame:Destroy() end)
        if keyChooser.conn then keyChooser.conn:Disconnect() end
        keyChooser = nil
    end
end
local function openKeyChooser(e)
    closeKeyChooser()
    local frame = new("Frame", {
        Name = "HvHModeChooser", Size = UDim2.new(0, 120, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = Theme.Palette.Panel,
        BackgroundTransparency = 0.02, BorderSizePixel = 0, ZIndex = 230, Parent = popupScreen,
    }, {
        corner(6), stroke(Theme.Palette.Border, 1),
        new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
            PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }),
        new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
    })
    for _, mode in ipairs({ "Hold", "Toggle" }) do
        local sel = (HV[e.m] or "Hold") == mode
        local opt = new("TextButton", {
            Size = UDim2.new(1, 0, 0, 22), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = sel and 0.2 or 1, AutoButtonColor = false, Text = mode,
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
            TextColor3 = sel and Theme.Palette.Accent or Theme.Palette.TextMuted, ZIndex = 231, Parent = frame,
        }, { corner(4) })
        opt.MouseButton1Click:Connect(function()
            HV[e.m] = mode
            e.latch = false
            closeKeyChooser()
            syncKeyPill(e, true)
        end)
    end
    local abs, siz = e.pill.AbsolutePosition, e.pill.AbsoluteSize
    local ox, oy = popupOffsetFor(frame, abs.X + siz.X - 120, abs.Y + siz.Y + 6)
    frame.Position = UDim2.new(0, ox, 0, oy)
    keyChooser = { frame = frame }
    task.defer(function()
        if not keyChooser then return end
        keyChooser.conn = UserInputService.InputBegan:Connect(function(input)
            local it = input.UserInputType
            if it == Enum.UserInputType.MouseButton1 or it == Enum.UserInputType.MouseButton2
            or it == Enum.UserInputType.Touch then
                local mp = input.Position
                local a, s = frame.AbsolutePosition, frame.AbsoluteSize
                if not (mp.X >= a.X and mp.X <= a.X + s.X and mp.Y >= a.Y and mp.Y <= a.Y + s.Y) then
                    closeKeyChooser()
                end
            end
        end)
    end)
end
local function actPill(row, e)
    local pill = new("TextButton", {
        Name = "HvHKeyPill", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
        Size = UDim2.new(0, 30, 0, 16), AutomaticSize = Enum.AutomaticSize.X,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2, BorderSizePixel = 0,
        AutoButtonColor = false, Text = "-", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
        TextColor3 = Theme.Palette.TextMuted, ZIndex = 38, Parent = row,
    }, {
        pillCorner(), stroke(Theme.Palette.BorderSubtle),
        new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }),
    })
    local function refresh()
        local bind = HV[e.k]
        local nm = keyLabel(bind)
        if not nm then
            if type(bind) == "string" then nm = bind == "XButton1" and "XB1" or "XB2"
            else nm = "-" end
        end
        pill.Text = nm
        syncKeyPill(e, true)
    end
    refresh()
    e.pill, e.refresh = pill, refresh
    pill.MouseEnter:Connect(function()
        tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Text })
    end)
    pill.MouseLeave:Connect(function()
        if not (pendingKey and pendingKey.pill == pill) then
            syncKeyPill(e, true)
        end
    end)
    pill.MouseButton1Click:Connect(function()
        if pendingKey and pendingKey.pill == pill then
            pendingKey.refresh(); pendingKey = nil
            return
        end
        if pendingKey then pendingKey.refresh() end
        pill.Text = "..."
        tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.Accent })
        pendingKey = { e = e, pill = pill, refresh = refresh }
    end)
    pill.MouseButton2Click:Connect(function() openKeyChooser(e) end)
    popFx(pill)
    return refresh
end
local function keyMatch(input, bind)
    if typeof(bind) ~= "EnumItem" then return false end
    if bind.EnumType == Enum.KeyCode then
        return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == bind
    elseif bind.EnumType == Enum.UserInputType then
        return input.UserInputType == bind
    end
    return false
end
UserInputService.InputBegan:Connect(function(input, gpe)
    -- v0.68.5: re-execs stack input connections (nothing disconnects them).
    -- Without this, every old run flips Toggle again: two flips per press read
    -- as "toggle does nothing". Dead runs stay silent now.
    if Koffee.dead() then return end
    if pendingKey then
        local e = pendingKey.e
        local it = input.UserInputType
        if it == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Escape then
            HV[e.k] = nil; e.held, e.latch = false, false
            pendingKey.refresh(); pendingKey = nil; return
        end
        if gpe and (it == Enum.UserInputType.MouseButton1
                or it == Enum.UserInputType.MouseButton2
                or it == Enum.UserInputType.MouseButton3) then
            return
        end
        local bind
        if it == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then bind = input.KeyCode
        elseif it ~= Enum.UserInputType.Focus and it ~= Enum.UserInputType.MouseMovement
           and it ~= Enum.UserInputType.MouseWheel and it ~= Enum.UserInputType.None
           and it ~= Enum.UserInputType.TextInput and it ~= Enum.UserInputType.InputMethod then bind = it end
        -- fresh key, fresh state: a held-down old key must not stick firing on.
        if bind then HV[e.k] = bind; e.held, e.latch = false, false
            pendingKey.refresh(); pendingKey = nil end
        return
    end
    if gpe then return end
    for _, e in ipairs(keyReg) do
        if keyMatch(input, HV[e.k]) then
            if (HV[e.m] or "Hold") == "Toggle" then e.latch = not e.latch
            else e.held = true end
            hvhDbg(e.mod .. " edge")
            syncKeyPill(e)
        end
    end
end)
UserInputService.InputEnded:Connect(function(input)
    if Koffee.dead() then return end
    for _, e in ipairs(keyReg) do
        if (HV[e.m] or "Hold") == "Hold" and keyMatch(input, HV[e.k]) then
            e.held = false
            syncKeyPill(e)
        end
    end
end)

-- v0.70.0: Spam TP helpers. The sphere follows the locked target (first
-- prioritized player while engaged); without a live one it idles instead of
-- scattering you somewhere dumb.
local nextSpam = 0
local function lockTarget()
    if not lockOn() then return nil end
    local plr = Shared.targetLockPlayer and Shared.targetLockPlayer()
    local ch = plr and plr.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 then return plr, ch end
    return nil
end
-- uniform random point INSIDE a ball: unit direction scaled by radius with a
-- cube-root roll, so volume (not just shell) fills evenly.
local function ballPoint(center, R)
    local rng = Random.new()
    local z = rng:NextNumber(-1, 1)
    local a = rng:NextNumber(0, math.pi * 2)
    local rr = math.sqrt(math.max(1 - z * z, 0))
    local rad = R * (rng:NextNumber(0, 1) ^ (1 / 3))
    return center + Vector3.new(rr * math.cos(a), z, rr * math.sin(a)) * rad
end
-- inside-ball landing with shell-grade void safety, but spam favors motion over
-- caution: every failed check used to return one fixed Up fallback, parking
-- the user in a single spot that read as "locked". Two ground chances, then
-- the raw (clamped) point goes anyway. Falling beats standing still here.
local function safeBall(center, R)
    local floor = killY() + 100
    for _ = 1, 2 do
        local cand = ballPoint(center, R)
        if cand.Y < floor then cand = Vector3.new(cand.X, floor, cand.Z) end
        if groundBelow(cand, 2000) then return cand end
    end
    local cand = ballPoint(center, R)
    if cand.Y < floor then cand = Vector3.new(cand.X, floor, cand.Z) end
    return cand
end
-- hand the aim systems their target directly: prime both _targets and snap
-- the camera same-tick, so the loop after a teleport starts aimed, not sweeping.
local function primeAim(plr)
    local combat = Shared.Combat
    if combat then
        if combat.Aim then combat.Aim._target = plr end
        if combat.Silent then combat.Silent._target = plr end
    end
    local ch = plr.Character
    local part = ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))
    local cam = Workspace.CurrentCamera
    if part and cam then pcall(function() cam.CFrame = CFrame.new(cam.CFrame.Position, part.Position) end) end
end
-- boomerang anchor: where you stood when the key first went active. Release
-- (or unlatch, or disarm) snaps you back to it. Cleared on respawn so death
-- never slingshots a fresh body back into the fight that killed it. Spam TP
-- keeps its own anchor pair under the same Return toggle.
local wasBlinkActive = false
local spamAnchorCF, spamAnchorChar, wasSpamActive = nil, nil, false
local lastDrawLock = false
LocalPlayer.CharacterAdded:Connect(function()
    anchorCF, anchorChar, wasBlinkActive = nil, nil, false
    spamAnchorCF, spamAnchorChar, wasSpamActive = nil, nil, false
    lastDrawLock = false
    -- v0.73.0: hand the fresh rig the gun, delayed past rig + backpack
    -- replication so both actually exist to touch. (v0.74.0: no desync state
    -- to re-arm anymore; the cadence needs no per-rig setup.)
    task.spawn(function()
        task.wait(1)
        if Koffee.dead() then return end
        local dm = Modules.hvh_draw
        if dm and dm.Enabled and HV.DrawSpawn ~= false then drawWeapon() end
    end)
end)

-- armed Blink auto-fires on its interval while its key is active. Rising edge
-- saves the anchor; falling edge snaps back to it when Return is on.
local nextBlink, pBX = 0, { false, false }
RunService.Heartbeat:Connect(function()
    if Koffee.dead() then return end
    local now = os.clock()
    -- v0.68.5: Hold backfill for every key. A game-consumed key never fires
    -- Began, so edges alone silently never arm. Live polled state cannot be
    -- eaten. Mirrors the silent-aim LMB backfill precedent.
    for _, e in ipairs(keyReg) do
        if (HV[e.m] or "Hold") == "Hold" then
            local k = HV[e.k]
            if typeof(k) == "EnumItem" then
                local before = e.held
                if k.EnumType == Enum.KeyCode then
                    e.held = UIS:IsKeyDown(k)
                elseif k.EnumType == Enum.UserInputType then
                    local ok, down = pcall(function() return UIS:IsMouseButtonPressed(k) end)
                    if ok then e.held = down end
                end
                if e.held ~= before then syncKeyPill(e) end
            end
        end
    end
    -- XButton driver for every key (Roblox never fires mouse 4/5). Reads the
    -- feed unconditionally like combat does: gating capture on "already bound
    -- to XB" made XB unbindable, the pill sat on "..." forever. That was the bug.
    local xb1, xb2 = Helper.XB1, Helper.XB2
    local e1, e2 = (xb1 and not pBX[1]), (xb2 and not pBX[2])
    local function xbDown(k) return (k == "XButton1" and xb1) or (k == "XButton2" and xb2) or false end
    local function xbEdge(k) return (k == "XButton1" and e1) or (k == "XButton2" and e2) or false end
    if pendingKey then
        local e = pendingKey.e
        local k = (e2 and "XButton2") or (e1 and "XButton1") or nil
        if k then HV[e.k] = k; e.held, e.latch = false, false
            pendingKey.refresh(); pendingKey = nil end
    else
        for _, e in ipairs(keyReg) do
            local k = HV[e.k]
            if type(k) == "string" then
                if (HV[e.m] or "Hold") == "Toggle" then
                    if xbEdge(k) then e.latch = not e.latch; syncKeyPill(e) end
                else
                    local held = xbDown(k)
                    if held ~= e.held then e.held = held; syncKeyPill(e) end
                end
            end
        end
    end
    pBX[1], pBX[2] = xb1, xb2
    -- armed Blink auto-fires on its interval while its key is active. No lock
    -- needed: manual mobility works in any fight, locked or not.
    local b = Modules.hvh_blink
    local active = b and b.Enabled and keyActive(BlinkK)
    if active and not wasBlinkActive then
        local r = myRoot()
        if r then anchorCF, anchorChar = r.CFrame, LocalPlayer.Character end
    end
    if active and now >= nextBlink then
        nextBlink = now + (HV.BlinkRate or 0.25)
        fireBlink()
    end
    if not active and wasBlinkActive then
        if HV.BlinkReturn ~= false then
            local r = myRoot()
            if r and anchorCF and LocalPlayer.Character == anchorChar then
                pcall(function()
                    r.CFrame = anchorCF
                    r.AssemblyLinearVelocity = Vector3.zero
                end)
                hvhDbg("blink returned")
            end
        end
        anchorCF, anchorChar = nil, nil
    end
    wasBlinkActive = active
    -- Spam TP: sphere follows the locked target, fresh inside-ball point per
    -- interval, targets primed so aim starts aimed. Idles with no live target.
    -- v0.70.1: same boomerang contract as Blink under the shared Return toggle.
    do
        local s = Modules.hvh_spam
        local on = s and s.Enabled and keyActive(SpamK)
        if on and not wasSpamActive then
            local r = myRoot()
            if r then spamAnchorCF, spamAnchorChar = r.CFrame, LocalPlayer.Character end
        end
        if on and now >= nextSpam then
            nextSpam = now + (HV.SpamRate or 0.25)
            local plr, ch = lockTarget()
            local r = myRoot()
            local hr = ch and ch:FindFirstChild("HumanoidRootPart")
            if plr and r and hr then
                local dest = safeBall(hr.Position, HV.SpamDist or 300)
                pcall(function()
                    r.CFrame = r.CFrame - r.Position + dest
                    r.AssemblyLinearVelocity = Vector3.zero
                end)
                primeAim(plr)
                hvhDbg("spam tp")
            end
        end
        if not on and wasSpamActive then
            if HV.BlinkReturn ~= false then
                local r = myRoot()
                if r and spamAnchorCF and LocalPlayer.Character == spamAnchorChar then
                    pcall(function()
                        r.CFrame = spamAnchorCF
                        r.AssemblyLinearVelocity = Vector3.zero
                    end)
                    hvhDbg("spam returned")
                end
            end
            spamAnchorCF, spamAnchorChar = nil, nil
        end
        wasSpamActive = on
    end
    -- v0.74.0: velocity desync lives on its own connection (Wait interleaves
    -- render; the shared tick must never stall behind it). See registration.
    -- Fast Draw on lock engage.
    do
        local dm = Modules.hvh_draw
        local engaged = lockOn()
        if engaged and not lastDrawLock then
            if dm and dm.Enabled and HV.DrawLock ~= false then drawWeapon() end
        end
        lastDrawLock = engaged
    end
    -- v0.73.1: relentless retry. Missing tool (respawn delay, pickup mid-fight,
    -- backpack lag) re-attempts every Heartbeat until something is out. The
    -- call self-skips on empty name or an equipped tool, so idle cost is ~nil.
    do
        local dm = Modules.hvh_draw
        if dm and dm.Enabled then drawWeapon() end
    end
end)

-- v0.68.1: manual blink. v0.68.4: arm + key (movement pattern). The checkbox
-- arms, the pill key activates (Hold streams, Toggle latches). Fires alone.
registerModule("hvh_blink", "Blink", function() end,
    function() BlinkK.held, BlinkK.latch = false, false; syncKeyPill(BlinkK, true) end)
registerModule("hvh_spam", "Spam TP", function() end,
    function() SpamK.held, SpamK.latch = false, false; syncKeyPill(SpamK, true) end)
-- v0.74.0: ported desync cadence. Every Heartbeat: micro-rotate the root
-- (marks it dirty so it replicates without moving), write a huge fresh random
-- velocity, hold it through the render step, then restore the saved one. Other
-- clients extrapolate the lie and render you wrong; you keep your velocity, so
-- walking, jumps, and fly all feel normal. No pinning, no state changes: one
-- toggle. Own connection (the render Wait must not stall the shared tick).
local veloConn = nil
local function startVelo()
    if veloConn then return end
    veloConn = RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local m = Modules.hvh_velo
        if not (m and m.Enabled) then return end
        local r = myRoot()
        if not r then return end
        local ok, saved = pcall(function() return r.AssemblyLinearVelocity end)
        pcall(function()
            r.CFrame = r.CFrame * CFrame.Angles(0, math.rad(0.0001), 0)
            local rng = Random.new()
            r.AssemblyLinearVelocity = Vector3.new(
                rng:NextNumber(2000, 4000), rng:NextNumber(2000, 4000), rng:NextNumber(2000, 4000))
        end)
        RunService.RenderStepped:Wait()
        if ok then pcall(function() r.AssemblyLinearVelocity = saved end) end
    end)
end
local function stopVelo()
    if veloConn then veloConn:Disconnect(); veloConn = nil end
    local r = myRoot()
    if r then pcall(function() r.AssemblyLinearVelocity = Vector3.zero end) end
end
-- v0.74.1: ported anti-script shell, source-faithful and unconditional like the
-- original (runs whether desync is on or not). On spawn, drops character Scripts
-- outside Health/Sound that carry a LocalScript; matching Scripts added later
-- get their LocalScript fired once after a beat. pcall-wrapped so a strange rig
-- can never break load. Skipped the toggle print: print policy still stands.
local function clearUnwantedScripts(character)
    for _, v in pairs(character:GetChildren()) do
        if v:IsA("Script") and v.Name ~= "Health" and v.Name ~= "Sound" and v:FindFirstChild("LocalScript") then
            pcall(function() v:Destroy() end)
        end
    end
end
-- v0.74.1: ported anti-script shell, source-faithful. v0.74.2: gated on the
-- velo toggle. Unconditional firing blind-fired game remotes on every spawn,
-- which is the prime suspect for weird-feeling joins. Same mechanism, armed
-- only while you actually want desync running.
local function shellOn()
    local vm = Modules.hvh_velo
    return vm and vm.Enabled
end
LocalPlayer.CharacterAdded:Connect(function(char)
    repeat task.wait() until char
    if shellOn() then clearUnwantedScripts(char) end
    char.ChildAdded:Connect(function(child)
        if child:IsA("Script") and child:FindFirstChild("LocalScript") then
            task.wait(0.25)
            if shellOn() then
                hvhDbg("shell fire " .. tostring(child.Name))
                pcall(function() child.LocalScript:FireServer() end)
            end
        end
    end)
end)
registerModule("hvh_velo", "Velocity Desync", startVelo, stopVelo)
registerModule("hvh_draw", "Fast Draw", function() end, function() end)
Modules.hvh_blink.IsActive = function()
    local m = Modules.hvh_blink
    return (m and m.Enabled and keyActive(BlinkK)) and true or false
end
Modules.hvh_spam.IsActive = function()
    local m = Modules.hvh_spam
    return (m and m.Enabled and keyActive(SpamK)) and true or false
end

function HV.buildPanel(host)
    new("TextLabel", {
        Text = "Hacker vs Hacker features.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left,
        AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 14), Parent = host,
    })
    local cbBlink = moduleCheckbox(host, "Blink", "hvh_blink")
    local blinkRef = actPill(cbBlink.row, BlinkK)
    -- v0.68.7: 0 means uncapped (every Heartbeat). Random escapes want max rate.
    slider(host, "Blink Interval (s)", 0, 0.6, HV.BlinkRate or 0.25, 2, function(v) HV.BlinkRate = v end)
    local cbSpam = moduleCheckbox(host, "Spam TP", "hvh_spam")
    local spamRef = actPill(cbSpam.row, SpamK)
    -- v0.70.0: follow-sphere radius around the locked target, capped at 10000.
    -- Points land INSIDE the ball (volume), void-checked like shell landings.
    slider(host, "Spam Radius", 10, 10000, HV.SpamDist or 300, 0, function(v) HV.SpamDist = v end)
    slider(host, "Spam Interval (s)", 0, 0.6, HV.SpamRate or 0.25, 2, function(v) HV.SpamRate = v end)
    -- v0.68.9: exact entry, not a drag slider. Past 1M one slider pixel is
    -- thousands of studs, so small and huge jumps cannot share a control.
    -- Typing keeps both 500 and 8000000 settable. Clamped 10 to 10000000:
    -- float32 holds ~0.1 studs at 1M and ~1 stud at 10M (past that the rig
    -- itself degrades, verified by our own 253M probe reading ~16 studs off).
    local distRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, ZIndex = 34, Parent = host,
    })
    new("TextLabel", {
        Text = "Blink Distance", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, -110, 1, 0),
        ZIndex = 34, Parent = distRow,
    })
    local distBox = new("TextBox", {
        Text = tostring(math.floor(HV.BlinkDist or 500)), ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Body, TextColor3 = Theme.Palette.Text,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2, BorderSizePixel = 0,
        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
        Size = UDim2.new(0, 100, 0, 22), ZIndex = 35, Parent = distRow,
    }, { corner(7), stroke(Theme.Palette.BorderSubtle) })
    distBox.FocusLost:Connect(function(enter)
        if enter then
            -- parens: gsub returns (string, count) and count would land in
            -- tonumber's base slot (the exact crash in the screenshot).
            local n = tonumber((distBox.Text:gsub("[^%d%.]", "")))
            if n then HV.BlinkDist = math.clamp(math.floor(n), 10, 10000000) end
        end
        distBox.Text = tostring(math.floor(HV.BlinkDist or 500))
    end)
    -- v0.69.1: release (or unlatch, or disarm) snaps back to the anchor saved
    -- when the key first went active. Unchecked means one-way trips only.
    configCheckbox(host, "Return To Start", HV.BlinkReturn ~= false, function(v) HV.BlinkReturn = v end)
    configCheckbox(host, "Face Target After Blink", HV.FaceTarget, function(v) HV.FaceTarget = v end)
    local cbVelo = moduleCheckbox(host, "Velocity Desync", "hvh_velo")
    local veloPill = keybindPill(cbVelo.row, "hvh_velo", nil, "Velocity Desync")
    local cbDraw = moduleCheckbox(host, "Fast Draw", "hvh_draw")
    local drawRow = new("Frame", {
        Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, ZIndex = 34, Parent = host,
    })
    new("TextLabel", {
        Text = "Draw Weapon", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Body,
        TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, -110, 1, 0),
        ZIndex = 34, Parent = drawRow,
    })
    local drawBox = new("TextBox", {
        Text = tostring(HV.DrawName or ""), ClearTextOnFocus = false,
        FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Body, TextColor3 = Theme.Palette.Text,
        BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2, BorderSizePixel = 0,
        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
        Size = UDim2.new(0, 100, 0, 22), ZIndex = 35, Parent = drawRow,
    }, { corner(7), stroke(Theme.Palette.BorderSubtle) })
    drawBox.FocusLost:Connect(function(enter)
        if enter then HV.DrawName = tostring(drawBox.Text or "") end
        drawBox.Text = tostring(HV.DrawName or "")
    end)
    -- v0.73.1: click-to-pick from the live backpack (exact names, no typos).
    -- Rescan re-reads it; typing still works for tools you do not own yet.
    local toolList = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1, ZIndex = 34, Parent = host,
    }, {
        new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical,
            Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
    })
    local function refreshTools()
        for _, c in ipairs(toolList:GetChildren()) do
            if c:IsA("GuiObject") then c:Destroy() end
        end
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        local n = 0
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") and n < 12 then
                    n = n + 1
                    local nm = t.Name
                    local b = new("TextButton", {
                        Text = nm, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
                        TextColor3 = (HV.DrawName == nm) and Theme.Palette.Accent or Theme.Palette.Text,
                        AutoButtonColor = false, BackgroundColor3 = Theme.Palette.PanelElevated,
                        BackgroundTransparency = 0.2, BorderSizePixel = 0,
                        Size = UDim2.new(1, 0, 0, 20), ZIndex = 35, Parent = toolList,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                    }, { corner(4), stroke(Theme.Palette.BorderSubtle) })
                    b.MouseButton1Click:Connect(function()
                        HV.DrawName = nm
                        drawBox.Text = nm
                        refreshTools()
                    end)
                end
            end
        end
        if n == 0 then
            new("TextLabel", {
                Text = "No tools right now. Pick up the gun, then Rescan.",
                FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
                TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
                TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, 0, 0, 14),
                ZIndex = 34, Parent = toolList,
            })
        end
        local rs = new("TextButton", {
            Text = "Rescan", FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, AutoButtonColor = false,
            BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Size = UDim2.new(0, 70, 0, 20), ZIndex = 35, Parent = toolList,
        }, { corner(4), stroke(Theme.Palette.BorderSubtle) })
        rs.MouseButton1Click:Connect(function() refreshTools() end)
    end
    refreshTools()
    local drawSpawn = configCheckbox(host, "Draw On Spawn", HV.DrawSpawn ~= false, function(v) HV.DrawSpawn = v end)
    local drawLock = configCheckbox(host, "Draw On Lock", HV.DrawLock ~= false, function(v) HV.DrawLock = v end)
    local drawLand = configCheckbox(host, "Draw On Land", HV.DrawLand ~= false, function(v) HV.DrawLand = v end)
    -- Extra is never rebuilt but the watcher wipe is global (see Anticheats
    -- above): re-subscribe + resync here so config loads cannot orphan these.
    Shared._hvhResync = function()
        for _, pr in ipairs({ { cbBlink, "hvh_blink" }, { cbSpam, "hvh_spam" }, { cbVelo, "hvh_velo" }, { cbDraw, "hvh_draw" } }) do
            local ctrl, id = pr[1], pr[2]
            local m = Modules[id]
            ctrl.setState(m and m.Enabled or false)
            subscribeModule(id, function(s) ctrl.setState(s) end)
        end
        if blinkRef then blinkRef() end
        if spamRef then spamRef() end
        if veloPill then veloPill.Text = keyLabel(Keybinds["hvh_velo"]) or "No Keybind" end
        drawSpawn.setState(HV.DrawSpawn ~= false)
        drawLock.setState(HV.DrawLock ~= false)
        drawLand.setState(HV.DrawLand ~= false)
        pcall(function()
            if distBox and not distBox:IsFocused() then
                distBox.Text = tostring(math.floor(HV.BlinkDist or 500))
            end
        end)
        pcall(function()
            if not drawBox:IsFocused() then drawBox.Text = tostring(HV.DrawName or "") end
        end)
    end
end
end)()

-- v0.70.0: suspect scanner. Watches every living rig for teleport jumps and
-- sustained inhuman velocity, one cheap roster sweep per 0.25s (positions +
-- velocity only, no raycasts, respawns re-baseline silently). Flags publish on
-- Shared.Suspects for the player list; stale flags expire after 90 seconds.
;(function()
local SUS = {}
Shared.Suspects = SUS
local Plrs = game:GetService("Players")
local track, nextSweep = {}, 0
Plrs.PlayerRemoving:Connect(function(p) track[p] = nil; SUS[tostring(p.UserId)] = nil end)
local function note(uid, reason)
    local k = tostring(uid)
    if not SUS[k] then
        SUS[k] = { reason = reason, at = os.clock() }
        if Shared._playerListRefresh then pcall(Shared._playerListRefresh) end
    else
        SUS[k].reason, SUS[k].at = reason, os.clock()
    end
end
RunService.Heartbeat:Connect(function()
    if Koffee.dead() then return end
    local now = os.clock()
    if now < nextSweep then return end
    nextSweep = now + 0.25
    for k, f in pairs(SUS) do
        if now - f.at > 90 then SUS[k] = nil end
    end
    for _, p in ipairs(Plrs:GetPlayers()) do
        if p ~= LocalPlayer and p.Character then
            local hum = p.Character:FindFirstChildOfClass("Humanoid")
            local hr = p.Character:FindFirstChild("HumanoidRootPart")
            if hum and hum.Health > 0 and hr then
                local t = track[p]
                local pos, vel = hr.Position, hr.AssemblyLinearVelocity
                if not t or t.char ~= p.Character then
                    track[p] = { char = p.Character, pos = pos, vel = vel, t = now, events = {}, fast = 0 }
                else
                    local dt = math.max(now - t.t, 0.001)
                    local disp = (pos - t.pos).Magnitude
                    local carried = (t.vel and t.vel.Magnitude or 0) * dt * 1.25
                    t.pos, t.vel, t.t = pos, vel, now
                    local ev, n = t.events, 0
                    for i = #ev, 1, -1 do if now - ev[i] > 10 then table.remove(ev, i) else n = n + 1 end end
                    if disp - carried > 40 then
                        ev[#ev + 1] = now; n = n + 1
                        if n >= 3 then note(p.UserId, "teleports x" .. n .. "/10s") end
                    end
                    local spd = vel and vel.Magnitude or 0
                    local seated = hum:GetState() == Enum.HumanoidStateType.Seated
                    if not seated and spd > 300 then
                        t.fast = (t.fast or 0) + 1
                        if t.fast >= 3 then note(p.UserId, "velocity " .. math.floor(spd)) end
                    else t.fast = 0 end
                end
            else track[p] = nil end
        end
    end
end)
end)()

addTab("Extra", function(epanel)
    -- v0.48.3: no card title: Combat/Custom cards are titleless so the
    -- secondary bar sits at the very top of the feature box. Same here.
    local card = panel(epanel)
    local R = Shared.subTabs and Shared.subTabs(card, { "Mods", "Anticheats", "Hvh" }) or nil
    local host = (R and R["Mods"]) or card
    if R and R["Anticheats"] and Shared.Anticheat then Shared.Anticheat.buildPanel(R["Anticheats"]) end
    if R and R["Hvh"] and Shared.Hvh then Shared.Hvh.buildPanel(R["Hvh"]) end
    -- pins live across rescans, keyed so a rebuild re-attaches, not dupes.
    -- { on, want, orig, kind } / kind = number|bool|string.
    -- v0.75.0: pins persist. ModSave mirrors {id, on, want, kind} (never orig,
    -- conns, or instances) at every mutation; reconcile re-seeds from it load.
    local ModSave = { Pins = {} }
    registerConfig("modpins", ModSave)
    local pins = {}
    local function syncPinSave(id)
        local pin = pins[id]
        if not pin then ModSave.Pins[id] = nil; return end
        ModSave.Pins[id] = { id = id, on = pin.on and true or false, want = pin.want, kind = pin.kind }
    end
    local rows = {}   -- id -> { cur, entry } for the heartbeat refresh
    local srcLabel, listBox
    -- v0.82.0: Full Game results picker. Forward-declared: the scope dropdown
    -- above calls refreshFullUI, defined after scan().
    local refreshFullUI, gameSweep, resDD, resMap
    local current = { mode = "none", inst = nil, path = "" }

    local function entryId(srcId, sub, name) return srcId .. "|" .. sub .. "|" .. name end
    local function srcId()
        if current.mode == "tool" then return "tool:" .. (current.toolName or "?") end
        if current.mode == "multi" then return "multi:" .. (current.name or "?") end
        return "path:" .. current.path
    end
    local function resolveRoot()
        if current.mode == "tool" then
            local ch = LocalPlayer and LocalPlayer.Character
            -- follow the gun into the backpack: Tools leave the character
            -- on unequip, and pins silently dying with them is a trap.
            local nm = current.toolName
            local t = ch and nm and ch:FindFirstChild(nm)
            if t and t:IsA("Tool") then return t end
            local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
            t = bp and nm and bp:FindFirstChild(nm)
            if t and t:IsA("Tool") then return t end
            return nil
        elseif current.mode == "picked" then
            if current.inst and current.inst.Parent then return current.inst end
            if current.path ~= "" and Shared.resolvePath then
                local ok, inst = pcall(Shared.resolvePath, current.path)
                if ok and inst and inst.Parent then
                    current.inst = inst
                    return inst
                end
            end
        end
        return nil
    end
    -- v0.83.0 BULK: multi mode holds a same-named instance set. resolveRoots
    -- lists the live ones; nodeOf/resolveAll fan a row out across them, so one
    -- row sets/pins every same-named gun at once. Single modes behave as before.
    local function resolveRoots()
        if current.mode == "multi" then
            local out = {}
            for _, inst in ipairs(current.roots or {}) do
                if inst and inst.Parent then out[#out + 1] = inst end
            end
            return out
        end
        local r = resolveRoot()
        if r then return { r } end
        return {}
    end
    local function nodeOf(e, root)
        local node = root
        if e.sub ~= "" then
            node = root:FindFirstChild(e.sub)
            if not node then return nil end
        end
        return node
    end
    local function handleOf(e, root)
        local node = nodeOf(e, root)
        if not node then return nil end
        if e.isAttr then
            local v = node:GetAttribute(e.name)
            return (v ~= nil) and { attr = true, node = node } or nil
        end
        local v = node:FindFirstChild(e.name)
        if v and (v:IsA("IntValue") or v:IsA("NumberValue")
            or v:IsA("BoolValue") or v:IsA("StringValue")) then return v end
        return nil
    end
    local function resolveEntry(e)
        for _, root in ipairs(resolveRoots()) do
            local h = handleOf(e, root)
            if h then return h end
        end
        return nil
    end
    local function resolveAll(e)
        local out = {}
        for _, root in ipairs(resolveRoots()) do
            local h = handleOf(e, root)
            if h then out[#out + 1] = h end
        end
        return out
    end
    local function readEntry(e)
        for _, h in ipairs(resolveAll(e)) do
            if e.isAttr then
                local v = h.node:GetAttribute(e.name)
                if v ~= nil then return v end
            else
                return h.Value
            end
        end
        return nil
    end
    local function writeEntry(e, want)
        local wrote = false
        for _, h in ipairs(resolveAll(e)) do
            local ok
            if e.isAttr then
                ok = pcall(function() h.node:SetAttribute(e.name, want) end)
            else
                ok = pcall(function() h.Value = want end)
            end
            if ok then wrote = true end
        end
        return wrote
    end
    local function fmt(v)
        local t = typeof(v)
        if t == "number" then
            return tostring(math.floor(v * 1000 + 0.5) / 1000)
        elseif t == "boolean" then
            return v and "true" or "false"
        elseif t == "string" then
            return #v > 18 and (v:sub(1, 17) .. "..") or v
        end
        return "?"
    end
    -- v0.46.2: instant re-assert. Polling loses to games that rewrite the
    -- value every frame (spread bloom): the changed signal wins it back
    -- the same frame. Heartbeat re-hooks after round rebuilds.
    local function unhookPin(pin)
        if pin.conns then
            for _, c in ipairs(pin.conns) do pcall(function() c:Disconnect() end) end
        end
        pin.conns = {}
    end
    local function hookPin(pin, e)
        unhookPin(pin)
        for _, h in ipairs(resolveAll(e)) do
            local inst = e.isAttr and h.node or h
            local sig = e.isAttr and h.node:GetAttributeChangedSignal(e.name)
                or h:GetPropertyChangedSignal("Value")
            if sig then
                pin.conns[#pin.conns + 1] = sig:Connect(function()
                    if not pin.on then return end
                    local cur = readEntry(e)
                    if cur ~= nil and pin.want ~= nil and cur ~= pin.want then
                        writeEntry(e, pin.want)
                    end
                end)
            end
        end
        if pin.want ~= nil then writeEntry(e, pin.want) end
    end
    -- per-handle originals: same-named guns may hold different values, so each
    -- handle restores its own. Keyed inline (handle + attr name).
    local function snapOrig(pin, e)
        pin.origs = pin.origs or {}
        for _, h in ipairs(resolveAll(e)) do
            local hi = e.isAttr and h.node or h
            local nm = e.isAttr and e.name or nil
            local found = false
            for _, r in ipairs(pin.origs) do
                if r.h == hi and r.nm == nm then found = true; break end
            end
            if not found then
                local v = e.isAttr and hi:GetAttribute(e.name) or hi.Value
                if v ~= nil then pin.origs[#pin.origs + 1] = { h = hi, nm = nm, v = v } end
            end
        end
    end
    local function restoreOrigs(pin)
        for _, r in ipairs(pin.origs or {}) do
            pcall(function()
                if r.h.Parent then
                    if r.nm then r.h:SetAttribute(r.nm, r.v) else r.h.Value = r.v end
                end
            end)
        end
    end
    -- one row: pin toggle | name | live value | editor (box or bool flip).
    -- Enter in the box = set once now. Pin = hold against rewrites.
    local function buildRow(list, e, id, kind)
        local pin = pins[id]
        if not pin then
            pin = { on = false, want = nil, origs = nil, conns = {}, kind = kind }
            pins[id] = pin
        end
        local row = new("Frame", {
            Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
            ZIndex = 34, Parent = list,
        }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 6), VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder }) })
        local pinBtn = new("TextButton", {
            Size = UDim2.new(0, 30, 0, 20), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.2, BorderSizePixel = 0, AutoButtonColor = false,
            Text = pin.on and "On" or "Off", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = pin.on and Theme.Palette.Accent or Theme.Palette.TextMuted,
            LayoutOrder = 1, ZIndex = 35, Parent = row,
        }, { pillCorner() })
        popFx(pinBtn)   -- v0.48.0: pin flips squash on press
        Koffee.attachBtnHover(pinBtn, 0, 0.2)   -- v0.48.0: background eases in on hover
        new("TextLabel", {
            Text = (e.sub ~= "" and (e.sub .. ".") or "") .. e.name .. (e.isAttr and " *" or ""),
            FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            Size = UDim2.new(1, -190, 1, 0), TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            LayoutOrder = 2, ZIndex = 35, Parent = row,
        })
        local cur = new("TextLabel", {
            Text = "", FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            Size = UDim2.new(0, 64, 1, 0), TextXAlignment = Enum.TextXAlignment.Right,
            TextTruncate = Enum.TextTruncate.AtEnd,
            LayoutOrder = 3, ZIndex = 35, Parent = row,
        })
        rows[id] = { cur = cur, entry = e }
        local function paintPin()
            pinBtn.Text = pin.on and "On" or "Off"
            pinBtn.TextColor3 = pin.on and Theme.Palette.Accent or Theme.Palette.TextMuted
        end
        pinBtn.MouseButton1Click:Connect(function()
            pin.on = not pin.on
            if pin.on then
                snapOrig(pin, e)
                hookPin(pin, e)
            else
                unhookPin(pin)
                restoreOrigs(pin)
            end
            paintPin()
            syncPinSave(id)
        end)
        if kind == "bool" then
            local flip = new("TextButton", {
                Size = UDim2.new(0, 80, 0, 20), BackgroundColor3 = Theme.Palette.PanelElevated,
                BackgroundTransparency = 0.2, BorderSizePixel = 0, AutoButtonColor = false,
                Text = pin.want ~= nil and tostring(pin.want) or "Set?",
                FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
                TextColor3 = Theme.Palette.Text, LayoutOrder = 4, ZIndex = 35, Parent = row,
            }, { pillCorner() })
            popFx(flip)   -- v0.48.0: bool flips squash on press
            Koffee.attachBtnHover(flip, 0, 0.2)   -- v0.48.0: background eases in on hover
            flip.MouseButton1Click:Connect(function()
                local v = readEntry(e)
                pin.want = not (v == true)
                if pin.want == false and v == false then pin.want = true end
                snapOrig(pin, e)
                writeEntry(e, pin.want)
                flip.Text = tostring(pin.want)
                syncPinSave(id)
            end)
        else
            local box = new("TextBox", {
                Size = UDim2.new(0, 80, 0, 20),
                Text = pin.want ~= nil and tostring(pin.want) or "",
                PlaceholderText = kind == "number" and "Num" or "Text",
                ClearTextOnFocus = false, FontFace = Theme.Fonts.Mono, TextSize = Theme.Text.Tiny,
                TextColor3 = Theme.Palette.Text, PlaceholderColor3 = Theme.Palette.TextFaint,
                BackgroundColor3 = Theme.Palette.PanelElevated, BackgroundTransparency = 0.2,
                BorderSizePixel = 0, LayoutOrder = 4, ZIndex = 35, Parent = row,
            }, { pillCorner() })
            box.FocusLost:Connect(function(enter)
                if not enter then return end
                local w = kind == "number" and tonumber(box.Text) or box.Text
                if w == nil or (kind ~= "number" and w == "") then return end
                pin.want = w
                snapOrig(pin, e)
                writeEntry(e, w)
                syncPinSave(id)
            end)
        end
        return row   -- v0.48.0: scan() staggers rows in on rebuild
    end
    -- v0.46.1: common gun-value patterns. Substring match on the lowercase
    -- name: games rename everything, but ammo/damage/rate always read alike.
    local COMMON_GUN = { "ammo", "clip", "mag", "reserve", "storedammo",
        "bullet", "damage", "dmg", "headshot", "firerate", "rateoffire",
        "rpm", "burst", "cooldown", "reload", "range", "falloff", "spread",
        "recoil", "bloom", "kick", "auto", "suppres", "velocity", "equip",
        "aim", "zoom", "fov", "penetrat", "pellet", "shot" }
    local function isCommonGun(name)
        local q = tostring(name):lower()
        for _, p in ipairs(COMMON_GUN) do
            if q:find(p, 1, true) then return true end
        end
        return false
    end
    local function sectionLbl(list, text)
        new("TextLabel", {
            Text = text, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Tiny,
            TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 12), TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 34, Parent = list,
        })
    end
    local function scan()
        for _, c in ipairs(listBox:GetChildren()) do
            if c:IsA("Frame") or c:IsA("TextLabel") then c:Destroy() end
        end
        rows = {}
        -- v0.82.0/v0.82.2/v0.83.0: Full Game scope never needs a source.
        -- Nothing picked, or every root dead, sweeps the game into the
        -- results picker. Multi mode resolves its own root set.
        local scopeOn = ((Shared.Combat and Shared.Combat.Gun
            and Shared.Combat.Gun.ScanScope) or "Replicated") == "Full Game"
        local scanRoots = {}
        if current.mode == "multi" then
            scanRoots = resolveRoots()
        else
            local r = resolveRoot()
            if r then scanRoots = { r } end
        end
        if scopeOn and #scanRoots == 0 and gameSweep then
            current = { mode = "none", inst = nil, path = "" }
            gameSweep()
            return
        end
        if #scanRoots == 0 then
            srcLabel.Text = "Source gone: rescan"
            return
        end
        local root = scanRoots[1]
        if current.mode == "multi" then
            srcLabel.Text = #scanRoots .. " x " .. (current.name or "?")
        else
            srcLabel.Text = (current.mode == "tool" and "tool: " or "instance: ") .. root.Name
        end
        local sid = srcId()
        local seen = {}
        local common, rest = {}
        local function add(rt, sub, v, isAttr, aname)
            local key = sub .. "|" .. (isAttr and ("@" .. aname) or v.Name)
            if seen[key] then return end
            seen[key] = true
            local kind = "string"
            if not isAttr then
                kind = v:IsA("BoolValue") and "bool"
                    or ((v:IsA("IntValue") or v:IsA("NumberValue")) and "number" or "string")
            else
                local av = rt:GetAttribute(aname)
                local at = typeof(av)
                kind = (at == "number" and "number") or (at == "boolean" and "bool") or "string"
                if at ~= "number" and at ~= "boolean" and at ~= "string" then return end
            end
            local e = { sub = sub, name = isAttr and aname or v.Name, isAttr = isAttr }
            local bucket = isCommonGun(e.name) and common or rest
            bucket[#bucket + 1] = { e = e, kind = kind }
        end
        for _, rt in ipairs(scanRoots) do
            for _, c in ipairs(rt:GetChildren()) do
                if c:IsA("IntValue") or c:IsA("NumberValue")
                    or c:IsA("BoolValue") or c:IsA("StringValue") then
                    add(rt, "", c, false)
                end
            end
            local okA, attrs = pcall(function() return rt:GetAttributes() end)
            if okA and attrs then
                for aname in pairs(attrs) do add(rt, "", nil, true, aname) end
            end
            -- one level into Folders (Gunfight-style Variables pattern).
            for _, c in ipairs(rt:GetChildren()) do
                if c:IsA("Folder") then
                    for _, k in ipairs(c:GetChildren()) do
                        if k:IsA("IntValue") or k:IsA("NumberValue")
                            or k:IsA("BoolValue") or k:IsA("StringValue") then
                            add(rt, c.Name, k, false)
                        end
                    end
                end
            end
        end
        local function emit(bucket)
            -- v0.48.0: scanned rows cascade in with a tiny stagger (capped, so
            -- a 60-value gun doesn't take all day). Lists off shows them all.
            local n = 0
            for _, item in ipairs(bucket) do
                local row = buildRow(listBox, item.e, entryId(sid, item.e.sub, item.e.name), item.kind)
                if row and Koffee.Anim.spot("AnimLists") then
                    n = n + 1
                    local sc, target = uScaleOf(row), row
                    sc.Scale = 0.96
                    task.delay(math.min(n * 0.02, 0.4), function()
                        if target.Parent then
                            tween(sc, Theme.Animation.Fast, { Scale = 1 })
                        end
                    end)
                end
            end
        end
        if #common + #rest == 0 then
            srcLabel.Text = root.Name .. ": No tunable values"
            return
        end
        if #common > 0 then sectionLbl(listBox, "common") emit(common) end
        if #rest > 0 then sectionLbl(listBox, "everything else") emit(rest) end
    end
    -- v0.82.0: Full Game results picker. Sweeps the whole game (minus UI) for
    -- catalog-named values, groups hits by parent, and offers the parents in
    -- a dropdown. Picking one loads its rows like a manual pick. Values only:
    -- attributes stay manual-pick. Auto-picks the first hit so rows show now.
    gameSweep = function()
        srcLabel.Text = "Scanning game..."
        task.spawn(function()
            local results = {}
            local supported = Shared.GunMods and Shared.GunMods.fullScan
            if supported then
                local ok, r = pcall(Shared.GunMods.fullScan)
                if ok and type(r) == "table" then results = r end
            else
                srcLabel.Text = "Re-exec latest Koffee for Full Game scan"
                return
            end
            if resDD then resDD.destroy(); resDD = nil end
            resMap = {}
            if #results == 0 then
                srcLabel.Text = "Full scan: no tunables found"
                return
            end
            -- v0.83.0 BULK: merge same-named parents. One pick drives every
            -- same-named gun at once through multi mode.
            local groups, order = {}, {}
            for _, e in ipairs(results) do
                local g = groups[e.name]
                if not g then
                    g = { name = e.name, insts = {}, count = 0 }
                    groups[e.name] = g
                    order[#order + 1] = g
                end
                g.insts[#g.insts + 1] = e.inst
                g.count = g.count + (e.count or 0)
            end
            local opts = {}
            for i, g in ipairs(order) do
                resMap[i] = g
                opts[#opts + 1] = g.name .. " (" .. #g.insts .. ")"
            end
            resDD = dropdown(host, "Results", opts, opts[1], function(v)
                for i, o in ipairs(opts) do
                    local g = resMap[i]
                    if o == v and g then
                        local live = {}
                        for _, inst in ipairs(g.insts) do
                            if inst.Parent then live[#live + 1] = inst end
                        end
                        if #live > 0 then
                            current = { mode = "multi", name = g.name, roots = live }
                            scan()
                        end
                        break
                    end
                end
            end)
            if resDD and resDD.frame then resDD.frame.LayoutOrder = 2 end
            local first = resMap[1]
            if first then
                local live = {}
                for _, inst in ipairs(first.insts) do
                    if inst.Parent then live[#live + 1] = inst end
                end
                if #live > 0 then
                    current = { mode = "multi", name = first.name, roots = live }
                    scan()
                end
            end
            refreshFullUI()
        end)
    end
    refreshFullUI = function()
        local on = ((Shared.Combat and Shared.Combat.Gun
            and Shared.Combat.Gun.ScanScope) or "Replicated") == "Full Game"
        if resDD and resDD.frame then resDD.frame.Visible = on end
        if on and (not resMap or #resMap == 0) then gameSweep() end
    end
    -- header: source buttons + rescan + restore-all.
    local bar = new("Frame", {
        Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
        LayoutOrder = 1, ZIndex = 34, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }) })
    local function hdrBtn(label, order, fn)
        local b = new("TextButton", {
            Size = UDim2.new(0, 86, 0, 22), BackgroundColor3 = Theme.Palette.PanelElevated,
            BackgroundTransparency = 0.2, BorderSizePixel = 0, AutoButtonColor = false,
            Text = label, FontFace = Theme.Fonts.Medium, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.Text, LayoutOrder = order, ZIndex = 35, Parent = bar,
        }, { pillCorner() })
        b.MouseButton1Click:Connect(fn)
        popFx(b)   -- v0.48.0: header buttons squash on press like the rest
        Koffee.attachBtnHover(b, 0, 0.2)   -- v0.48.0: background eases in on hover
        return b
    end
    hdrBtn("Held Tool", 1, function()
        local ch = LocalPlayer and LocalPlayer.Character
        local tool = ch and ch:FindFirstChildOfClass("Tool")
        current = { mode = "tool", toolName = tool and tool.Name or nil,
                    inst = nil, path = "" }
        scan()
    end)
    hdrBtn("Pick...", 2, function()
        if not Shared.openInstancePicker then return end
        Shared.openInstancePicker(function(inst, path)
            if inst then
                current = { mode = "picked", inst = inst, path = path or "" }
                scan()
            end
        end, { title = "pick a gun or template" })
    end)
    hdrBtn("Rescan", 3, function() scan() end)
    hdrBtn("Restore All", 4, function()
        for id, pin in pairs(pins) do
            unhookPin(pin)
            if rows[id] then restoreOrigs(pin) end
            pin.on = false
            syncPinSave(id)
        end
        scan()
    end)
    -- v0.81.3: catalog scan scope as a real dropdown above the header bar
    -- (the cycling button wrapped the row). Persists through combat_gun.
    do
        local G = Shared.Combat and Shared.Combat.Gun
        local dd = dropdown(host, "Scan Scope",
            { "Character", "Replicated", "Full Game" },
            (G and G.ScanScope) or "Replicated",
            function(v)
                if G then G.ScanScope = v end
                if refreshFullUI then refreshFullUI() end
            end)
        if dd and dd.frame then dd.frame.LayoutOrder = 0 end
    end
    srcLabel = new("TextLabel", {
        Text = "Hold a gun, pick an instance, or set Scope to Full Game", FontFace = Theme.Fonts.Regular,
        TextSize = Theme.Text.Small, TextColor3 = Theme.Palette.TextMuted,
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 3, ZIndex = 34, Parent = host,
    })
    listBox = new("Frame", {
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1, LayoutOrder = 4, ZIndex = 34, Parent = host,
    }, { new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical,
        Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }) })
    new("TextLabel", {
        Text = "* = attribute. enter in a box = set once. pin = hold. unpin restores.",
        FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Tiny,
        TextColor3 = Theme.Palette.TextFaint, BackgroundTransparency = 1,
        TextWrapped = true, Size = UDim2.new(1, 0, 0, 22),
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 4, ZIndex = 34, Parent = host,
    })
    -- v0.82.1: Full Game needs no starting source, so the sweep fires on its
    -- own: when this page is shown (and once at build) with Scope on Full and
    -- nothing picked yet. Opening the tab is all it takes.
    host:GetPropertyChangedSignal("Visible"):Connect(function()
        if Koffee.dead() then return end
        if not host.Visible then return end
        local on = ((Shared.Combat and Shared.Combat.Gun
            and Shared.Combat.Gun.ScanScope) or "Replicated") == "Full Game"
        -- v0.82.2: no results yet and no live source: sweep. Never wipes
        -- an existing pick or populated dropdown.
        if on and gameSweep and (not resMap or #resMap == 0) then
            local root = resolveRoot()
            if current.mode == "none" or not root then
                current = { mode = "none", inst = nil, path = "" }
                gameSweep()
            end
        end
    end)
    refreshFullUI()
    -- reassert pins + refresh live values, throttled. Resolves fresh per
    -- tick so round rebuilds re-attach instead of dying on stale refs.
    local lastTick = 0
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local now = os.clock()
        if now - lastTick < 0.5 then return end
        lastTick = now
        for id, pin in pairs(pins) do
            local r = rows[id]
            if r then
                local v = readEntry(r.entry)
                if v == nil then
                    r.cur.Text = "Gone"
                else
                    r.cur.Text = fmt(v)
                    if pin.on then
                        -- re-hook after rebuilds (fresh instances, dead
                        -- signals): hook count must match live handles.
                        local hs = resolveAll(r.entry)
                        if #(pin.conns or {}) ~= #hs then
                            hookPin(pin, r.entry)
                        elseif pin.want ~= nil and v ~= pin.want then
                            writeEntry(r.entry, pin.want)
                        end
                    end
                end
            end
        end
    end)
    -- v0.75.0: pin reconcile. Retires live pins (originals restored), reseeds
    -- from the loaded set, switches to the saved source with the most pins
    -- that still resolves, and scans. The heartbeat re-hooks + enforces after.
    local function splitPinId(id)
        local src, sub, nm = id:match("^(.*)|(.*)|(.*)$")
        if not (src and sub and nm) then return nil end
        return src, sub, nm
    end
    -- v0.83.0: multi sources reseed by name off the full-scan cache, so a
    -- bulk pick survives reloads as long as same-named instances exist.
    local function resolveMulti(name)
        if not name or name == "" then return nil end
        if not (Shared.GunMods and Shared.GunMods.fullScan) then return nil end
        local ok, r = pcall(Shared.GunMods.fullScan)
        if not ok or type(r) ~= "table" then return nil end
        local out = {}
        for _, e in ipairs(r) do
            if e.name == name and e.inst.Parent then out[#out + 1] = e.inst end
        end
        return #out > 0 and out or nil
    end
    local function resolveSrc(src)
        local tname = src:match("^tool:(.*)$")
        if tname then
            local ch = LocalPlayer and LocalPlayer.Character
            local t = ch and ch:FindFirstChild(tname)
            if t and t:IsA("Tool") then return t end
            local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
            t = bp and bp:FindFirstChild(tname)
            if t and t:IsA("Tool") then return t end
            return nil
        end
        local path = src:match("^path:(.*)$")
        if path and path ~= "" and Shared.resolvePath then
            local ok, inst = pcall(Shared.resolvePath, path)
            if ok and inst and inst.Parent then return inst end
        end
        return nil
    end
    Shared._modsReconcile = function()
        for id, pin in pairs(pins) do
            unhookPin(pin)
            if rows[id] then restoreOrigs(pin) end
        end
        for k in pairs(pins) do pins[k] = nil end
        local counts = {}
        for id, sp in pairs(ModSave.Pins or {}) do
            if type(sp) == "table" and type(id) == "string" and splitPinId(id) then
                local src = splitPinId(id)
                pins[id] = { on = sp.on and true or false, want = sp.want, origs = nil, conns = {}, kind = sp.kind }
                counts[src] = (counts[src] or 0) + 1
            end
        end
        local best, bestN = nil, 0
        for src, n in pairs(counts) do
            local live = false
            local mname = src:match("^multi:(.*)$")
            if mname then live = resolveMulti(mname) ~= nil
            else live = resolveSrc(src) ~= nil end
            if n > bestN and live then best, bestN = src, n end
        end
        if best then
            local tname = best:match("^tool:(.*)$")
            local mname = best:match("^multi:(.*)$")
            if tname then
                current = { mode = "tool", toolName = tname, inst = nil, path = "" }
            elseif mname then
                current = { mode = "multi", name = mname, roots = resolveMulti(mname) or {} }
            else
                current = { mode = "picked", inst = nil, path = best:match("^path:(.*)$") or "" }
            end
        end
        scan()
    end
end)

-- select first tab AFTER layout AND positioning have settled.
-- v0.0.5 only checked AbsoluteSize: but AbsolutePosition can still be zero
-- for a frame or two after that, which put the pill at (0,0) on first launch.
-- also, the tabBar AbsolutePosition signal above will re-snap once it moves.
task.spawn(function()
    local btn = tabs.Visuals.Button
    for _ = 1, 240 do
        local bp = btn.AbsolutePosition
        local bs = btn.AbsoluteSize
        local tp = tabBar.AbsolutePosition
        if bs.X > 0 and (bp.X ~= 0 or bp.Y ~= 0) and (tp.X ~= 0 or tp.Y ~= 0) then
            break
        end
        RunService.RenderStepped:Wait()
    end
    selectTab("Visuals")
end)

-- v0.0.97: the bottom-right session toast was removed entirely (the user
-- asked to drop the widget, not just the headline label). nothing replaces it.

-- WINDOW TOGGLE + BACKGROUND SYNC
-- Delete key toggles. Everything (window + snow + dim + blur) fades
-- with the same linear timing so they leave together, cleanly.
-- IIFE: own register budget. The main chunk rides Luau's 200-local ceiling
-- (same pattern as the Combat IIFE further up).
;(function()
local windowOpen = true

-- v0.0.95: track pre-open mouse state so we can restore what the game (or 3rd
-- Person, or shift-lock, etc.) was doing after the user closes the menu.
local _preMenuMouseBehavior, _preMenuMouseIcon, _preMenuCamMode = nil, nil, nil
-- v0.18.3: setting MouseBehavior once loses in first person. The PlayerModule's
-- camera re-locks it EVERY frame during camera update, so the fix is to re-assert
-- after it: RenderPriority.Last (2000) runs after Camera (200), where 3rd Person
-- and the aimbot bind.
local MFREE = KID.name("mfree")
local function holdMouseFree(on)
    pcall(function() RunService:UnbindFromRenderStep(MFREE) end)
    if not on then return end
    pcall(function()
        RunService:BindToRenderStep(MFREE, Enum.RenderPriority.Last.Value, function()
            if UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            end
            if not UserInputService.MouseIconEnabled then
                UserInputService.MouseIconEnabled = true
            end
        end)
    end)
end
local function setWindowOpen(open)
    if windowOpen == open then return end
    windowOpen = open
    -- v0.62.0: publish the primary-interface state to the window manager so its
    -- drag gate ("only draggable while the main UI is open") needs no chunk upvalue.
    if Koffee.Windows then Koffee.Windows._setPrimary(open) end
    if open then
        window.Visible = true
        -- v0.48.0: window open honours the Animations > Window Open flag; off
        -- snaps straight to the resting state instead of fading + growing in.
        if Koffee.Anim.spot("AnimWindow") then
            window.GroupTransparency = 1
            local wsc = uScaleOf(window)   -- v0.0.98: window pops open (fade + grow)
            wsc.Scale = 0.90
            tween(window, Theme.Animation.WindowFade, { GroupTransparency = 0 })
            tween(wsc,   Theme.Animation.WindowFade, { Scale = 1 })
        else
            window.GroupTransparency = 0
            if _us_cache[window] then _us_cache[window].Scale = 1 end
        end
        -- v0.0.95: force the cursor UNLOCKED + visible while the menu is up so
        -- the user can click Koffee widgets without having to open the Roblox
        -- menu (Esc) first. Restore whatever the game/3rd-Person had set on close.
        _preMenuMouseBehavior = UserInputService.MouseBehavior
        _preMenuMouseIcon     = UserInputService.MouseIconEnabled
        UserInputService.MouseBehavior   = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
        -- LockFirstPerson makes the ENGINE hold the cursor centred, under the
        -- re-assert. Classic frees it without zooming out, because the camera keeps
        -- its current distance and forced-first-person games pin that at min zoom.
        _preMenuCamMode = LocalPlayer.CameraMode
        if _preMenuCamMode == Enum.CameraMode.LockFirstPerson then
            pcall(function() LocalPlayer.CameraMode = Enum.CameraMode.Classic end)
        end
        holdMouseFree(true)
    else
        -- v0.0.22: popups live in a SEPARATE ScreenGui, so the window's fade
        -- doesn't touch them. Dismiss any open color picker + dropdowns on close
        -- so they don't linger over the game after the menu is hidden.
        closeColorPicker()
        for _, closer in pairs(openDropdowns) do closer(true) end
        for _, closer in pairs(openSettingsPopups) do closer() end
        if Koffee.Anim.spot("AnimWindow") then
            tween(window, Theme.Animation.WindowFade, { GroupTransparency = 1 })
            -- v0.0.98: sink slightly as it goes, with the fade.
            if _us_cache[window] then
                tween(_us_cache[window], Theme.Animation.WindowFade, { Scale = 0.96 })
            end
