    -- Target Lock (moved out of Combat): Armed checkbox + keybind pill. Arms
    -- Shared.TargetLock; the key toggles it; while engaged it locks onto the
    -- Prioritize set (set each player's Status above).
    -- v0.67.0: real module checkbox, so a config load re-syncs it through the
    -- watcher like every tab toggle. Pill ref + resync below cover the keybind.
    local tlArmed = moduleCheckbox(tlWrap, "Target Lock", "targetlock")
    local tlPill = keybindPill(tlArmed.row, "targetlock", nil, "Target Lock")
    -- v0.67.0: the player list is never rebuilt, so a config load would leave
    -- this row stale. Re-applied from rebuildConfigTabs like the Extra resync.
    -- v0.70.3 fix: the wipe kills EVERY watcher, so re-subscribe here (the Extra
    -- pattern) or the box freezes after the first config load. That was the bug.
    local tkRow, tkPill
    Shared._targetlockResync = function()
        local m = Modules.targetlock
        if m and (m.Enabled and true or false) ~= (Shared.TargetLock.Enabled and true or false) then
            toggleModule("targetlock")
        else
            tlArmed.setState(Shared.TargetLock.Enabled)
        end
        subscribeModule("targetlock", function(s) tlArmed.setState(s) end)
        tlPill.Text = keyLabel(Keybinds["targetlock"]) or "No Keybind"
        if tkPill then tkPill.Text = keyLabel(Keybinds["targetkeybind"]) or "No Keybind" end
        if tkRow then tkRow.setState(TK.Enabled) end
    end
    -- v0.70.3: Target Keybind. A global key that toggles whoever sits closest
    -- to the biggest FOV center into/out of Prioritize (multi-target; same
    -- person twice returns them to None). Resolver + detail read the set live.
    PL.persist.targetkey = PL.persist.targetkey or { Enabled = false }
    local TK = PL.persist.targetkey
    tkRow = configCheckbox(tlWrap, "Target Keybind", TK.Enabled, function(v) TK.Enabled = v end)
    tkPill = keybindPill(tkRow.row, "targetkeybind", nil, "Target Keybind")
    local TUIS = game:GetService("UserInputService")
    local function tkMatch(input, bind)
        if type(bind) == "table" and bind.mod and bind.key then
            if input.UserInputType ~= Enum.UserInputType.Keyboard then return false end
            if input.KeyCode ~= bind.key then return false end
            return TUIS:IsKeyDown(bind.mod)
        end
        if typeof(bind) ~= "EnumItem" then return false end
        if bind.EnumType == Enum.KeyCode then
            return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == bind
        elseif bind.EnumType == Enum.UserInputType then
            return input.UserInputType == bind
        end
        return false
    end
    local function tkFire()
        if not TK.Enabled then return end
        local combat = Shared.Combat
        local which = "Aim"
        if combat then
            local asz = (combat.Aim.FOV.Enabled and combat.Aim.FOV.Size) or 0
            local ssz = (combat.Silent.FOV.Enabled and combat.Silent.FOV.Size) or 0
            if ssz > asz then which = "Silent" end
        end
        local plr = Shared.crosshairTarget and Shared.crosshairTarget(which)
        if not plr or plr == LocalPlayer then return end
        if PL.statusFor(plr) == "prioritize" then
            PL.setStatus(plr, nil)
            Koffee.notify("Target removed", "@" .. plr.Name, { severity = "info" })
        else
            PL.setStatus(plr, "prioritize")
            Koffee.notify("Priority target", "@" .. plr.Name, { severity = "success" })
        end
        if curPlr and curPlr.UserId == plr.UserId then updateDetail(plr) end
    end
    UserInputService.InputBegan:Connect(function(input, gpe)
        if Koffee.dead() then return end
        if pendingRebind then return end
        if gpe then return end
        if tkMatch(input, Keybinds["targetkeybind"]) then tkFire() end
    end)
    do
        local px1, px2 = false, false
        RunService.Heartbeat:Connect(function()
            if Koffee.dead() then return end
            local xb1, xb2 = Helper.XB1, Helper.XB2
            local e1, e2 = (xb1 and not px1), (xb2 and not px2)
            local k = Keybinds["targetkeybind"]
            if TK.Enabled and type(k) == "string" then
                if (k == "XButton1" and e1) or (k == "XButton2" and e2) then tkFire() end
            end
            px1, px2 = xb1, xb2
        end)
    end

    local function ownHumanoid()
        local c = LocalPlayer.Character
        return c and c:FindFirstChildOfClass("Humanoid")
    end
    local function tpTo(targetChar)
        local c = LocalPlayer.Character
        local hrp = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Torso") or c.PrimaryPart)
        local thrp = targetChar and (targetChar:FindFirstChild("HumanoidRootPart") or targetChar.PrimaryPart)
        if not (hrp and thrp) then return end
        pcall(function() hrp.CFrame = thrp.CFrame + Vector3.new(0, 3, 0) end)
    end
    local function restoreCamera()
        spectatingId = nil
        local cam = workspace.CurrentCamera
        if cam then pcall(function() cam.CameraSubject = ownHumanoid() end) end
    end
    -- Fling: adapted from the reference "skid fling" -- cycle the local HRP's CFrame
    -- around the target with extreme velocity so the physics ejects them; saves +
    -- restores position, kills fall damage, bails on ejection / timeout. Re-click cancels.
    local function flingPlayer(plr)
        if flinging then flinging = false; return end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = hum and hum.RootPart
        local tchar = plr and plr.Character
        local thum = tchar and tchar:FindFirstChildOfClass("Humanoid")
        local trp = thum and thum.RootPart
        local thead = tchar and tchar:FindFirstChild("Head")
        if not (hrp and trp) then return end
        flinging = true
        local oldPos = hrp.CFrame
        local ws = workspace
        local prevFDH = ws.FallenPartsDestroyHeight
        pcall(function() ws.FallenPartsDestroyHeight = -50000 end)
        local bv = Instance.new("BodyVelocity")
        bv.Name = KID.name("v"); bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge); bv.Parent = hrp
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false) end)
        local part = (thead and (trp.Position - thead.Position).Magnitude > 5) and thead or trp
        task.spawn(function()
            local t0, ang = os.clock(), 0
            local function fp(pos, angc)
                pcall(function()
                    hrp.CFrame = CFrame.new(part.Position) * pos * angc
                    hrp.AssemblyLinearVelocity = Vector3.new(9e7, 9e8, 9e7)
                    hrp.AssemblyAngularVelocity = Vector3.new(9e8, 9e8, 9e8)
                end)
            end
            repeat
                ang = ang + 100
                local md = thum.MoveDirection * (part.AssemblyLinearVelocity.Magnitude / 1.25)
                fp(CFrame.new(0, 1.5, 0) + md, CFrame.Angles(math.rad(ang), 0, 0)); task.wait()
                fp(CFrame.new(0, -1.5, 0) + md, CFrame.Angles(math.rad(ang), 0, 0)); task.wait()
                fp(CFrame.new(2.25, 1.5, -2.25) + md, CFrame.Angles(math.rad(ang), 0, 0)); task.wait()
                fp(CFrame.new(-2.25, -1.5, 2.25) + md, CFrame.Angles(math.rad(ang), 0, 0)); task.wait()
            until not flinging or part.Parent ~= tchar or plr.Parent ~= Players
                or part.AssemblyLinearVelocity.Magnitude > 500 or os.clock() > t0 + 2.5
            pcall(function() bv:Destroy() end)
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true) end)
            local rt = os.clock()
            repeat
                if hrp and hrp.Parent then
                    pcall(function() hrp.CFrame = oldPos + Vector3.new(0, 0.5, 0) end)
                    for _, x in ipairs(char:GetChildren()) do
                        if x:IsA("BasePart") then
                            x.AssemblyLinearVelocity = Vector3.zero
                            x.AssemblyAngularVelocity = Vector3.zero
                        end
                    end
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                end
                task.wait()
            until (hrp and (hrp.Position - oldPos.Position).Magnitude < 25) or os.clock() > rt + 2
            pcall(function() ws.FallenPartsDestroyHeight = prevFDH end)
            flinging = false
        end)
    end

    local followBtn, infoBtn
    local followId, followConn = nil, nil
    local RunService = game:GetService("RunService")
    local function stopFollow()
        followId = nil
        if followConn then followConn:Disconnect(); followConn = nil end
        if followBtn then followBtn.Text = "Follow" end
    end
    -- v0.82.0: models have no UserId, so follow keys are UserId-or-instance.
    -- v0.83.1: NEVER read ._model off a Player directly: unknown members on
    -- Instances throw (the old _npc crash). typeof gate first, everywhere.
    local function isModelRef(p)
        return typeof(p) == "table" and p._model == true
    end
    local function followKey(t)
        if not t then return nil end
        if isModelRef(t) then return t.model end
        return t.UserId
    end
    -- Follow: constantly walk toward the target (re-issues MoveTo, throttled). Re-click cancels.
    local function toggleFollow()
        if not curPlr then return end
        if followId == followKey(curPlr) then stopFollow(); return end
        stopFollow()
        local target = curPlr
        followId = followKey(target)
        if followBtn then followBtn.Text = "Following" end
        local nextAt = 0
        followConn = RunService.Heartbeat:Connect(function()
            if followId ~= followKey(target) then stopFollow(); return end
            local tc = target.Character
            if not (tc and tc.Parent) then stopFollow(); return end
            local t = os.clock()
            if t < nextAt then return end
            nextAt = t + 0.12
            local myhum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            local thrp = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
            if myhum and thrp then myhum:MoveTo(thrp.Position) end
        end)
    end
    -- Copy Info: player details -> clipboard. Models copy name + health.
    local function copyInfo()
        if not curPlr then return end
        if isModelRef(curPlr) then
            local hum = curPlr.Character and curPlr.Character:FindFirstChildOfClass("Humanoid")
            local txt = string.format("NPC: %s\nHealth: %s",
                curPlr.Name, hum and tostring(math.floor(hum.Health + 0.5)) or "?")
            pcall(function()
                if setclipboard then setclipboard(txt)
                elseif toclipboard then toclipboard(txt) end
            end)
            if infoBtn then
                infoBtn.Text = "Copied!"
                task.delay(1.2, function() if infoBtn and infoBtn.Text == "Copied!" then infoBtn.Text = "Copy Info" end end)
            end
            return
        end
        local uid = curPlr.UserId
        local seen, seenStr = PL._joinAt[uid], "unknown"
        if seen then
            local s = math.max(0, math.floor(os.clock() - seen))
            seenStr = string.format("%dm %ds", math.floor(s / 60), s % 60)
        end
        local age = 0
        pcall(function() age = curPlr.AccountAge end)
        local txt = string.format(
            "Display: %s\nUsername: @%s\nUser ID: %d\nAccount age: %d days\nSeen this session: %s",
            curPlr.DisplayName, curPlr.Name, uid, age, seenStr)
        pcall(function()
            if setclipboard then setclipboard(txt)
            elseif toclipboard then toclipboard(txt) end
        end)
        if infoBtn then
            infoBtn.Text = "Copied!"
            task.delay(1.2, function() if infoBtn and infoBtn.Text == "Copied!" then infoBtn.Text = "Copy Info" end end)
        end
    end

    local function actionBtn(text, pos, size, cb)
        local b = new("TextButton", {
            Text = text, AutoButtonColor = false, FontFace = Theme.Fonts.Bold,
            TextSize = Theme.Text.Small, TextColor3 = Palette.TextMuted,
            BackgroundColor3 = Palette.PanelElevated, BackgroundTransparency = 0.2,
            BorderSizePixel = 0, Position = pos, Size = size, Parent = actsFrame,
        }, { corner(6), stroke(Palette.BorderSubtle) })
        b.MouseEnter:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Palette.Text }) end)
        b.MouseLeave:Connect(function() tween(b, Theme.Animation.Fast, { TextColor3 = Palette.TextMuted }) end)
        b.MouseButton1Click:Connect(cb)
        return b
    end
