    -- v0.82.0: selection keys are UserId-or-debugId so models highlight too.
    local function selKey(p)
        if not p then return nil end
        if isModelRef(p) then return "m" .. (p.model and p.model:GetDebugId() or "?") end
        if typeof(p) ~= "Instance" then return nil end
        return p.UserId
    end
    function updateDetail(plr)
        local changed = selKey(plr) ~= selKey(curPlr)
        curPlr = plr
        local isModel = isModelRef(plr)
        local ref = isModel and plr.model or plr
        if not plr or not ref or not ref.Parent then content.Visible = false; placeholder.Visible = true; return end
        placeholder.Visible = false; content.Visible = true
        local isSelf = (plr == LocalPlayer)
        dPfp.Image = isModel and "" or ("rbxthumb://type=AvatarHeadShot&id=" .. plr.UserId .. "&w=180&h=180")
        dName.Text = plr.DisplayName
        dUser.Text = isModel and "NPC" or ("@" .. plr.Name)
        idOdo.set(isModel and "-" or tostring(plr.UserId))
        if isModel then
            dTeam.Text = "NPC"; dTeam.TextColor3 = Palette.TextMuted
        else
            local tt, tc = teamInfo(plr)
            dTeam.Text = tt; dTeam.TextColor3 = tc
        end
        if followBtn then followBtn.Text = (followId == followKey(plr)) and "Following" or "Follow" end
        if infoBtn then infoBtn.Text = "Copy Info" end
        statusWrap.Visible = not isSelf and not isModel
        actsFrame.Visible = not isSelf
        tlWrap.Visible = not isSelf and not isModel
        selfNote.Visible = isSelf
        for _, c in ipairs(statusWrap:GetChildren()) do c:Destroy() end
        if not isSelf and not isModel then
            local cur = PL.statusFor(plr)
            local curName = (cur == "exclude" and "Exclude") or (cur == "prioritize" and "Prioritize") or "None"
            dropdown(statusWrap, "Status", { "None", "Exclude", "Prioritize" }, curName, function(v)
                PL.setStatus(plr, (v == "Exclude" and "exclude") or (v == "Prioritize" and "prioritize") or nil)
            end)
        end
        if changed then   -- fade the header (pfp + name + user) in on a new selection
            dPfp.ImageTransparency, dName.TextTransparency, dUser.TextTransparency = 1, 1, 1
            tween(dPfp, Theme.Animation.Menu, { ImageTransparency = 0 })
            tween(dName, Theme.Animation.Menu, { TextTransparency = 0 })
            tween(dUser, Theme.Animation.Menu, { TextTransparency = 0 })
        end
    end

    local function refreshHighlight()
        for uid, rec in pairs(cards) do
            local sel = (uid == selectedId)
            tween(rec.dn, Theme.Animation.Fast, { TextColor3 = sel and Palette.Accent or Palette.Text })
            if rec.stroke then tween(rec.stroke, Theme.Animation.Fast, { Color = sel and Palette.Accent or Palette.Border }) end
        end
    end
    function selectPlayer(plr)
        selectedId = selKey(plr)
        WM.raise("players")
        refreshHighlight()
        updateDetail(plr)
    end

    local function makeCard(plr)
        local card = new("TextButton", { Name = "c" .. plr.UserId, AutoButtonColor = false, Text = "",
            BackgroundColor3 = Palette.Panel, BorderSizePixel = 0, Parent = gridScroll },
            { corner(10), stroke(Palette.Border) })
        local strokeI = card:FindFirstChildOfClass("UIStroke")
        -- full-body avatar fills the card (rounded on the child, since ClipsDescendants
        -- is rectangular); legs run under the name strip = "cut off at the bottom".
        new("ImageLabel", { BackgroundColor3 = Palette.PanelElevated, BorderSizePixel = 0,
            Image = "rbxthumb://type=Avatar&id=" .. plr.UserId .. "&w=420&h=420",
            ScaleType = Enum.ScaleType.Crop, Size = UDim2.new(1, 0, 1, 0), Parent = card }, { corner(10) })
        -- solid name strip (NOT transparent), cleanly separated by a divider line.
        local strip = new("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0),
            Size = UDim2.new(1, 0, 0, 28), BackgroundColor3 = Palette.Panel, BorderSizePixel = 0,
            ZIndex = 2, Parent = card }, { corner(10) })
        -- square off the strip's TOP corners so only the bottom two are rounded.
        new("Frame", { BackgroundColor3 = Palette.Panel, BorderSizePixel = 0, ZIndex = 2,
            Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, 0, 0, 12), Parent = strip })
        new("Frame", { BackgroundColor3 = Palette.Border, BorderSizePixel = 0, ZIndex = 3,
            Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, 0, 0, 1), Parent = strip })
        local dn = new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.new(0, 4, 0, 3),
            Size = UDim2.new(1, -8, 0, 11), TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 3,
            FontFace = Theme.Fonts.Bold, TextSize = 10, TextColor3 = Palette.Text,
            TextTruncate = Enum.TextTruncate.AtEnd, Text = plr.DisplayName, Parent = strip })
        new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.new(0, 4, 0, 15),
            Size = UDim2.new(1, -8, 0, 9), TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 3,
            FontFace = Theme.Fonts.Bold, TextSize = 8, TextColor3 = Palette.TextFaint,
            TextTruncate = Enum.TextTruncate.AtEnd, Text = "@" .. plr.Name, Parent = strip })
        -- team pill fully INSIDE the pfp's top-right corner.
        local tt, tc, isSelf = teamInfo(plr)
        local pill = new("TextLabel", {
            BackgroundColor3 = isSelf and Palette.Accent or Palette.Background,
            BackgroundTransparency = isSelf and 0.0 or 0.35, ZIndex = 4,
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -5, 0, 5),
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 15),
            FontFace = Theme.Fonts.Bold, TextSize = 10,
            TextColor3 = isSelf and Palette.Background or tc, Text = tt, Parent = card },
            { corner(7), new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }) })
        -- v0.70.1: suspect mark is a 14px "!" box, top-left mirror of the team
        -- pill. No warning glyph exists in either icon set and a new asset for
        -- a 14px badge is not worth the preloader weight. Rebuilds on new flags.
        local sus = Shared.Suspects and Shared.Suspects[tostring(plr.UserId)]
        if sus then
            new("TextLabel", {
                BackgroundColor3 = Palette.Danger, BackgroundTransparency = 0.15, ZIndex = 4,
                AnchorPoint = Vector2.new(0, 0), Position = UDim2.new(0, 5, 0, 5),
                Size = UDim2.new(0, 14, 0, 14),
                FontFace = Theme.Fonts.Bold, TextSize = 10,
                TextColor3 = Palette.Text, Text = "!", Parent = card },
                { corner(4) })
        end
        card.MouseEnter:Connect(function()
            if selectedId ~= plr.UserId then tween(dn, Theme.Animation.Fast, { TextColor3 = Palette.Accent }) end end)
        card.MouseLeave:Connect(function()
            if selectedId ~= plr.UserId then tween(dn, Theme.Animation.Fast, { TextColor3 = Palette.Text }) end end)
        card.MouseButton1Click:Connect(function() selectPlayer(plr) end)
        return { card = card, dn = dn, pill = pill, stroke = strokeI, plr = plr }
    end
    -- v0.82.0: model cards for the all-humanoids feed. No avatar/UserId/team:
    -- name strip + muted NPC pill, same selection/detail path via wrapper.
    local function makeModelCard(model)
        local wrap = { _model = true, model = model, Character = model,
            Name = model.Name, DisplayName = model.Name }
        local key = "m" .. model:GetDebugId()
        local card = new("TextButton", { Name = "c" .. key, AutoButtonColor = false, Text = "",
            BackgroundColor3 = Palette.PanelElevated, BorderSizePixel = 0, Parent = gridScroll },
            { corner(10), stroke(Palette.Border) })
        local strokeI = card:FindFirstChildOfClass("UIStroke")
        local strip = new("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0),
            Size = UDim2.new(1, 0, 0, 28), BackgroundColor3 = Palette.Panel, BorderSizePixel = 0,
            ZIndex = 2, Parent = card }, { corner(10) })
        new("Frame", { BackgroundColor3 = Palette.Panel, BorderSizePixel = 0, ZIndex = 2,
            Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, 0, 0, 12), Parent = strip })
        new("Frame", { BackgroundColor3 = Palette.Border, BorderSizePixel = 0, ZIndex = 3,
            Position = UDim2.new(0, 0, 0, 0), Size = UDim2.new(1, 0, 0, 1), Parent = strip })
        local dn = new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.new(0, 4, 0, 3),
            Size = UDim2.new(1, -8, 0, 11), TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 3,
            FontFace = Theme.Fonts.Bold, TextSize = 10, TextColor3 = Palette.Text,
            TextTruncate = Enum.TextTruncate.AtEnd, Text = model.Name, Parent = strip })
        new("TextLabel", { BackgroundTransparency = 1, Position = UDim2.new(0, 4, 0, 15),
            Size = UDim2.new(1, -8, 0, 9), TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 3,
            FontFace = Theme.Fonts.Bold, TextSize = 8, TextColor3 = Palette.TextFaint,
            TextTruncate = Enum.TextTruncate.AtEnd, Text = "NPC", Parent = strip })
        new("TextLabel", {
            BackgroundColor3 = Palette.Background, BackgroundTransparency = 0.35, ZIndex = 4,
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -5, 0, 5),
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 15),
            FontFace = Theme.Fonts.Bold, TextSize = 10,
            TextColor3 = Palette.TextMuted, Text = "NPC", Parent = card },
            { corner(7), new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }) })
        card.MouseEnter:Connect(function()
            if selectedId ~= key then tween(dn, Theme.Animation.Fast, { TextColor3 = Palette.Accent }) end end)
        card.MouseLeave:Connect(function()
            if selectedId ~= key then tween(dn, Theme.Animation.Fast, { TextColor3 = Palette.Text }) end end)
        card.MouseButton1Click:Connect(function() selectPlayer(wrap) end)
        return { card = card, dn = dn, stroke = strokeI, plr = wrap }
    end

    function rebuildGrid()
        for _, rec in pairs(cards) do rec.card:Destroy() end
        cards = {}
        local q = string.lower(search.Text or "")
        local list = Players:GetPlayers()
        local order = 0
        for _, plr in ipairs(list) do
            local ok = q == ""
                or string.find(string.lower(plr.Name), q, 1, true) ~= nil
                or string.find(string.lower(plr.DisplayName), q, 1, true) ~= nil
            if ok then
                local rec = makeCard(plr)
                rec.card.LayoutOrder = (plr == LocalPlayer) and 0 or (order + 1)
                cards[plr.UserId] = rec
                order = order + 1
            end
        end
        -- v0.82.0: all-humanoids feed appends model cards after the players.
        local nModels = 0
        if KoffeeOptions.IncludeHumanoids and NPC.allHumanoids then
            for _, model in ipairs(NPC.allHumanoids()) do
                if model.Parent and (q == ""
                    or string.find(string.lower(model.Name), q, 1, true) ~= nil) then
                    local rec = makeModelCard(model)
                    rec.card.LayoutOrder = order + 1
                    cards["m" .. model:GetDebugId()] = rec
                    order, nModels = order + 1, nModels + 1
                end
            end
        end
        refreshHighlight()
        setTitle(#list + nModels)
    end
    -- v0.70.0: lets the suspect scanner re-render badges when a new flag lands.
    Shared._playerListRefresh = function() if root.Visible then rebuildGrid() end end

    -- live wiring
    Players.PlayerAdded:Connect(function(plr)
        PL._joinAt[plr.UserId] = os.clock()
        if root.Visible then rebuildGrid() end
    end)
    Players.PlayerRemoving:Connect(function(plr)
        if plr.UserId == selectedId then selectedId = nil; updateDetail(nil) end
        if plr.UserId == spectatingId then restoreCamera() end
        if plr.UserId == followId then stopFollow() end
        task.defer(function() if root.Visible then rebuildGrid() end end)
    end)
    search:GetPropertyChangedSignal("Text"):Connect(function() if root.Visible then rebuildGrid() end end)

    updateDetail(nil)

    -- open / close animation (CanvasGroup fade + a small scale pop).
    local function animShow()
        root.Visible = true
        uscale.Scale = SCALE * 0.94
        root.GroupTransparency = 1
        tween(uscale, Theme.Animation.Menu, { Scale = SCALE })
        tween(root, Theme.Animation.Menu, { GroupTransparency = 0 })
    end
    local function animHide()
        tween(uscale, Theme.Animation.Menu, { Scale = SCALE * 0.94 })
        tween(root, Theme.Animation.Menu, { GroupTransparency = 1 })
        task.delay(Koffee.Anim.wait(0.22), function()
            if not WM.shouldShow("players") then root.Visible = false end
        end)
    end

    WM.makeDraggable(root, header, "players")
    WM.attachBody("players", root, {
        onShow = function() animShow(); rebuildGrid() end,
        onHide = animHide,
    })
end)()

-- v0.66.0 ESP preview window (id "esp", the 2nd bar button after the pen): a
-- floating primary window with a real R6 rig in a ViewportFrame and the live ESP
-- box/name/distance/etc drawn on it, so the ESP styling can be eyeballed without
-- another player. No logo in the header; its last segment shows the rig render mode.
-- A settings button flips render type (2D static / 3D spin) and rig size. Own IIFE
-- for its own O0 register budget.
;(function()
    local WM = Koffee.Windows
    if not WM then return end
    local Palette = Theme.Palette
    local RunService = game:GetService("RunService")
    local Players = game:GetService("Players")

    -- preview-local state: rig display mode + rig size (%). render "3D" spins the
    -- rig; "2D" holds it static, facing forward. (This is about the RIG, not the ESP
    -- box type -- that mirrors ESP.Boxes.BoxType independently.) Persisted.
    local PV = { render = "3D", size = 100, hidden = false, npc = false }
    registerConfig("esppreview", PV)

    -- window root
    local W, H = 300, 372
    local SCALE = 1.15
    -- v0.66.0: MUST be a plain Frame, NOT a CanvasGroup. A CanvasGroup flattens its
    -- children into a texture and a ViewportFrame's 3D pass does not compose into it,
    -- so the rig would render blank. Plain Frame + Active=false still clicks through
    -- empty areas; the open/close uses a scale-pop instead of a group fade.
    local root = new("Frame", {
        Name = KID.name("espprev"), Active = false,   -- empty areas click through
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, -360, 0.5, 0),
        Size = UDim2.new(0, W, 0, H), BackgroundColor3 = Palette.Background,
        BorderSizePixel = 0, Visible = false, ZIndex = 50, Parent = screen,
    }, { corner(Theme.Radius.Large), stroke(Palette.Border), new("UIScale", { Scale = SCALE }) })
    local uscale = root:FindFirstChildOfClass("UIScale")
    do
        local p = WM.persist.pos and WM.persist.pos.esp
        if p then root.Position = UDim2.new(p[1], p[2], p[3], p[4]) end
    end

    -- ---- header (drag handle + breadcrumb + settings button; NO logo icon) ----
    local header = new("Frame", { Name = "hdr", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 32), Parent = root })
    local titleRow = new("Frame", { BackgroundTransparency = 1, Position = UDim2.new(0, 14, 0, 0),
        Size = UDim2.new(1, -70, 1, 0), Parent = header }, {
        new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 8),
            SortOrder = Enum.SortOrder.LayoutOrder }),
    })
    local function titleTxt(t, color, order)
        return new("TextLabel", { BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.new(0, 0, 1, 0), FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Header,
            TextColor3 = color, Text = t, LayoutOrder = order, Parent = titleRow })
    end
    local function titleDot(order)
        new("Frame", { BackgroundColor3 = Palette.TextFaint, BorderSizePixel = 0,
            Size = UDim2.new(0, 3, 0, 3), LayoutOrder = order, Parent = titleRow }, { corner(2) })
    end
    titleTxt("ESP", Palette.TextMuted, 1)
    titleDot(2)
    titleTxt("Preview", Palette.Text, 3)
    titleDot(4)
    local renderLbl = titleTxt(PV.render, Palette.Accent, 5)

    -- settings button (top-right of the bar)
    local gearBtn = new("TextButton", { Text = "", AutoButtonColor = false,
        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0),
        Size = UDim2.new(0, 24, 0, 24), BackgroundColor3 = Palette.Panel,
        BackgroundTransparency = 0.25, BorderSizePixel = 0, Parent = header },
        { corner(6), stroke(Palette.BorderSubtle) })
    local gearIcon = Koffee.lucideIcon(gearBtn, "sliders-horizontal", 14, Palette.TextMuted)
    gearIcon.AnchorPoint = Vector2.new(0.5, 0.5); gearIcon.Position = UDim2.new(0.5, 0, 0.5, 0)

    -- viewport stage
    local stage = new("Frame", { Name = "stage", BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, Position = UDim2.new(0, 12, 0, 38), Size = UDim2.new(1, -24, 1, -50),
        Parent = root }, { corner(10), stroke(Palette.BorderSubtle),
        new("UIGradient", { Rotation = 90, Color = ColorSequence.new(
            Color3.fromRGB(40, 40, 47), Color3.fromRGB(20, 20, 24)) }) })
    local vpf = new("ViewportFrame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0),
        Ambient = Color3.fromRGB(225, 225, 225), LightColor = Color3.fromRGB(255, 255, 255),
        LightDirection = Vector3.new(-0.4, -0.7, -1), Parent = stage })
    local world = new("WorldModel", { Parent = vpf })
    local cam = new("Camera", { FieldOfView = 60, Parent = vpf })
    vpf.CurrentCamera = cam

    -- v0.90.0: the dummy is drawn by the real ESP renderer (Shared.espDrawRig) through a
    -- stand-in camera that projects into stage pixels, so every ESP option shows here
    local STAGE_W, STAGE_H = 276, 322
    local overlay = new("Frame", { Name = "overlay", BackgroundTransparency = 1, ClipsDescendants = true,
        Size = UDim2.new(1, 0, 1, 0), ZIndex = 5, Parent = stage })
    local fcam = setmetatable({}, { __index = function(_, k) return cam[k] end })
    function fcam.WorldToViewportPoint(_, p)
        local rel = cam.CFrame:PointToObjectSpace(p)
        local depth = -rel.Z
        local d = math.abs(depth) > 1e-3 and depth or 1e-3
        local tanY = math.tan(math.rad(cam.FieldOfView) * 0.5)
        local nx = (rel.X / d) / (tanY * (STAGE_W / STAGE_H))
        local ny = (rel.Y / d) / tanY
        return Vector3.new((nx * 0.5 + 0.5) * STAGE_W, (0.5 - ny * 0.5) * STAGE_H, depth), depth > 0
    end

    local CENTER = Vector3.new(0, -0.5, 0)
    local model, basePivot
    local entry = { rig = nil, phase = 0 }

    local function finalizeRig(m)
        m.Parent = world
        local cf = m:GetBoundingBox()
        m:PivotTo(CFrame.new(CENTER - cf.Position) * m:GetPivot())   -- centre bbox at CENTER
        basePivot = m:GetPivot(); model = m
        local hum = m:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum.MaxHealth = 100; hum.Health = 72 end) end
        -- build a real ESP rig whose frames live in the stage overlay
        local saved = ESP.BoxLayer
        ESP.BoxLayer = overlay
        local ok, rig = pcall(makeRig, LocalPlayer, m, false)
        ESP.BoxLayer = saved
        if ok and rig then
            rig.preview = true
            -- adornments don't render in a ViewportFrame, so the 3D Cube fill drives a
            -- real part in the viewport through a stand-in with the adornment's fields
            if rig.fill3D then pcall(function() rig.fill3D:Destroy() end) end
            local box = new("Part", { Name = "fill3d", Anchored = true, CanCollide = false, CastShadow = false,
                Material = Enum.Material.SmoothPlastic, Transparency = 1, Size = Vector3.one, Parent = world })
            local st = { Visible = false, Transparency = 0.72, CFrame = CFrame.identity }
            local function sync()
                local torso = rig.torso
                if torso and torso.Parent then box.CFrame = torso.CFrame * st.CFrame end
                box.Transparency = st.Visible and st.Transparency or 1
            end
            rig.fill3D = setmetatable({}, {
                __index = function(_, k) return st[k] end,
                __newindex = function(_, k, v)
                    st[k] = v
                    if k == "Size" then box.Size = v
                    elseif k == "Color3" then box.Color = v end
                    sync()
                end,
            })
            rig._fillSync = sync
            entry.rig = rig
        end
    end
    local function buildFallback()
        local m = Instance.new("Model")
        local function bp(name, size, color, pos)
            local p = new("Part", { Name = name, Size = size, Color = color, Anchored = true,
                CanCollide = false, CastShadow = false, Material = Enum.Material.SmoothPlastic,
                CFrame = CFrame.new(pos), Parent = m })
            return p
        end
        bp("Torso", Vector3.new(2, 2, 1), Color3.fromRGB(13, 105, 172), Vector3.new(0, 0, 0))
        local h = bp("Head", Vector3.new(2, 1, 1), Color3.fromRGB(245, 205, 48), Vector3.new(0, 1.5, 0))
        new("SpecialMesh", { MeshType = Enum.MeshType.Head, Parent = h })
        new("Decal", { Texture = "rbxasset://textures/face.png", Face = Enum.NormalId.Back, Parent = h })
        bp("Right Arm", Vector3.new(1, 2, 1), Color3.fromRGB(245, 205, 48), Vector3.new( 1.5, 0, 0))
        bp("Left Arm",  Vector3.new(1, 2, 1), Color3.fromRGB(245, 205, 48), Vector3.new(-1.5, 0, 0))
        bp("Right Leg", Vector3.new(1, 2, 1), Color3.fromRGB(164, 189, 71), Vector3.new( 0.5, -2, 0))
        bp("Left Leg",  Vector3.new(1, 2, 1), Color3.fromRGB(164, 189, 71), Vector3.new(-0.5, -2, 0))
        m.PrimaryPart = m:FindFirstChild("Torso")
        return m
    end

    task.spawn(function()
        local ok, m = pcall(function()
            -- a blank HumanoidDescription defaults every body colour to black, which the
            -- engine paints on AFTER creation (racing any post-load recolour). Bake the
            -- classic default colours into the description so the engine applies them.
            local desc = Instance.new("HumanoidDescription")
            desc.HeadColor    = Color3.fromRGB(245, 205, 48)
            desc.TorsoColor   = Color3.fromRGB(13, 105, 172)
            desc.LeftArmColor = Color3.fromRGB(245, 205, 48)
            desc.RightArmColor= Color3.fromRGB(245, 205, 48)
            desc.LeftLegColor = Color3.fromRGB(164, 189, 71)
            desc.RightLegColor= Color3.fromRGB(164, 189, 71)
            return Players:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R6)
        end)
        if ok and typeof(m) == "Instance" and m:IsA("Model") then
            local an = m:FindFirstChild("Animate"); if an then an:Destroy() end
            local hum = m:FindFirstChildOfClass("Humanoid")
            if hum then pcall(function() hum.EvaluateStateMachine = false end) end
            -- a blank HumanoidDescription rig ships dark default colours + shirt/pants,
            -- so it renders as a black silhouette. Strip the clothing and paint the
            -- classic default body colours (the iconic yellow/blue/green avatar).
            local COL = {
                Head        = Color3.fromRGB(245, 205, 48), Torso       = Color3.fromRGB(13, 105, 172),
                ["Left Arm"]= Color3.fromRGB(245, 205, 48), ["Right Arm"]= Color3.fromRGB(245, 205, 48),
                ["Left Leg"]= Color3.fromRGB(164, 189, 71), ["Right Leg"]= Color3.fromRGB(164, 189, 71),
            }
            for _, p in ipairs(m:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Anchored = true; p.CanCollide = false; p.CastShadow = false
                    local c = COL[p.Name]; if c then p.Color = c; p.Material = Enum.Material.SmoothPlastic end
                elseif p:IsA("Shirt") or p:IsA("Pants") or p:IsA("ShirtGraphic") or p:IsA("BodyColors") then
                    p:Destroy()
                end
            end
            finalizeRig(m)
        else
            finalizeRig(buildFallback())   -- CreateHumanoidModelFromDescription unsupported -> box rig
        end
    end)

    -- camera
    local function applyCamera()
        local dist = 700 / math.clamp(PV.size, 40, 220)
        -- aimed a little above the body so the name / avatar stack keeps headroom
        local aim = CENTER + Vector3.new(0, dist * 0.09, 0)
        cam.CFrame = CFrame.lookAt(aim + Vector3.new(0, 0, dist), aim)
    end
    applyCamera()

    -- chams mirror: clones of the dummy's parts inside the viewport (Pattern / Lit)
    -- or projected box edges on the overlay (Wireframe), coloured like the real chams
    local chm = { clones = {}, key = nil, lines = {}, used = 0 }
    local CORN, EDGES = {}, {}
    for i = 0, 7 do
        CORN[i + 1] = Vector3.new(i % 2 == 0 and -0.5 or 0.5, math.floor(i / 2) % 2 == 0 and -0.5 or 0.5,
            math.floor(i / 4) == 0 and -0.5 or 0.5)
    end
    for a = 1, 8 do
        for b = a + 1, 8 do
            local d = CORN[a] - CORN[b]
            if math.abs(d.X) + math.abs(d.Y) + math.abs(d.Z) == 1 then EDGES[#EDGES + 1] = { a, b } end
        end
    end
    local PATTEX = { Hex = "fx_pat_hex", Stripes = "fx_pat_stripes", Dots = "fx_pat_dots", Circuit = "fx_pat_circuit" }
    local function chamsDrop()
        for _, c in ipairs(chm.clones) do pcall(function() c.part:Destroy() end) end
        chm.clones, chm.key = {}, nil
    end
    local function wline(a, b, color, th, alpha)
        chm.used += 1
        local f = chm.lines[chm.used]
        if not f then
            f = new("Frame", { BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 4, Parent = overlay })
            chm.lines[chm.used] = f
        end
        local d = b - a
        f.Size = UDim2.fromOffset(d.Magnitude + th * 0.5, th)
        f.Position = UDim2.fromOffset((a.X + b.X) * 0.5, (a.Y + b.Y) * 0.5)
        f.Rotation = math.deg(math.atan2(d.Y, d.X))
        f.BackgroundColor3, f.BackgroundTransparency = color, alpha
        f.Visible = true
    end
    local function bodyOf(m)
        local out = {}
        for _, p in ipairs(m:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 0.95 then out[#out + 1] = p end
        end
        return out
    end
    local function chamsStep()
        chm.used = 0
        local CH = Koffee.Chams
        local on = CH and model and Modules.chams and Modules.chams.Enabled
        local style = nil
        if on then
            style = (CH.Split and PV.hidden) and (CH.HiddenStyle or "Wireframe") or (CH.Style or "Pattern")
        end
        local color = ESP.Colors.Visible
        if on and Shared.chamsColor then
            local ok, c = pcall(Shared.chamsColor, LocalPlayer, model:FindFirstChildOfClass("Humanoid"), PV.hidden == true, 7, false)
            if ok and c then color = c end
        end
        local a = math.clamp(CH and CH.Alpha or 0.3, 0, 0.95)
        local key = (style == "Pattern" or style == "Lit") and (style .. tostring(CH.Pattern)) or nil
        if key ~= chm.key then
            chamsDrop()
            chm.key = key
            if key then
                for _, p in ipairs(bodyOf(model)) do
                    local c = p:Clone()
                    for _, d in ipairs(c:GetChildren()) do
                        if not d:IsA("DataModelMesh") then d:Destroy() end
                    end
                    local sm = c:FindFirstChildWhichIsA("SpecialMesh")
                    if sm then sm.TextureId = "" end
                    c.Size = p.Size * 1.04
                    c.Material = Enum.Material.SmoothPlastic
                    local texs = {}
                    if style == "Pattern" then
                        local img = Shared._hfx and Shared._hfx.tex(PATTEX[CH.Pattern] or PATTEX.Hex) or ""
                        for _, face in ipairs(Enum.NormalId:GetEnumItems()) do
                            texs[#texs + 1] = new("Texture", { Face = face, StudsPerTileU = 1.2, StudsPerTileV = 1.05,
                                Texture = img, Parent = c })
                        end
                    end
                    c.Parent = world
                    chm.clones[#chm.clones + 1] = { part = c, src = p, texs = texs }
                end
            end
        end
        local off = (os.clock() * 0.5 * (CH and CH.Scroll or 1)) % 1.2
        for _, c in ipairs(chm.clones) do
            c.part.CFrame = c.src.CFrame
            c.part.Color = color
            if style == "Lit" then
                c.part.Transparency = a
            else
                c.part.Transparency = 0.45 + a * 0.5
                for _, t in ipairs(c.texs) do
                    t.Color3 = color:Lerp(Color3.new(1, 1, 1), 0.35)
                    t.Transparency = a * 0.5
                    t.OffsetStudsU, t.OffsetStudsV = off, off
                end
            end
        end
        if style == "Wireframe" then
            for _, p in ipairs(bodyOf(model)) do
                local pts, ok = {}, true
                for i, cn in ipairs(CORN) do
                    local v = fcam:WorldToViewportPoint(p.CFrame:PointToWorldSpace(cn * p.Size))
                    if v.Z <= 0 then ok = false; break end
                    pts[i] = Vector2.new(v.X, v.Y)
                end
                if ok then
                    for _, e in ipairs(EDGES) do
                        if CH.Glow ~= false then wline(pts[e[1]], pts[e[2]], color, 5, 0.8) end
                        wline(pts[e[1]], pts[e[2]], color:Lerp(Color3.new(1, 1, 1), 0.3), 1.5, a * 0.6)
                    end
                end
            end
        end
        for i = chm.used + 1, #chm.lines do chm.lines[i].Visible = false end
    end

    -- spin + draw loop (idles when hidden)
    RunService.RenderStepped:Connect(function()
        if not root.Visible or Koffee.dead() or not model then return end
        -- Render Type drives the RIG: 3D spins it, 2D holds it static facing forward
        local ang = (PV.render == "3D") and (tick() * 0.7) % (math.pi * 2) or 0
        local about = CFrame.new(CENTER) * CFrame.Angles(0, ang, 0) * CFrame.new(-CENTER)
        model:PivotTo(about * basePivot)
        if entry.rig then
            local saved = (PV.npc and Shared.NPCESP) and Shared.espSwap(Shared.NPCESP) or nil
            Shared._pvHidden = PV.hidden == true
            ESP._cam, ESP._vp = fcam, Vector2.new(STAGE_W, STAGE_H)
            local ok, err = pcall(Shared.espDrawRig, LocalPlayer, entry, fcam, cam.CFrame.Position, false)
            ESP._cam, ESP._vp = nil, nil
            if entry.rig._fillSync then entry.rig._fillSync() end
            if saved then Shared.espRestore(saved) end
            Shared._pvErr = (not ok) and err or nil
        end
        local ok2, err2 = pcall(chamsStep)
        Shared._pvChamsErr = (not ok2) and err2 or nil
    end)
    -- settings popup
    local settings = new("Frame", { Name = "settings", Visible = false, BackgroundColor3 = Palette.Panel,
        BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 32),
        Size = UDim2.new(0, 190, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 60, Parent = root },
        { corner(8), stroke(Palette.Border),
        new("UIPadding", { PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 8),
            PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }),
        new("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }) })
    -- Render Type: a segmented 2D | 3D toggle (reliable in a cramped popup where the
    -- dropdown's fly-out was awkward). It drives the REAL ESP box type, so the preview,
    -- the header, and the live ESP all stay in sync.
    local rtWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 44), Parent = settings })
    new("TextLabel", { BackgroundTransparency = 1, Text = "Render Type", FontFace = Theme.Fonts.Regular,
        TextSize = Theme.Text.Small, TextColor3 = Palette.TextMuted, TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, 0, 0, 14), Parent = rtWrap })
    local seg = new("Frame", { BackgroundColor3 = Palette.PanelElevated, BackgroundTransparency = 0.15,
        BorderSizePixel = 0, Position = UDim2.new(0, 0, 0, 18), Size = UDim2.new(1, 0, 0, 26), Parent = rtWrap },
        { corner(4), stroke(Palette.BorderSubtle),
        new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder }) })
    local segBtns = {}
    local function setRender(mode)
        PV.render = mode
        renderLbl.Text = mode
        for m, b in pairs(segBtns) do
            local on = m == mode
            b.BackgroundTransparency = on and 0 or 1
            b.TextColor3 = on and Color3.fromRGB(20, 20, 22) or Palette.TextMuted
        end
    end
    for i, mode in ipairs({ "2D", "3D" }) do
        local b = new("TextButton", { Text = mode, AutoButtonColor = false, BackgroundColor3 = Palette.Accent,
            BackgroundTransparency = 1, BorderSizePixel = 0, FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Small,
            TextColor3 = Palette.TextMuted, Size = UDim2.new(0.5, 0, 1, 0), LayoutOrder = i, Parent = seg }, { corner(3) })
        segBtns[mode] = b
        b.MouseButton1Click:Connect(function() setRender(mode) end)
    end
    setRender(PV.render == "2D" and "2D" or "3D")
    slider(settings, "Rig Size", 60, 160, PV.size, 0, function(v) PV.size = v; applyCamera() end)
    configCheckbox(settings, "Behind Wall", PV.hidden, function(v) PV.hidden = v end)
    configCheckbox(settings, "NPC ESP Look", PV.npc, function(v) PV.npc = v end)
    gearBtn.MouseButton1Click:Connect(function()
        WM.raise("esp")
        settings.Visible = not settings.Visible
    end)

    -- open / close animation
    local function animShow()
        settings.Visible = false
        root.Visible = true
        uscale.Scale = SCALE * 0.9
        tween(uscale, Theme.Animation.Menu, { Scale = SCALE })
    end
    local function animHide()
        tween(uscale, Theme.Animation.Menu, { Scale = SCALE * 0.9 })
        task.delay(Koffee.Anim.wait(0.22), function()
            if not WM.shouldShow("esp") then root.Visible = false end
        end)
    end

    WM.makeDraggable(root, header, "esp")
    WM.attachBody("esp", root, { onShow = animShow, onHide = animHide })
end)()

-- v0.90.0: Hotkeys window design, switched by right-clicking the window
Koffee.KeybindsUI = { Design = "Pills" }
registerConfig("keybinds_ui", Koffee.KeybindsUI)
-- v0.66.0 keybinds window (the "Hotkeys" HUD): a floating secondary HUD, a stack of
-- very-rounded pills each showing a [key cap] + the action it fires, driven live off
-- the keybind registry (Koffee._keybinds) and the live Keybinds table. A held key
-- glows green. Own IIFE for its own O0 register budget.
;(function()
    local WM = Koffee.Windows
    if not WM then return end
    local Palette = Theme.Palette
    local RunService = game:GetService("RunService")
    local UIS = game:GetService("UserInputService")

    -- CanvasGroup so the whole HUD fades as one; Active=false clicks through. It
    -- auto-sizes to its pills (each pill hugs its own text), so nothing is full-width.
    local root = new("CanvasGroup", {
        Name = KID.name("keybinds"), Active = false, GroupTransparency = 0,
        Position = UDim2.new(0, 24, 0, 130), Size = UDim2.new(0, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.XY, BackgroundTransparency = 1,
        BorderSizePixel = 0, Visible = false, ZIndex = 40, Parent = screen,
    }, {
        new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 7),
            HorizontalAlignment = Enum.HorizontalAlignment.Left, SortOrder = Enum.SortOrder.LayoutOrder }),
        -- a little room so borders and rounded corners are not clipped by the group
        new("UIPadding", { PaddingTop = UDim.new(0, 3), PaddingBottom = UDim.new(0, 3),
            PaddingLeft = UDim.new(0, 3), PaddingRight = UDim.new(0, 3) }),
    })
    do
        local p = WM.persist.pos and WM.persist.pos.keybinds
        if p then root.Position = UDim2.new(p[1], p[2], p[3], p[4]) end
    end

    -- shared pill: dark, a touch transparent, fully rounded, hugs its own content.
    local PILL_BG, PILL_T = Color3.fromRGB(20, 20, 24), 0.15
    local function pill(order, parent, padX)
        return new("Frame", { BackgroundColor3 = PILL_BG, BackgroundTransparency = PILL_T,
            BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 32),
            LayoutOrder = order, Parent = parent }, { pillCorner(), stroke(Palette.BorderSubtle),
            new("UIPadding", { PaddingLeft = UDim.new(0, padX), PaddingRight = UDim.new(0, padX) }) })
    end
    local function pillText(parent, text)
        return new("TextLabel", { BackgroundTransparency = 1, Text = text, FontFace = Theme.Fonts.Bold,
            TextSize = Theme.Text.Body, TextColor3 = Palette.Text, AutomaticSize = Enum.AutomaticSize.X,
            TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(0, 0, 1, 0), LayoutOrder = 1, Parent = parent })
    end

    -- header pill (also the drag handle): "Keybinds" + a keyboard glyph.
    local header = pill(0, root, 14)
    header.Name = "hdr"
    new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10),
        VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Parent = header })
    pillText(header, "Hotkeys")
    local hicon = Koffee.lucideIcon(header, "keyboard", 15, Palette.TextMuted); hicon.LayoutOrder = 2

    -- empty-state pill (shown when nothing is bound)
    local empty = pill(998, root, 12); empty.Name = "empty"; empty.Visible = false
    local emptyLbl = pillText(empty, "No hotkeys set")
    emptyLbl.TextColor3 = Palette.TextFaint

    local function isHeld(bind)
        if typeof(bind) == "EnumItem" and bind.EnumType == Enum.KeyCode then
            return UIS:IsKeyDown(bind)
        elseif type(bind) == "table" and bind.mod and bind.key then
            return UIS:IsKeyDown(bind.mod) and UIS:IsKeyDown(bind.key)
        end
        return false
    end

    -- one row: two disconnected pills, [key] then [name], each hugging its own text.
    local rows = {}   -- moduleId -> { row, keyPill, keyLbl, bind }
    local function makeEntry(id, label, bind, order)
        local row = new("Frame", { Name = "kb_" .. id, BackgroundTransparency = 1,
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 0, 32), LayoutOrder = order, Parent = root },
            { new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 7),
                VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
        local keyPill = pill(1, row, 12)
        local keyLbl = pillText(keyPill, keyLabel(bind) or "-")
        local namePill = pill(2, row, 12)
        pillText(namePill, label)
        rows[id] = { row = row, keyPill = keyPill, keyLbl = keyLbl, bind = bind }
    end

    -- the currently-bound keybinds, in registration order.
    local function boundList()
        local out = {}
        for _, e in ipairs(Koffee._keybinds or {}) do
            local bind = Keybinds[e.id]
            if bind ~= nil then out[#out + 1] = { id = e.id, label = e.label, bind = bind } end
        end
        return out
    end
    local function signature(bl)
        local parts = {}
        for _, e in ipairs(bl) do parts[#parts + 1] = e.id .. "=" .. (keyLabel(e.bind) or "?") end
        return table.concat(parts, "|")
    end
    -- v0.90.0 "Card" design: one dark card, a KeyBinds header with a badge, a row per
    -- bind with the key in an accent cap; names of switched-on modules light up
    local KBUI = Koffee.KeybindsUI
    local cardF, cardRows = nil, {}
    local function buildCard(bl)
        if cardF then cardF:Destroy() end
        cardRows = {}
        cardF = new("Frame", { Name = "card", BackgroundColor3 = Color3.fromRGB(17, 17, 21), BackgroundTransparency = 0.06,
            BorderSizePixel = 0, Size = UDim2.fromOffset(210, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 0,
            Parent = root }, { corner(8), stroke(Palette.BorderSubtle),
            new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 11),
                PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 12) }),
            new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }) })
        local head = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 0, Parent = cardF })
        new("TextLabel", { BackgroundTransparency = 1, Text = "Keybinds", FontFace = Theme.Fonts.Bold, TextSize = 15,
            TextColor3 = Palette.Text, TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, -34, 1, 0), Parent = head })
        local badge = new("Frame", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.fromOffset(28, 20), BackgroundColor3 = Palette.Accent, BorderSizePixel = 0, Parent = head }, { corner(4) })
        local bi = Koffee.lucideIcon(badge, "keyboard", 15, Color3.fromRGB(20, 20, 24))
        bi.AnchorPoint = Vector2.new(0.5, 0.5); bi.Position = UDim2.fromScale(0.5, 0.5)
        if #bl == 0 then
            new("TextLabel", { BackgroundTransparency = 1, Text = "No hotkeys set", FontFace = Theme.Fonts.Medium, TextSize = 13,
                TextColor3 = Palette.TextFaint, TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, 0, 0, 18),
                LayoutOrder = 1, Parent = cardF })
        end
        for i, e in ipairs(bl) do
            local r = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20), LayoutOrder = i, Parent = cardF })
            local lbl = new("TextLabel", { BackgroundTransparency = 1, Text = e.label, FontFace = Theme.Fonts.Medium, TextSize = 13,
                TextColor3 = Palette.Text, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
                Size = UDim2.new(1, -70, 1, 0), Parent = r })
            local cap = new("TextLabel", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
                AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 17), BackgroundColor3 = Palette.Accent,
                BorderSizePixel = 0, Text = keyLabel(e.bind) or "-", FontFace = Theme.Fonts.Bold, TextSize = 12,
                TextColor3 = Color3.fromRGB(255, 255, 255), Parent = r }, { corner(4),
                new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }) })
            cardRows[#cardRows + 1] = { id = e.id, lbl = lbl, cap = cap, bind = e.bind }
        end
    end

    local shownSig = nil
    local function rebuild()
        for _, r in pairs(rows) do r.row:Destroy() end
        rows = {}
        local bl = boundList()
        local card = KBUI.Design == "Card"
        header.Visible = not card
        if card then
            empty.Visible = false
            buildCard(bl)
        else
            if cardF then cardF:Destroy(); cardF = nil end
            cardRows = {}
            empty.Visible = #bl == 0
            for i, e in ipairs(bl) do makeEntry(e.id, e.label, e.bind, i) end
        end
        shownSig = signature(bl) .. KBUI.Design
    end
    -- right-click anywhere on the window cycles the design
    local DESIGNS = { "Pills", "Card" }
    UIS.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton2 or not root.Visible or Koffee.dead() then return end
        local m = UIS:GetMouseLocation() - game:GetService("GuiService"):GetGuiInset()
        local a, z = root.AbsolutePosition, root.AbsoluteSize
        if m.X < a.X or m.X > a.X + z.X or m.Y < a.Y or m.Y > a.Y + z.Y then return end
        local nxt = 1
        for i, d in ipairs(DESIGNS) do if d == KBUI.Design then nxt = i % #DESIGNS + 1 end end
        KBUI.Design = DESIGNS[nxt]
        rebuild()
    end)

    -- live: rebuild when the bound set changes; glow held keys each frame.
    RunService.RenderStepped:Connect(function()
        if not root.Visible then return end
        local bl = boundList()
        if signature(bl) .. KBUI.Design ~= shownSig then rebuild() end
        -- card design: switched-on modules light their name in the accent colour
        for _, r in ipairs(cardRows) do
            local m = Modules[r.id]
            local on = m and m.Enabled
            r.lbl.TextColor3 = on and Palette.Accent or Palette.Text
            r.cap.BackgroundTransparency = isHeld(r.bind) and 0.35 or 0
        end
        for _, r in pairs(rows) do
            local held = isHeld(r.bind)
            r.keyPill.BackgroundColor3 = held and Color3.fromRGB(120, 220, 130) or PILL_BG
            r.keyPill.BackgroundTransparency = held and 0 or PILL_T
            r.keyLbl.TextColor3 = held and Color3.fromRGB(18, 24, 18) or Palette.Text
        end
    end)

    local function animShow()
        root.Visible = true
        rebuild()
        root.GroupTransparency = 1
        tween(root, Theme.Animation.Menu, { GroupTransparency = 0 })
    end
    local function animHide()
        tween(root, Theme.Animation.Menu, { GroupTransparency = 1 })
        task.delay(Koffee.Anim.wait(0.22), function()
            if not WM.shouldShow("keybinds") then root.Visible = false end
        end)
    end

    WM.makeDraggable(root, header, "keybinds")
    WM.attachBody("keybinds", root, { onShow = animShow, onHide = animHide })
end)()

-- v0.90.0 MEDIA window (the dock's music slot): a mini-player for local music. Audio
-- files dropped in the executor workspace folder "Koffee-music" play through a local
-- Sound; a same-named .lrc beside a track shows synced lyrics (word tags = karaoke).
Koffee.Media = { Level = 0.2, Repeat = "All", Shuffle = false, Last = "", Lyrics = true, List = false }
registerConfig("media", Koffee.Media)
;(function()
    local WM = Koffee.Windows
    if not WM then return end
    local MC = Koffee.Media
    local Palette = Theme.Palette
    local GS = game:GetService("GuiService")
    local DIR = "Koffee-music"
    local AUDIO = { mp3 = true, ogg = true, wav = true, flac = true }
    local W, LYR_H, LIST_H, LINE_H = 300, 132, 150, 24

    local M = { tracks = {}, idx = 0, lines = nil, lineLbls = {}, cur = 0, scrubbing = false }
    Shared.Media = M

    local function fsOk() return listfiles and isfolder and makefolder and getcustomasset and true or false end
    local function baseName(p) return (tostring(p):match("([^/\\]+)$")) or tostring(p) end
    local function stem(n) return n:match("^(.*)%.[^.]+$") or n end
    local function fmt(t)
        t = math.max(0, math.floor(t or 0))
        return string.format("%d:%02d", t // 60, t % 60)
    end

    -- :: lyrics :: a sidecar with the song's exact name. LRC ([mm:ss.xx] lines,
    -- <mm:ss.xx> word karaoke), SRT, VTT (<hh:mm:ss.mmm> word karaoke), ASS/SSA
    -- ({\k} karaoke) and plain TXT (unsynced, scrolls with the song)
    local LYR = { lrc = 1, vtt = 2, srt = 3, ass = 4, ssa = 5, txt = 6 }
    local function stamp(m, s) return (tonumber(m) or 0) * 60 + (tonumber(s) or 0) end
    local function clock(str)
        str = str:gsub(",", ".")
        local h, m, sec = str:match("^(%d+):(%d+):(%d+%.?%d*)$")
        if h then return tonumber(h) * 3600 + tonumber(m) * 60 + tonumber(sec) end
        local m2, s2 = str:match("^(%d+):(%d+%.?%d*)$")
        if m2 then return tonumber(m2) * 60 + tonumber(s2) end
        return nil
    end
    local function eachLine(text)
        local out = {}
        for raw in (text .. "\n"):gmatch("([^\n]*)\n") do out[#out + 1] = (raw:gsub("\r", "")) end
        return out
    end
    local function tidy(t) return (t:gsub("<[^>]->", ""):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")) end
    local function wordsText(words)
        local parts = {}
        for _, wd in ipairs(words) do parts[#parts + 1] = wd.w end
        return (table.concat(parts):gsub("^%s+", ""):gsub("%s+$", ""))
    end

    local function parseLrc(text)
        local out, meta, offset = {}, {}, 0
        for _, line in ipairs(eachLine(text)) do
            local key, val = line:match("^%[(%a+):(.-)%]%s*$")
            if key then
                key = key:lower()
                if key == "offset" then offset = (tonumber(val) or 0) / 1000 else meta[key] = val end
            else
                local times, rest = {}, line
                while true do
                    local m, s, after = rest:match("^%[(%d+):(%d+%.?%d*)%](.*)$")
                    if not m then break end
                    times[#times + 1] = stamp(m, s)
                    rest = after
                end
                if #times > 0 then
                    local words = nil
                    if rest:find("<%d+:%d") then
                        words = {}
                        local lead = rest:match("^([^<]*)")
                        if lead and lead:match("%S") then words[#words + 1] = { t = times[1], w = lead } end
                        for m, s, w in rest:gmatch("<(%d+):(%d+%.?%d*)>([^<]*)") do
                            words[#words + 1] = { t = stamp(m, s), w = w }
                        end
                        rest = wordsText(words)
                    end
                    rest = tidy(rest)
                    for _, t in ipairs(times) do out[#out + 1] = { t = t, text = rest, words = words } end
                end
            end
        end
        for _, l in ipairs(out) do
            l.t -= offset
            if l.words then for _, wd in ipairs(l.words) do wd.t -= offset end end
        end
        return out, meta
    end

    -- SRT and VTT share the cue shape: a "start --> end" line, then text lines
    local function parseCues(text)
        local out, lines = {}, eachLine(text)
        local i = 1
        while i <= #lines do
            local a, b = lines[i]:match("^%s*([%d:%.,]+)%s*%-%->%s*([%d:%.,]+)")
            if a then
                local t0, t1 = clock(a), clock(b)
                local body = {}
                i += 1
                while i <= #lines and lines[i]:match("%S") do body[#body + 1] = lines[i]; i += 1 end
                local raw = table.concat(body, " ")
                local words = nil
                if t0 and raw:find("<%d+:%d") then
                    words = {}
                    local lead = raw:match("^([^<]*)")
                    if lead and lead:match("%S") then words[#words + 1] = { t = t0, w = tidy(lead) .. " " } end
                    for ts, w in raw:gmatch("<([%d:%.]+)>([^<]*)") do
                        local tt = clock(ts)
                        if tt then words[#words + 1] = { t = tt, w = w } end
                    end
                    -- inline <c> / <i> tags leave empty chunks behind; drop them
                    for k = #words, 1, -1 do if words[k].w == "" then table.remove(words, k) end end
                    if #words == 0 then words = nil end
                end
                if t0 then
                    out[#out + 1] = { t = t0, e = t1, text = words and wordsText(words) or tidy(raw), words = words }
                end
            else
                i += 1
            end
        end
        return out, {}
    end

    -- ASS / SSA: Dialogue lines in [Events]; {\k<centiseconds>} tags time each syllable
    local function parseAss(text)
        local out, fmtCols = {}, nil
        for _, line in ipairs(eachLine(text)) do
            local f = line:match("^Format:%s*(.+)$")
            if f and f:find("Text") then
                fmtCols = {}
                for col in f:gmatch("[^,]+") do fmtCols[#fmtCols + 1] = (col:gsub("%s", "")) end
            end
            local d = line:match("^Dialogue:%s*(.+)$")
            if d then
                local cols = fmtCols or { "Layer", "Start", "End", "Style", "Name", "MarginL", "MarginR", "MarginV", "Effect", "Text" }
                local vals, rest = {}, d
                for c = 1, #cols - 1 do
                    local v, after = rest:match("^([^,]*),(.*)$")
                    vals[cols[c]] = v or ""
                    rest = after or ""
                end
                local t0, t1 = clock(vals.Start or ""), clock(vals.End or "")
                if t0 then
                    rest = rest:gsub("\\[Nn]", " ")
                    local words, at = nil, t0
                    if rest:find("{[^}]*\\[kK][fo]?%d") then
                        words = {}
                        for tags, chunk in rest:gmatch("{([^}]*)}([^{]*)") do
                            local cs = tags:match("\\[kK][fo]?(%d+)")
                            words[#words + 1] = { t = at, w = chunk }
                            at += (tonumber(cs) or 0) / 100
                        end
                    end
                    local plain = rest:gsub("{[^}]*}", "")
                    out[#out + 1] = { t = t0, e = t1, text = words and wordsText(words) or tidy(plain), words = words }
                end
            end
        end
        return out, {}
    end

    local function parseLyrics(path, text)
        local ext = (path:match("%.([^.]+)$") or ""):lower()
        local lines, meta
        if ext == "lrc" then lines, meta = parseLrc(text)
        elseif ext == "srt" or ext == "vtt" then lines, meta = parseCues(text)
        elseif ext == "ass" or ext == "ssa" then lines, meta = parseAss(text)
        else
            lines = {}
            for _, l in ipairs(eachLine(text)) do
                if l:match("%S") then lines[#lines + 1] = { t = 0, text = tidy(l) } end
            end
            return lines, {}, true
        end
        table.sort(lines, function(a, b) return a.t < b.t end)
        return lines, meta, false
    end

    local function scan()
        local list = {}
        if not fsOk() then M.tracks = list; return list end
        pcall(function() if not isfolder(DIR) then makefolder(DIR) end end)
        local ok, files = pcall(listfiles, DIR)
        if not ok or type(files) ~= "table" then M.tracks = list; return list end
        -- lyric sidecars keyed by the exact song name (without extension)
        local lrcs, rank = {}, {}
        for _, f in ipairs(files) do
            local n = baseName(f)
            local ext = (n:match("%.([^.]+)$") or ""):lower()
            local r = LYR[ext]
            if r then
                local k = stem(n):lower()
                if not rank[k] or r < rank[k] then lrcs[k], rank[k] = f, r end
            end
        end
        for _, f in ipairs(files) do
            local n = baseName(f)
            local ext = (n:match("%.([^.]+)$") or ""):lower()
            if AUDIO[ext] then
                local s = stem(n)
                local artist, title = s:match("^(.-)%s+%-%s+(.+)$")
                list[#list + 1] = { path = f, name = n, title = title or s, artist = artist or "", lrc = lrcs[s:lower()] }
            end
        end
        table.sort(list, function(a, b) return a.name:lower() < b.name:lower() end)
        M.tracks = list
        return list
    end

    local group = KID.track(new("SoundGroup", { Name = KID.name("mediag"), Volume = 1, Parent = game:GetService("SoundService") }))
    local sound = KID.track(new("Sound", { Name = KID.name("media"), Volume = 0.5, SoundGroup = group,
        Parent = game:GetService("SoundService") }))
    -- the slider runs on a cube so the low end is fine-grained and the top end goes
    -- far past normal: 0.2 is about 0.8, the max is 100 (sound 10 x group 10)
    local function gainOf(x) return 100 * math.clamp(x or 0, 0, 1) ^ 3 end
    local function applyGain()
        local g = gainOf(MC.Level)
        sound.Volume = math.min(g, 10)
        group.Volume = g > 10 and g / 10 or 1
    end
    M.sound = sound

    -- :: window ::
    local root = new("CanvasGroup", {
        Name = KID.name("media"), Active = false, GroupTransparency = 0,
        Position = UDim2.new(0, 24, 0, 300), Size = UDim2.fromOffset(W, 0),
        AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = Palette.Background,
        BackgroundTransparency = 0, BorderSizePixel = 0, Visible = false, ZIndex = 40, Parent = screen,
    }, { corner(Theme.Radius.Large), stroke(Palette.Border),
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }),
        new("UIPadding", { PaddingBottom = UDim.new(0, 10) }) })
    do
