    local vol = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 5, Parent = root })
    local volBtn, volIc = iconBtn(vol, "volume-2", 13, UDim2.new(0, 24, 0.5, 0))
    local vtrack = new("TextButton", { Text = "", AutoButtonColor = false, BackgroundColor3 = Palette.PanelElevated,
        BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 42, 0.5, 0),
        Size = UDim2.new(1, -60, 0, 4), Parent = vol }, { pillCorner() })
    local vfill = new("Frame", { BackgroundColor3 = Palette.TextMuted, BorderSizePixel = 0,
        Size = UDim2.fromScale(MC.Level, 1), Parent = vtrack }, { pillCorner() })
    vtrack.Size = UDim2.new(1, -96, 0, 4)
    local volLbl = new("TextLabel", { BackgroundTransparency = 1, Text = "", FontFace = Theme.Fonts.Mono, TextSize = 11,
        TextColor3 = Palette.TextFaint, TextXAlignment = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(36, 14), Parent = vol })

    -- lyrics: every line is its own label in a strip that glides so the sung line
    -- stays centred; the sung line fills word by word when the .lrc has word tags
    local lyr = new("Frame", { BackgroundColor3 = Palette.Panel, BackgroundTransparency = 0.3, BorderSizePixel = 0,
        ClipsDescendants = true, Size = UDim2.new(1, -20, 0, LYR_H), LayoutOrder = 6, Parent = root },
        { corner(8), new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.22, 0), NumberSequenceKeypoint.new(0.78, 0),
            NumberSequenceKeypoint.new(1, 1) }) }) })
    local lyrWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, LYR_H + 6), LayoutOrder = 6,
        Parent = root })
    lyr.Parent = lyrWrap
    lyr.AnchorPoint = Vector2.new(0.5, 0); lyr.Position = UDim2.new(0.5, 0, 0, 4)
    local strip = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), Parent = lyr })
    local noLyr = new("TextLabel", { BackgroundTransparency = 1, Text = "", FontFace = Theme.Fonts.Medium, TextSize = 12,
        TextColor3 = Palette.TextFaint, Size = UDim2.fromScale(1, 1), TextWrapped = true, Parent = lyr })

    -- track list
    local listWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, LIST_H + 6), LayoutOrder = 7,
        Visible = false, Parent = root })
    local listBox = new("ScrollingFrame", { BackgroundColor3 = Palette.Panel, BackgroundTransparency = 0.3,
        BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 4),
        Size = UDim2.new(1, -20, 0, LIST_H), ScrollBarThickness = 3, ScrollBarImageColor3 = Palette.TextFaint,
        CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = listWrap },
        { corner(8), new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }),
        new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4), PaddingLeft = UDim.new(0, 4),
            PaddingRight = UDim.new(0, 8) }) })

    -- info popup (the tiny "i"): how to import music and lyrics
    -- its own frame on the screen, pinned under the card header each frame, so the
    -- card's clip can never cut it off however short the card is
    local probe = new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromOffset(0, 0), Parent = screen })
    local info = new("CanvasGroup", { BackgroundColor3 = Palette.PanelElevated, BorderSizePixel = 0, Visible = false,
        GroupTransparency = 1, Size = UDim2.fromOffset(W - 20, 0), AutomaticSize = Enum.AutomaticSize.Y,
        ZIndex = 45, Parent = screen }, { corner(8), stroke(Palette.Border),
        new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 12),
            PaddingRight = UDim.new(0, 12) }),
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6) }) })
    local function infoText(order, text, head)
        new("TextLabel", { BackgroundTransparency = 1, RichText = true, TextWrapped = true, ZIndex = 46,
            FontFace = head and Theme.Fonts.Bold or Theme.Fonts.Medium, TextSize = head and 13 or 12, LineHeight = 1.1,
            TextColor3 = head and Palette.Text or Palette.TextMuted, TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.fromScale(1, 0),
            LayoutOrder = order, Text = text, Parent = info })
    end
    infoText(1, "Importing music", true)
    infoText(2, "1. Open your executor's <b>workspace</b> folder. Koffee made a folder there called <b>" .. DIR .. "</b>.")
    infoText(3, "2. Drop in .mp3, .ogg, .wav or .flac files. Name them <i>Artist - Title</i> to show the artist.")
    infoText(4, "3. Press the refresh button at the top of the card.")
    infoText(5, "Lyrics", true)
    infoText(6, "Put a lyric file next to the song with the <b>exact same name</b>, like <i>Artist - Title.mp3</i> and <i>Artist - Title.lrc</i>.")
    infoText(7, "Works with .lrc, .srt, .vtt, .ass, .ssa and .txt. Word-timed .lrc, .vtt word stamps and .ass karaoke tags fill in word by word. A .txt just scrolls along.")
    infoText(8, "<font color=\"#6e6e78\">Click this card to close it.</font>")

    -- :: playback ::
    local function lyricsShown() return MC.Lyrics ~= false end
    local function buildLyrics()
        for _, l in ipairs(M.lineLbls) do l:Destroy() end
        M.lineLbls, M.cur = {}, 0
        local lines = M.lines
        if not lines or #lines == 0 then
            noLyr.Text = M.idx > 0 and "No lyrics for this track\nadd a lyric file with the same name" or ""
            strip.Size = UDim2.new(1, 0, 0, 0)
            return
        end
        noLyr.Text = ""
        for i, l in ipairs(lines) do
            local lbl = new("TextLabel", { BackgroundTransparency = 1, Text = l.text ~= "" and l.text or "...",
                FontFace = Theme.Fonts.Bold, TextScaled = true, TextWrapped = false, TextColor3 = Palette.Text, TextTransparency = 0.6,
                AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, (i - 1) * LINE_H),
                Size = UDim2.new(1, -20, 0, LINE_H - 4), Parent = strip },
                { new("UITextSizeConstraint", { MaxTextSize = 15, MinTextSize = 9 }), new("UIGradient", { Enabled = false }) })
            M.lineLbls[i] = lbl
        end
        strip.Size = UDim2.new(1, 0, 0, #lines * LINE_H)
        strip.Position = UDim2.fromOffset(0, LYR_H / 2 - LINE_H / 2)
    end

    local function paintList()
        for _, c in ipairs(listBox:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
        if #M.tracks == 0 then
            new("TextButton", { Text = fsOk() and ("No songs yet. Drop files in " .. DIR) or "Your executor has no file API",
                AutoButtonColor = false, BackgroundTransparency = 1, FontFace = Theme.Fonts.Medium, TextSize = 12,
                TextColor3 = Palette.TextFaint, Size = UDim2.new(1, 0, 0, 26), Parent = listBox })
            return
        end
        for i, t in ipairs(M.tracks) do
            local on = i == M.idx
            local b = new("TextButton", { Text = "", AutoButtonColor = false, BackgroundColor3 = Palette.Accent,
                BackgroundTransparency = on and 0.82 or 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 30),
                LayoutOrder = i, Parent = listBox }, { corner(6) })
            new("TextLabel", { BackgroundTransparency = 1, Text = t.title, FontFace = Theme.Fonts.Bold, TextSize = 13,
                TextColor3 = on and Palette.Accent or Palette.Text, TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd, Position = UDim2.fromOffset(8, 2), Size = UDim2.new(1, -30, 0, 15), Parent = b })
            new("TextLabel", { BackgroundTransparency = 1, Text = t.artist ~= "" and t.artist or t.name, FontFace = Theme.Fonts.Medium,
                TextSize = 11, TextColor3 = Palette.TextFaint, TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd, Position = UDim2.fromOffset(8, 16), Size = UDim2.new(1, -30, 0, 12), Parent = b })
            if t.lrc then
                local li = Koffee.lucideIcon(b, "mic-vocal", 11, Palette.TextFaint)
                li.AnchorPoint = Vector2.new(1, 0.5); li.Position = UDim2.new(1, -6, 0.5, 0)
            end
            b.MouseEnter:Connect(function() if i ~= M.idx then b.BackgroundTransparency = 0.93 end end)
            b.MouseLeave:Connect(function() b.BackgroundTransparency = (i == M.idx) and 0.82 or 1 end)
            b.MouseButton1Click:Connect(function() M.play(i) end)
        end
    end

    local function paintState()
        setIcon(playIc, sound.IsPlaying and "pause" or "play")
        playIc.Position = UDim2.new(0.5, sound.IsPlaying and 0 or 1, 0.5, 0)
        shufIc.ImageColor3 = MC.Shuffle and Palette.Accent or Palette.TextMuted
        setIcon(repIc, MC.Repeat == "One" and "repeat-1" or "repeat")
        repIc.ImageColor3 = MC.Repeat == "Off" and Palette.TextMuted or Palette.Accent
        setIcon(volIc, MC.Level <= 0.001 and "volume-x" or "volume-2")
        lyrIc.ImageColor3 = lyricsShown() and Palette.Text or Palette.TextMuted
        listIc.ImageColor3 = MC.List and Palette.Text or Palette.TextMuted
        lyrWrap.Visible = lyricsShown()
        listWrap.Visible = MC.List == true
    end

    function M.play(i)
        local t = M.tracks[i]
        if not t then return end
        M.idx = i
        MC.Last = t.name
        local ok, id = pcall(getcustomasset, t.path)
        if not ok or not id then
            if Koffee.notify then Koffee.notify("Media", "Could not load " .. t.name, { severity = "error" }) end
            return
        end
        sound:Stop()
        sound.SoundId = id
        sound.TimePosition = 0
        sound:Play()
        titleLbl.Text = t.title
        artistLbl.Text = t.artist ~= "" and t.artist or "Unknown artist"
        M.lines, M.unsynced = nil, false
        if t.lrc and readfile then
            local okr, txt = pcall(readfile, t.lrc)
            if okr and type(txt) == "string" then
                local okp, lines, meta, unsynced = pcall(parseLyrics, t.lrc, txt)
                if not okp then lines, meta, unsynced = {}, {}, false end
                M.lines, M.unsynced = lines, unsynced
                if meta.ti and meta.ti ~= "" then titleLbl.Text = meta.ti end
                if meta.ar and meta.ar ~= "" then artistLbl.Text = meta.ar end
            end
        end
        buildLyrics()
        paintList()
        paintState()
    end
    local function step(dir)
        local n = #M.tracks
        if n == 0 then return end
        if MC.Shuffle and n > 1 then
            local j = M.idx
            while j == M.idx do j = math.random(n) end
            M.play(j)
        else
            M.play(((M.idx - 1 + dir) % n) + 1)
        end
    end
    local function toggle()
        if M.idx == 0 then
            if #M.tracks == 0 then scan() end
            if #M.tracks > 0 then M.play(1) end
            return
        end
        -- the remembered track is selected but not loaded yet
        if sound.SoundId == "" then M.play(M.idx); return end
        if sound.IsPlaying then sound:Pause() else sound:Resume() end
        paintState()
    end
    local function showSelected()
        local sel = M.tracks[M.idx]
        if sel and sound.SoundId == "" then
            titleLbl.Text = sel.title
            artistLbl.Text = sel.artist ~= "" and sel.artist or "Unknown artist"
            noLyr.Text = "Press play"
        elseif M.idx == 0 then
            titleLbl.Text = "Nothing playing"
            artistLbl.Text = "Drop music in " .. DIR
            noLyr.Text = "Drop music in " .. DIR .. "\npress the tiny i for help"
        end
    end
    local function refresh(quiet)
        local cur = M.tracks[M.idx]
        scan()
        M.idx = 0
        if cur then
            for i, t in ipairs(M.tracks) do if t.path == cur.path then M.idx = i end end
        end
        -- nothing loaded yet: line up the first song so play is one click away
        if M.idx == 0 and sound.SoundId == "" and #M.tracks > 0 then M.idx = 1 end
        showSelected()
        paintList()
        if not quiet then
            refIc.Rotation = 0
            tween(refIc, TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Rotation = 360 })
            if Koffee.notify then
                local n = #M.tracks
                Koffee.notify("Media", n == 0 and ("No songs in " .. DIR) or (n .. (n == 1 and " song" or " songs") .. " found"),
                    { severity = n == 0 and "error" or "success", duration = 2.5 })
            end
        end
    end
    M.refresh = refresh

    sound.Ended:Connect(function()
        if Koffee.dead() then return end
        if MC.Repeat == "One" then
            sound.TimePosition = 0; sound:Play()
        elseif MC.Repeat == "All" or MC.Shuffle or M.idx < #M.tracks then
            step(1)
        end
        paintState()
    end)

    playBtn.MouseButton1Click:Connect(toggle)
    prevBtn.MouseButton1Click:Connect(function()
        -- a few seconds in, "back" restarts the song first
        if sound.TimePosition > 3 then sound.TimePosition = 0 else step(-1) end
    end)
    nextBtn.MouseButton1Click:Connect(function() step(1) end)
    shufBtn.MouseButton1Click:Connect(function() MC.Shuffle = not MC.Shuffle; paintState() end)
    repBtn.MouseButton1Click:Connect(function()
        MC.Repeat = ({ Off = "All", All = "One", One = "Off" })[MC.Repeat] or "All"
        paintState()
    end)
    lyrBtn.MouseButton1Click:Connect(function() MC.Lyrics = not lyricsShown(); paintState() end)
    listBtn.MouseButton1Click:Connect(function() MC.List = not MC.List; paintState() end)
    refBtn.MouseButton1Click:Connect(function() refresh(false) end)
    local infoOpen, infoY = false, -24
    local function setInfo(v)
        infoOpen = v
        if v then info.Visible = true end
    end
    infoBtn.MouseButton1Click:Connect(function() setInfo(not infoOpen) end)
    info.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then setInfo(false) end
    end)
    local lastVol = MC.Level > 0 and MC.Level or 0.2
    volBtn.MouseButton1Click:Connect(function()
        if MC.Level > 0.001 then lastVol = MC.Level; MC.Level = 0 else MC.Level = lastVol end
        paintState()
    end)

    -- scrubbing: mouse location minus the inset is AbsolutePosition space
    local dragging = nil
    local function fracOn(bar)
        local m = UserInputService:GetMouseLocation() - GS:GetGuiInset()
        return math.clamp((m.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
    end
    local function applyDrag()
        if dragging == track then
            if sound.TimeLength > 0 then sound.TimePosition = fracOn(track) * sound.TimeLength end
        elseif dragging == vtrack then
            MC.Level = fracOn(vtrack)
        end
    end
    track.MouseButton1Down:Connect(function() dragging = track; applyDrag() end)
    vtrack.MouseButton1Down:Connect(function() dragging = vtrack; applyDrag() end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then applyDrag() end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 and dragging then
            dragging = nil
            paintState()
        end
    end)

    -- per frame: progress, volume, lyric scroll + karaoke fill
    local LO = Color3.fromRGB(110, 110, 120)
    RunService.RenderStepped:Connect(function(dt)
        if Koffee.dead() then pcall(function() sound:Stop() end); return end
        applyGain()
        vfill.Size = UDim2.fromScale(MC.Level, 1)
        -- red past 10x as a warning that it is getting very loud
        local g = gainOf(MC.Level)
        vfill.BackgroundColor3 = g > 10 and Palette.Danger or (g > 2 and Palette.Accent or Palette.TextMuted)
        volLbl.Text = g >= 10 and string.format("%dx", math.floor(g + 0.5)) or string.format("%.1fx", g)
        if not root.Visible then infoOpen, infoY = false, -24; info.Visible = false; return end
        if info.Visible then
            local k = math.min(dt * 11, 1)
            infoY += ((infoOpen and 0 or -24) - infoY) * k
            local a = info.GroupTransparency
            a += ((infoOpen and 0 or 1) - a) * k
            info.GroupTransparency = a
            if not infoOpen and a > 0.98 then info.Visible = false; infoY = -24 end
            local o = root.AbsolutePosition - probe.AbsolutePosition
            info.Position = UDim2.fromOffset(o.X + 10, o.Y + 34 + infoY)
            info.Size = UDim2.fromOffset(root.AbsoluteSize.X - 20, 0)
            info.ZIndex = root.ZIndex + 1
        end
        local len, pos = sound.TimeLength, sound.TimePosition
        local f = len > 0 and math.clamp(pos / len, 0, 1) or 0
        fill.Size = UDim2.fromScale(f, 1)
        knob.Position = UDim2.fromScale(f, 0.5)
        knob.Size = UDim2.fromOffset(dragging == track and 12 or 10, dragging == track and 12 or 10)
        tNow.Text, tEnd.Text = fmt(pos), fmt(len)
        local lines = M.lines
        if not (lines and #lines > 0 and lyricsShown()) then return end
        local cur = 0
        if M.unsynced then
            -- no timings: glide through the text at the song's pace, no highlight
            cur = len > 0 and math.clamp(math.floor(f * #lines) + 1, 1, #lines) or 1
        else
            for i, l in ipairs(lines) do if l.t <= pos + 0.05 then cur = i else break end end
            -- SRT / VTT / ASS cues end; between cues nothing is being sung
            local cl = lines[cur]
            if cl and cl.e and pos > cl.e + 0.05 and lines[cur + 1] then cur = -cur end
        end
        local gap = cur < 0
        cur = math.abs(cur)
        local target = LYR_H / 2 - LINE_H / 2 - (math.max(cur, 1) - 1) * LINE_H
        local y = strip.Position.Y.Offset
        strip.Position = UDim2.fromOffset(0, y + (target - y) * math.min(dt * 10, 1))
        for i, lbl in ipairs(M.lineLbls) do
            local d = math.abs(i - cur)
            local lit = i == cur and not gap and not M.unsynced
            -- only touch a line when its look changes; rewriting every line every
            -- frame is what made the lyrics shimmer
            local tt = lit and 0 or math.clamp(0.45 + math.max(d, 1) * 0.15, 0, 0.9)
            -- untimed lyrics: the line the song is roughly at still reads clearly
            if M.unsynced and i == cur then tt = 0.15 end
            if lbl.TextTransparency ~= tt then lbl.TextTransparency = tt end
            local g = lbl:FindFirstChildOfClass("UIGradient")
            local l = lines[i]
            if lit and l.words and #l.words > 0 then
                -- share of the line sung so far, by characters
                local total, done = 0, 0
                for wi, wd in ipairs(l.words) do
                    local nxt = l.words[wi + 1]
                    local wEnd = nxt and nxt.t or l.e or (lines[i + 1] and lines[i + 1].t or wd.t + 0.6)
                    local n = #wd.w
                    total += n
                    if pos >= wEnd then done += n
                    elseif pos > wd.t then done += n * math.clamp((pos - wd.t) / math.max(wEnd - wd.t, 0.05), 0, 1) end
                end
                -- the gradient spans the label box; map the sung share onto the
                -- centred text itself
                local bw, tb = lbl.AbsoluteSize.X, lbl.TextBounds.X
                local frac = total > 0 and done / total or 0
                if bw > 0 and tb > 0 then frac = ((bw - tb) / 2 + frac * tb) / bw end
                local p = math.clamp(frac, 0.001, 0.998)
                g.Enabled = true
                g.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Palette.Accent), ColorSequenceKeypoint.new(p, Palette.Accent),
                    ColorSequenceKeypoint.new(math.min(p + 0.001, 0.999), LO), ColorSequenceKeypoint.new(1, LO) })
            elseif g.Enabled then
                g.Enabled = false
            end
        end
    end)

    task.spawn(function()
        local lastSig = nil
        while not Koffee.dead() do
            task.wait(2)
            if root.Visible and fsOk() then
                local ok, files = pcall(listfiles, DIR)
                if ok and type(files) == "table" then
                    table.sort(files)
                    local sig = table.concat(files, "|")
                    if lastSig and sig ~= lastSig then pcall(refresh, true) end
                    lastSig = sig
                end
            end
        end
    end)
    local function animShow()
        root.Visible = true
        infoOpen = false
        info.Visible = false
        if #M.tracks == 0 then
            scan()
            if MC.Last ~= "" and M.idx == 0 then
                for i, t in ipairs(M.tracks) do if t.name == MC.Last then M.idx = i end end
            end
        end
        paintList()
        paintState()
        if M.idx == 0 and sound.SoundId == "" and #M.tracks > 0 then M.idx = 1 end
        showSelected()
        root.GroupTransparency = 1
        tween(root, Theme.Animation.Menu, { GroupTransparency = 0 })
    end
    local function animHide()
        infoOpen = false
        tween(root, Theme.Animation.Menu, { GroupTransparency = 1 })
        task.delay(Koffee.Anim.wait(0.22), function()
            if not WM.shouldShow("media") then root.Visible = false end
        end)
    end

    -- the folder exists from the first load, so the info steps are true
    task.spawn(function() pcall(function() if fsOk() and not isfolder(DIR) then makefolder(DIR) end end) end)
    WM.makeDraggable(root, header, "media")
    WM.attachBody("media", root, { onShow = animShow, onHide = animHide })
end)()

-- v0.72.0 TOASTS. Bottom-right stack, max 3 visible, overflow queues. Each card
-- carries an accent edge, a Lucide icon, a ProximaSoft Bold title + muted
-- message. Cards are translucent (light, the game shows through) with a
-- hairline stroke. Entrance is fade + pop, exit is fade; hover pauses the
-- timer, click dismisses. Identical toasts coalesce, never stack.
-- Own IIFE for its register budget. Front door: Koffee.notify(title, msg, opts)
-- with opts.severity ("info" | "success" | "error") and opts.duration (seconds).
;(function()
local MAXVIS = 3
local SEV = {
    info    = { color = Theme.Palette.Accent,  icon = "info"  },
    success = { color = Theme.Palette.Success, icon = "check" },
    error   = { color = Theme.Palette.Danger,  icon = "x"     },
}
local root = new("CanvasGroup", {
    Name = KID.name("toasts"), Active = false, BackgroundTransparency = 1,
    BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.new(1, -16, 1, -16), Size = UDim2.new(0, 300, 0, 0),
    AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 60, Parent = screen,
}, {
    new("UIListLayout", { FillDirection = Enum.FillDirection.Vertical, Padding = UDim.new(0, 8),
        VerticalAlignment = Enum.VerticalAlignment.Bottom, SortOrder = Enum.SortOrder.LayoutOrder }),
})
local live, queued, order = {}, {}, 0
local function pump()
    while #live < MAXVIS and #queued > 0 do
        local job = table.remove(queued, 1)
        job.show()
    end
end
local function dismiss(rec, instant)
    for i, r in ipairs(live) do if r == rec then table.remove(live, i); break end end
    rec.done = true
    pcall(function()
        if instant then rec.wrap:Destroy()
        else
            tween(rec.wrap, Theme.Animation.Menu, { GroupTransparency = 1 })
            task.delay(Koffee.Anim.wait(0.22), function() pcall(function() rec.wrap:Destroy() end) end)
        end
    end)
    pump()
end
function Koffee.notify(title, msg, opts)
    opts = opts or {}
    local sev = SEV[opts.severity] or SEV.info
    local key = (opts.severity or "info") .. "\0" .. tostring(title) .. "\0" .. tostring(msg)
    for _, r in ipairs(live) do
        if r.key == key then r.remain = r.total; return end
    end
    for i, q in ipairs(queued) do
        if q.key == key then table.remove(queued, i); break end
    end
    local total = tonumber(opts.duration) or (3 + #tostring(msg or "") * 0.04)
    local rec = { key = key, total = total, remain = total, done = false }
    local function show()
        if Koffee.dead() then return end
        order = order + 1
        local wrap = new("CanvasGroup", {
            Name = KID.name("toast"), Active = false, BackgroundTransparency = 1,
            BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.XY,
            Size = UDim2.new(0, 300, 0, 0), GroupTransparency = 1,
            LayoutOrder = order, Parent = root,
        })
        local scale = new("UIScale", { Scale = 0.96, Parent = wrap })
        local card = new("Frame", {
            BackgroundColor3 = Theme.Palette.Panel, BackgroundTransparency = 0.35,
            BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.Y,
            Size = UDim2.new(0, 300, 0, 0), Parent = wrap,
        }, { corner(10), stroke(Theme.Palette.BorderSubtle) })
        new("Frame", {
            BackgroundColor3 = sev.color, BorderSizePixel = 0,
            Position = UDim2.new(0, 0, 0, 10), Size = UDim2.new(0, 2, 1, -20),
            Parent = card,
        }, { pillCorner() })
        Koffee.lucideIcon(card, sev.icon, 15, sev.color, 2).Position = UDim2.new(0, 12, 0, 12)
        new("TextLabel", {
            Text = tostring(title or ""), FontFace = Theme.Fonts.Bold, TextSize = Theme.Text.Body,
            TextColor3 = Theme.Palette.Text, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
            Position = UDim2.new(0, 34, 0, 8), Size = UDim2.new(1, -44, 0, 16), Parent = card,
        })
        local body = new("TextLabel", {
            Text = tostring(msg or ""), FontFace = Theme.Fonts.Regular, TextSize = Theme.Text.Small,
            TextColor3 = Theme.Palette.TextMuted, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left, TextWrapped = true,
            AutomaticSize = Enum.AutomaticSize.Y,
            Position = UDim2.new(0, 34, 0, 26), Size = UDim2.new(1, -44, 0, 14), Parent = card,
        })
        -- v0.72.4: lifetime bar removed (read as clutter). Dwell time still
        -- scales with content length; hover still pauses, click still dismisses.
        new("UIPadding", { PaddingBottom = UDim.new(0, 10), Parent = card })
        rec.wrap = wrap
        live[#live + 1] = rec
        tween(wrap, Theme.Animation.Menu, { GroupTransparency = 0 })
        tween(scale, Theme.Animation.Menu, { Scale = 1 })
        local paused = false
        card.MouseEnter:Connect(function() paused = true end)
        card.MouseLeave:Connect(function() paused = false end)
        card.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then dismiss(rec) end
        end)
        task.spawn(function()
            while not rec.done and rec.remain > 0 do
                task.wait(0.1)
                if Koffee.dead() or not wrap.Parent then rec.done = true; break end
                if not paused then rec.remain = rec.remain - 0.1 end
            end
            if not rec.done then dismiss(rec) end
        end)
    end
    if #live < MAXVIS then show() else queued[#queued + 1] = { key = key, show = show } end
end
end)()

-- v0.0.36: does this input fire a bind? Binds are EnumItems: a KeyCode
-- (keyboard) OR a UserInputType (mouse/other button).
local function bindMatches(input, bind)
    -- v0.0.94 combo bind: { mod = KeyCode, key = KeyCode }: fires only when
    -- the target key is pressed AND the modifier is currently held.
    if type(bind) == "table" and bind.mod and bind.key then
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return false end
        if input.KeyCode ~= bind.key then return false end
        return UserInputService:IsKeyDown(bind.mod)
    end
    if typeof(bind) ~= "EnumItem" then return false end
    if bind.EnumType == Enum.KeyCode then
        return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == bind
    elseif bind.EnumType == Enum.UserInputType then
        return input.UserInputType == bind
    end
    return false
end

UserInputService.InputBegan:Connect(function(input, processed)
    local it = input.UserInputType

    -- pending rebind captures ANY key/button (bypasses processed so users can
    -- rebind even with a textbox focused). v0.0.36: ESC CLEARS the bind; mouse
    -- buttons (and whatever the runtime surfaces, e.g. XButton1/2) are accepted.
    if pendingRebind then
        local pill = pendingRebind.pill
        if it == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Escape then
            Keybinds[pendingRebind.moduleId] = nil
            pill.Text = "No Keybind"
            tween(pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
            pendingRebind = nil
            return
        end
        -- v0.27.0: bind mouse buttons even when the click lands on the koffee UI.
        -- Rebind is armed ("...") so the next press is intentional, and the arming
        -- click's own edge already fired. (gpe-gating forced a game-world click.)
        -- v0.0.94: pressing JUST a modifier alone (Shift/Ctrl/Alt without another key)
        -- doesn't complete the rebind: user needs to press the actual key while
        -- holding the modifier. Otherwise the modifier itself gets bound as the key.
        if it == Enum.UserInputType.Keyboard then
            local kc = input.KeyCode
            if kc == Enum.KeyCode.LeftShift  or kc == Enum.KeyCode.RightShift
            or kc == Enum.KeyCode.LeftControl or kc == Enum.KeyCode.RightControl
            or kc == Enum.KeyCode.LeftAlt    or kc == Enum.KeyCode.RightAlt then
                return   -- wait for a real key
            end
        end
        local bind
        if it == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
            -- v0.0.94: capture combo if any modifier is currently held.
            local heldMod
            if     UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)   then heldMod = Enum.KeyCode.LeftShift
            elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then heldMod = Enum.KeyCode.LeftControl
            elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt)     then heldMod = Enum.KeyCode.LeftAlt
            elseif UserInputService:IsKeyDown(Enum.KeyCode.RightShift)  then heldMod = Enum.KeyCode.RightShift
            elseif UserInputService:IsKeyDown(Enum.KeyCode.RightControl)then heldMod = Enum.KeyCode.RightControl
            elseif UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)    then heldMod = Enum.KeyCode.RightAlt
            end
            if heldMod then bind = { mod = heldMod, key = input.KeyCode }
            else bind = input.KeyCode end
        elseif it ~= Enum.UserInputType.Focus and it ~= Enum.UserInputType.MouseMovement
           and it ~= Enum.UserInputType.MouseWheel and it ~= Enum.UserInputType.None
           and it ~= Enum.UserInputType.TextInput and it ~= Enum.UserInputType.InputMethod then
            bind = it
        end
        if bind then completeRebind(bind) end
        return
    end

    if processed then return end

    -- menu toggle (keyboard only)
    if it == Enum.UserInputType.Keyboard
    and (input.KeyCode == Enum.KeyCode.Delete or input.KeyCode == Enum.KeyCode.RightShift) then
        setWindowOpen(not windowOpen)
        return
    end

    -- module bindings (KeyCode or UserInputType)
    for id, key in pairs(Keybinds) do
        -- v0.66.1: combat has no toggle bind. v0.67.0: the lock key only engages,
        -- never arms. Ignore stale entries if they slip in.
        if id ~= "aimbot" and id ~= "silentaim" and id ~= "triggerbot" and id ~= "targetlock" then
            if bindMatches(input, key) then
                toggleModule(id)
                return
            end
        end
    end
end)

-- v0.0.37: MODULE-keybind virtual XButton driver (mirror of the combat one, for
-- module keybind pills). Roblox can't fire mouse 4/5, so the helper drives rebind
-- capture + module toggles for keybinds set to a virtual XButton.
;(function()
    local pXB1, pXB2 = false, false
    RunService.Heartbeat:Connect(function()
        if Koffee.dead() then return end
        local xb1, xb2 = Helper.XB1, Helper.XB2
        local e1, e2 = (xb1 and not pXB1), (xb2 and not pXB2)
        if pendingRebind then
            local k = (e2 and "XButton2") or (e1 and "XButton1") or nil
            if k then
                Keybinds[pendingRebind.moduleId] = k
                pendingRebind.pill.Text = keyLabel(k)
                tween(pendingRebind.pill, Theme.Animation.Fast, { TextColor3 = Theme.Palette.TextMuted })
                pendingRebind = nil
            end
        elseif e1 or e2 then
            for id, key in pairs(Keybinds) do
                -- v0.66.1: combat has no toggle bind. v0.67.0: lock key only engages.
                -- Ignore stale entries if they slip in.
                if id ~= "aimbot" and id ~= "silentaim" and id ~= "triggerbot" and id ~= "targetlock" then
                    if (key == "XButton2" and e2) or (key == "XButton1" and e1) then
                        toggleModule(id)
                    end
                end
            end
        end
        pXB1, pXB2 = xb1, xb2
    end)
end)()

-- v0.0.37: poll the Koffee Helper for OS-level input (XButton1/2). It serves live
-- button state over localhost; we cache it in `Helper` for the virtual-bind drivers.
-- Degrades silently on a slow backoff when the helper isn't running.
;(function()
    local HttpService = game:GetService("HttpService")
    local reqFn = (syn and syn.request) or (http and http.request) or http_request or request
    if reqFn then
        task.spawn(function()
            while true do
                -- v0.22.0: was immortal. Unload kept polling the helper forever and
                -- each re-exec added another poller (3 runs = ~90 req/s at :7912).
                if Koffee.dead() then
                    Helper.Connected, Helper.XB1, Helper.XB2 = false, false, false
                    break
                end
                local ok, res = pcall(reqFn, {
                    Url = Helper.Url(Helper.PortInput, "/"), Method = "GET",
                    Headers = Helper.Headers(),
                })
                local body = ok and res and res.Body
                local data
                if body then
                    local dok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
                    if dok then data = decoded end
                end
                if type(data) == "table" then
                    if not Helper.Connected then
                        Helper.Connected = true
                        print("Helper connected - K")
                    end
                    Helper.XB1 = data.xb1 and true or false
                    Helper.XB2 = data.xb2 and true or false
                    task.wait(0.03)
                else
                    if Helper.Connected then print("Helper disconnected - K") end
                    Helper.Connected, Helper.XB1, Helper.XB2 = false, false, false
                    task.wait(1)
                end
            end
        end)
    end
end)()

-- v0.85.0: Koffee Lab dev handle. Only exists when getgenv().KoffeeDev = true is
-- set before loading, so a normal load publishes nothing new.
if getgenv and getgenv().KoffeeDev == true then
    getgenv().KoffeeDev = { Koffee = Koffee, Shared = Shared, KID = KID, Combat = Shared.Combat,
        ESP = ESP, World = World, Modules = Modules, Options = KoffeeOptions, Theme = Theme,
        toggle = toggleModule, Crosshair = Crosshair }
end

-- v0.0.34: auto-load this game's saved config (if one is pinned). Deferred +
-- pcall'd so a bad/locked config never blocks the UI from coming up.
task.spawn(function()
    -- v0.56.0: resolve auto-load rules (a per-game rule beats the global one).
    local auto = Koffee.Config.autoResolve()
    if not auto then return end
    task.wait(0.25)
    pcall(function() Koffee.Config.load(auto) end)
end)
end)()

return Koffee
